(globalThis.CATALOG_PARTS=globalThis.CATALOG_PARTS||{})[4]=[{"id":"4-1-1","grade":4,"module":1,"number":1,"title":"Комп'ютерні системи: системне й прикладне ПЗ","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок1_Гра1_Три-шари.html","title":"Три шари комп'ютера","description":"сортування карток","data":{"id":"g1a","lesson":1,"tag":"ШАРИ","icon":"🧁","type":"sort","title":"Три шари комп'ютера","file":"Урок1_Гра1_Три-шари.html","conceptName":"системне й прикладне ПЗ","concept":"Комп'ютерна система має три шари. Апаратура — деталі, які можна торкнутися. Системне ПЗ, насамперед операційна система, керує апаратурою. Прикладними програмами користується людина.","skill":"розрізняю апаратуру, системне програмне забезпечення й прикладні програми","data":{"categories":[{"id":"hw","label":"🖥️ Апаратура","hint":"апаратуру можна торкнутися руками"},{"id":"sys","label":"⚙️ Системне ПЗ","hint":"системне ПЗ керує апаратурою й допомагає іншим програмам"},{"id":"app","label":"🎨 Прикладні програми","hint":"прикладною програмою користується людина для своєї справи"}],"items":[{"text":"🧠 Процесор","cat":"hw","explain":"Процесор — деталь усередині пристрою. Це апаратура.","hint":"це деталь усередині комп'ютера"},{"text":"⌨️ Клавіатура","cat":"hw","explain":"Клавіатуру можна торкнутися — це апаратура.","hint":"нею друкують, і її можна торкнутися"},{"text":"🖥️ Екран","cat":"hw","explain":"Екран — пристрій, який показує зображення. Це апаратура.","hint":"це частина пристрою, яку видно"},{"text":"💾 Пам'ять","cat":"hw","explain":"Пам'ять — мікросхеми, де зберігаються дані. Це апаратура.","hint":"це мікросхеми всередині пристрою"},{"text":"🪟 Операційна система Windows","cat":"sys","explain":"Операційна система — головна системна програма: вона запускає застосунки й керує пристроями.","hint":"вона запускає всі інші програми"},{"text":"🖨️ Драйвер принтера","cat":"sys","explain":"Драйвер — допоміжна системна програма: вона допомагає операційній системі працювати з принтером.","hint":"він допомагає ОС працювати з пристроєм"},{"text":"📁 Провідник файлів","cat":"sys","explain":"Провідник входить до операційної системи: папки й файли — її робота.","hint":"папки й кошик — це робота операційної системи"},{"text":"⚙️ Застосунок «Параметри»","cat":"sys","explain":"«Параметри» — частина операційної системи: там змінюють гучність, яскравість, мову.","hint":"там налаштовують сам пристрій"},{"text":"🎨 Графічний редактор","cat":"app","explain":"Графічним редактором людина малює — це прикладна програма.","hint":"ним людина малює"},{"text":"🌐 Браузер","cat":"app","explain":"Браузер відкриває сайти для людини — це прикладна програма.","hint":"ним людина переглядає сайти"},{"text":"🐱 Scratch","cat":"app","explain":"У Scratch діти створюють проєкти — це прикладна програма.","hint":"у ньому створюють ігри й історії"},{"text":"🎮 Комп'ютерна гра","cat":"app","explain":"Грою користується людина — це прикладна програма.","hint":"у неї грає людина"}]}},"after":{"index":1,"heading":"💡 Три шари, а не два"}},{"path":"app/games/Урок1_Гра2_Вхід-опрацювання-вихід.html","title":"Вхід → опрацювання → вихід","description":"послідовність кроків","data":{"id":"g1b","lesson":1,"tag":"ЛАНЦЮГ","icon":"📐","type":"order","title":"Вхід → опрацювання → вихід","file":"Урок1_Гра2_Вхід-опрацювання-вихід.html","conceptName":"система керування","concept":"Система керування працює за схемою з трьох блоків: вхід (датчик дізнається новину) → опрацювання (правило «якщо… то…») → вихід (дія у світі).","skill":"будую схему input → process → output для системи керування","data":{"rounds":[{"title":"🚪 Автоматичні двері","steps":["🚶 Вхід: датчик руху помічає людину","⚙️ Опрацювання: якщо є рух — відчинити","🚪 Вихід: мотор відчиняє двері"],"hint":"спочатку датчик, потім правило, наприкінці — дія","explain":"Датчик дає вхід, правило — опрацювання, мотор — вихід. Двері відчиняються і людині, і собаці: датчик не бачить різниці."},{"title":"🚦 Кнопка світлофора для пішоходів","steps":["🔘 Вхід: пішохід натискає кнопку","⚙️ Опрацювання: якщо кнопку натиснуто — заждати й увімкнути зелений","🟢 Вихід: загоряється зелене світло"],"hint":"спочатку хтось повідомляє системі, потім вона перевіряє правило, потім діє","explain":"Кнопка — вхід, правило «якщо… то…» — опрацювання, світло — вихід."},{"title":"💡 Вуличний ліхтар","steps":["🌗 Вхід: датчик міряє, скільки світла надворі","⚙️ Опрацювання: якщо темніше за поріг — ввімкнути","💡 Вихід: реле вмикає лампу"],"hint":"що система вимірює? яке правило перевіряє? що змінюється на вулиці?","explain":"Датчик освітлення — вхід, поріг у правилі — опрацювання, лампа — вихід."},{"title":"🧺 Пральна машина","steps":["💧 Вхід: датчик міряє рівень води","⚙️ Опрацювання: якщо води достатньо — зупинити набір","🚰 Вихід: клапан закривається"],"hint":"спочатку вимірювання, потім рішення, потім деталь спрацьовує","explain":"Датчик рівня — вхід, правило — опрацювання, клапан — вихід. Далі машина сама переходить до прання: це автоматизація."}]}},"after":{"index":4,"heading":"📐 Як виглядає схема системи керування"}}],"legacyTitle":"Урок 1. Комп'ютерні системи: системне й прикладне ПЗ","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 1</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Комп'ютерні системи: системне й прикладне ПЗ</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Computer Systems: System and Application Software</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: чому застосунку потрібна операційна система?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я розрізняю <b>hardware</b>, <b>system software</b> і <b>application software</b>.</li>\n      <li style=\"margin:6px 0;\">Я називаю, що операційна система робить на моєму пристрої.</li>\n      <li style=\"margin:6px 0;\">Я будую схему <b>input → process → output</b> для системи керування.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">💡 Три шари, а не два</h2>\n  <p style=\"margin:0 0 14px;\">У 2 класі ми ділили комп'ютер надвоє: залізо й програми. Тепер поділимо точніше — бо програми бувають двох дуже різних видів.</p>\n\n  <svg viewBox=\"0 0 860 250\" role=\"img\" aria-labelledby=\"g4u1-t g4u1-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u1-t\">Три шари комп'ютерної системи</title>\n    <desc id=\"g4u1-d\">Найнижчий шар — апаратура: процесор, пам'ять, екран, клавіатура. Над ним системне програмне забезпечення, насамперед операційна система, яка керує апаратурою. Найвищий шар — прикладні програми, якими користується людина: Scratch, браузер, редактор тексту.</desc>\n\n    <rect x=\"10\" y=\"16\" width=\"840\" height=\"66\" rx=\"10\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"30\" y=\"44\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">3. APPLICATION SOFTWARE — прикладні програми</text>\n    <text x=\"30\" y=\"68\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Scratch &bull; браузер &bull; редактор тексту &bull; ігри. Ними користується людина.</text>\n\n    <rect x=\"10\" y=\"92\" width=\"840\" height=\"66\" rx=\"10\" fill=\"#0033A0\"></rect>\n    <text x=\"30\" y=\"120\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">2. SYSTEM SOFTWARE — насамперед операційна система</text>\n    <text x=\"30\" y=\"144\" font-size=\"15\" fill=\"#D6E0F5\" font-family=\"Arial, sans-serif\">Windows &bull; iPadOS &bull; Android. Запускає програми, зберігає файли, керує пристроями.</text>\n\n    <rect x=\"10\" y=\"168\" width=\"840\" height=\"66\" rx=\"10\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"30\" y=\"196\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">1. HARDWARE — апаратура</text>\n    <text x=\"30\" y=\"220\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Процесор &bull; пам'ять &bull; екран &bull; клавіатура &bull; диск.</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Читай схему знизу вгору. <b>Операційна система</b> стоїть посередині не випадково: вона з'єднує апаратуру і програми.</p>\n  <p style=\"margin:0 0 12px;\">Коли ти зберігаєш проєкт у Scratch, натискаєш «Друк» чи робиш звук гучнішим, застосунок звертається до операційної системи. А вже вона керує диском, принтером чи динаміком.</p>\n  <p style=\"margin:0 0 12px;\">Системне ПЗ — це насамперед операційна система. Але до нього належать і допоміжні програми, наприклад <b>драйвери</b>: вони допомагають операційній системі працювати з конкретним пристроєм.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧰 Що операційна система робить для тебе</h2>\n  <p style=\"margin:0 0 12px;\">Роботу операційної системи видно щодня, якщо знати, куди дивитися.</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Запускає і закриває застосунки.</b> Ти торкаєшся піктограми — і програма відкривається.</li>\n    <li style=\"margin:8px 0;\"><b>Зберігає і знаходить файли.</b> Папки, назви файлів, кошик — це все робота операційної системи.</li>\n    <li style=\"margin:8px 0;\"><b>Керує налаштуваннями пристрою:</b> гучністю, яскравістю екрана, мовою клавіатури.</li>\n    <li style=\"margin:8px 0;\"><b>Підключає пристрій до інших:</b> Wi-Fi, Bluetooth, принтер, навушники.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Усе це можна побачити в застосунку «Параметри» (Settings), який входить до операційної системи. Одна й та сама програма, наприклад браузер, часто має окремі версії для різних операційних систем.</p>\n\n  <details style=\"background:#FAFAFA;border:1px solid #D9E2F0;border-radius:8px;padding:14px 16px;margin:16px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">🧠 Четвертий вид: control system</summary>\n    <p style=\"margin:12px 0 0;\">У пральній машині, ліфті чи світлофорі теж є комп'ютер. Його головне призначення — не запускати різні програми користувача, а керувати певним процесом.</p>\n    <p style=\"margin:10px 0 0;\">Це <b>система керування (control system)</b>: вона отримує сигнали від кнопок і датчиків, виконує спеціалізовану програму та керує виходами. Її firmware або програму іноді оновлює виробник чи фахівець.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚙️ Автоматизація: коли процес виконується автоматично</h2>\n  <p style=\"margin:0 0 12px;\"><b>Автоматизація (automation)</b> — це коли людина налаштовує систему, а далі та виконує певні кроки автоматично за програмою.</p>\n  <p style=\"margin:0 0 12px;\">Автоматичні двері не питають дозволу щоразу: програма виконує правило «якщо датчик помітив рух — відчини двері». Так само телефон може сам вимикати екран, а пральна машина — переходити до віджимання.</p>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Але автоматизація має межу.</p>\n    <p style=\"margin:0;\">Правило спрацьовує лише в тій ситуації, яку люди передбачили заздалегідь. Двері відчиняються і людині, і бездомному собаці — датчик руху не бачить різниці.</p>\n    <p style=\"margin:10px 0 0;\">Для деяких завдань розпізнавання, наприклад відрізнення людини від тварини на зображенні, можна використати штучний інтелект. Це один із можливих способів опрацювання даних, а не обов'язкова заміна звичайних алгоритмів.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📐 Як виглядає схема системи керування</h2>\n  <p style=\"margin:0 0 14px;\">Ось зразок, зроблений до кінця. Візьмемо вуличний ліхтар із датчиком освітлення.</p>\n\n  <svg viewBox=\"0 0 880 250\" role=\"img\" aria-labelledby=\"g4u1b-t g4u1b-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u1b-t\">Схема системи керування вуличного ліхтаря</title>\n    <desc id=\"g4u1b-d\">Вхід: датчик освітлення вимірює, скільки світла надворі. Опрацювання: правило «якщо стало темніше за поріг, то ввімкнути» перевіряється щохвилини. Вихід: реле вмикає лампу. Внизу позначено, що жодного застосунку в цій системі немає — програма одна і вбудована.</desc>\n\n    <rect x=\"6\" y=\"26\" width=\"266\" height=\"122\" rx=\"10\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"139\" y=\"54\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">INPUT &bull; вхід</text>\n    <text x=\"139\" y=\"88\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">🌗</text>\n    <text x=\"139\" y=\"114\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">датчик освітлення</text>\n    <text x=\"139\" y=\"134\" text-anchor=\"middle\" font-size=\"14\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">міряє, скільки світла надворі</text>\n\n    <path d=\"M276 87 H298\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"298,79 311,87 298,95\" fill=\"#0033A0\"></polygon>\n\n    <rect x=\"316\" y=\"26\" width=\"266\" height=\"122\" rx=\"10\" fill=\"#0033A0\"></rect>\n    <text x=\"449\" y=\"54\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">PROCESS &bull; опрацювання</text>\n    <text x=\"449\" y=\"88\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">⚙️</text>\n    <text x=\"449\" y=\"114\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">якщо темніше за поріг —</text>\n    <text x=\"449\" y=\"134\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">то ввімкнути</text>\n\n    <path d=\"M586 87 H608\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"608,79 621,87 608,95\" fill=\"#0033A0\"></polygon>\n\n    <rect x=\"626\" y=\"26\" width=\"248\" height=\"122\" rx=\"10\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"750\" y=\"54\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">OUTPUT &bull; вихід</text>\n    <text x=\"750\" y=\"88\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">💡</text>\n    <text x=\"750\" y=\"114\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">реле вмикає лампу</text>\n    <text x=\"750\" y=\"134\" text-anchor=\"middle\" font-size=\"14\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">на вулиці стає світло</text>\n\n    <rect x=\"6\" y=\"170\" width=\"868\" height=\"60\" rx=\"10\" fill=\"#F0F4F8\"></rect>\n    <text x=\"30\" y=\"196\" font-size=\"15\" font-weight=\"700\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">Чому це спеціалізована control system:</text>\n    <text x=\"30\" y=\"218\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">її головне завдання — зчитувати датчик і керувати лампою за програмою.</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Зверни увагу: у кожному блоці названо <b>конкретну деталь</b>, а не просто «щось вимірює»? Датчик освітлення, поріг, реле. Саме такої точності чекають і від твоєї схеми.</p>\n  <p style=\"margin:0 0 12px;\">У цьому прикладі опрацювання вміщується в одне речення виду «якщо… то…». Інші системи керування можуть виконувати довші й складніші програми.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: розклади по шарах</h2>\n  <p style=\"margin:0 0 14px;\">До якого шару належить кожен пункт? Назви вголос.</p>\n\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 230px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\">🖨️ драйвер принтера</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\">🎨 графічний редактор</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\">🧠 процесор</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\">📁 провідник файлів</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\">🚦 програма світлофора</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\">🌐 браузер</p>\n    </div>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Дізнайся назву операційної системи свого пристрою в «Параметрах» (Settings), а потім назви будь-які дві прикладні програми. Запиши окремо назву ОС і назви двох програм; самі «Параметри» не потрібно класифікувати.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Обери одну систему керування: мікрохвильовку, ліфт, світлофор або автоматичні двері.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Побудуй для неї схему з трьох блоків: <b>input → process → output</b>. Для кожного блоку познач, який саме датчик чи пристрій працює.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">💡 Підказка</summary>\n    <p style=\"margin:10px 0 0;\">Щоб знайти вхід, спитай: <i>звідки система дізнається, що час діяти?</i> Щоб знайти вихід — <i>що змінюється у світі після її роботи?</i></p>\n    <p style=\"margin:10px 0 0;\">Опрацювання — це правило між ними. Часто його можна сказати як «якщо… то…».</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Візьми автоматичні двері. Один блок уже заповнено:</p>\n    <div style=\"overflow-x:auto;margin:12px 0 0;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:420px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:9px 11px;border-bottom:1px solid #EDD3B0;width:34%;\"><b>Input</b></td><td style=\"padding:9px 11px;border-bottom:1px solid #EDD3B0;\">датчик руху бачить людину</td></tr>\n          <tr><td style=\"padding:9px 11px;border-bottom:1px solid #EDD3B0;\"><b>Process</b></td><td style=\"padding:9px 11px;border-bottom:1px solid #EDD3B0;\">______________</td></tr>\n          <tr><td style=\"padding:9px 11px;\"><b>Output</b></td><td style=\"padding:9px 11px;\">______________</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:12px 0 0;\">Заповни два порожні рядки — і завдання виконано. Крок 1 можна пропустити.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Порівняй дві автоматизовані системи:</p>\n    <ul style=\"margin:10px 0 0;padding-left:22px;\">\n      <li style=\"margin:5px 0;\"><b>Автоматичні двері.</b> Датчик щось помітив — двері відчиняються.</li>\n      <li style=\"margin:5px 0;\"><b>Розумна камера,</b> яка відрізняє людину від кота.</li>\n    </ul>\n    <p style=\"margin:10px 0 0;\">У якій із них досить наперед заданого правила, а в якій потрібен штучний інтелект? Поясни, чому саме.</p>\n    <p style=\"margin:10px 0 0;\">Підказка для роздумів: у дверях достатньо перевірити сигнал одного датчика, а камера має опрацювати багато ознак зображення. Для такого розпізнавання часто використовують модель ШІ.</p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Симулятор налаштування ПК:</b> досліди операційну систему та прикладне ПЗ у безпечному симуляторі без зміни налаштувань свого пристрою.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/assembly/software.html\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;\">Відкрити симулятор ПЗ ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u1-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що з переліку належить до системного програмного забезпечення?</label>\n    <select id=\"g4-u1-q1\" name=\"g4-u1-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Scratch — середовище для програмування</option>\n      <option>Chrome — браузер для перегляду сайтів</option>\n      <option>Windows — операційна система пристрою</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Windows. Scratch і Chrome — прикладні програми: вони працюють <i>поверх</i> операційної системи.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u1-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Scratch зберігає проєкт на диск. Хто насправді записує файл?</label>\n    <select id=\"g4-u1-q2\" name=\"g4-u1-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Операційна система на прохання Scratch</option>\n      <option>Сам Scratch звертається до диска</option>\n      <option>Процесор вирішує це без програм</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Операційна система на прохання Scratch. Застосунок каже «збережи файл із такою назвою», а записує його на диск операційна система.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u1-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чим система керування у ліфті відрізняється від планшета?</label>\n    <select id=\"g4-u1-q3\" name=\"g4-u1-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Вона створена насамперед для керування роботою ліфта</option>\n      <option>У неї немає процесора всередині</option>\n      <option>Вона працює зовсім без електрики</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Вона створена насамперед для керування ліфтом. Усередині є процесор і спеціалізоване ПЗ, яке може обслуговуватися або оновлюватися фахівцями.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку одним-двома реченнями:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Застосунку потрібна операційна система, бо ___»</i></p>\n    <p style=\"margin:12px 0 0;\">А тепер додай друге речення — про свою систему керування:</p>\n    <p style=\"margin:8px 0 0;font-size:18px;\"><i>«У моїй системі правило звучить так: якщо ___, то ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я відношу щонайменше 4 приклади до правильного шару.</li>\n      <li style=\"margin:8px 0;\">Я пояснюю, за що відповідає операційна система.</li>\n      <li style=\"margin:8px 0;\">Моя схема містить усі три блоки з назвами датчиків і пристроїв.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> достатньо виконати всі кроки блоку «Потрібна допомога?» й пояснити один результат.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережену схему системи або її фото із зошита.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>system software</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">системне ПЗ</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>application software</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">прикладне ПЗ</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>operating system</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">операційна система</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>control system</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">система керування</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>automation</b></td><td style=\"padding:8px 10px;\">автоматизація</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The operating system manages the hardware. Scratch is application software. A lift uses a control system.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-1-2","grade":4,"module":1,"number":2,"title":"Інтернет, WWW, URL, клієнти й сервери","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок2_Гра1_Шлях-сторінки.html","title":"Шлях сторінки","description":"послідовність кроків","data":{"id":"g2a","lesson":2,"tag":"ЗАПИТ","icon":"🔁","type":"order","title":"Шлях сторінки","file":"Урок2_Гра1_Шлях-сторінки.html","conceptName":"запит і відповідь","concept":"Клієнт (твій браузер) надсилає серверу запит — request. Сервер знаходить сторінку й повертає відповідь — response. Обидва шляхи проходять через Інтернет.","skill":"показую на схемі client, server, request і response","data":{"rounds":[{"title":"🌐 Що відбувається після Enter","steps":["👆 Ти вводиш адресу й натискаєш Enter","💻 Браузер-клієнт надсилає запит (request)","🗄️ Сервер знаходить потрібну сторінку","📦 Сервер надсилає відповідь (response)","🖥️ Браузер складає сторінку на екрані"],"hint":"спочатку запит летить до сервера, аж потім відповідь повертається","explain":"Клієнт просить — сервер відповідає. Без запиту відповіді не буває."},{"title":"⭐ Як зберегти закладку","steps":["🌐 Відкрий сторінку за адресою","⭐ Натисни зірочку біля адресного рядка","📑 Адреса збереглась у закладках","🔁 Наступного разу відкрий сторінку зі списку закладок"],"hint":"зірочку натискають, коли сторінка вже відкрита","explain":"Закладка зберігає URL, щоб не вводити адресу щоразу."}]}},"after":{"index":2,"heading":"🔁 Клієнт просить — сервер відповідає"}},{"path":"app/games/Урок2_Гра2_Дороги-й-транспорт.html","title":"Дороги й транспорт","description":"сценарний вибір","data":{"id":"g2b","lesson":2,"tag":"ДОРОГИ","icon":"🛣️","type":"quiz","title":"Дороги й транспорт","file":"Урок2_Гра2_Дороги-й-транспорт.html","conceptName":"Інтернет і WWW","concept":"Інтернет — це «дороги»: кабелі й радіозв'язок між мільйонами комп'ютерів. WWW — вебсторінки, лише один із видів «транспорту» на цих дорогах.","skill":"розрізняю Internet і WWW та читаю частини URL","data":{"questions":[{"q":"У дорожній аналогії Інтернет — це…","options":["Усі дороги світу","Один із видів транспорту","Світлофор на перехресті"],"correct":0,"explain":"Інтернет — це дороги: кабелі й радіозв'язок. А WWW — лише один із видів транспорту на них.","wrong":"Згадай: дороги з'єднують комп'ютери, а їздять ними різні «транспорти»."},{"q":"WWW — це…","options":["вебсторінки, пов'язані посиланнями","усі кабелі світу","назва браузера"],"correct":0,"explain":"Всесвітня павутина — це вебсторінки. Тими ж дорогами їздять і пошта, і відеодзвінки.","wrong":"Павутина — не кабелі, а те, що ти відкриваєш у браузері."},{"q":"Хто надсилає запит (request)?","options":["Клієнт, наприклад браузер","Сервер, який зберігає сайт","Кабель у стіні"],"correct":0,"explain":"Клієнт просить сторінку, а сервер повертає відповідь.","wrong":"Хто просить дані — той і надсилає запит."},{"q":"Що робить сервер?","options":["Зберігає сайт і надсилає відповідь","Друкує сторінку на папері","Малює картинки для сайту"],"correct":0,"explain":"Сервер — комп'ютер, що зберігає дані й надає їх іншим.","wrong":"Сервер нічого не друкує — він відповідає на запити."},{"q":"У адресі https://example.com/news доменне ім'я — це…","options":["example.com","https","/news"],"correct":0,"explain":"Доменне ім'я — назва сайту. https — протокол, а /news — шлях до сторінки.","wrong":"Доменне ім'я — це назва сайту між // і першою скісною рискою."},{"q":"Замок 🔒 і https біля адреси означають…","options":["з'єднання захищене, але сайт може бути нечесним","сайт точно чесний","сторінка відкриється без Інтернету"],"correct":0,"explain":"Захищене з'єднання не доводить, що сайт чесний. Читай уважно доменне ім'я.","wrong":"Замок каже лише про захист дорогою, а не про чесність сайту."},{"q":"Інші сайти відкриваються, а один — ні. Що найімовірніше?","options":["Проблема з цим сервером або з адресою","Зник Інтернет у всій школі","Зламався браузер"],"correct":0,"explain":"Якщо інші сайти працюють, з'єднання в порядку. Спершу перевір, чи правильно написано адресу.","wrong":"Якби зник Інтернет, не працював би жоден сайт."},{"q":"Навіщо потрібні закладки?","options":["Щоб не вводити адресу щоразу","Щоб сайт відкривався швидше","Щоб захистити пароль"],"correct":0,"explain":"Закладка зберігає URL. Зазвичай її створює кнопка ⭐ біля адресного рядка.","wrong":"Закладка просто запам'ятовує адресу."}]}},"after":{"index":1,"heading":"🛣 Інтернет і WWW — не одне й те саме"}}],"legacyTitle":"Урок 2. Інтернет, WWW, URL, клієнти й сервери","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 2</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Інтернет, WWW, URL, клієнти й сервери</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">The Internet, WWW, URLs, Clients and Servers</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: що відбувається між натисканням Enter і появою сторінки на екрані?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я розрізняю <b>Internet</b> і <b>World Wide Web</b>.</li>\n      <li style=\"margin:6px 0;\">Я показую на схемі <b>client</b>, <b>server</b>, <b>request</b> і <b>response</b>.</li>\n      <li style=\"margin:6px 0;\">Я відкриваю сторінку за <b>URL</b> і зберігаю її в закладках.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛣 Інтернет і WWW — не одне й те саме</h2>\n  <p style=\"margin:0 0 12px;\">Ці два слова часто вживають як однакові. Але вони означають різне, і різницю легко запам'ятати за дорожньою аналогією.</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Інтернет (Internet) — це дороги.</b> Кабелі, радіозв'язок і спеціальні пристрої з'єднують мільйони комп'ютерів у всьому світі в одну велику мережу.</li>\n    <li style=\"margin:8px 0;\"><b>Всесвітня павутина (WWW) — це один із видів транспорту на цих дорогах.</b> Це вебсторінки, пов'язані посиланнями. Ти відкриваєш їх у <b>браузері (browser)</b>.</li>\n    <li style=\"margin:8px 0;\"><b>Інший «транспорт»</b> теж їздить тими самими дорогами: електронна пошта, відеодзвінки, онлайн-ігри.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Отже, коли пошта працює, а сайт не відкривається, дороги можуть бути в порядку — проблема в конкретному «транспорті».</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔁 Клієнт просить — сервер відповідає</h2>\n  <p style=\"margin:0 0 12px;\">Комп'ютери в мережі мають різні ролі. <b>Клієнт (client)</b> — це пристрій або програма, яка просить дані. Твій браузер — клієнт. <b>Сервер (server)</b> — це комп'ютер або програма, що зберігає дані й надає їх іншим.</p>\n  <p style=\"margin:0 0 14px;\">Розмова між ними завжди складається з двох кроків: <b>запит (request)</b> і <b>відповідь (response)</b>.</p>\n\n  <svg viewBox=\"0 0 860 250\" role=\"img\" aria-labelledby=\"g4u2a-t g4u2a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u2a-t\">Клієнт і сервер: запит і відповідь</title>\n    <desc id=\"g4u2a-d\">Ліворуч клієнт — браузер на твоєму пристрої. Праворуч сервер — комп'ютер, що зберігає сайт. Верхня стрілка: крок 1, запит — клієнт просить сторінку за URL. Нижня стрілка: крок 2, відповідь — сервер надсилає текст і картинки сторінки. Обидві стрілки проходять через Інтернет.</desc>\n    <rect x=\"6\" y=\"30\" width=\"226\" height=\"170\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"119\" y=\"76\" text-anchor=\"middle\" font-size=\"30\" font-family=\"Arial, sans-serif\">💻</text>\n    <text x=\"119\" y=\"114\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">CLIENT • клієнт</text>\n    <text x=\"119\" y=\"146\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">браузер на твоєму</text>\n    <text x=\"119\" y=\"168\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">пристрої</text>\n\n    <path d=\"M242 88 H606\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"606,80 620,88 606,96\" fill=\"#0033A0\"></polygon>\n    <text x=\"430\" y=\"50\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">1. REQUEST • запит</text>\n    <text x=\"430\" y=\"74\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">«надішли сторінку за цим URL»</text>\n\n    <path d=\"M620 142 H256\" fill=\"none\" stroke=\"#1B6B3A\" stroke-width=\"3\"></path>\n    <polygon points=\"256,134 242,142 256,150\" fill=\"#1B6B3A\"></polygon>\n    <text x=\"430\" y=\"168\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">2. RESPONSE • відповідь</text>\n    <text x=\"430\" y=\"192\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">текст і картинки сторінки</text>\n\n    <rect x=\"628\" y=\"30\" width=\"226\" height=\"170\" rx=\"12\" fill=\"#0033A0\"></rect>\n    <text x=\"741\" y=\"76\" text-anchor=\"middle\" font-size=\"30\" font-family=\"Arial, sans-serif\">🗄️</text>\n    <text x=\"741\" y=\"114\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">SERVER • сервер</text>\n    <text x=\"741\" y=\"146\" text-anchor=\"middle\" font-size=\"15\" fill=\"#D6E0F5\" font-family=\"Arial, sans-serif\">комп'ютер, що</text>\n    <text x=\"741\" y=\"168\" text-anchor=\"middle\" font-size=\"15\" fill=\"#D6E0F5\" font-family=\"Arial, sans-serif\">зберігає сайт</text>\n\n    <text x=\"430\" y=\"232\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">обидва шляхи проходять через Інтернет</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Тепер можна відповісти на питання уроку. Ти натискаєш Enter — браузер-клієнт надсилає запит за адресою. Сервер знаходить потрібну сторінку й повертає відповідь. Браузер отримує текст і картинки та складає з них сторінку на екрані.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔗 З чого складається URL</h2>\n  <p style=\"margin:0 0 14px;\">Щоб клієнт знав, куди надсилати запит, у кожної сторінки є адреса — <b>URL</b>. Це не суцільний рядок: у ньому кілька частин, і кожна щось повідомляє.</p>\n  <svg viewBox=\"0 0 860 220\" role=\"img\" aria-labelledby=\"g4u2b-t g4u2b-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u2b-t\">Чотири частини веб-адреси</title>\n    <desc id=\"g4u2b-d\">Протокол https означає захищене з'єднання. Далі йде доменне ім'я — назва сайту. Закінчення домену вказує на тип або країну. Після скісної риски йде шлях до конкретної сторінки всередині сайту.</desc>\n    <rect x=\"6\" y=\"14\" width=\"848\" height=\"54\" rx=\"10\" fill=\"#F0F4F8\"></rect>\n    <text x=\"30\" y=\"50\" font-size=\"21\" font-weight=\"700\" fill=\"#1A1A1A\" font-family=\"'Courier New',monospace\">https://  example.com  /pages/  info.html</text>\n    <rect x=\"6\" y=\"84\" width=\"206\" height=\"122\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n    <text x=\"109\" y=\"116\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">https://</text>\n    <text x=\"109\" y=\"148\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">протокол</text>\n    <text x=\"109\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">🔒 з'єднання</text>\n    <text x=\"109\" y=\"196\" text-anchor=\"middle\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">захищене</text>\n    <rect x=\"224\" y=\"84\" width=\"206\" height=\"122\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"327\" y=\"116\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">example</text>\n    <text x=\"327\" y=\"148\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">доменне ім'я</text>\n    <text x=\"327\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">назва</text>\n    <text x=\"327\" y=\"196\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">сайту</text>\n    <rect x=\"442\" y=\"84\" width=\"206\" height=\"122\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"545\" y=\"116\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">.com</text>\n    <text x=\"545\" y=\"148\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">тип або країна</text>\n    <text x=\"545\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">.ua .org .com</text>\n    <rect x=\"660\" y=\"84\" width=\"194\" height=\"122\" rx=\"12\" fill=\"#F0F4F8\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"757\" y=\"116\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">/pages/info.html</text>\n    <text x=\"757\" y=\"148\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">шлях до сторінки</text>\n    <text x=\"757\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">усередині сайту</text>\n  </svg>\n  <p style=\"margin:0 0 12px;\">Найважливіше читати уважно <b>доменне ім'я</b>: воно показує, на який сайт ти потрапиш. Шахраї інколи створюють домени, дуже схожі на справжні, з однією зміненою літерою.</p>\n  <p style=\"margin:0 0 12px;\">Замок і <b>https</b> означають, що дані між браузером і сайтом передаються захищено. Але вони не доводять, що сам сайт чесний.</p>\n  <p style=\"margin:0 0 12px;\">Щоб не вводити адресу щоразу, її зберігають у <b>закладках (bookmarks)</b>. У різних браузерах вони називаються трохи по-різному, наприклад «Обране» (favourites). Зазвичай закладку створює кнопка ⭐ біля адресного рядка.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🎲 Спробуй: гра «Кам'яні посланці»</h2>\n  <p style=\"margin:0 0 12px;\">Розіграйте клієнт-сервер без комп'ютера. Ролі такі:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Клієнт</b> пише на картці запит з адресою сторінки, наприклад <code style=\"background:#F0F4F8;padding:2px 6px;border-radius:4px;\">https://example.com/axolotl</code>.</li>\n    <li style=\"margin:8px 0;\"><b>Посланець</b> — це мережа. Він несе картку через клас.</li>\n    <li style=\"margin:8px 0;\"><b>Сервер</b> сидить біля коробки з картками-відповідями. Він знаходить картку з аксолотлем і віддає посланцеві.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Коли все працює, клієнт отримує відповідь. Потім учитель двічі втручається з картками збою:</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 280px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFF2F2;border:1px solid #E6B0AA;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0 0 6px;font-weight:700;color:#96271B;\">💥 Картка «Зв'язок обірвано»</p>\n      <p style=\"margin:0;\">Учитель зупиняє посланця посеред шляху. Запит так і не доходить до сервера.</p>\n    </div>\n    <div style=\"background:#FFF2F2;border:1px solid #E6B0AA;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0 0 6px;font-weight:700;color:#96271B;\">🛑 Картка «Сервер не відповідає»</p>\n      <p style=\"margin:0;\">Посланець доходить до сервера, але сервер тримає табличку «Недоступний» і нічого не віддає.</p>\n    </div>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Відкрий браузер, який дозволила школа. Введи в адресний рядок адресу, яку дасть учитель, наприклад <b>itnauka.org</b>. Перш ніж натиснути Enter, прочитай доменне ім'я.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Коли сторінка відкриється, створи закладку кнопкою ⭐. Закрий вкладку й відкрий сторінку знову — вже із закладок.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Намалюй у зошиті схему для цієї сторінки: клієнт, сервер і дві стрілки. Підпиши стрілки словами <b>request</b> і <b>response</b>, а над першою запиши URL.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4.</b> Після гри «Кам'яні посланці» запиши, чим відрізняються дві картки збою. Що в кожному випадку бачить клієнт на екрані?</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити Крок 4</summary>\n    <p style=\"margin:10px 0 0;\"><b>«Зв'язок обірвано»:</b> запит не доходить до сервера. Браузер пише щось на кшталт «Немає підключення до Інтернету». Не відкривається жоден сайт.</p>\n    <p style=\"margin:10px 0 0;\"><b>«Сервер не відповідає»:</b> дорога працює, але цей сервер недоступний. Браузер повідомляє, що сайт недоступний, а інші сайти відкриваються.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Заповни схему, у якій уже є частина слів:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>Браузер — це ______. Він надсилає ______. Сервер повертає ______.</i></p>\n    <p style=\"margin:12px 0 0;\">Слова для вставки: <b>response</b>, <b>client</b>, <b>request</b>. Для Кроку 1 попроси вчителя показати адресний рядок. Кроки 3 і 4 зараховуються, якщо схема заповнена правильно.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Як браузер знаходить сервер.</b> Комп'ютери в мережі мають числові адреси. Спеціальна служба <b>DNS</b> працює як телефонна книга: за доменним ім'ям вона знаходить числову адресу сервера. Якщо адресу написано з помилкою, DNS нічого не знайде — і це не означає, що сервер вимкнено.</p>\n    <p style=\"margin:10px 0 0;\"><b>Помилка 404.</b> Сервер працює, але такої сторінки на ньому немає. Наприклад, у шляху після скісної риски є помилка.</p>\n    <p style=\"margin:10px 0 0;\"><b>Онлайн-сервіси ШІ</b> теж працюють за моделлю «клієнт — сервер». Твій запит летить через Інтернет на сервери, там модель його опрацьовує і повертає відповідь. Тому без мережі такий сервіс недоступний. Існують і менші моделі, що працюють прямо на пристрої.</p>\n    <p style=\"margin:10px 0 0;\">Порівняй два способи послухати пісню: файл на пристрої і стримінг. Скільки ланок має спрацювати в кожному випадку? Що стане недоступним, якщо в школі на день зникне Інтернет?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>A local file needs no server. A stream needs a request and a response.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Веселі адреси:</b> потренуйся точно вводити URL. Потім у «Порятунку сервера» простеж, що може статися з мережевим сервісом.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/digital_literacy/typing_skills/urls_typing/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Відкрити «Веселі адреси» ↗</a>\n    <a href=\"https://itnauka.org/services/quizes/save_server/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;\">Відкрити «Порятунок сервера» ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u2-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що в дорожній аналогії означає WWW?</label>\n    <select id=\"g4-u2-q1\" name=\"g4-u2-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Усі дороги світу</option>\n      <option>Один із видів транспорту на дорогах</option>\n      <option>Світлофор на перехресті</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Один із видів транспорту. Дороги — це Інтернет, а WWW — вебсторінки, які ним користуються, як і пошта чи відеодзвінки.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u2-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Хто надсилає request?</label>\n    <select id=\"g4-u2-q2\" name=\"g4-u2-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Сервер, коли хоче показати рекламу</option>\n      <option>Клієнт, наприклад браузер</option>\n      <option>Кабель, яким підключено комп'ютер</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Клієнт. Браузер просить сторінку, а сервер повертає response.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u2-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Інші сайти відкриваються, а один — ні. Що найімовірніше?</label>\n    <select id=\"g4-u2-q3\" name=\"g4-u2-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Зник Інтернет у всій школі</option>\n      <option>Проблема з цим сервером або з адресою</option>\n      <option>Зламався браузер</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Проблема з цим сервером або з адресою. Якщо інші сайти працюють, то і з'єднання, і браузер у порядку. Спершу перевір, чи правильно написано URL.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Поясни різницю, яку часто плутають:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Інтернет — це ___, а WWW — це ___»</i></p>\n    <p style=\"margin:12px 0 0;\">А тепер дай відповідь на питання уроку одним реченням, використавши слова <i>request</i> і <i>response</i>.</p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я пояснюю різницю між Internet і WWW.</li>\n      <li style=\"margin:8px 0;\">Моя схема показує client, server, request і response.</li>\n      <li style=\"margin:8px 0;\">У браузері є моя закладка, а я називаю доменне ім'я сторінки.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> достатньо правильно заповнити схему з блоку «Потрібна допомога?».</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> схему в зошиті й закладку в браузері.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>Internet</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">Інтернет, мережа мереж</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>World Wide Web</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">Всесвітня павутина</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>URL</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">адреса вебсторінки</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>client / server</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">клієнт / сервер</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>request / response</b></td><td style=\"padding:8px 10px;\">запит / відповідь</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The client sends a request. The server sends a response. The web uses the Internet.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-1-3","grade":4,"module":1,"number":3,"title":"Wi-Fi, Ethernet, діагностика мережі та цифровий розрив","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок3_Гра1_Wi-Fi-чи-Ethernet.html","title":"Wi-Fi чи Ethernet?","description":"сортування карток","data":{"id":"g3a","lesson":3,"tag":"СИГНАЛ","icon":"📶","type":"sort","title":"Wi-Fi чи Ethernet?","file":"Урок3_Гра1_Wi-Fi-чи-Ethernet.html","conceptName":"дротове й бездротове з'єднання","concept":"Ethernet — дротова мережа через кабель: зазвичай стабільніша. Wi-Fi — бездротова: дає свободу руху, але їй заважають стіни й відстань.","skill":"обираю Wi-Fi чи Ethernet для ситуації й пояснюю чому","data":{"categories":[{"id":"wifi","label":"📶 Wi-Fi","hint":"Wi-Fi потрібен, коли пристрій рухається або кабелю немає"},{"id":"eth","label":"🔌 Ethernet","hint":"Ethernet обирають, коли пристрій стоїть на місці й важлива стабільність"}],"items":[{"text":"📱 Планшети, з якими учні ходять по класу й фотографують рослини","cat":"wifi","explain":"Пристрої рухаються — потрібен Wi-Fi."},{"text":"🖥️ Настільний комп'ютер біля мережевої розетки, на якому пишуть важливий тест","cat":"eth","explain":"Пристрій стоїть на місці, а тест потребує стабільного з'єднання — Ethernet."},{"text":"📱 Телефон у кишені","cat":"wifi","explain":"Телефон носять із собою — лише бездротова мережа."},{"text":"🎮 Ігрова приставка біля телевізора поруч із роутером","cat":"eth","explain":"Вона стоїть на місці, і кабель дасть стабільнішу швидкість."},{"text":"📚 Планшет у бібліотеці, де немає мережевих розеток","cat":"wifi","explain":"Кабель нікуди підключити — тому Wi-Fi."},{"text":"🏫 Стаціонарні комп'ютери в комп'ютерному класі","cat":"eth","explain":"Вони не рухаються, тому кабель — передбачуваніше і стабільніше."},{"text":"🎵 Розумна колонка на кухні без мережевої розетки","cat":"wifi","explain":"Немає куди встромити кабель — Wi-Fi."},{"text":"💻 Ноутбук, який носять із кімнати в кімнату","cat":"wifi","explain":"Потрібна свобода руху — Wi-Fi. Якщо сигнал слабкий, працюй ближче до роутера."}]}},"after":{"index":1,"heading":"📶 Два способи підключитися до мережі"}},{"path":"app/games/Урок3_Гра2_Сайт-не-відкривається.html","title":"Сайт не відкривається","description":"послідовність кроків","data":{"id":"g3b","lesson":3,"tag":"ПОРЯДОК","icon":"🧭","type":"order","title":"Сайт не відкривається","file":"Урок3_Гра2_Сайт-не-відкривається.html","conceptName":"діагностика мережі","concept":"Коли щось не працює, дій за порядком — від найпростішого. Налаштувань комп'ютера й роутера ми не змінюємо: це робота дорослих.","skill":"проходжу безпечні кроки, коли сайт не відкривається","data":{"rounds":[{"title":"🌳 Правильний порядок дій","steps":["👀 Подивись на значок мережі на екрані","🌐 Відкрий інший сайт","🔍 Перевір адресу й перезапусти вкладку","🔌 Якщо є кабель — лише подивись, чи він на місці","🧑‍🏫 Скажи дорослому, які кроки вже зроблено"],"hint":"починай з найпростішого — з екрана, а дорослого клич наприкінці","explain":"Від простого до складного: значок → інший сайт → адреса → погляд на кабель → дорослий."},{"title":"🤔 Інші сайти працюють, а один — ні","steps":["✅ Зрозумій: з'єднання в порядку","🔍 Перевір, чи правильно написано адресу","🗣️ Скажи дорослому: можливо, цей сервер недоступний"],"hint":"якщо інші сайти відкриваються, то «дороги» в порядку","explain":"Працюють інші сайти — отже, проблема з цим сайтом або з адресою, а не з мережею."}]}},"after":{"index":2,"heading":"🌳 Сайт не відкривається: безпечні кроки"}},{"path":"app/games/Урок3_Гра3_Шість-барєрів.html","title":"Шість бар'єрів","description":"сортування карток","data":{"id":"g3c","lesson":3,"tag":"МОСТИ","icon":"⚖️","type":"sort","title":"Шість бар'єрів","file":"Урок3_Гра3_Шість-барєрів.html","conceptName":"цифровий розрив","concept":"Цифровий розрив — це коли люди мають різні можливості користуватися технологіями. Причина — не лише сигнал: бувають бар'єри вартості, впевненості, здоров'я, навчання, довіри й вибору.","skill":"називаю бар'єри цифрового розриву","data":{"categories":[{"id":"cost","label":"💰 Вартість","hint":"справа в грошах на пристрій чи тариф"},{"id":"conf","label":"😟 Впевненість","hint":"людині страшно щось зламати"},{"id":"health","label":"🩺 Здоров'я","hint":"зір, слух чи рухи заважають користуватися пристроєм"},{"id":"learn","label":"🎓 Навчання","hint":"ніхто не показав, як"},{"id":"trust","label":"🤝 Довіра","hint":"людина не вірить сайтам і сервісам"},{"id":"choice","label":"🙅 Вибір","hint":"людина сама вирішує не користуватися"}],"items":[{"text":"«Хочу малювати на планшеті, але він коштує більше, ніж родина може виділити»","cat":"cost","explain":"Це бар'єр вартості. Допоможуть шкільні пристрої чи бібліотека."},{"text":"«Боюся натиснути щось не те, тому лише телефоную»","cat":"conf","explain":"Це бар'єр впевненості. Допоможе спокійне пояснення й можливість спробувати самостійно."},{"text":"«У мене тремтять руки, важко влучати в дрібні кнопки»","cat":"health","explain":"Це бар'єр здоров'я. Допоможуть великі кнопки чи голосове введення."},{"text":"«У нас у школі ніхто не показує, як програмувати роботів»","cat":"learn","explain":"Це бар'єр навчання: пристрої можуть бути, але без навчання розрив лишається."},{"text":"«Не вірю онлайн-магазинам: раптом там шахраї»","cat":"trust","explain":"Це бар'єр довіри. Допомагають перевірені сайти й поради дорослих."},{"text":"«Мені й без Інтернету добре, не хочу ним користуватися»","cat":"choice","explain":"Це власний вибір людини, і його поважають."},{"text":"«Я погано бачу дрібний текст на екрані»","cat":"health","explain":"Це бар'єр здоров'я. Допоможуть великий шрифт і озвучення тексту."},{"text":"«Не вистачає грошей на домашній інтернет-тариф»","cat":"cost","explain":"Це бар'єр вартості. Виручають безкоштовний Wi-Fi у бібліотеці чи школі."}]}},"after":{"index":3,"heading":"⚖️ Цифровий розрив"}}],"legacyTitle":"Урок 3. Wi-Fi, Ethernet, діагностика мережі та цифровий розрив","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 3</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Wi-Fi, Ethernet, діагностика мережі та цифровий розрив</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Wi-Fi, Ethernet, Network Troubleshooting and the Digital Divide</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: інтернет є, але не в усіх удома. Чи це лише технічна проблема?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я порівнюю <b>Wi-Fi</b> та <b>Ethernet</b> і обираю з'єднання для ситуації.</li>\n      <li style=\"margin:6px 0;\">Я проходжу безпечні кроки, коли сайт не відкривається.</li>\n      <li style=\"margin:6px 0;\">Я називаю причини <b>digital divide</b> і пропоную, як допомогти.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📶 Два способи підключитися до мережі</h2>\n  <p style=\"margin:0 0 12px;\"><b>Ethernet</b> — це технологія дротової мережі (wired). Зазвичай пристрій з'єднують мережевим кабелем із роутером або мережевою розеткою в стіні.</p>\n  <p style=\"margin:0 0 12px;\"><b>Wi-Fi</b> — це технологія бездротової мережі (wireless). Дані передаються радіохвилями між пристроєм і точкою доступу, наприклад роутером.</p>\n\n  <svg viewBox=\"0 0 860 260\" role=\"img\" aria-labelledby=\"g4u3a-t g4u3a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u3a-t\">Порівняння Ethernet і Wi-Fi</title>\n    <desc id=\"g4u3a-d\">Ethernet: кабель від пристрою до роутера; зазвичай стабільніший; швидкість передбачуваніша; але пристрій прив'язаний до кабелю. Wi-Fi: радіосигнал від точки доступу; можна пересуватися з пристроєм; легко підключити багато пристроїв; але заважають стіни й відстань. Внизу: обидва способи можуть бути безпечними, якщо мережу правильно налаштовано.</desc>\n    <rect x=\"6\" y=\"10\" width=\"418\" height=\"186\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"30\" y=\"44\" font-size=\"18\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">🔌 Ethernet • дротове</text>\n    <text x=\"30\" y=\"80\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">кабель від пристрою до роутера</text>\n    <text x=\"30\" y=\"110\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">✔ зазвичай стабільніший</text>\n    <text x=\"30\" y=\"138\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">✔ швидкість передбачуваніша</text>\n    <text x=\"30\" y=\"166\" font-size=\"15\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">✖ пристрій прив'язаний до кабелю</text>\n\n    <rect x=\"436\" y=\"10\" width=\"418\" height=\"186\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"460\" y=\"44\" font-size=\"18\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">📶 Wi-Fi • бездротове</text>\n    <text x=\"460\" y=\"80\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">радіосигнал від точки доступу</text>\n    <text x=\"460\" y=\"110\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">✔ можна пересуватися з пристроєм</text>\n    <text x=\"460\" y=\"138\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">✔ легко підключити багато пристроїв</text>\n    <text x=\"460\" y=\"166\" font-size=\"15\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">✖ заважають стіни й відстань</text>\n\n    <rect x=\"6\" y=\"208\" width=\"848\" height=\"44\" rx=\"10\" fill=\"#F0F4F8\"></rect>\n    <text x=\"430\" y=\"236\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">Обидва способи можуть бути безпечними, якщо мережу правильно налаштовано.</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Зверни увагу на слова «зазвичай» і «часто». На Wi-Fi сильніше впливають відстань до роутера, стіни й кількість пристроїв поруч. Ethernet часто працює стабільніше й передбачуваніше, але й кабель може бути пошкоджений.</p>\n  <p style=\"margin:0 0 12px;\">Про безпеку кажуть так: щоб під'єднатися до дротової мережі, потрібен доступ до кабелю чи розетки, тому її часто вважають безпечнішою. Але Wi-Fi-мережа з надійним паролем і шифруванням теж захищена. Головне — щоб мережу налаштував дорослий, який на цьому знається.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🌳 Сайт не відкривається: безпечні кроки</h2>\n  <p style=\"margin:0 0 12px;\">Коли щось не працює, хочеться натискати все підряд. Краще діяти за порядком — від найпростішого. <b>Налаштувань комп'ютера й роутера ми не змінюємо.</b></p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Подивись на значок мережі</b> на екрані. Є з'єднання, чи там хрестик або знак оклику?</li>\n    <li style=\"margin:8px 0;\"><b>Відкрий інший сайт.</b> Якщо він працює, з'єднання в порядку — проблема з першим сайтом або з його адресою.</li>\n    <li style=\"margin:8px 0;\"><b>Перевір адресу</b> і перезапусти вкладку чи браузер.</li>\n    <li style=\"margin:8px 0;\"><b>Якщо пристрій на кабелі</b> — лише подивись, чи кабель на місці. Не витягай його й нічого не лагодь.</li>\n    <li style=\"margin:8px 0;\"><b>Скажи дорослому:</b> учителю в класі або батькам удома. Розкажи, які кроки вже зроблено.</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚖️ Цифровий розрив</h2>\n  <p style=\"margin:0 0 12px;\">Не всі люди мають однакові можливості користуватися технологіями. Цю різницю називають <b>цифровим розривом (digital divide)</b>. Причиною буває не лише відсутність сигналу. Дослідники виділяють кілька <b>бар'єрів (barriers)</b>:</p>\n\n  <svg viewBox=\"0 0 860 300\" role=\"img\" aria-labelledby=\"g4u3b-t g4u3b-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u3b-t\">Шість бар'єрів цифрового розриву</title>\n    <desc id=\"g4u3b-d\">Вартість: пристрій і тариф коштують грошей. Впевненість: людина боїться щось зламати. Здоров'я: зір, слух чи рухи заважають користуватися пристроєм. Навчання: ніхто не показав, як. Довіра: людина не вірить сайтам і сервісам. Вибір: людина сама вирішує не користуватися.</desc>\n    <rect x=\"6\" y=\"10\" width=\"272\" height=\"132\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"142\" y=\"52\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">💰</text>\n    <text x=\"142\" y=\"86\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">Вартість</text>\n    <text x=\"142\" y=\"116\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">пристрій і тариф коштують</text>\n    <rect x=\"294\" y=\"10\" width=\"272\" height=\"132\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"430\" y=\"52\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">😟</text>\n    <text x=\"430\" y=\"86\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">Впевненість</text>\n    <text x=\"430\" y=\"116\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">страшно щось зламати</text>\n    <rect x=\"582\" y=\"10\" width=\"272\" height=\"132\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"718\" y=\"52\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">🩺</text>\n    <text x=\"718\" y=\"86\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">Здоров'я</text>\n    <text x=\"718\" y=\"116\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">зір, слух чи рухи заважають</text>\n    <rect x=\"6\" y=\"158\" width=\"272\" height=\"132\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"142\" y=\"200\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">🎓</text>\n    <text x=\"142\" y=\"234\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">Навчання</text>\n    <text x=\"142\" y=\"264\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">ніхто не показав, як</text>\n    <rect x=\"294\" y=\"158\" width=\"272\" height=\"132\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"430\" y=\"200\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">🤝</text>\n    <text x=\"430\" y=\"234\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">Довіра</text>\n    <text x=\"430\" y=\"264\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">не вірю сайтам і сервісам</text>\n    <rect x=\"582\" y=\"158\" width=\"272\" height=\"132\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"718\" y=\"200\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">🙅</text>\n    <text x=\"718\" y=\"234\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">Вибір</text>\n    <text x=\"718\" y=\"264\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">вирішую не користуватися</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Буває й так, що в селі чи районі просто немає зв'язку або часто зникає електрика. Тоді потрібні вишки, кабелі й генератори. Але навіть коли зв'язок є, людина може не мати грошей на планшет, соромитися попросити допомоги або не довіряти онлайн-сервісам.</p>\n  <p style=\"margin:0 0 12px;\">Отже, відповідь на питання уроку: цифровий розрив — це не лише техніка. Кожен бар'єр потребує свого рішення: десь допоможе безкоштовний комп'ютерний клас, десь — терпляче пояснення, а десь — пристрій з озвученням тексту.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Обери Wi-Fi чи Ethernet для кожної ситуації та поясни одним реченням:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>А.</b> Настільний комп'ютер стоїть біля мережевої розетки. На ньому пишуть важливий онлайн-тест.</li>\n    <li style=\"margin:8px 0;\"><b>Б.</b> Учні ходять із планшетами по класу й фотографують рослини.</li>\n    <li style=\"margin:8px 0;\"><b>В.</b> Ноутбук у дальній кімнаті, куди сигнал роутера доходить слабко.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Ситуація: сайт не відкривається, але значок Wi-Fi показує повний сигнал, а інші сайти працюють. Запиши, на якому кроці діагностики ти зупинишся і що зробиш далі.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Прочитай три історії. Для кожної назви бар'єр і запропонуй одну підтримку.</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 240px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\"><b>Історія 1.</b> «Я хочу малювати на планшеті, але він коштує більше, ніж може виділити моя родина».</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\"><b>Історія 2.</b> «У мене тремтять руки, тому мені важко влучати в дрібні кнопки й тримати мишку».</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0;\"><b>Історія 3.</b> «Бабуся має смартфон, але боїться натиснути щось не те, тому користується лише дзвінками».</p>\n    </div>\n  </div>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> А — Ethernet: пристрій нікуди не рухається, а тест потребує стабільного з'єднання. Б — Wi-Fi: потрібна свобода руху. В — Ethernet, якщо поруч є розетка; інакше Wi-Fi ближче до роутера. Правильні й інші відповіді, якщо причина пояснена.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Уже на кроці 2: інші сайти працюють, тож з'єднання в порядку. Далі — перевірити адресу, а якщо вона правильна, сказати дорослому: можливо, цей сервер тимчасово недоступний.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> 1 — вартість: шкільні пристрої, бібліотека. 2 — здоров'я: голосове введення, великі кнопки. 3 — впевненість: спокійно показати кілька кроків і дати спробувати самій.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Для Кроку 1 постав до кожної ситуації одне питання: <i>«Пристрій рухається чи стоїть на місці?»</i> Рухається — Wi-Fi. Стоїть поруч із розеткою — можна Ethernet.</p>\n    <p style=\"margin:10px 0 0;\">Для Кроку 3 вибери бар'єр зі слів: <b>вартість</b>, <b>здоров'я</b>, <b>впевненість</b>.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти розв'язуєш Крок 1 і Крок 3, а Крок 2 обговорюєш з учителем усно.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Офлайн-план.</b> Візьми одне шкільне завдання, яке зазвичай виконують онлайн. Придумай, як зробити його без Інтернету: наприклад, у Блокноті, Paint чи офлайн-версії Scratch. Потім назви, чого твій офлайн-варіант усе ж не дає.</p>\n    <p style=\"margin:10px 0 0;\"><b>Суперечка.</b> Мер пропонує купити ноутбук кожній родині в гірському селі, де немає стабільного зв'язку та електрики. Чи вирішить це проблему? Чого ще бракує? Запиши 2–3 речення.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>A new laptop does not remove every barrier.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Місія: Порятунок сервера:</b> застосуй безпечну послідовність діагностики та допоможи відновити шкільний сервіс.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/quizes/save_server/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;\">Розпочати місію ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u3-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке Ethernet?</label>\n    <select id=\"g4-u3-q1\" name=\"g4-u3-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Назва мідного дроту</option>\n      <option>Технологія дротової мережі</option>\n      <option>Сильний Wi-Fi-сигнал</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Технологія дротової мережі. Вона використовує кабель, але Ethernet — це не сам кабель, а правила й обладнання, за якими пристрої обмінюються даними.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u3-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Яке твердження точне?</label>\n    <select id=\"g4-u3-q2\" name=\"g4-u3-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Wi-Fi завжди небезпечний</option>\n      <option>Ethernet завжди має однакову швидкість</option>\n      <option>На Wi-Fi сильніше впливають стіни й відстань</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Третє. Слова «завжди» тут неточні: правильно налаштований Wi-Fi теж безпечний, а швидкість Ethernet теж може змінюватися.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u3-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. У школі немає вчителя, який показав би, як програмувати роботів. Який це бар'єр?</label>\n    <select id=\"g4-u3-q3\" name=\"g4-u3-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Вартість</option>\n      <option>Навчання</option>\n      <option>Власний вибір</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Навчання. Пристрої можуть бути, але без можливості навчитися ними користуватися розрив залишається.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Доступ — це не тільки кабель і сигнал, а ще й ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я обираю Wi-Fi чи Ethernet для трьох ситуацій і пояснюю вибір без слова «завжди».</li>\n      <li style=\"margin:8px 0;\">Я знаходжу, на якому кроці діагностики можна зупинитися.</li>\n      <li style=\"margin:8px 0;\">Я називаю бар'єр і підтримку для трьох історій.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> достатньо Кроків 1 і 3 за підказками з блоку «Потрібна допомога?».</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> записи до Кроків 1–3 у зошиті.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>wired / wireless</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">дротовий / бездротовий</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>Ethernet</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">технологія дротової мережі</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>troubleshoot</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">шукати причину несправності</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>digital divide</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">цифровий розрив</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>barrier</b></td><td style=\"padding:8px 10px;\">бар'єр, перешкода</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>Ethernet is usually more stable. Wi-Fi lets me move around. Cost can be a barrier.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-1-4","grade":4,"module":1,"number":4,"title":"Способи входу, цифрова ідентичність і захист облікового запису","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок4_Гра1_Детектив-паролів.html","title":"Детектив паролів","description":"сортування карток","data":{"id":"g4a","lesson":4,"tag":"ПАРОЛІ","icon":"🕵️","type":"sort","title":"Детектив паролів","file":"Урок4_Гра1_Детектив-паролів.html","conceptName":"надійний пароль","concept":"Надійний пароль довгий, непередбачуваний і єдиний для кожного акаунта. Довга фраза з кількох не пов'язаних слів краща за коротке слово. Усі паролі в грі — вигадані; своїх справжніх ніколи нікому не показуй.","skill":"оцінюю вигадані паролі й пояснюю, що робить пароль надійним","data":{"categories":[{"id":"weak","label":"🟥 Слабкий","hint":"слабкі паролі легко вгадати: короткі слова, імена, дати, «123456»"},{"id":"mid","label":"🟨 Середній","hint":"середній пароль важко вгадати, але важко й запам'ятати"},{"id":"strong","label":"🟩 Надійний","hint":"надійний — довга фраза з не пов'язаних слів"}],"items":[{"text":"1️⃣ 123456","cat":"weak","explain":"Слабкий. Це перший варіант, який перевіряють програми підбору."},{"text":"2️⃣ qwerty","cat":"weak","explain":"Слабкий. Це рядок клавіш — його вгадують миттєво."},{"text":"3️⃣ Elephant7","cat":"weak","explain":"Слабкий. Велика літера й цифра не рятують коротке словникове слово."},{"text":"4️⃣ Priya2016","cat":"weak","explain":"Слабкий. Ім'я й рік народження легко дізнатися."},{"text":"5️⃣ G8#pL2!zR9","cat":"mid","explain":"Середній. Вгадати важко, але й запам'ятати важко — такі паролі записують на папірці, а це новий ризик."},{"text":"6️⃣ Orbit-Lemon-Bridge-Cloud","cat":"strong","explain":"Надійний зразок: довгий, із не пов'язаних слів, легко запам'ятати. Але цей приклад уже всі бачили — для справжнього акаунта вигадуй власну фразу."},{"text":"7️⃣ Password","cat":"weak","explain":"Слабкий. Слово «пароль» англійською — одне з найпоширеніших."},{"text":"8️⃣ Sontse-Richka-Kamin-Voda","cat":"strong","explain":"Надійний зразок: чотири не пов'язані слова — довго підбирати, легко пам'ятати."},{"text":"9️⃣ Timko2015","cat":"weak","explain":"Слабкий. Ім'я та рік — це передбачувано."}]}},"after":{"index":4,"heading":"🧩 Що робить пароль надійним"}},{"path":"app/games/Урок4_Гра2_Як-увійти.html","title":"Як увійти?","description":"сценарний вибір","data":{"id":"g4b","lesson":4,"tag":"ВХІД","icon":"🔑","type":"quiz","title":"Як увійти?","file":"Урок4_Гра2_Як-увійти.html","conceptName":"способи входу","concept":"Пароль можна змінити, PIN легко запам'ятати, а біометрія швидка, але палець чи обличчя не заміниш. Жоден спосіб не найкращий завжди — обирають під ситуацію.","skill":"обираю спосіб входу для ситуації й називаю його недолік","data":{"questions":[{"q":"Твій особистий планшет удома. Що зручно й безпечно?","options":["Біометрія + запасний PIN","Пароль, записаний на папірці біля екрана","Узагалі без блокування"],"correct":0,"explain":"На своєму пристрої біометрія зручна, а запасний PIN виручить, якщо впізнавання не спрацює.","wrong":"Навіть удома пристрій блокують — і завжди потрібен запасний спосіб."},{"q":"Спільний комп'ютер у бібліотеці. Як увійти?","options":["Паролем, а наприкінці — вийти з акаунта","Налаштувати свій відбиток пальця","Попросити браузер запам'ятати пароль"],"correct":0,"explain":"На чужому пристрої біометрію не налаштовують і паролі не зберігають. Наприкінці — обов'язковий вихід.","wrong":"Чужий пристрій не повинен запам'ятовувати ні твій палець, ні твій пароль."},{"q":"Чому пристрої з біометрією все одно просять запасний PIN?","options":["Бо біометрія інколи не спрацьовує","Бо PIN працює швидше","Бо так вимагає кожна гра"],"correct":0,"explain":"У темряві камера може не впізнати обличчя. Тоді виручає запасний PIN.","wrong":"Згадай: що станеться, якщо впізнавання обличчя не спрацює в темряві?"},{"q":"Прийшло сповіщення: «Незнайомий вхід, Лондон, 22:42». Перший крок?","options":["Одразу сказати дорослому","Натиснути посилання в листі","Видалити сповіщення й забути"],"correct":0,"explain":"Перший крок — дорослий. Посилання в листі може бути підробленим, тому застосунок відкривають окремо.","wrong":"Лист може бути підробленим. Спочатку — дорослий."},{"q":"Друг просить пароль від твого ігрового акаунта «на один день».","options":["Ввічливо відмовити","Дати, бо це найкращий друг","Дати, а завтра змінити"],"correct":0,"explain":"Відмова — це правило, а не образа. Друг може ненароком увійти з ненадійного пристрою.","wrong":"Пароль знаєш лише ти та дорослі, які за тебе відповідають."},{"q":"Чому для кожного акаунта — свій пароль?","options":["Щоб витік одного пароля не відкрив інші акаунти","Щоб швидше входити","Бо так вимагає закон"],"correct":0,"explain":"Якщо пароль від гри хтось дізнається, пошта й шкільний акаунт залишаться захищеними.","wrong":"Уяви, що пароль від однієї гри хтось підгледів. Що далі?"},{"q":"Людина пише: «Я зі служби підтримки, назви код з SMS». Твоя дія?","options":["Не називати код і сказати дорослому","Назвати код, бо це підтримка","Назвати лише половину коду"],"correct":0,"explain":"Код для відновлення нікому не повідомляють — навіть тим, хто називається підтримкою.","wrong":"Код відновлення — це майже ключ від акаунта. Його не називають нікому."}]}},"after":{"index":2,"heading":"🔑 Три способи входу"}},{"path":"app/games/Урок4_Гра3_Незнайомий-вхід.html","title":"Незнайомий вхід: план дій","description":"послідовність кроків","data":{"id":"g4c","lesson":4,"tag":"ТРИВОГА","icon":"🚨","type":"order","title":"Незнайомий вхід: план дій","file":"Урок4_Гра3_Незнайомий-вхід.html","conceptName":"відновлення доступу","concept":"Якщо прийшло сповіщення про незнайомий вхід, панікувати не треба — треба діяти за планом разом із дорослим.","skill":"складаю план дій на випадок підозрілого входу","data":{"rounds":[{"title":"⚠️ Сповіщення «Це були ви?» — і це не ти","steps":["🗣️ Одразу скажи дорослому","🌐 Разом відкрийте сам застосунок, а не посилання з листа","❌ Відповідайте «Ні, це не я»","🔑 Разом змініть пароль на новий надійний"],"hint":"дорослий — на першому місці; посилання в листі може бути підробленим","explain":"Дорослий → власний застосунок → «Це не я» → новий пароль. Посиланням із листа не користуємося."},{"title":"🔑 Забуто пароль шкільного акаунта","steps":["🧑‍🏫 Скажи вчителю","🔄 Вчитель або адміністратор відновлює доступ","✨ Придумайте новий надійний пароль","🤐 Новий пароль нікому не передавай"],"hint":"шкільний акаунт відновлює не пошта, а людина в школі","explain":"Шкільний акаунт відновлюють учитель чи адміністратор. Новий пароль — лише для тебе й дорослих."}]}},"after":{"index":3,"heading":"🔄 Якщо доступ втрачено"}}],"legacyTitle":"Урок 4. Способи входу, цифрова ідентичність і захист облікового запису","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 4</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Способи входу, цифрова ідентичність і захист облікового запису</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Logon Methods, Digital Identity and Account Protection</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: чому різні способи входу підходять для різних ситуацій?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я порівнюю <b>password</b>, <b>PIN</b> і біометрію: що в кожного сильне, а що слабке.</li>\n      <li style=\"margin:6px 0;\">Я оцінюю вигадані паролі й пояснюю, що робить пароль надійним.</li>\n      <li style=\"margin:6px 0;\">Я знаю, що робити, коли приходить повідомлення про незнайомий вхід.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🪪 Акаунт і цифрова ідентичність</h2>\n  <p style=\"margin:0 0 12px;\">Шкільний кабінет, ігровий профіль, пошта — усе це <b>облікові записи (accounts)</b>. Разом вони утворюють твою <b>цифрову ідентичність (digital identity)</b>: те, як тебе бачать сервіси.</p>\n  <svg viewBox=\"0 0 860 200\" role=\"img\" aria-labelledby=\"g4u4a-t g4u4a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u4a-t\">Чотири складові облікового запису</title>\n    <desc id=\"g4u4a-d\">Логін показує, хто ти для сервісу. Спосіб входу доводить, що це справді ти. Дозволи визначають, що сервіс може про тебе знати. Історія дій показує, що вже відбувалося в акаунті.</desc>\n    <rect x=\"6\" y=\"14\" width=\"206\" height=\"172\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"109\" y=\"62\" text-anchor=\"middle\" font-size=\"30\" font-family=\"Arial, sans-serif\">🪪</text>\n    <text x=\"109\" y=\"98\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">Логін</text>\n    <text x=\"109\" y=\"132\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">хто ти</text>\n    <text x=\"109\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">для сервісу</text>\n    <rect x=\"224\" y=\"14\" width=\"206\" height=\"172\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n    <text x=\"327\" y=\"62\" text-anchor=\"middle\" font-size=\"30\" font-family=\"Arial, sans-serif\">🔐</text>\n    <text x=\"327\" y=\"98\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">Спосіб входу</text>\n    <text x=\"327\" y=\"132\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">доводить,</text>\n    <text x=\"327\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">що це справді ти</text>\n    <rect x=\"442\" y=\"14\" width=\"206\" height=\"172\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"545\" y=\"62\" text-anchor=\"middle\" font-size=\"30\" font-family=\"Arial, sans-serif\">⚙️</text>\n    <text x=\"545\" y=\"98\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">Дозволи</text>\n    <text x=\"545\" y=\"132\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">що сервіс може</text>\n    <text x=\"545\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">про тебе знати</text>\n    <rect x=\"660\" y=\"14\" width=\"194\" height=\"172\" rx=\"12\" fill=\"#F0F4F8\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"757\" y=\"62\" text-anchor=\"middle\" font-size=\"30\" font-family=\"Arial, sans-serif\">🕘</text>\n    <text x=\"757\" y=\"98\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">Історія дій</text>\n    <text x=\"757\" y=\"132\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">що вже було</text>\n    <text x=\"757\" y=\"158\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">в акаунті</text>\n  </svg>\n  <p style=\"margin:0 0 12px;\">Щоб увійти (<b>log on</b>), треба довести сервісу, що це справді ти. Для цього існують різні способи входу — <b>logon methods</b>.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔑 Три способи входу</h2>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 240px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0 0 8px;font-weight:700;color:#0033A0;\">🔑 Пароль (password)</p>\n      <p style=\"margin:0 0 6px;\">✅ Можна змінити, якщо хтось дізнався.</p>\n      <p style=\"margin:0;\">⚠️ Можна забути, а короткий — вгадати.</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0 0 8px;font-weight:700;color:#0033A0;\">🔢 PIN-код</p>\n      <p style=\"margin:0 0 6px;\">✅ Швидко вводити, легко запам'ятати.</p>\n      <p style=\"margin:0;\">⚠️ Лише цифри, тож його легше підгледіти чи підібрати.</p>\n    </div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0 0 8px;font-weight:700;color:#0033A0;\">👤 Біометрія</p>\n      <p style=\"margin:0 0 6px;\">✅ Відбиток пальця чи обличчя (facial recognition): швидко й нічого не треба пам'ятати.</p>\n      <p style=\"margin:0;\">⚠️ Палець чи обличчя не заміниш, як пароль. Інколи не спрацьовує, тому потрібен запасний спосіб.</p>\n    </div>\n  </div>\n  <p style=\"margin:0 0 12px;\">Жоден спосіб не найкращий завжди. Для особистого планшета зручна біометрія. На спільному комп'ютері в класі її не налаштовують — там потрібен пароль. Тому різні платформи й пристрої використовують різні способи входу.</p>\n  <div style=\"background:#FFF2F2;border-left:5px solid #C0392B;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Правило безпеки.</b> Не завантажуй свої фото чи відбитки пальців у сторонні ігри, тести й застосунки. Біометрію налаштовують лише на своєму пристрої й разом із дорослим.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔄 Якщо доступ втрачено</h2>\n  <p style=\"margin:0 0 12px;\">Будь-який спосіб входу може підвести: пароль забувається, PIN блокується після кількох помилок, камера не впізнає обличчя в темряві. Тому в акаунтів є спосіб відновити доступ (recovery).</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Шкільний акаунт відновлює вчитель або адміністратор школи.</li>\n    <li style=\"margin:8px 0;\">Особистий акаунт — через пошту чи телефон батьків, які вказали під час реєстрації.</li>\n    <li style=\"margin:8px 0;\">Пристрій із біометрією просить запасний PIN або пароль.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Код для відновлення нікому не повідомляють, навіть якщо людина пише, що вона «зі служби підтримки».</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Що робить пароль надійним</h2>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Довжина.</b> Довга фраза з кількох не пов'язаних слів краща за коротке слово.</li>\n    <li style=\"margin:8px 0;\"><b>Унікальність.</b> Для кожного акаунта — свій пароль. Тоді витік одного не відкриє решту.</li>\n    <li style=\"margin:8px 0;\"><b>Непередбачуваність.</b> Жодних імен, дат народження, кличок улюбленців чи «qwerty».</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">І головне: пароль знаєш лише ти та дорослі, які за тебе відповідають. Навіть найкращому другові його не передають.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🕵️ Спробуй: детектив паролів</h2>\n  <p style=\"margin:0 0 12px;\">Ці паролі придумали вигадані користувачі. Для кожного запиши в зошиті: <b>слабкий</b>, <b>середній</b> чи <b>надійний</b> — і чому. Лише потім відкривай «Звірити».</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 230px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;font-size:18px;font-weight:700;\">1. 123456</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;font-size:18px;font-weight:700;\">2. Elephant7</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;font-size:18px;font-weight:700;\">3. Priya2016</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;font-size:18px;font-weight:700;\">4. G8#pL2!zR9</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;font-size:18px;font-weight:700;\">5. Orbit-Lemon-Bridge-Cloud</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;font-size:18px;font-weight:700;\">6. Password</p></div>\n  </div>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>1 і 6 — слабкі.</b> Це одні з перших варіантів, які перевіряють програми підбору.</p>\n    <p style=\"margin:10px 0 0;\"><b>2 — слабкий.</b> Велика літера й цифра не рятують коротке словникове слово.</p>\n    <p style=\"margin:10px 0 0;\"><b>3 — слабкий.</b> Ім'я й рік народження легко дізнатися.</p>\n    <p style=\"margin:10px 0 0;\"><b>4 — середній.</b> Його важко вгадати, але так само важко запам'ятати. Такі паролі часто записують на папірці, а це новий ризик.</p>\n    <p style=\"margin:10px 0 0;\"><b>5 — надійний.</b> Довгий, із не пов'язаних слів, його легко запам'ятати. Але цей приклад уже всі бачили, тож для справжнього акаунта він не годиться.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Для кожної ситуації обери спосіб входу і допиши, з яким недоліком ти погоджуєшся.</p>\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:480px;font-size:16px;\">\n      <thead><tr>\n        <th style=\"text-align:left;padding:10px 12px;border-bottom:2px solid #D9E2F0;background:#F0F4F8;\">Ситуація</th>\n        <th style=\"text-align:left;padding:10px 12px;border-bottom:2px solid #D9E2F0;background:#F0F4F8;width:42%;\">Мій вибір і недолік</th>\n      </tr></thead>\n      <tbody>\n        <tr><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">1. Шкільний акаунт, у який входиш із різних комп'ютерів класу</td><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">______________</td></tr>\n        <tr><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">2. Твій особистий планшет удома</td><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">______________</td></tr>\n        <tr><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">3. Ігровий акаунт, де зберігається прогрес</td><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">______________</td></tr>\n        <tr><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">4. Спільний комп'ютер у бібліотеці</td><td style=\"padding:10px 12px;border-bottom:1px solid #EDF1F8;\">______________</td></tr>\n        <tr><td style=\"padding:10px 12px;\">5. Телефон батьків, на якому є банківський застосунок</td><td style=\"padding:10px 12px;\">______________</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Вигадана гра-головоломка «Smart Blocks» просить дозволи (<b>permissions</b>): мікрофон, збереження файлів, точну геолокацію. Для кожного запиши «дозволити» чи «відхилити» і чому.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Вигаданому гравцеві приходить таке сповіщення. Склади план із трьох кроків.</p>\n  <div style=\"background:#FFF2F2;border:2px solid #C0392B;border-radius:10px;padding:14px 16px;margin:12px 0 16px;font-family:'Courier New',monospace;\">\n    <p style=\"margin:0 0 6px;font-weight:700;\">⚠️ Suspicious login — незнайомий вхід</p>\n    <p style=\"margin:0;\">Акаунт: andriy_super_gamer<br>Пристрій: Windows PC, Chrome<br>Місце: Лондон, 22:42<br>Це були ви?</p>\n  </div>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> 1 — довга унікальна парольна фраза: біометрія на чужих комп'ютерах не працює, а наприкінці уроку треба вийти з акаунта. 2 — біометрія або PIN, плюс запасний PIN. 3 — окремий пароль, не такий, як в інших акаунтах. 4 — пароль і обов'язковий вихід з акаунта; нічого не зберігати в браузері. 5 — вирішують дорослі; часто поєднують кілька способів. Інші відповіді теж правильні, якщо пояснено недолік.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Мікрофон — відхилити: головоломці він не потрібен. Збереження файлів — можна дозволити, якщо гра зберігає прогрес на пристрої. Геолокацію — відхилити: грі не треба знати, де ти живеш.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> 1) Одразу сказати дорослому. 2) Разом відкрити сам застосунок чи сайт і відповісти «Ні, це не я» — не за посиланням із листа, бо сповіщення буває підробленим. 3) З дорослим змінити пароль.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">У Кроці 1 виконай лише ситуації 1, 2 і 4. До кожної постав два питання:</p>\n    <ul style=\"margin:10px 0 0;padding-left:22px;\">\n      <li style=\"margin:5px 0;\">Це мій пристрій чи ним користуються інші?</li>\n      <li style=\"margin:5px 0;\">Що буде, якщо хтось чужий увійде?</li>\n    </ul>\n    <p style=\"margin:10px 0 0;\">Для Кроку 3 досить одного правильного першого кроку. Жодних справжніх паролів не записуй.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">У кожного способу входу є ще одна властивість: що станеться, якщо його <b>втратити</b>.</p>\n    <p style=\"margin:10px 0 0;\">Пароль можна забути і відновити. А обличчя чи палець змінити неможливо, якщо їхні дані колись витечуть.</p>\n    <p style=\"margin:10px 0 0;\">Порівняй пароль, PIN і біометрію за трьома ознаками: зручність, приватність і відновлення доступу. Чому майже кожен пристрій із біометрією все одно просить запасний PIN?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>A password can be changed. A fingerprint cannot.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Кібербезпека для дітей:</b> закріпи правила захисту облікового запису. Не вводь у тренажері жодного свого реального пароля.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/security_and_safety/cybersecurity_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;\">Відкрити урок із кібербезпеки ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u4-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Друг просить пароль від твого ігрового акаунта «на один день». Що робити?</label>\n    <select id=\"g4-u4-q1\" name=\"g4-u4-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Дати, бо це найкращий друг</option>\n      <option>Ввічливо відмовити</option>\n      <option>Дати, а завтра змінити пароль</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Ввічливо відмовити. Друг може ненароком увійти з ненадійного пристрою або записати пароль, і тоді акаунт можуть украсти. Відмова — це не образа, а правило.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u4-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Яка слабка сторона входу за обличчям?</label>\n    <select id=\"g4-u4-q2\" name=\"g4-u4-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Обличчя не можна замінити, як пароль</option>\n      <option>Його треба довго вводити</option>\n      <option>Воно працює лише в Інтернеті</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Обличчя не можна замінити. Тому біометрію тримають лише на своєму пристрої й завжди мають запасний спосіб входу.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u4-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чому для кожного акаунта потрібен свій пароль?</label>\n    <select id=\"g4-u4-q3\" name=\"g4-u4-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Так вимагає закон</option>\n      <option>Щоб витік одного пароля не відкрив інші акаунти</option>\n      <option>Щоб швидше входити</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб витік одного пароля не відкрив інші. Якщо пароль від гри хтось дізнається, пошта й шкільний акаунт залишаться захищеними.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку на прикладі однієї ситуації з Кроку 1:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Для цього акаунта я обираю ___, бо ___, але пам'ятаю, що ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я обираю спосіб входу щонайменше в чотирьох ситуаціях і називаю недолік.</li>\n      <li style=\"margin:8px 0;\">Я пояснюю, що робить пароль надійним, на прикладах із детектива паролів.</li>\n      <li style=\"margin:8px 0;\">Мій план на незнайомий вхід починається з дорослого.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> три ситуації з Кроку 1 і перший крок плану.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> заповнену таблицю, рішення про дозволи й план у зошиті. Жодного справжнього пароля.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>log on</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">увійти в систему</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>account</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">обліковий запис</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>password / PIN</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">пароль / PIN-код</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>facial recognition</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">розпізнавання обличчя</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>permission</b></td><td style=\"padding:8px 10px;\">дозвіл</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>A long password keeps my account secure. Facial recognition is fast, but I need a backup PIN.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-1-5","grade":4,"module":1,"number":5,"title":"«Безкоштовні» сервіси, cookies і збирання даних","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок5_Гра1_Три-види-cookies.html","title":"Три види cookies","description":"сортування карток","data":{"id":"g5a","lesson":5,"tag":"ПЕЧИВО","icon":"🍪","type":"sort","title":"Три види cookies","file":"Урок5_Гра1_Три-види-cookies.html","conceptName":"cookies","concept":"Cookies — невеликі файли даних, які сайт зберігає у браузері. Це не програми й не віруси, а лише записи. Важливо, хто і навіщо їх читає.","skill":"розрізняю обов'язкові, налаштувальні й рекламні cookies","data":{"categories":[{"id":"ess","label":"🔧 Обов'язкові","hint":"без них сайт відкриється, але не впізнає тебе: вхід, кошик, сесія"},{"id":"pref","label":"🎛️ Налаштувальні","hint":"вони пам'ятають твої вибори: мову, тему, розмір тексту"},{"id":"ads","label":"📢 Рекламні","hint":"вони стежать за інтересами, а без них сайт працює як звичайно"}],"items":[{"text":"🔑 Пам'ятає, що ти вже увійшов у кабінет","cat":"ess","explain":"Вхід — це обов'язкові cookies. Без них довелося б входити на кожній сторінці."},{"text":"🗣️ Пам'ятає обрану тобою мову сайту","cat":"pref","explain":"Мова — це твій вибір, його зберігають налаштувальні cookies."},{"text":"👟 Показує рекламу кросівок після того, як ти їх шукав","cat":"ads","explain":"Це рекламні cookies: вони запам'ятовують інтереси."},{"text":"🛒 Тримає товари в кошику, поки ти гуляєш сайтом","cat":"ess","explain":"Кошик — обов'язкові cookies. Без них кошик щоразу спорожняв би."},{"text":"🌙 Запам'ятовує темну тему","cat":"pref","explain":"Тема оформлення — вибір користувача, тож це налаштувальні cookies."},{"text":"👀 Передає рекламодавцям, які сайти ти відвідуєш","cat":"ads","explain":"Це рекламні cookies. Такі можна відхилити — сайт працюватиме як звичайно."},{"text":"🔁 Не «забуває» тебе між сторінками під час сесії","cat":"ess","explain":"Сесія — обов'язкові cookies."},{"text":"🔠 Зберігає обраний розмір тексту","cat":"pref","explain":"Розмір тексту — налаштування, його пам'ятають налаштувальні cookies."},{"text":"🎯 Допомагає показувати рекламу «під тебе» на інших сайтах","cat":"ads","explain":"Це робота рекламних cookies — їх можна відхилити."}]}},"after":{"index":2,"heading":"🍪 Що таке cookie"}},{"path":"app/games/Урок5_Гра2_Що-дати-грі.html","title":"Що дати грі?","description":"сценарний вибір","data":{"id":"g5b","lesson":5,"tag":"ДАНІ","icon":"🛡️","type":"quiz","title":"Що дати грі?","file":"Урок5_Гра2_Що-дати-грі.html","conceptName":"мінімізація даних","concept":"Давай сервісу лише те, без чого він не може працювати. Питай себе: «Що зламається, якщо я це відхилю?» Якщо нічого — це зайве.","skill":"вирішую, якими даними поділитися, а які відхилити","data":{"questions":[{"q":"Гра-головоломка «Dino-Run 3D» просить доступ до мікрофона.","options":["Відхилити: головоломці мікрофон не потрібен","Дозволити: раптом захочеться поговорити з динозавром","Дозволити, якщо гра безкоштовна"],"correct":0,"explain":"Якщо відхилити — нічого в грі не зламається. Отже, доступ зайвий.","wrong":"Постав питання: «Що зламається, якщо я це відхилю?»"},{"q":"Та сама гра просить дозвіл зберігати файли, щоб пам'ятати твій прогрес.","options":["Можна дозволити: прогрес зберігається у файлі","Відхилити: файли — це завжди небезпечно","Дозволити, але ще й надіслати фото"],"correct":0,"explain":"Це потрібно для роботи гри — прогрес треба десь зберігати.","wrong":"Без цього дозволу гра не запам'ятає прогрес — отже, він потрібен."},{"q":"Гра просить твою точну геолокацію.","options":["Відхилити: грі не треба знати, де ти живеш","Дозволити: так гра стане цікавішою","Дозволити, якщо вдома"],"correct":0,"explain":"Геолокація для гри не потрібна — це зайві дані про тебе.","wrong":"Цікавість — не привід ділитися адресою."},{"q":"Гра просить придумати нікнейм гравця.","options":["Дозволити: вигадане ім'я — нормально","Написати справжнє ім'я й прізвище","Написати ім'я й адресу"],"correct":0,"explain":"Нікнейм — це вигадане ім'я. Справжні ім'я, адресу й телефон іграм не потрібні.","wrong":"У грі працює правило: вигадане ім'я — так, справжні дані — ні."},{"q":"Гра просить номер телефону батьків «для подарунків».","options":["Відхилити: телефон для гри не потрібен","Дозволити: подарунки — це добре","Дати номер сусіда"],"correct":0,"explain":"Телефон батьків — особисті дані. Жодній грі він не потрібен.","wrong":"«Подарунки» — частий привід випросити дані."},{"q":"Банер сайту: величезна яскрава кнопка «ПРИЙНЯТИ ВСЕ» і дрібне сіре «налаштувати». Що тут не так?","options":["Банер підштовхує до одного вибору — це «темний шаблон»","Усе чесно: велика кнопка — найкраща","Сірий колір означає, що сайт зламаний"],"correct":0,"explain":"Такі прийоми дизайну називають dark patterns. Читай усі кнопки, а не лише найяскравішу.","wrong":"Яскравість кнопки не робить вибір кращим."},{"q":"Ти питаєш у чат-бота рецепт пирога. Чи варто додати свою адресу, щоб він «краще зрозумів»?","options":["Ні: запит може зберігатися, а адреса для рецепта не потрібна","Так: бот нікому не розповість","Так, якщо написати англійською"],"correct":0,"explain":"Деякі сервіси зберігають запити. Особисті дані в запит не додаємо.","wrong":"Для рецепта пирога адреса не потрібна."}]}},"after":{"index":2,"heading":"🍪 Що таке cookie"}}],"legacyTitle":"Урок 5. «Безкоштовні» сервіси, cookies і збирання даних","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 5</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">«Безкоштовні» сервіси, cookies і збирання даних</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">“Free” Services, Cookies and Data Collection</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: якщо гра безкоштовна — хто тоді платить за її створення?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я пояснюю, як «безкоштовний» сервіс може отримувати цінність.</li>\n      <li style=\"margin:6px 0;\">Я розрізняю <b>essential</b>, <b>preference</b> і <b>advertising cookies</b>.</li>\n      <li style=\"margin:6px 0;\">Я вирішую, якими даними поділитися, а які відхилити.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">💰 Хто платить за безкоштовне</h2>\n  <p style=\"margin:0 0 12px;\">Щоб зробити гру чи пошуковик, потрібні розробники, художники й сервери. Усе це коштує грошей. Якщо користувач нічого не платить, сервіс заробляє інакше:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Реклама (advertising).</b> Тобі показують оголошення, а рекламодавці платять сервісу.</li>\n    <li style=\"margin:8px 0;\"><b>Платне оновлення.</b> Основна версія безкоштовна, а за додаткові рівні чи гру без реклами просять заплатити.</li>\n    <li style=\"margin:8px 0;\"><b>Збирання даних (data collection).</b> Сервіс записує, що ти робиш і що тобі цікаво. Ці дані допомагають показувати рекламу «під тебе».</li>\n  </ul>\n\n  <svg viewBox=\"0 0 860 240\" role=\"img\" aria-labelledby=\"g4u5a-t g4u5a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u5a-t\">Як безкоштовна гра може заробляти</title>\n    <desc id=\"g4u5a-d\">Гравець грає безкоштовно, але дає сервісу свою увагу й дані про дії. Гра збирає ці дані й продає місце для реклами. Рекламодавці платять грі та показують гравцеві рекламу, дібрану під його інтереси. Стрілка від рекламодавців повертається до гравця.</desc>\n    <rect x=\"6\" y=\"20\" width=\"250\" height=\"120\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"131\" y=\"58\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">🎮 Гравець</text>\n    <text x=\"131\" y=\"90\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">грає безкоштовно,</text>\n    <text x=\"131\" y=\"112\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">дає увагу й дані</text>\n    <path d=\"M260 80 H292\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"292,72 305,80 292,88\" fill=\"#0033A0\"></polygon>\n    <rect x=\"308\" y=\"20\" width=\"244\" height=\"120\" rx=\"12\" fill=\"#0033A0\"></rect>\n    <text x=\"430\" y=\"58\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">📱 «Безкоштовна» гра</text>\n    <text x=\"430\" y=\"90\" text-anchor=\"middle\" font-size=\"15\" fill=\"#D6E0F5\" font-family=\"Arial, sans-serif\">збирає дані,</text>\n    <text x=\"430\" y=\"112\" text-anchor=\"middle\" font-size=\"15\" fill=\"#D6E0F5\" font-family=\"Arial, sans-serif\">продає місце для реклами</text>\n    <path d=\"M556 80 H588\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"588,72 601,80 588,88\" fill=\"#0033A0\"></polygon>\n    <rect x=\"604\" y=\"20\" width=\"250\" height=\"120\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"729\" y=\"58\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">📢 Рекламодавці</text>\n    <text x=\"729\" y=\"90\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">платять грі за</text>\n    <text x=\"729\" y=\"112\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">показ реклами</text>\n    <path d=\"M729 144 V196 H131 V156\" fill=\"none\" stroke=\"#B38600\" stroke-width=\"3\" stroke-dasharray=\"8 6\"></path>\n    <polygon points=\"123,158 131,144 139,158\" fill=\"#B38600\"></polygon>\n    <text x=\"430\" y=\"226\" text-anchor=\"middle\" font-size=\"15\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">реклама, дібрана під інтереси гравця</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Так працюють не всі сервіси. Деякі безкоштовні програми фінансують школи, благодійні організації чи держава. Але якщо про гроші ніде не сказано, варто спитати себе: <i>як цей сервіс отримує цінність?</i> Навіть платні застосунки можуть збирати дані, тому дізнаватися, що саме збирається, корисно завжди.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🍪 Що таке cookie</h2>\n  <p style=\"margin:0 0 12px;\">Уяви парк розваг. На вході тобі дають браслет, і на кожному атракціоні на ньому ставлять позначку. Увечері працівник подивиться на браслет і скаже, що тобі сподобалося.</p>\n  <p style=\"margin:0 0 12px;\">На сайтах роль такого браслета виконують <b>cookies</b> — невеликі файли даних, які сайт зберігає у твоєму браузері. Вони пам'ятають, що ти робиш на сайті. Cookies — не програми й не віруси, а лише записи з даними. Важливо інше: хто і навіщо їх читає. Тому не всі cookies однакові — різниця в тому, навіщо вони потрібні.</p>\n\n  <svg viewBox=\"0 0 860 210\" role=\"img\" aria-labelledby=\"g4u5b-t g4u5b-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u5b-t\">Обов'язкові, налаштувальні та рекламні cookies</title>\n    <desc id=\"g4u5b-d\">Обов'язкові cookies потрібні для входу, кошика й сесії: без них сайт відкриється, але не впізнає тебе. Налаштувальні пам'ятають мову й тему — без них доведеться щоразу обирати заново. Рекламні стежать за інтересами, і без них сайт працює як звичайно.</desc>\n    <rect x=\"6\" y=\"14\" width=\"276\" height=\"182\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n    <text x=\"144\" y=\"56\" text-anchor=\"middle\" font-size=\"28\" font-family=\"Arial, sans-serif\">🔧</text>\n    <text x=\"144\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">Обов'язкові</text>\n    <text x=\"144\" y=\"120\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Вхід, кошик, сесія</text>\n    <text x=\"144\" y=\"150\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Без них сайт відкриється,</text>\n    <text x=\"144\" y=\"172\" text-anchor=\"middle\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">але не впізнає тебе</text>\n    <rect x=\"292\" y=\"14\" width=\"276\" height=\"182\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"430\" y=\"56\" text-anchor=\"middle\" font-size=\"28\" font-family=\"Arial, sans-serif\">🎛️</text>\n    <text x=\"430\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">Налаштувальні</text>\n    <text x=\"430\" y=\"120\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Мова, тема, розмір</text>\n    <text x=\"430\" y=\"150\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Без них обиратимеш</text>\n    <text x=\"430\" y=\"172\" text-anchor=\"middle\" font-size=\"15\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">щоразу заново</text>\n    <rect x=\"578\" y=\"14\" width=\"276\" height=\"182\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"716\" y=\"56\" text-anchor=\"middle\" font-size=\"28\" font-family=\"Arial, sans-serif\">📢</text>\n    <text x=\"716\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">Рекламні</text>\n    <text x=\"716\" y=\"120\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Стежать за інтересами</text>\n    <text x=\"716\" y=\"150\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">Без них сайт</text>\n    <text x=\"716\" y=\"172\" text-anchor=\"middle\" font-size=\"15\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">працює як звичайно</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Коли ти вперше заходиш на сайт, часто з'являється <b>банер згоди</b>. Ти вирішуєш, які cookies дозволити. Обов'язкові вимкнути не можна, а інші — можна. Деякі банери навмисно роблять один вибір помітнішим або заплутують відмову, тому читай усі кнопки, а не лише найяскравішу.</p>\n  <p style=\"margin:0 0 8px;\">Три питання до будь-якого банера:</p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\">Яка кнопка дозволяє лише обов'язкові cookies?</li>\n    <li style=\"margin:6px 0;\">Для чого сайт просить інші cookies — чи це пояснено зрозуміло?</li>\n    <li style=\"margin:6px 0;\">Чи можна змінити вибір пізніше?</li>\n  </ol>\n  <p style=\"margin:0 0 12px;\">Згоду справді можна змінити: у налаштуваннях сайту або браузера. Попроси дорослого показати, де це робиться на твоєму пристрої.</p>\n\n  <div style=\"background:#FFF2F2;border-left:5px solid #C0392B;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Сервіси ШІ.</b> Деякі чат-боти можуть обробляти або зберігати запити — це залежить від сервісу та налаштувань. Тому не пиши туди свого імені, адреси, паролів і секретів. На уроках ми користуємося лише вигаданими запитами та акаунтом учителя.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Прочитай банер вигаданого сайту «Зоопарк онлайн». Для кожного виду cookies запиши: «дозволяю» чи «відхиляю» — і чому.</p>\n  <div style=\"background:#FFFFFF;border:2px solid #0033A0;border-radius:10px;padding:16px 18px;margin:12px 0 16px;\">\n    <p style=\"margin:0 0 10px;font-weight:700;\">🍪 «Зоопарк онлайн» використовує cookies</p>\n    <p style=\"margin:0 0 6px;\">🔧 <b>Обов'язкові</b> — щоб працював вхід у кабінет. <i>Завжди увімкнені.</i></p>\n    <p style=\"margin:0 0 6px;\">🎛️ <b>Налаштувальні</b> — щоб сайт пам'ятав мову й темну тему.</p>\n    <p style=\"margin:0 0 12px;\">📢 <b>Рекламні</b> — щоб показувати рекламу за твоїми інтересами на інших сайтах.</p>\n    <p style=\"margin:0;\"><span style=\"display:inline-block;background:#F0F4F8;border:1px solid #0033A0;border-radius:6px;padding:6px 12px;margin:0 6px 6px 0;\">Прийняти все</span><span style=\"display:inline-block;background:#F0F4F8;border:1px solid #0033A0;border-radius:6px;padding:6px 12px;margin:0 6px 6px 0;\">Лише обов'язкові</span><span style=\"display:inline-block;background:#F0F4F8;border:1px solid #0033A0;border-radius:6px;padding:6px 12px;margin:0 6px 6px 0;\">Налаштувати</span></p>\n  </div>\n  <p style=\"margin:0 0 12px;\">Для Кроку 2 знадобиться <b>правило мінімізації даних</b>: давай сервісу лише те, без чого він не може працювати.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Вигадана безкоштовна гра «Dino-Run 3D» просить ці дані. Для кожного запиши: «потрібно для гри» чи «зайве».</p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\">Вигадане ім'я гравця (нікнейм)</li>\n    <li style=\"margin:6px 0;\">Точна геолокація</li>\n    <li style=\"margin:6px 0;\">Номер телефону батьків</li>\n    <li style=\"margin:6px 0;\">Мова пристрою</li>\n    <li style=\"margin:6px 0;\">Історія відвідування інших сайтів</li>\n  </ol>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Запиши своє рішення двома реченнями: <i>«Я дозволяю ___, бо ___. Я відхиляю ___, бо ___»</i>.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Обов'язкові працюють завжди. Налаштувальні — на твій вибір: вони роблять сайт зручнішим. Рекламні можна відхилити: без них «Зоопарк онлайн» працює як звичайно. Найкоротший шлях — кнопка «Лише обов'язкові».</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Потрібні: нікнейм і мова пристрою. Зайві: геолокація, телефон батьків, історія інших сайтів. Грі, щоб запуститися, вони не потрібні.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">До кожного пункту постав одне питання: <i>«Що зламається, якщо я це відхилю?»</i></p>\n    <p style=\"margin:10px 0 0;\">Якщо нічого не зламається — пункт зайвий. Виконай Крок 2 лише для пунктів 1, 2 і 5 та запиши одне речення з Кроку 3.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Порівняй два банери вигаданих сайтів:</p>\n    <ul style=\"margin:10px 0 0;padding-left:22px;\">\n      <li style=\"margin:5px 0;\"><b>Банер А:</b> величезна яскрава кнопка «ПРИЙНЯТИ ВСЕ» і дрібне сіре посилання «налаштувати».</li>\n      <li style=\"margin:5px 0;\"><b>Банер Б:</b> кнопки «Прийняти все» і «Відхилити необов'язкові» однакового розміру й кольору.</li>\n    </ul>\n    <p style=\"margin:10px 0 0;\">Банер А підштовхує до одного вибору. Такі прийоми дизайну називають <b>dark patterns</b> — «темні шаблони».</p>\n    <p style=\"margin:10px 0 0;\">Ще один прийом — заплутаний текст: <i>«Я не хочу не погоджуватися на відмову від реклами»</i>. Порахуй заперечення. Перепиши обидві кнопки так, щоб вибір був чесним і зрозумілим.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>A fair banner gives equal choices.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\">Перевір, які дані справді потрібні сервісу, а які запити варто поставити під сумнів.</p>\n    <ul style=\"margin:0;padding-left:20px;line-height:1.55;\">\n      <li style=\"margin-bottom:8px;\"><a href=\"https://itnauka.org/services/security_and_safety/critical_thinking_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">Критичне мислення для дітей ↗</a> — розрізняй факти, переконування й приховані цілі повідомлень.</li>\n      <li><a href=\"https://beinternetawesome.withgoogle.com/en_us/interland/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">Interland: Mindful Mountain ↗</a> — потренуйся обирати, чим і з ким безпечно ділитися.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u5-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Гра безкоштовна. Що це означає?</label>\n    <select id=\"g4-u5-q1\" name=\"g4-u5-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Розробники нічого не отримують</option>\n      <option>Сервіс може отримувати цінність інакше, ніж грошима від гравця</option>\n      <option>Гра не збирає жодних даних</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Це може бути реклама, платні оновлення чи дані про гравців. А може — підтримка школи чи благодійників. Правила конкретного сервісу варто перевіряти.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u5-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Які cookies пам'ятають обрану тобою мову сайту?</label>\n    <select id=\"g4-u5-q2\" name=\"g4-u5-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Рекламні</option>\n      <option>Налаштувальні (preference)</option>\n      <option>Жодні, мову пам'ятає клавіатура</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Налаштувальні. Вони зберігають твої вибори на сайті — мову, тему, розмір тексту.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u5-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Ти питаєш у чат-бота рецепт пирога. Чи варто додати свою адресу, щоб він «краще зрозумів»?</label>\n    <select id=\"g4-u5-q3\" name=\"g4-u5-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Так, бот нікому не розповість</option>\n      <option>Ні, запит може зберігатися, а адреса для рецепта не потрібна</option>\n      <option>Так, якщо написати англійською</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Ні. Деякі сервіси можуть зберігати запити, а для рецепта адреса не потрібна. Особисті дані в запит не додаємо.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Безкоштовний сервіс може отримувати цінність через ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я пояснюю, навіщо потрібні щонайменше два види cookies.</li>\n      <li style=\"margin:8px 0;\">Я відхиляю явно зайві дані й пояснюю чому.</li>\n      <li style=\"margin:8px 0;\">Моє рішення про згоду записане двома реченнями.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> три пункти з Кроку 2 і одне речення рішення.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> записи до Кроків 1–3 у зошиті чи текстовому файлі.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>free service</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">безкоштовний сервіс</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>cookie</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">файл даних сайту в браузері</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>data collection</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">збирання даних</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>consent</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">згода</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>privacy</b></td><td style=\"padding:8px 10px;\">приватність</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>Essential cookies make the site work. I can say no to advertising cookies.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-1-6","grade":4,"module":1,"number":6,"title":"Цифрова комунікація: інструмент, аудиторія, етикет і добробут","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок6_Гра1_Обери-інструмент.html","title":"Обери інструмент","description":"сценарний вибір","data":{"id":"g6a","lesson":6,"tag":"ЛИСТ","icon":"📨","type":"quiz","title":"Обери інструмент","file":"Урок6_Гра1_Обери-інструмент.html","conceptName":"аудиторія й мета","concept":"Перед тим як писати, запитай себе: кому (audience)? навіщо (purpose)? чи терміново (urgent)? чи приватно (private)? Від відповідей залежить вибір інструмента.","skill":"обираю інструмент спілкування за аудиторією, метою, терміновістю й приватністю","data":{"questions":[{"q":"Треба швидко спитати в мами, чи можна після школи піти до друга.","options":["Чат або дзвінок","Лист email","Спільний документ"],"correct":0,"explain":"Відповідь потрібна зараз — це терміновість. Чат чи дзвінок найшвидші.","wrong":"Подумай про терміновість: відповідь потрібна зараз чи може зачекати?"},{"q":"Група з чотирьох учнів пише одну спільну казку.","options":["Спільний документ","Чотири окремі листи","Голосові повідомлення"],"correct":0,"explain":"Мета — працювати над одним текстом разом. У спільному документі видно, хто що змінив.","wrong":"Тут мета — редагувати один текст усією групою."},{"q":"Потрібно надіслати вчителю виконану роботу.","options":["Email або шкільна платформа","Загальний чат класу","Коментар під відео"],"correct":0,"explain":"Аудиторія — учитель, і лист лишає запис. Загальний чат бачать усі.","wrong":"Подумай про аудиторію: кому призначене повідомлення?"},{"q":"Однокласник не розуміє, як пройти рівень у навчальній грі, і просить показати.","options":["Відеодзвінок із показом екрана (якщо дозволили дорослі)","Довгий лист із описом","Сто повідомлень у чаті"],"correct":0,"explain":"Мета — показати. На відеодзвінку видно екран і чути пояснення.","wrong":"Словами показати рухи на екрані важко. Що допоможе побачити?"},{"q":"Увечері тобі сумно, і хочеться, щоб хтось підтримав.","options":["Поговорити з рідними чи другом","Написати чат-боту","Написати в загальний чат"],"correct":0,"explain":"Чат-бот — програма без почуттів, він не друг. Справжня підтримка — у людей, яким довіряєш.","wrong":"Чат-бот відповідає дружньо, але не має почуттів і не знає твого життя."},{"q":"Треба домовитися з учителем про перездачу.","options":["Лист або повідомлення в шкільній платформі","Загальний чат класу","Голосове о десятій вечора"],"correct":0,"explain":"Питання особисте й не термінове, аудиторія — учитель. Лист лишає запис.","wrong":"Це особисте питання для однієї людини — і воно не термінове."}]}},"after":{"index":1,"heading":"📨 Як обрати інструмент"}},{"path":"app/games/Урок6_Гра2_Перепиши-ввічливо.html","title":"Перепиши ввічливо","description":"сценарний вибір","data":{"id":"g6b","lesson":6,"tag":"ПОВАГА","icon":"💬","type":"quiz","title":"Перепиши ввічливо","file":"Урок6_Гра2_Перепиши-ввічливо.html","conceptName":"мережевий етикет","concept":"У тексті не видно усмішки й не чути тону, тому жарт легко прочитати як образу. Перед надсиланням перечитай повідомлення очима того, хто його отримає.","skill":"переписую неповажне повідомлення так, щоб воно стало ввічливим","data":{"questions":[{"q":"У чаті: «ЧОМУ ТИ НЕ ВІДПОВІДАЄШ??? ШВИДКО СКИНЬ СВОЮ ЧАСТИНУ ПРОЄКТУ!!!» Як переписати?","options":["«Привіт! Коли матимеш час, надішли, будь ласка, свою частину проєкту. Дякую!»","«СКИНЬ СЬОГОДНІ, А ТО ВИЙДУ З ГРУПИ!»","«Ну нарешті, я чекаю вже сто років…»"],"correct":0,"explain":"Без крику (великі літери = крик), з «будь ласка» й без тиску — так повідомлення працює краще.","wrong":"Прибери крик, тиск і докори. Додай «будь ласка» й «дякую»."},{"q":"У чаті: «Твоя хата в грі жахлива, видали її і не ганьбися!» Як переписати?","options":["«Видно, скільки праці в цій хаті. Може, разом придумаємо інший дах?»","«Хата так собі, але хай буде»","«Усі кажуть, що хата дивна»"],"correct":0,"explain":"Пропозиція допомоги замість образи — це повага. «Усі кажуть» — це натяк на чутки.","wrong":"Знайди варіант, де є пошана до чужої праці й пропозиція допомоги."},{"q":"Пишеш листа вчителю. Яке звертання правильне?","options":["«Доброго дня, Олено Петрівно!»","«Прив»","«Ей, вчителько»"],"correct":0,"explain":"Учителеві пишемо ввічливо: привітання на ім'я та по батькові, повні речення, подяка наприкінці.","wrong":"Учитель — це аудиторія, якій пишуть офіційно."},{"q":"Чому не варто писати ВЕЛИКИМИ ЛІТЕРАМИ?","options":["Читач сприймає це як крик","Це витрачає більше заряду батареї","Сервер видаляє такі повідомлення"],"correct":0,"explain":"Великі літери читаються як крик і тиск, навіть якщо автор так не думав.","wrong":"Подумай, як це звучить для того, хто читає."},{"q":"Тебе образили в груповому чаті. Що робити?","options":["Зберегти повідомлення, заблокувати кривдника й розповісти дорослому","Відповісти такою само образою","Видалити все й мовчати"],"correct":0,"explain":"Образою на образу відповідати не можна. Збережи доказ, заблокуй і розкажи дорослому.","wrong":"Відповідь образою лише розпалить суперечку. Дорослий допоможе."}]}},"after":{"index":2,"heading":"💬 Повага онлайн"}}],"legacyTitle":"Урок 6. Цифрова комунікація: інструмент, аудиторія, етикет і добробут","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 6</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Цифрова комунікація: інструмент, аудиторія, етикет і добробут</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Digital Communication: Tool, Audience, Etiquette and Wellbeing</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: та сама фраза комусь жарт, а комусь образа. Хто вирішує?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я обираю інструмент спілкування за <b>audience</b>, <b>purpose</b>, терміновістю й приватністю.</li>\n      <li style=\"margin:6px 0;\">Я переписую неповажне повідомлення так, щоб воно стало <b>respectful</b> — ввічливим і зрозумілим.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📨 Як обрати інструмент</h2>\n  <p style=\"margin:0 0 12px;\">Повідомлення можна надіслати листом, у чаті, сказати під час відеодзвінка чи написати у спільному документі. Щоб обрати, постав собі кілька питань:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">👥 <b>Аудиторія (audience).</b> Кому я пишу? Учителеві — інакше, ніж другові.</li>\n    <li style=\"margin:8px 0;\">🎯 <b>Мета (purpose).</b> Що я хочу: запитати, домовитися, показати, працювати разом?</li>\n    <li style=\"margin:8px 0;\">⚡ <b>Терміновість (urgent).</b> Відповідь потрібна зараз чи може зачекати до завтра?</li>\n    <li style=\"margin:8px 0;\">🔒 <b>Приватність (private).</b> Чи можуть це бачити інші? Особисте не пишуть у загальний чат класу.</li>\n    <li style=\"margin:8px 0;\">♿ <b>Доступність.</b> Чи зручно цей формат людині? Хтось краще сприймає голос, а хтось — текст із субтитрами.</li>\n  </ul>\n\n  <svg viewBox=\"0 0 860 210\" role=\"img\" aria-labelledby=\"g4u6a-t g4u6a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u6a-t\">Чотири інструменти спілкування та їхні задачі</title>\n    <desc id=\"g4u6a-d\">Email підходить для офіційного звернення до дорослого, бо лишає запис. Чат — для короткого швидкого питання, але його легко зрозуміти не так. Відеодзвінок — коли тема складна й потрібні обличчя та тон голосу. Спільний документ — коли кілька людей працюють над одним текстом і видно, хто що змінив.</desc>\n    <rect x=\"6\" y=\"14\" width=\"206\" height=\"182\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"109\" y=\"58\" text-anchor=\"middle\" font-size=\"28\" font-family=\"Arial, sans-serif\">✉️</text>\n    <text x=\"109\" y=\"92\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">Email</text>\n    <text x=\"109\" y=\"124\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">офіційно, до</text>\n    <text x=\"109\" y=\"146\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">дорослого</text>\n    <text x=\"109\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">лишає запис</text>\n    <rect x=\"224\" y=\"14\" width=\"206\" height=\"182\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"327\" y=\"58\" text-anchor=\"middle\" font-size=\"28\" font-family=\"Arial, sans-serif\">💬</text>\n    <text x=\"327\" y=\"92\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">Чат</text>\n    <text x=\"327\" y=\"124\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">коротке</text>\n    <text x=\"327\" y=\"146\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">швидке питання</text>\n    <text x=\"327\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">легко зрозуміти не так</text>\n    <rect x=\"442\" y=\"14\" width=\"206\" height=\"182\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n    <text x=\"545\" y=\"58\" text-anchor=\"middle\" font-size=\"28\" font-family=\"Arial, sans-serif\">📹</text>\n    <text x=\"545\" y=\"92\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">Відеодзвінок</text>\n    <text x=\"545\" y=\"124\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">складна тема,</text>\n    <text x=\"545\" y=\"146\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">потрібні емоції</text>\n    <text x=\"545\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">видно обличчя й тон</text>\n    <rect x=\"660\" y=\"14\" width=\"194\" height=\"182\" rx=\"12\" fill=\"#F0F4F8\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"757\" y=\"58\" text-anchor=\"middle\" font-size=\"28\" font-family=\"Arial, sans-serif\">📄</text>\n    <text x=\"757\" y=\"92\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">Спільний документ</text>\n    <text x=\"757\" y=\"124\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">кілька людей</text>\n    <text x=\"757\" y=\"146\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">над одним текстом</text>\n    <text x=\"757\" y=\"176\" text-anchor=\"middle\" font-size=\"15\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">видно, хто що змінив</text>\n  </svg>\n  <p style=\"margin:0 0 12px;\">Важить і те, як писати. У чаті з другом можна коротко, а вчителеві навіть у чаті краще писати повними реченнями, з привітанням і подякою.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">💬 Повага онлайн</h2>\n  <p style=\"margin:0 0 12px;\">Слова на екрані діють на людей так само сильно, як сказані вголос. Тому повага (<b>respect</b>) онлайн важить стільки ж, скільки під час розмови віч-на-віч. І так само важливо, щоб поважали тебе.</p>\n  <p style=\"margin:0 0 12px;\">У тексті не видно усмішки й не чути тону. Через це жарт легко прочитати як образу. Правила мережевого етикету (<b>online etiquette</b>) допомагають уникнути непорозумінь:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Не пиши ВЕЛИКИМИ ЛІТЕРАМИ: читач сприймає це як крик.</li>\n    <li style=\"margin:8px 0;\">Не поширюй чуток і не пиши образ — навіть «для сміху».</li>\n    <li style=\"margin:8px 0;\">Якщо образили тебе, не відповідай образою: збережи повідомлення, заблокуй кривдника й розкажи дорослому.</li>\n    <li style=\"margin:8px 0;\">Перед тим як натиснути «Надіслати», зроби паузу й перечитай повідомлення очима того, хто його отримає.</li>\n  </ul>\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">То хто вирішує, жарт це чи образа?</p>\n    <p style=\"margin:0;\">Намір автора важливий. Але важить і те, як повідомлення сприйняла інша людина. Якщо їй стало боляче, варто вибачитися, навіть якщо це був жарт. Сумніваєшся — переформулюй з повагою ще до надсилання.</p>\n  </div>\n  <p style=\"margin:0 0 12px;\">І ще одне: чат-бот зі штучним інтелектом (AI) може відповідати дуже дружньо, але він не має почуттів і не розуміє твого життя. Це не друг і не суддя в суперечці. Якщо тебе образили, розкажи дорослому, якому довіряєш.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Для кожної ситуації обери інструмент і запиши одне слово-причину: аудиторія, мета, терміновість чи приватність.</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 240px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>1.</b> Треба швидко спитати в мами, чи можна після школи піти до друга.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>2.</b> Група з чотирьох учнів пише одну спільну казку.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>3.</b> Потрібно надіслати вчителеві виконану роботу.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>4.</b> Однокласник не розуміє, як пройти рівень у навчальній грі, і просить показати.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>5.</b> Увечері тобі сумно, і хочеться, щоб хтось підтримав.</p></div>\n  </div>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Однокласник написав у груповий чат одне з цих повідомлень. Обери одне й перепиши його ввічливо, без крику й тиску.</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 280px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFF2F2;border:1px solid #E6B0AA;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;\">«ЧОМУ ТИ НЕ ВІДПОВІДАЄШ??? ШВИДКО СКИНЬ СВОЮ ЧАСТИНУ ПРОЄКТУ!!!»</p></div>\n    <div style=\"background:#FFF2F2;border:1px solid #E6B0AA;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;font-family:'Courier New',monospace;\">«Твоя хата в грі жахлива, видали її і не ганьбися!»</p></div>\n  </div>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Напиши чернетку короткого листа вчителеві: тобі не вдалося знайти інструкцію до домашнього завдання. Використай рамку.</p>\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:420px;font-size:16px;\">\n      <tbody>\n        <tr><td style=\"padding:9px 11px;border-bottom:1px solid #EDF1F8;width:34%;\"><b>Тема</b></td><td style=\"padding:9px 11px;border-bottom:1px solid #EDF1F8;\">кілька слів про суть листа</td></tr>\n        <tr><td style=\"padding:9px 11px;border-bottom:1px solid #EDF1F8;\"><b>Звертання</b></td><td style=\"padding:9px 11px;border-bottom:1px solid #EDF1F8;\">ввічливе вітання на ім'я та по батькові</td></tr>\n        <tr><td style=\"padding:9px 11px;border-bottom:1px solid #EDF1F8;\"><b>Мета</b></td><td style=\"padding:9px 11px;border-bottom:1px solid #EDF1F8;\">чітке запитання або прохання</td></tr>\n        <tr><td style=\"padding:9px 11px;\"><b>Завершення</b></td><td style=\"padding:9px 11px;\">подяка, твоє ім'я і клас</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> 1 — чат або дзвінок (терміновість). 2 — спільний документ (мета: працювати разом). 3 — email або шкільна платформа (аудиторія: учитель). 4 — відеодзвінок із показом екрана, якщо дозволили дорослі (мета: показати). 5 — розмова з рідними чи другом (приватність і справжня підтримка), а не чат-бот.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2, приклади.</b> «Привіт! Коли матимеш час, надішли, будь ласка, свою частину проєкту. Дякую!» або «Видно, що над хатою попрацювали. Може, зробимо дах разом по-іншому?»</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> У листі є всі чотири частини, немає великих літер і вимог «негайно».</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">У Кроці 1 виконай ситуації 1, 2 і 3. Інструменти для вибору: <b>чат</b>, <b>спільний документ</b>, <b>email</b>.</p>\n    <p style=\"margin:10px 0 0;\">Для Кроку 2 скористайся готовими словами: <i>«Привіт!», «будь ласка», «коли матимеш час», «дякую», «давай разом»</i>. Прибери великі літери й знаки оклику.</p>\n    <p style=\"margin:10px 0 0;\">Крок 3 можна пропустити.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Анонімність (anonymity)</b> — коли в мережі ти під вигаданим ім'ям. Вона може захищати: людина безпечно ставить питання чи ділиться малюнком. А може й шкодити: хтось думає, що його не знайдуть, і пише грубощі.</p>\n    <p style=\"margin:10px 0 0;\">Опиши по одній ситуації, де анонімність — щит, і де вона — зброя. Подумай, що відчуває кожен учасник розмови. Пам'ятай: нікнейм ховає ім'я від інших гравців, але платформа все одно пов'язує дії з акаунтом.</p>\n    <p style=\"margin:10px 0 0;\"><b>Спільний екранний час (shared screentime)</b> — коли ви разом із другом створюєте гру чи проєкт. Це може бути радісно, бо ви вчитеся одне в одного. Напиши три правила для такої роботи: хто коли керує мишкою, як слухати ідеї партнера і коли зробити перерву.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>Anonymity can protect and it can harm.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\">Відпрацюй доброзичливе спілкування та безпечну реакцію на образливі повідомлення.</p>\n    <ul style=\"margin:0;padding-left:20px;line-height:1.55;\">\n      <li style=\"margin-bottom:8px;\"><a href=\"https://itnauka.org/services/security_and_safety/cybersecurity_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">Кібербезпека для дітей ↗</a> — короткі ситуації про приватність, спілкування й допомогу дорослих.</li>\n      <li><a href=\"https://beinternetawesome.withgoogle.com/en_us/interland/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">Interland: Kind Kingdom ↗</a> — гра про доброзичливість, блокування та повідомлення про кривдника.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u6-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Чому не варто писати ВЕЛИКИМИ ЛІТЕРАМИ?</label>\n    <select id=\"g4-u6-q1\" name=\"g4-u6-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Це витрачає більше заряду батареї</option>\n      <option>Читач сприймає це як крик</option>\n      <option>Сервер видаляє такі повідомлення</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Читач сприймає це як крик і тиск, навіть якщо автор так не думав.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u6-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Треба домовитися з учителем про перездачу. Що краще?</label>\n    <select id=\"g4-u6-q2\" name=\"g4-u6-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Написати в загальний чат класу</option>\n      <option>Написати лист або повідомлення в шкільній платформі</option>\n      <option>Записати голосове о десятій вечора</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Лист або шкільна платформа. Аудиторія — учитель, питання особисте й не термінове.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u6-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чи може чат-бот розсудити твою суперечку з другом?</label>\n    <select id=\"g4-u6-q3\" name=\"g4-u6-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Так, він знає всі правила</option>\n      <option>Ні, він не має почуттів і не знає вашої ситуації</option>\n      <option>Так, якщо відповідає дружньо</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Ні. Чат-бот — програма: він складає відповіді за зразками з даних, але не відчуває й не відповідає за пораду. Важливу суперечку розв'язують із людьми.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Назви свою перевірку перед надсиланням:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Перш ніж надіслати, я перечитую повідомлення очима ___ і питаю себе ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я правильно обираю інструмент щонайменше в чотирьох ситуаціях із п'яти.</li>\n      <li style=\"margin:8px 0;\">Моє переписане повідомлення без образ, крику й тиску.</li>\n      <li style=\"margin:8px 0;\">Мій лист учителеві має тему, звертання, мету й завершення.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> три ситуації та одне переписане повідомлення.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> вибір інструментів, переписане повідомлення й чернетку листа.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>audience</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">аудиторія, хто прочитає</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>purpose</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">мета</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>urgent / private</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">терміновий / приватний</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>respectful</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">шанобливий, ввічливий</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>online etiquette</b></td><td style=\"padding:8px 10px;\">мережевий етикет</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I choose email because my audience is a teacher. I pause and read my message again.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-1-7","grade":4,"module":1,"number":7,"title":"Цифровий слід і архівні дані: чому видалити складно","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок7_Гра1_Б-Д-чи-Н.html","title":"Б, Д чи Н?","description":"сортування карток","data":{"id":"g7a","lesson":7,"tag":"СЛІД","icon":"👣","type":"sort","title":"Б, Д чи Н?","file":"Урок7_Гра1_Б-Д-чи-Н.html","conceptName":"цифровий слід","concept":"Усе, що ти публікуєш, лишає цифровий слід. Перед публікацією запитай: чи можу я показати це незнайомій людині на вулиці?","skill":"вирішую, чим можна ділитися, де потрібен дозвіл, а що не публікують","data":{"categories":[{"id":"b","label":"✅ Б — безпечно","hint":"немає приватних даних і чужих облич"},{"id":"d","label":"🙋 Д — спершу дозвіл","hint":"на фото чи в тексті є інші люди"},{"id":"n","label":"⛔ Н — не поширювати","hint":"особисті дані, паролі, фото людей без згоди"}],"items":[{"text":"🎨 Фото твого малюнка тварини для шкільного блогу","cat":"b","explain":"Безпечно: це твоя робота, без приватних даних і чужих облич."},{"text":"🎂 Спільне фото з дня народження друга","cat":"d","explain":"На фото інші люди — спершу запитай їхнього дозволу."},{"text":"🏠 Домашня адреса й телефон батьків","cat":"n","explain":"Не поширювати: це особисті дані родини."},{"text":"🔑 Пароль від ігрового акаунта","cat":"n","explain":"Пароль не передають нікому — навіть найкращому другові."},{"text":"✈️ «Вся родина їде у відпустку на два тижні»","cat":"n","explain":"Таке повідомлення каже всім, що дім порожній. Не публікуємо."},{"text":"😄 Знімок кумедної помилки в навчальній грі, без імен гравців","cat":"b","explain":"Безпечно: немає ні імен, ні облич, ні особистих даних."},{"text":"😴 Фото однокласника, який заснув на уроці","cat":"n","explain":"Не поширювати: це неповага без згоди і може стати приводом для цькування."},{"text":"📚 Відгук про прочитану книжку на дитячому форумі","cat":"b","explain":"Безпечно: твоя думка про книжку без особистих даних."}]}},"after":{"index":1,"heading":"👣 Що таке цифровий слід"}},{"path":"app/games/Урок7_Гра2_Видалено-і-зникло.html","title":"Видалено — і зникло?","description":"сценарний вибір","data":{"id":"g7b","lesson":7,"tag":"КОПІЇ","icon":"🗑️","type":"quiz","title":"Видалено — і зникло?","file":"Урок7_Гра2_Видалено-і-зникло.html","conceptName":"видалення й копії","concept":"Кнопка «Видалити» прибирає допис із твого профілю. Але копії — скопійований текст, пересилання, знімки екрана, резервні копії сервісу — могли лишитися.","skill":"пояснюю, чому видалений допис може зберегтися в копіях","data":{"questions":[{"q":"Фото видалили через 2 хвилини після публікації. Що точно?","options":["Воно зникло з профілю, але копії могли лишитися","Воно зникло з усіх пристроїв світу","Видаляти вже не було сенсу"],"correct":0,"explain":"Видалити — правильно: менше людей побачать. Але знімки екрана й пересилання видалення не повертає.","wrong":"Згадай про screenshot: що лишається на чужих пристроях?"},{"q":"Хтось зробив знімок екрана допису до того, як його видалили. Де тепер цей допис?","options":["На пристрої того, хто зробив знімок","Ніде, допис же видалили","Лише в автора допису"],"correct":0,"explain":"Знімок екрана лишається на чужому пристрої, навіть якщо оригінал уже видалено.","wrong":"Видалення прибирає оригінал, але не чужі знімки."},{"q":"Що таке архівні дані?","options":["Резервні копії, які сервіс зберігає довго за своїми правилами","Малюнок олівцями в зошиті","Вкладка браузера, яку щойно закрили"],"correct":0,"explain":"Backup — резервна копія. Скільки її зберігати, вирішують правила сервісу.","wrong":"Архівні дані — це те, що сервіс зберігає довго."},{"q":"Ти опублікував допис і тепер шкодуєш. Перший крок?","options":["Видалити допис і розповісти дорослому","Нічого: усе одно не зникне","Опублікувати ще один, щоб старий загубився"],"correct":0,"explain":"Далі — попросити тих, хто переслав, видалити копії, і за потреби поскаржитися.","wrong":"Видалення не марне: менше людей побачить допис."},{"q":"Яке з чотирьох питань перед публікацією спрацює для фото з обличчям друга?","options":["«Чи є там інші люди, які не давали згоди?»","«Чи гарний у фото колір?»","«Чи багато лайків воно збере?»"],"correct":0,"explain":"Чотири питання: хто побачить? чи є інші люди без згоди? як прочитають через роки? чи поясню спокійно дорослому?","wrong":"Перед публікацією перевір, чи є на фото інші люди."},{"q":"«Якщо хоч на одне питання відповідь «не знаю»…» — що це означає?","options":["Це вагома причина зачекати з публікацією","Треба публікувати швидше","Питання можна пропустити"],"correct":0,"explain":"Ненадісланий допис можна надіслати пізніше, а надісланий назад не забереш.","wrong":"«Не знаю» — це сигнал зупинитися, а не прискоритися."}]}},"after":{"index":2,"heading":"🗑 Видалено з екрана — ще не зникло всюди"}}],"legacyTitle":"Урок 7. Цифровий слід і архівні дані","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 7</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Цифровий слід і архівні дані: чому видалити складно</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Digital Footprints and Archived Data: Why Deletion Is Difficult</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: допис видалено вже за хвилину. Чому цього може бути замало?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я пояснюю, що таке <b>digital footprint</b> і чому видалений допис може зберегтися в копіях.</li>\n      <li style=\"margin:6px 0;\">Я вирішую, чим можна ділитися, де потрібен дозвіл, а що не публікують.</li>\n      <li style=\"margin:6px 0;\">Я перевіряю допис чотирма питаннями перед публікацією.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">👣 Що таке цифровий слід</h2>\n  <p style=\"margin:0 0 12px;\">Узимку твої черевики лишають сліди на снігу. Навесні сніг розтане — і сліди зникнуть.</p>\n  <p style=\"margin:0 0 12px;\">В Інтернеті теж лишаються сліди: опубліковане фото, коментар, «лайк», повідомлення в груповому чаті. Разом вони утворюють <b>цифровий слід (digital footprint)</b>. Частина таких записів зникає швидко, а частина може зберігатися роками.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🗑 Видалено з екрана — ще не зникло всюди</h2>\n  <p style=\"margin:0 0 12px;\">Коли ти натискаєш «Видалити» (<b>delete</b>), допис зникає з твого профілю. Але поки він був у мережі, з ним могло статися ось що:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">📋 <b>Copy</b> — хтось скопіював текст чи картинку собі.</li>\n    <li style=\"margin:8px 0;\">📤 <b>Share</b> — допис переслали в іншу групу.</li>\n    <li style=\"margin:8px 0;\">📸 <b>Screenshot</b> — хтось зробив знімок екрана. Він лишиться на чужому пристрої, навіть якщо оригінал уже видалено.</li>\n    <li style=\"margin:8px 0;\">💾 <b>Backup</b> — сервіс якийсь час зберігає резервні копії за своїми правилами.</li>\n  </ul>\n\n  <svg viewBox=\"0 0 860 260\" role=\"img\" aria-labelledby=\"g4u7a-t g4u7a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u7a-t\">Куди може потрапити допис до видалення</title>\n    <desc id=\"g4u7a-d\">Ліворуч мій допис, який я видаляю зі свого екрана. Від нього чотири стрілки: хтось скопіював, допис переслали в групу, зробили знімок екрана, сервіс зберіг резервну копію на сервері. Від усіх чотирьох копій стрілки ведуть праворуч, до нової аудиторії, яка може побачити допис навіть пізніше.</desc>\n    <defs>\n      <marker id=\"g4u7a-m\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto\"><path d=\"M0 0 L10 5 L0 10 z\" fill=\"#0033A0\"></path></marker>\n    </defs>\n    <rect x=\"6\" y=\"80\" width=\"214\" height=\"100\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"113\" y=\"118\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">📱 Мій допис</text>\n    <text x=\"113\" y=\"148\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">видаляю з екрана</text>\n\n    <path d=\"M222 130 L286 37\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n    <path d=\"M222 130 L286 99\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n    <path d=\"M222 130 L286 161\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n    <path d=\"M222 130 L286 223\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n\n    <rect x=\"290\" y=\"14\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"306\" y=\"43\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">📋 Copy — хтось скопіював</text>\n    <rect x=\"290\" y=\"76\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"306\" y=\"105\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">📤 Share — переслали в групу</text>\n    <rect x=\"290\" y=\"138\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"306\" y=\"167\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">📸 Screenshot — знімок екрана</text>\n    <rect x=\"290\" y=\"200\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"306\" y=\"229\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">💾 Backup — копія на сервері</text>\n\n    <path d=\"M582 37 L636 126\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n    <path d=\"M582 99 L636 128\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n    <path d=\"M582 161 L636 132\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n    <path d=\"M582 223 L636 134\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"2\" marker-end=\"url(#g4u7a-m)\"></path>\n\n    <rect x=\"640\" y=\"80\" width=\"214\" height=\"100\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n    <text x=\"747\" y=\"116\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">👀 Нова аудиторія</text>\n    <text x=\"747\" y=\"144\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">може побачити</text>\n    <text x=\"747\" y=\"166\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">навіть пізніше</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Тому кажуть: дані в мережі <b>може бути важко видалити повністю</b>. Це не означає, що видаляти марно. Якщо допис був помилкою, видали його якнайшвидше. Попроси тих, хто його переслав, теж видалити, скористайся кнопкою «Поскаржитися» (report) і розкажи дорослому.</p>\n  <p style=\"margin:0 0 12px;\">Старі дані, які сервіс зберігає довго, називають <b>архівними (archived data)</b>. Їх можуть побачити люди, для яких допис не призначався: нові однокласники, учителі, незнайомці.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: симуляція «Ехо-мережа»</h2>\n  <p style=\"margin:0 0 12px;\">Розіграйте в класі, що відбувається з дописом. Ролі:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Автор</b> пише на стікері вигаданий безпечний жарт — це допис.</li>\n    <li style=\"margin:8px 0;\"><b>Сервер</b> переписує стікер на свій папірець — це backup.</li>\n    <li style=\"margin:8px 0;\"><b>Троє друзів</b> отримують стікер по черзі й переписують його в зошит — це screenshot.</li>\n    <li style=\"margin:8px 0;\"><b>Нова аудиторія</b> отримує папірець від останнього друга — це share.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Наприкінці автор оголошує: «Я видаляю допис!» — і рве свій стікер. Учитель просить усіх інших підняти свої папірці. Скільки копій лишилося? Що саме вдалося видалити автору?</p>\n\n  <div style=\"background:#FFF2F2;border-left:5px solid #C0392B;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Фейки від ШІ.</b> Програми штучного інтелекту вміють створювати несправжні дописи й зображення. Такий «жарт» про реальну людину можуть швидко скопіювати, і він надовго зашкодить. Тому в уроках ми працюємо лише з вигаданими ситуаціями й ніколи не використовуємо справжніх імен чи фото дітей.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Для кожного прикладу запиши букву: <b>Б</b> — безпечно поширити (safe to share), <b>Д</b> — спершу запитати дозволу (ask permission), <b>Н</b> — не поширювати (do not share).</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 240px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>1.</b> Фото твого малюнка тварини для шкільного блогу.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>2.</b> Спільне фото з дня народження друга.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>3.</b> Домашня адреса й телефон батьків.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>4.</b> Пароль від ігрового акаунта.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>5.</b> Повідомлення, що вся родина їде у відпустку на два тижні.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>6.</b> Знімок кумедної помилки в навчальній грі, без імен гравців.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>7.</b> Фото однокласника, який заснув на уроці.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>8.</b> Відгук про прочитану книжку на дитячому форумі.</p></div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Перевір вигаданий допис чотирма питаннями нижче. Для кожного запиши відповідь і вирішуй: публікувати, змінити чи не публікувати.</p>\n  <div style=\"background:#FFFFFF;border:2px solid #0033A0;border-radius:10px;padding:14px 16px;margin:12px 0 16px;\">\n    <p style=\"margin:0;\"><i>«Ура, свято класу! 🎉» — і фото, на якому видно обличчя трьох однокласників і табличку з назвою школи.</i></p>\n  </div>\n\n  <svg viewBox=\"0 0 860 190\" role=\"img\" aria-labelledby=\"g4u7b-t g4u7b-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u7b-t\">Чотири питання перед публікацією</title>\n    <desc id=\"g4u7b-d\">Перше питання: хто це побачить, крім тих, кому призначено. Друге: чи є на фото чи в тексті інші люди, які не давали згоди. Третє: як це читатиметься через кілька років. Четверте: чи зможу я спокійно пояснити це дорослому.</desc>\n    <rect x=\"6\" y=\"14\" width=\"206\" height=\"162\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"109\" y=\"56\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">👥</text>\n    <text x=\"109\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">1. Хто побачить</text>\n    <text x=\"109\" y=\"122\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">крім тих, кому</text>\n    <text x=\"109\" y=\"144\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">призначено</text>\n    <rect x=\"224\" y=\"14\" width=\"206\" height=\"162\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"327\" y=\"56\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">🙋</text>\n    <text x=\"327\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">2. Чи є там інші</text>\n    <text x=\"327\" y=\"122\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">хто не давав</text>\n    <text x=\"327\" y=\"144\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">згоди</text>\n    <rect x=\"442\" y=\"14\" width=\"206\" height=\"162\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"545\" y=\"56\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">📅</text>\n    <text x=\"545\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">3. А через роки</text>\n    <text x=\"545\" y=\"122\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">як це прочитає</text>\n    <text x=\"545\" y=\"144\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">хтось інший</text>\n    <rect x=\"660\" y=\"14\" width=\"194\" height=\"162\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n    <text x=\"757\" y=\"56\" text-anchor=\"middle\" font-size=\"26\" font-family=\"Arial, sans-serif\">🗣️</text>\n    <text x=\"757\" y=\"90\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">4. Чи поясню</text>\n    <text x=\"757\" y=\"122\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">спокійно</text>\n    <text x=\"757\" y=\"144\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">дорослому</text>\n  </svg>\n  <p style=\"margin:0 0 12px;\">Якщо хоч на одне питання відповідь «не знаю» — це вагома причина зачекати. Ненадісланий допис можна надіслати пізніше, а надісланий назад не забереш.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Б — 1, 6, 8: у них немає приватних даних і чужих облич. Д — 2: на фото інші люди, їх треба спитати. Н — 3, 4, 5, 7: адреса, пароль і відомості про порожній дім небезпечні, а фото однокласника без згоди — неповага і може стати приводом для цькування.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Питання 2 і 1 не проходять: на фото обличчя однокласників без їхньої згоди та назва школи, яку побачать незнайомці. Варто змінити: запитати дозволу або обрати фото без облич і таблички.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">У Кроці 1 виконай приклади 1, 3, 4 і 7. Для кожного спитай себе: <i>«Чи можу я показати це незнайомій людині на вулиці?»</i></p>\n    <p style=\"margin:10px 0 0;\">У Кроці 2 досить відповісти на питання 1 і 2.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Старий допис — нова аудиторія.</b> Марійка написала в чаті з двома подругами: «Екскурсія — повний провал, я ледь не заснула 😴». Вона просто втомилася. Одна подруга зробила знімок екрана й переслала його в групу класу, де є вчитель, який готував екскурсію.</p>\n    <p style=\"margin:10px 0 0;\">Вчителеві стало прикро: він не знав, що Марійка просто втомилася того дня. Повідомлення для двох людей прочитала зовсім інша аудиторія.</p>\n    <p style=\"margin:10px 0 0;\">Подумай: хто відповідає за цю ситуацію — Марійка чи подруга, що переслала? Яке з чотирьох питань допомогло б кожній із них?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>Old posts are read by a new audience.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Кібербезпека для дітей:</b> розв'яжи ситуації з публікаціями та особистими даними. Порівняй свої рішення з чотирма питаннями.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">За бажанням • 10 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/security_and_safety/cybersecurity_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;\">Відкрити урок із кібербезпеки ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u7-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Фото видалили через 2 хвилини після публікації. Що точно?</label>\n    <select id=\"g4-u7-q1\" name=\"g4-u7-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Воно зникло з усіх пристроїв світу</option>\n      <option>Воно зникло з профілю, але копії могли лишитися</option>\n      <option>Видаляти вже не було сенсу</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Видалити — правильна дія: менше людей побачать фото. Але знімки екрана чи пересилання, зроблені раніше, видалення не повертає.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u7-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Що з цього — архівні дані?</label>\n    <select id=\"g4-u7-q2\" name=\"g4-u7-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Малюнок олівцями в зошиті</option>\n      <option>Вкладка браузера, яку щойно закрили</option>\n      <option>Резервна копія сервісу з дописами трирічної давнини</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Резервна копія. Архівні дані зберігаються довго, і скільки саме — вирішують правила сервісу.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u7-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Допис уже опубліковано, і тепер про нього шкодуєш. Що зробити першим?</label>\n    <select id=\"g4-u7-q3\" name=\"g4-u7-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Нічого, все одно не зникне</option>\n      <option>Видалити допис і розказати дорослому</option>\n      <option>Опублікувати ще один, щоб старий загубився</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Видалити й розказати дорослому. Далі — попросити тих, хто переслав, видалити копії, і за потреби поскаржитися.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку, а потім назви своє правило:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Видалити за хвилину замало, бо ___. Я публікую, лише якщо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я правильно оцінюю щонайменше 7 із 8 прикладів.</li>\n      <li style=\"margin:8px 0;\">Я перевіряю вигаданий допис чотирма питаннями й ухвалюю рішення.</li>\n      <li style=\"margin:8px 0;\">Я пояснюю різницю між «видалено з екрана» і «зникло всюди».</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> чотири приклади з Кроку 1 і два питання з Кроку 2.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> букви Б/Д/Н до прикладів і відповіді на чотири питання.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>digital footprint</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">цифровий слід</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>archived data</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">архівні дані</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>copy / share</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">копіювати / поширювати</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>screenshot / backup</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">знімок екрана / резервна копія</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>permission</b></td><td style=\"padding:8px 10px;\">дозвіл</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>A deleted post can still have copies. I ask permission before I share a photo of a friend.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-1-8","grade":4,"module":1,"number":8,"title":"Безпечне передавання даних: шифрування, Caesar і Pigpen","moduleTitle":"Комп'ютерні системи та безпечна робота в мережі","games":[{"path":"app/games/Урок8_Гра1_Шифр-Цезаря.html","title":"Шифр Цезаря","description":"шифрування","data":{"id":"g8a","lesson":8,"tag":"ЦЕЗАР","icon":"🔐","type":"cipher","title":"Шифр Цезаря","file":"Урок8_Гра1_Шифр-Цезаря.html","conceptName":"шифрування й ключ","concept":"Шифрування не заважає перехопити повідомлення, але заважає його зрозуміти. У шифрі Цезаря кожну літеру зсувають алфавітом, а кількість кроків — це ключ. Зашифрувати — зсув уперед, розшифрувати — назад.","skill":"шифрую й розшифровую короткі слова шифром Цезаря","data":{"tasks":[{"mode":"encrypt","word":"CAT","key":1},{"mode":"decrypt","word":"FAR","key":2},{"mode":"encrypt","word":"DATA","key":3},{"mode":"decrypt","word":"CAB","key":3},{"mode":"encrypt","word":"SUN","key":2},{"mode":"decrypt","word":"THE","key":5}]}},"after":{"index":2,"heading":"🏛 Шифр Цезаря"}},{"path":"app/games/Урок8_Гра2_Знайди-помилку-в-шифрі.html","title":"Знайди помилку в шифрі","description":"сценарний вибір","data":{"id":"g8b","lesson":8,"tag":"КЛЮЧ","icon":"🔎","type":"quiz","title":"Знайди помилку в шифрі","file":"Урок8_Гра2_Знайди-помилку-в-шифрі.html","conceptName":"ключ","concept":"Правило шифру можуть знати всі — секретом лишається ключ. Саме тому ключ передають окремо від повідомлення.","skill":"знаходжу помилку в шифротексті й пояснюю роль ключа","data":{"questions":[{"q":"Друг шифрував слово SAW ключем 3, а надіслав VDY. Розшифруй: V→S, D→A, Y→V. Де помилка?","options":["В останній літері: W ключем 3 — це Z, має бути VDZ","У першій літері: має починатися з U","У другій літері: має бути E"],"correct":0,"explain":"VDY розшифровується як SAV. Правильно: S→V, A→D, W→Z, тобто VDZ.","wrong":"Розшифруй отримане слово назад ключем 3 і порівняй із SAW."},{"q":"Що є ключем у шифрі Цезаря?","options":["Кількість кроків зсуву","Перша літера повідомлення","Назва шифру"],"correct":0,"explain":"Правило «зсувай літери» знають усі — секретом лишається число кроків.","wrong":"Ключ — це те, без чого шифротекст не прочитаєш."},{"q":"Зловмисник перехопив зашифрований лист. Що змінює шифрування?","options":["Без ключа зміст листа не зрозуміти","Лист неможливо перехопити","Лист сам видаляється"],"correct":0,"explain":"Перехопити шифрування не заважає. Але перехоплений шифротекст — незрозумілі літери.","wrong":"Шифрування не ховає повідомлення, а робить його незрозумілим."},{"q":"Чому ключ надсилають окремо від повідомлення?","options":["Якщо перехоплять і те, і те — усе прочитають","Так коротше писати","Бо ключ не влазить у повідомлення"],"correct":0,"explain":"Повідомлення й ключ разом — це як замкнені двері з ключем у замку.","wrong":"Уяви, що лист і ключ летять одним конвертом. Що станеться, якщо його перехоплять?"},{"q":"У шифрі Цезаря одну літеру зашифровано з помилкою. Що буде під час розшифрування?","options":["Неправильною вийде лише ця літера","Усе повідомлення стане незрозумілим","Помилка виправиться сама"],"correct":0,"explain":"Кожну літеру шифрують окремо, тому й помилка лишається лише в одній. Саме тому результат перевіряють літеру за літерою.","wrong":"У шифрі Цезаря кожна літера шифрується окремо від інших."}]}},"after":{"index":3,"heading":"🔎 Як перевірити себе"}}],"legacyTitle":"Урок 8. Безпечне передавання даних: шифрування","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 1 &bull; Урок 8</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Безпечне передавання даних: шифрування, Caesar і Pigpen</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Secure Data Transfer: Encryption, Caesar and Pigpen</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як ключ захищає повідомлення, навіть якщо його перехоплять?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я пояснюю, що роблять <b>encryption</b>, <b>decryption</b> і <b>key</b>, і де використовують шифрування.</li>\n      <li style=\"margin:6px 0;\">Я шифрую і розшифровую коротке слово шифром Цезаря (<b>Caesar cipher</b>).</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔐 Навіщо шифрувати</h2>\n  <p style=\"margin:0 0 12px;\">Уяви: ти передаєш записку другові через увесь клас. Її можуть перехопити й прочитати. А якщо записку написано так, що зрозуміти її може лише той, хто знає секретне правило?</p>\n  <p style=\"margin:0 0 12px;\">Це і є <b>шифрування (encryption)</b>. Шифрування не заважає перехопити повідомлення, але заважає його <b>зрозуміти</b>. Секретне правило, без якого не прочитаєш, називають <b>ключем (key)</b>. Повернути звичайний текст допомагає <b>розшифрування (decryption)</b>.</p>\n\n  <svg viewBox=\"0 0 860 190\" role=\"img\" aria-labelledby=\"g4u8a-t g4u8a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u8a-t\">Шифрування і розшифрування з ключем</title>\n    <desc id=\"g4u8a-d\">Відкритий текст CAB шифрують ключем 3 і отримують шифротекст FDE. Одержувач розшифровує його тим самим ключем 3 і знову бачить CAB. Хто перехопить FDE без ключа, побачить лише незрозумілі літери.</desc>\n    <rect x=\"6\" y=\"20\" width=\"190\" height=\"110\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"101\" y=\"54\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">PLAINTEXT</text>\n    <text x=\"101\" y=\"98\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#1A1A1A\" font-family=\"'Courier New',monospace\">CAB</text>\n    <path d=\"M198 75 H214\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"212,68 224,75 212,82\" fill=\"#0033A0\"></polygon>\n    <rect x=\"226\" y=\"20\" width=\"190\" height=\"110\" rx=\"12\" fill=\"#0033A0\"></rect>\n    <text x=\"321\" y=\"54\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">🔒 ENCRYPT</text>\n    <text x=\"321\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFD700\" font-family=\"Arial, sans-serif\">ключ = 3</text>\n    <text x=\"321\" y=\"116\" text-anchor=\"middle\" font-size=\"15\" fill=\"#D6E0F5\" font-family=\"Arial, sans-serif\">зсув уперед</text>\n    <path d=\"M418 75 H434\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"432,68 444,75 432,82\" fill=\"#0033A0\"></polygon>\n    <rect x=\"446\" y=\"20\" width=\"190\" height=\"110\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"541\" y=\"54\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">CIPHERTEXT</text>\n    <text x=\"541\" y=\"98\" text-anchor=\"middle\" font-size=\"26\" font-weight=\"700\" fill=\"#96271B\" font-family=\"'Courier New',monospace\">FDE</text>\n    <path d=\"M638 75 H654\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path>\n    <polygon points=\"652,68 664,75 652,82\" fill=\"#0033A0\"></polygon>\n    <rect x=\"666\" y=\"20\" width=\"188\" height=\"110\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n    <text x=\"760\" y=\"54\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">🔓 DECRYPT</text>\n    <text x=\"760\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">ключ = 3, назад</text>\n    <text x=\"760\" y=\"120\" text-anchor=\"middle\" font-size=\"22\" font-weight=\"700\" fill=\"#1A1A1A\" font-family=\"'Courier New',monospace\">CAB</text>\n    <text x=\"430\" y=\"170\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">хто перехопить FDE без ключа, побачить лише незрозумілі літери</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Де сьогодні працює шифрування:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">🌐 <b>Сайти з https</b> шифрують дані дорогою між браузером і сервером.</li>\n    <li style=\"margin:8px 0;\">💬 <b>Месенджери</b> шифрують повідомлення й фото під час передавання.</li>\n    <li style=\"margin:8px 0;\">💳 <b>Банківські картки й застосунки</b> захищають дані платежів.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Сучасні шифри набагато складніші за ті, що ти побачиш сьогодні. Але головна ідея та сама: алгоритм + секретний ключ.</p>\n\n  <figure style=\"margin:18px 0 20px;background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px;\">\n    <img src=\"https://commons.wikimedia.org/wiki/Special:Redirect/file/CipherDisk2000.jpg?width=800\" alt=\"Круглий шифрувальний диск із двома рухомими алфавітами\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;max-height:410px;object-fit:contain;border-radius:8px;\">\n    <figcaption style=\"margin-top:9px;font-size:15px;line-height:1.45;color:#3D4757;\">Шифрувальний диск: повертаєш внутрішнє коло — і кожна літера замінюється іншою. Так працює шифр Цезаря. Фото: <a href=\"https://commons.wikimedia.org/wiki/File:CipherDisk2000.jpg\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;\">Hubert Berberich, Wikimedia Commons</a>, суспільне надбання.</figcaption>\n  </figure>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🏛 Шифр Цезаря</h2>\n  <p style=\"margin:0 0 12px;\">Цей шифр названо на честь римського полководця Юлія Цезаря. Правило просте: кожну літеру зсувають алфавітом на однакову кількість кроків. Кількість кроків — це і є <b>ключ</b>.</p>\n  <p style=\"margin:0 0 12px;\">Щоб зашифрувати, зсуваєш <b>уперед</b>. Щоб розшифрувати — на стільки ж кроків <b>назад</b>. Дійшовши до кінця алфавіту, продовжуєш з початку: з ключем 3 літера Z стає C.</p>\n  <p style=\"margin:0 0 12px;\">Приклад: слово <b>CAB</b> з ключем 3. C → F, A → D, B → E. Виходить <b>FDE</b>.</p>\n\n  <svg viewBox=\"0 0 860 250\" role=\"img\" aria-labelledby=\"g4u8b-t g4u8b-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u8b-t\">Таблиця шифру Цезаря з ключем 3</title>\n    <desc id=\"g4u8b-d\">Два блоки по тринадцять літер. Верхній рядок кожного блоку — звичайна літера, нижній — шифрована, зсунута на три кроки вперед. A стає D, B стає E, C стає F і так далі. Наприкінці алфавіту відлік іде з початку: X стає A, Y стає B, Z стає C.</desc>\n    <text x=\"10\" y=\"50\" font-size=\"15\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">plain</text>\n    <text x=\"10\" y=\"100\" font-size=\"15\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">cipher</text>\n    <rect x=\"86\" y=\"74\" width=\"768\" height=\"38\" rx=\"8\" fill=\"#FFF2F2\"></rect>\n    <g font-size=\"22\" font-weight=\"700\" font-family=\"'Courier New',monospace\" text-anchor=\"middle\">\n      <text x=\"110\" y=\"50\" fill=\"#0033A0\">A</text><text x=\"166\" y=\"50\" fill=\"#0033A0\">B</text><text x=\"222\" y=\"50\" fill=\"#0033A0\">C</text><text x=\"278\" y=\"50\" fill=\"#0033A0\">D</text><text x=\"334\" y=\"50\" fill=\"#0033A0\">E</text><text x=\"390\" y=\"50\" fill=\"#0033A0\">F</text><text x=\"446\" y=\"50\" fill=\"#0033A0\">G</text><text x=\"502\" y=\"50\" fill=\"#0033A0\">H</text><text x=\"558\" y=\"50\" fill=\"#0033A0\">I</text><text x=\"614\" y=\"50\" fill=\"#0033A0\">J</text><text x=\"670\" y=\"50\" fill=\"#0033A0\">K</text><text x=\"726\" y=\"50\" fill=\"#0033A0\">L</text><text x=\"782\" y=\"50\" fill=\"#0033A0\">M</text>\n      <text x=\"110\" y=\"100\" fill=\"#96271B\">D</text><text x=\"166\" y=\"100\" fill=\"#96271B\">E</text><text x=\"222\" y=\"100\" fill=\"#96271B\">F</text><text x=\"278\" y=\"100\" fill=\"#96271B\">G</text><text x=\"334\" y=\"100\" fill=\"#96271B\">H</text><text x=\"390\" y=\"100\" fill=\"#96271B\">I</text><text x=\"446\" y=\"100\" fill=\"#96271B\">J</text><text x=\"502\" y=\"100\" fill=\"#96271B\">K</text><text x=\"558\" y=\"100\" fill=\"#96271B\">L</text><text x=\"614\" y=\"100\" fill=\"#96271B\">M</text><text x=\"670\" y=\"100\" fill=\"#96271B\">N</text><text x=\"726\" y=\"100\" fill=\"#96271B\">O</text><text x=\"782\" y=\"100\" fill=\"#96271B\">P</text>\n      <text x=\"110\" y=\"170\" fill=\"#0033A0\">N</text><text x=\"166\" y=\"170\" fill=\"#0033A0\">O</text><text x=\"222\" y=\"170\" fill=\"#0033A0\">P</text><text x=\"278\" y=\"170\" fill=\"#0033A0\">Q</text><text x=\"334\" y=\"170\" fill=\"#0033A0\">R</text><text x=\"390\" y=\"170\" fill=\"#0033A0\">S</text><text x=\"446\" y=\"170\" fill=\"#0033A0\">T</text><text x=\"502\" y=\"170\" fill=\"#0033A0\">U</text><text x=\"558\" y=\"170\" fill=\"#0033A0\">V</text><text x=\"614\" y=\"170\" fill=\"#0033A0\">W</text><text x=\"670\" y=\"170\" fill=\"#0033A0\">X</text><text x=\"726\" y=\"170\" fill=\"#0033A0\">Y</text><text x=\"782\" y=\"170\" fill=\"#0033A0\">Z</text>\n    </g>\n    <text x=\"10\" y=\"170\" font-size=\"15\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">plain</text>\n    <text x=\"10\" y=\"220\" font-size=\"15\" font-weight=\"700\" fill=\"#96271B\" font-family=\"Arial, sans-serif\">cipher</text>\n    <rect x=\"86\" y=\"194\" width=\"768\" height=\"38\" rx=\"8\" fill=\"#FFF2F2\"></rect>\n    <g font-size=\"22\" font-weight=\"700\" font-family=\"'Courier New',monospace\" text-anchor=\"middle\" fill=\"#96271B\">\n      <text x=\"110\" y=\"220\">Q</text><text x=\"166\" y=\"220\">R</text><text x=\"222\" y=\"220\">S</text><text x=\"278\" y=\"220\">T</text><text x=\"334\" y=\"220\">U</text><text x=\"390\" y=\"220\">V</text><text x=\"446\" y=\"220\">W</text><text x=\"502\" y=\"220\">X</text><text x=\"558\" y=\"220\">Y</text><text x=\"614\" y=\"220\">Z</text><text x=\"670\" y=\"220\">A</text><text x=\"726\" y=\"220\">B</text><text x=\"782\" y=\"220\">C</text>\n    </g>\n  </svg>\n  <p style=\"margin:0 0 12px;\">Таблиця вище — для ключа 3. Для іншого ключа склади свою: запиши алфавіт, а під ним — той самий алфавіт, зсунутий на потрібну кількість кроків.</p>\n  <p style=\"margin:0 0 12px;\">Шифрувати можна й українськими літерами, але тоді таблиця інша: в українській абетці 33 літери. Головне — не змішувати латиницю й кирилицю в одному слові.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔎 Як перевірити себе</h2>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Запиши слово великими літерами, залишаючи між ними трохи місця.</li>\n    <li style=\"margin:8px 0;\">Під кожною літерою напиши шифровану — по одній, не поспішаючи.</li>\n    <li style=\"margin:8px 0;\">Розшифруй свій результат назад тим самим ключем. Якщо вийшло початкове слово — усе правильно.</li>\n  </ol>\n  <p style=\"margin:0 0 12px;\">Такий зворотний шлях — звичайна перевірка в програмуванні: виконай дію, а потім обернену до неї, і порівняй із початком.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">Працюй лише з короткими англійськими словами й одним ключем за раз. Кожну літеру перевіряй окремо, а таблицю тримай перед очима.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Розшифруй.</b> Шифротекст <b style=\"font-family:'Courier New',monospace;font-size:18px;\">HCT</b>, ключ 2. Зсунь кожну літеру на 2 кроки назад.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Зашифруй.</b> Слово <b style=\"font-family:'Courier New',monospace;font-size:18px;\">DATA</b> з ключем 3. Користуйся таблицею.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Знайди помилку.</b> Друг хотів зашифрувати слово <b>SAW</b> ключем 3, а надіслав <b style=\"font-family:'Courier New',monospace;font-size:18px;\">VDY</b>. Розшифруй і знайди, яку літеру зашифровано неправильно.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Поясни роль ключа.</b> Хтось перехопив твоє повідомлення з Кроку 2, але не знає ключа. Запиши двома реченнями, чому йому буде складно, і чому ключ передають окремо від повідомлення.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> H → F, C → A, T → R. Відповідь: <b>FAR</b>.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> D → G, A → D, T → W, A → D. Відповідь: <b>GDWD</b>.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> VDY розшифровується як SAV. Помилка в останній літері: W із ключем 3 — це Z, а не Y. Правильно: <b>VDZ</b>.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Без ключа не зрозуміло, на скільки кроків зсувати. Якщо ключ надіслати разом із повідомленням, той, хто перехопив, прочитає все.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Почни з ключа 1: кожна літера стає наступною. Зашифруй слово <b>CAT</b>: C → D, A → ___, T → ___.</p>\n    <p style=\"margin:10px 0 0;\">Можна скористатися паперовим диском Цезаря: <a href=\"https://itnauka.org/services/offline_activities/pdfs/Cesar_Cipher_Disk_UA.pdf\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">роздрукувати диск ↗</a>.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти шифруєш CAT ключем 1 і розшифровуєш HCT з Кроку 1.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше? Шифр Pigpen</summary>\n    <p style=\"margin:12px 0 0;\">У шифрі <b>Pigpen</b> літери замінюють не іншими літерами, а малюнками. Кожна літера стоїть у своїй клітинці сітки. Символ — це форма ліній навколо клітинки, а в другій і четвертій сітках ще й крапка.</p>\n    <svg viewBox=\"0 0 860 190\" role=\"img\" aria-labelledby=\"g4u8c-t g4u8c-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n      <title id=\"g4u8c-t\">Легенда шифру Pigpen</title>\n      <desc id=\"g4u8c-d\">Перша сітка три на три містить літери від A до I без крапок. Друга така сама сітка — літери від J до R, у кожній клітинці крапка. Третя фігура — косий хрест із літерами S угорі, T ліворуч, U праворуч, V унизу. Четвертий косий хрест — літери W, X, Y, Z з крапками.</desc>\n      <g stroke=\"#1A1A1A\" stroke-width=\"3\" fill=\"none\">\n        <path d=\"M70 20 V170 M120 20 V170 M20 70 H170 M20 120 H170\"></path>\n        <path d=\"M260 20 V170 M310 20 V170 M210 70 H360 M210 120 H360\"></path>\n        <path d=\"M410 25 L550 165 M550 25 L410 165\"></path>\n        <path d=\"M620 25 L760 165 M760 25 L620 165\"></path>\n      </g>\n      <g font-size=\"20\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\">\n        <text x=\"45\" y=\"52\">A</text><text x=\"95\" y=\"52\">B</text><text x=\"145\" y=\"52\">C</text>\n        <text x=\"45\" y=\"102\">D</text><text x=\"95\" y=\"102\">E</text><text x=\"145\" y=\"102\">F</text>\n        <text x=\"45\" y=\"152\">G</text><text x=\"95\" y=\"152\">H</text><text x=\"145\" y=\"152\">I</text>\n        <text x=\"235\" y=\"48\">J</text><text x=\"285\" y=\"48\">K</text><text x=\"335\" y=\"48\">L</text>\n        <text x=\"235\" y=\"98\">M</text><text x=\"285\" y=\"98\">N</text><text x=\"335\" y=\"98\">O</text>\n        <text x=\"235\" y=\"148\">P</text><text x=\"285\" y=\"148\">Q</text><text x=\"335\" y=\"148\">R</text>\n        <text x=\"480\" y=\"62\">S</text><text x=\"440\" y=\"102\">T</text><text x=\"520\" y=\"102\">U</text><text x=\"480\" y=\"148\">V</text>\n        <text x=\"690\" y=\"58\">W</text><text x=\"650\" y=\"98\">X</text><text x=\"730\" y=\"98\">Y</text><text x=\"690\" y=\"144\">Z</text>\n      </g>\n      <g fill=\"#1A1A1A\">\n        <circle cx=\"235\" cy=\"58\" r=\"3.5\"></circle><circle cx=\"285\" cy=\"58\" r=\"3.5\"></circle><circle cx=\"335\" cy=\"58\" r=\"3.5\"></circle>\n        <circle cx=\"235\" cy=\"108\" r=\"3.5\"></circle><circle cx=\"285\" cy=\"108\" r=\"3.5\"></circle><circle cx=\"335\" cy=\"108\" r=\"3.5\"></circle>\n        <circle cx=\"235\" cy=\"158\" r=\"3.5\"></circle><circle cx=\"285\" cy=\"158\" r=\"3.5\"></circle><circle cx=\"335\" cy=\"158\" r=\"3.5\"></circle>\n        <circle cx=\"690\" cy=\"66\" r=\"3.5\"></circle><circle cx=\"650\" cy=\"106\" r=\"3.5\"></circle><circle cx=\"730\" cy=\"106\" r=\"3.5\"></circle><circle cx=\"690\" cy=\"152\" r=\"3.5\"></circle>\n      </g>\n    </svg>\n    <p style=\"margin:10px 0 0;\">Наприклад, A стоїть у лівому верхньому куті: навколо неї лінії лише праворуч і знизу, тож її символ — <b>┘</b>. Літера E в центрі оточена з усіх боків, її символ — квадрат <b>□</b>.</p>\n    <p style=\"margin:10px 0 0;\"><b>Розшифруй</b> три символи:</p>\n    <svg viewBox=\"0 0 860 120\" role=\"img\" aria-labelledby=\"g4u8d-t g4u8d-d\" style=\"display:block;width:100%;height:auto;margin:12px 0;\">\n      <title id=\"g4u8d-t\">Три символи Pigpen для розшифрування</title>\n      <desc id=\"g4u8d-d\">Перший символ — форма літери U, відкрита згори, з крапкою всередині. Другий — повний квадрат без крапки. Третій — кут, схожий на знак «менше», відкритий праворуч, з крапкою всередині.</desc>\n      <g stroke=\"#1A1A1A\" stroke-width=\"4\" fill=\"none\">\n        <path d=\"M60 20 V80 H120 V20\"></path>\n        <path d=\"M200 20 H260 V80 H200 Z\"></path>\n        <path d=\"M400 20 L350 50 L400 80\"></path>\n      </g>\n      <g fill=\"#1A1A1A\"><circle cx=\"90\" cy=\"55\" r=\"5\"></circle><circle cx=\"385\" cy=\"50\" r=\"5\"></circle></g>\n      <g font-size=\"17\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\"><text x=\"90\" y=\"108\">1</text><text x=\"230\" y=\"108\">2</text><text x=\"375\" y=\"108\">3</text></g>\n    </svg>\n    <details style=\"background:#FFFFFF;border-radius:8px;padding:12px 14px;margin:10px 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Звірити</summary>\n      <p style=\"margin:10px 0 0;\"><b>KEY.</b> 1 — верхня середня клітинка другої сітки з крапкою: K. 2 — центр першої сітки: E. 3 — права частина хреста з крапкою: Y.</p>\n    </details>\n    <p style=\"margin:10px 0 0;\"><b>Зашифруй</b> слово <b>DATA</b> символами Pigpen і дай перевірити однокласникові.</p>\n    <details style=\"background:#FFFFFF;border-radius:8px;padding:12px 14px;margin:10px 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Звірити</summary>\n      <p style=\"margin:10px 0 0;\">D — <b>⊐</b> (лінії згори, праворуч і знизу), A — <b>┘</b>, T — <b>&gt;</b> (ліва частина хреста), A — <b>┘</b>.</p>\n    </details>\n    <p style=\"margin:10px 0 0;\"><b>Чому старі шифри легко зламати?</b> У шифрі Цезаря для латиниці лише 25 можливих ключів. Людина перебере їх за кілька хвилин, а комп'ютер — миттєво. Сучасні шифри мають стільки можливих ключів, що перебрати всі на практиці неможливо. Але й цього мало: потрібні перевірений алгоритм і надійно збережений ключ.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The key helps to decrypt the ciphertext.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Криптографія для дітей</b> пояснює основи, а два тренажери дають зашифрувати й розшифрувати повідомлення шифром Цезаря.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">15–20 хв • потрібен інтернет • один алфавіт і один ключ</p>\n    <a href=\"https://itnauka.org/services/security_and_safety/cryptography_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Відкрити урок ↗</a>\n    <a href=\"https://itnauka.org/services/security_and_safety/caesar_cipher/caesar_encrypt.html\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;margin:0 8px 8px 0;\">Зашифрувати ↗</a>\n    <a href=\"https://itnauka.org/services/security_and_safety/caesar_cipher/caesar_decrypt.html\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;\">Розшифрувати ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u8-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Зловмисник перехопив зашифрований лист. Що змінює шифрування?</label>\n    <select id=\"g4-u8-q1\" name=\"g4-u8-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Лист неможливо перехопити</option>\n      <option>Без ключа зміст листа не зрозуміти</option>\n      <option>Лист сам видаляється</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Без ключа зміст не зрозуміти. Перехопити шифрування не заважає, але перехоплений шифротекст виглядає як набір незрозумілих символів.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u8-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Що є ключем у шифрі Цезаря?</label>\n    <select id=\"g4-u8-q2\" name=\"g4-u8-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Перша літера повідомлення</option>\n      <option>Кількість кроків зсуву</option>\n      <option>Назва шифру</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Кількість кроків зсуву. Правило «зсувай літери» всі можуть знати — секретом лишається саме число.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u8-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. У шифрі Цезаря одну літеру зашифровано з помилкою. Що буде під час розшифрування?</label>\n    <select id=\"g4-u8-q3\" name=\"g4-u8-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Усе повідомлення стане незрозумілим</option>\n      <option>Неправильною вийде лише ця літера</option>\n      <option>Помилка виправиться сама</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Лише ця літера: у шифрі Цезаря кожну літеру шифрують окремо. Саме так у Кроці 3 вийшло SAV замість SAW. Тому результат варто перевіряти літера за літерою.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Шифрування не заважає перехопити повідомлення, але ___, бо без ключа ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я правильно розшифровую одне слово й шифрую інше.</li>\n      <li style=\"margin:8px 0;\">Я знаходжу помилку в чужому шифротексті.</li>\n      <li style=\"margin:8px 0;\">Я пояснюю роль ключа і називаю, де використовують шифрування.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> CAT з ключем 1 і розшифроване HCT.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> розв'язки Кроків 1–3 з перевіркою кожної літери та два речення про ключ.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>encrypt / decrypt</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">зашифрувати / розшифрувати</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>cipher</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">шифр, правило шифрування</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>key</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">ключ</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>plaintext</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">відкритий текст</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>ciphertext</b></td><td style=\"padding:8px 10px;\">шифротекст</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>We use encryption to make data secure. The key is the number of steps.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-1","grade":4,"module":2,"number":1,"title":"Дані та інформація: поля, записи і типи даних","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок9_Гра1_Типи-даних.html","title":"Обери тип даних","description":"сортування карток","data":{"id":"m2g9a","lesson":9,"tag":"ТИПИ","icon":"🧮","type":"sort","title":"Обери тип даних","file":"М2_Урок9_Гра1_Типи-даних.html","conceptName":"типи даних","concept":"Кожне поле таблиці має тип: текст, число, дата, «так/ні» або категорія. Тип підказує, що можна робити зі значенням. Номер телефону — це текст: з ним не рахують, і він може починатися з нуля.","skill":"визначати тип даних для значення: текст, число, дата, «так/ні» чи категорія","data":{"categories":[{"id":"txt","label":"🔤 Текст","hint":"слова, назви, номери телефонів"},{"id":"num","label":"🔢 Число","hint":"з ним можна рахувати"},{"id":"date","label":"📅 Дата","hint":"день, місяць і рік"},{"id":"yn","label":"✅ Так чи ні","hint":"лише дві відповіді"},{"id":"cat","label":"🏷 Категорія","hint":"один варіант з готового списку"}],"items":[{"text":"Ім'я: Оля","cat":"txt","explain":"Ім'я — це слово, тож це текст.","hint":"це слово, а не число"},{"text":"Вік: 10","cat":"num","explain":"З віком можна рахувати: хто старший, на скільки. Це число.","hint":"чи можна з цим рахувати?"},{"text":"Дата народження: 12.05.2015","cat":"date","explain":"День, місяць і рік — це дата.","hint":"тут є день, місяць і рік"},{"text":"Є домашній улюбленець: так","cat":"yn","explain":"Відповідь лише «так» або «ні» — це тип «так/ні».","hint":"скільки тут можливих відповідей?"},{"text":"Колір очей: карі","cat":"cat","explain":"Колір обирають зі списку варіантів: блакитні, карі, зелені. Це категорія.","hint":"це один варіант зі списку"},{"text":"Телефон: 050 123 45 67","cat":"txt","explain":"Телефон — це текст. Ми не додаємо номери між собою, а нуль на початку треба зберегти.","hint":"чи будемо ми рахувати з номером?"},{"text":"Кількість сторінок: 192","cat":"num","explain":"Сторінки рахують, тож це число.","hint":"з цим можна рахувати"},{"text":"День тижня: середа","cat":"cat","explain":"День обираємо зі списку із семи варіантів. Це категорія.","hint":"це варіант із готового списку"},{"text":"Прочитано книгу: ні","cat":"yn","explain":"Лише «так» або «ні» — тип «так/ні».","hint":"дві можливі відповіді"},{"text":"День бібліотеки: 03.10.2025","cat":"date","explain":"Конкретний день із місяцем і роком — це дата.","hint":"шукай день, місяць, рік"}]}},"after":{"index":3,"heading":"🔢 Типи даних"}},{"path":"app/games/М2_Урок9_Гра2_Поле-запис-значення.html","title":"Поле, запис, значення","description":"сценарний вибір","data":{"id":"m2g9b","lesson":9,"tag":"ЗАПИС","icon":"🗂️","type":"quiz","title":"Поле, запис, значення","file":"М2_Урок9_Гра2_Поле-запис-значення.html","conceptName":"поле, запис, значення","concept":"Таблиця даних має поля — стовпчики, наприклад «Автор». Рядок про один об'єкт — це запис. Те, що стоїть у комірці, — значення. Правила перевірки не пускають «брудні» дані, наприклад слова в поле для числа.","skill":"розрізняти поле, запис і значення та помічати «брудні» дані","data":{"questions":[{"q":"У таблиці «Бібліотека» є стовпчик «Автор». Що це?","options":["Поле","Запис","Значення"],"correct":0,"explain":"Стовпчик таблиці — це поле. Усі назви стовпчиків — поля таблиці."},{"q":"Рядок із відомостями про книгу «Кайдашева сім'я»: автор, рік, сторінки. Що це?","options":["Значення","Запис","Поле"],"correct":1,"explain":"Рядок про один об'єкт — це запис. Одна книга — один запис."},{"q":"У комірці написано: «Іван Нечуй-Левицький». Що це?","options":["Поле","Запис","Значення"],"correct":2,"explain":"Те, що стоїть у конкретній комірці, — значення."},{"q":"Учень записав дату повернення книги так: «минулого вівторка». У чому помилка?","options":["Це нормальна дата","«Минулого вівторка» — не дата, треба записати день, місяць і рік","Треба було написати англійською"],"correct":1,"explain":"«Минулого вівторка» залежить від того, коли читають. Поле «дата» потребує точного запису, наприклад 30.09.2025."},{"q":"У полі «Кількість сторінок» хтось написав: «сто дев'яносто дві». Яке правило перевірки допоможе?","options":["Дозволити будь-який текст","Поле має приймати лише число","Прибрати це поле"],"correct":1,"explain":"Правило «лише число» одразу попросить записати 192 цифрами. Так таблиця лишається чистою."},{"q":"Як краще зберігати номер телефону в таблиці?","options":["Як число, бо це цифри","Як текст","Як дату"],"correct":1,"explain":"Телефон — це текст: ми не рахуємо з ним, а нуль чи «+» на початку треба зберегти."}]}},"after":{"index":2,"heading":"🗂 Як влаштована таблиця даних"}}],"legacyTitle":"Урок 9. Дані та інформація: поля, записи, типи даних","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 9</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Дані та інформація: поля, записи і типи даних</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Data and Information: Fields, Records and Data Types</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: чому для кожного поля важливо обрати відповідний тип даних?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я розрізняю <b>data</b> (дані) та <b>information</b> (інформацію).</li>\n      <li style=\"margin:6px 0;\">Я знаходжу в таблиці <b>field</b>, <b>record</b> і <b>value</b>.</li>\n      <li style=\"margin:6px 0;\">Я добираю тип даних для поля й виправляю значення, що йому не відповідають.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📊 Дані й інформація</h2>\n  <p style=\"margin:0 0 12px;\"><b>Дані (data)</b> — це записані значення: числа, слова, дати, позначки «так» чи «ні». Наприклад, <b>1883</b> або <b>Пригоди</b>. Самі по собі вони мало що кажуть: 1883 — це рік? кількість сторінок? номер квитка?</p>\n  <p style=\"margin:0 0 12px;\">Коли дані впорядковані й мають контекст — підписи, назви стовпчиків, пояснення, — ми можемо їх витлумачити. Так з'являється <b>інформація (information)</b>: «Книжку „Острів скарбів“ видано у 1883 році, це пригодницький роман».</p>\n\n  <figure style=\"margin:18px 0 20px;background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px;\">\n    <img src=\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Wooden_Card_Catalog_Furniture.jpg?width=800\" alt=\"Дерев'яна шафа бібліотечного каталогу з рядами підписаних шухляд\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;max-height:410px;object-fit:contain;border-radius:8px;\">\n    <figcaption style=\"margin-top:9px;font-size:15px;line-height:1.45;color:#3D4757;\">Картковий каталог — база даних без комп'ютера: кожна картка є записом, а на кожній картці ті самі рубрики — назва, автор, рік. Фото: <a href=\"https://commons.wikimedia.org/wiki/File:Wooden_Card_Catalog_Furniture.jpg\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;\">MarkBuckawicki, Wikimedia Commons</a>, CC0.</figcaption>\n  </figure>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🗂 Як влаштована таблиця даних</h2>\n  <p style=\"margin:0 0 14px;\">Щоб зберігати багато даних і швидко знаходити потрібне, люди створюють <b>бази даних (databases)</b>. Часто дані в них зберігаються в таблицях.</p>\n\n  <svg viewBox=\"0 0 860 300\" role=\"img\" aria-labelledby=\"g4u9a-t g4u9a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u9a-t\">Поле, запис і значення в таблиці бібліотеки</title>\n    <desc id=\"g4u9a-d\">Таблиця з трьох книжок і чотирьох стовпчиків: назва, жанр, рік, чи є в наявності. Виділено рядок про «Острів скарбів» — це запис. Виділено стовпчик «Жанр» — це поле. Виділено одну клітинку з числом 1892 — це значення.</desc>\n    <rect x=\"10\" y=\"14\" width=\"840\" height=\"44\" rx=\"8\" fill=\"#0033A0\"></rect>\n    <g font-size=\"16\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">\n      <text x=\"30\" y=\"42\">Назва</text><text x=\"330\" y=\"42\">Жанр</text><text x=\"520\" y=\"42\">Рік</text><text x=\"680\" y=\"42\">В наявності</text>\n    </g>\n    <rect x=\"10\" y=\"62\" width=\"840\" height=\"40\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#D9E2F0\"></rect>\n    <rect x=\"10\" y=\"106\" width=\"840\" height=\"40\" rx=\"6\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"3\"></rect>\n    <rect x=\"10\" y=\"150\" width=\"840\" height=\"40\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#D9E2F0\"></rect>\n    <g font-size=\"16\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">\n      <text x=\"30\" y=\"88\">Маленький принц</text><text x=\"330\" y=\"88\">Казка</text><text x=\"520\" y=\"88\">1943</text><text x=\"680\" y=\"88\">Так</text>\n      <text x=\"30\" y=\"132\" font-weight=\"700\">Острів скарбів</text><text x=\"330\" y=\"132\" font-weight=\"700\">Пригоди</text><text x=\"520\" y=\"132\" font-weight=\"700\">1883</text><text x=\"680\" y=\"132\" font-weight=\"700\">Ні</text>\n      <text x=\"30\" y=\"176\">Шерлок Холмс</text><text x=\"330\" y=\"176\">Детектив</text><text x=\"680\" y=\"176\">Так</text>\n    </g>\n    <rect x=\"506\" y=\"154\" width=\"90\" height=\"32\" rx=\"6\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"3\"></rect>\n    <text x=\"520\" y=\"176\" font-size=\"16\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">1892</text>\n    <rect x=\"316\" y=\"10\" width=\"140\" height=\"184\" rx=\"8\" fill=\"none\" stroke=\"#1B6B3A\" stroke-width=\"3\" stroke-dasharray=\"8 6\"></rect>\n\n    <text x=\"130\" y=\"232\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">RECORD • запис</text>\n    <text x=\"130\" y=\"256\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">рядок про один об'єкт</text>\n    <text x=\"386\" y=\"232\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#155C32\" font-family=\"Arial, sans-serif\">FIELD • поле</text>\n    <text x=\"386\" y=\"256\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">стовпчик однієї ознаки</text>\n    <text x=\"640\" y=\"232\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">VALUE • значення</text>\n    <text x=\"640\" y=\"256\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">дані в одній клітинці</text>\n  </svg>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Поле (field)</b> — стовпчик. Він містить одну ознаку для всіх об'єктів, наприклад лише жанри. Кожне поле має назву й тип даних.</li>\n    <li style=\"margin:8px 0;\"><b>Запис (record)</b> — рядок. Він збирає всі дані про один об'єкт, наприклад усе про «Острів скарбів».</li>\n    <li style=\"margin:8px 0;\"><b>Значення (value)</b> — дані в одній клітинці, на перетині поля й запису. Число 1892 — значення поля «Рік» для книжки «Шерлок Холмс».</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔢 Типи даних</h2>\n  <p style=\"margin:0 0 12px;\">Для кожного поля обирають <b>тип даних (data type)</b> — який вид значень там зберігатиметься:</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 230px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>Текст (text)</b> — слова й символи: «Льюїс Керролл».</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>Число (number)</b> — те, що рахують чи порівнюють: 192.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>Дата (date)</b> — день, місяць, рік: 12.10.2025.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>Так/Ні (yes/no)</b> — лише два варіанти.</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\"><b>Категорія (category)</b> — вибір зі списку: «Пригоди», «Казка».</p></div>\n  </div>\n  <p style=\"margin:0 0 12px;\">У звичайній електронній таблиці в клітинку часто можна ввести що завгодно. Але якщо в поле «Кількість сторінок» записати «192 сторінки», програма сприйме це як текст. Тоді вона не зможе правильно впорядкувати книжки за товщиною чи порахувати середню кількість сторінок.</p>\n  <p style=\"margin:0 0 12px;\">Те саме стосується й програм зі штучним інтелектом: вони аналізують дані лише настільки добре, наскільки дозволяють самі дані й чіткість завдання. Відповідний тип для кожного поля — перший крок до корисної інформації.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй</h2>\n  <p style=\"margin:0 0 8px;\">Подивись на схему таблиці й запиши:</p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\">Слово «Пригоди» у стовпчику «Жанр» — це поле, запис чи значення?</li>\n    <li style=\"margin:6px 0;\">Увесь рядок про «Острів скарбів» — це поле, запис чи значення?</li>\n  </ol>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\">1 — значення: це дані в одній клітинці. 2 — запис: рядок збирає все про одну книжку.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">Ось частина вигаданої таблиці шкільної бібліотеки. Хтось заповнював її поспіхом.</p>\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:640px;font-size:16px;\">\n      <thead><tr>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">ID</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Назва</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Автор</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Рік видання</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Сторінок</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Дата видачі</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Повернуто?</th>\n      </tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Аліса в Країні Див</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Льюїс Керролл</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1865</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">192 сторінки</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">12.10.2025</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Так</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Пригоди Мюнхгаузена</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Рудольф Распе</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1785</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">312</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">минулого вівторка</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Ні</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">3</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Том Сойєр</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Марк Твен</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">стародавня книга</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">240</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">18.10.2025</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Так</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">4</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Робінзон Крузо</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Даніель Дефо</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1719</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">320</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">20.10.2025</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">можливо</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Знайди чотири значення, які не відповідають типу свого поля. Запиши ID і назву поля для кожного.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Запиши виправлене значення для кожної з чотирьох клітинок. «Том Сойєр» вийшов у 1876 році; дату видачі для ID 2 придумай сам чи сама у форматі ДД.ММ.РРРР.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Обери тип даних (текст, число, дата, так/ні, категорія) для семи полів:</p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:5px 0;\">Рейтинг книжки від 1 до 5</li>\n    <li style=\"margin:5px 0;\">Дата народження автора</li>\n    <li style=\"margin:5px 0;\">Чи є електронна версія</li>\n    <li style=\"margin:5px 0;\">Ім'я ілюстратора</li>\n    <li style=\"margin:5px 0;\">Скільки разів книжку брали</li>\n    <li style=\"margin:5px 0;\">Мова книжки (українська, англійська, польська)</li>\n    <li style=\"margin:5px 0;\">День початку канікул</li>\n  </ol>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4.</b> Користуючись лише записом з ID 4, дай відповідь: скільки сторінок у книжці, виданій 1719 року?</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 1–2.</b> ID 1, «Сторінок»: 192. ID 2, «Дата видачі»: будь-яка дата, наприклад 14.10.2025. ID 3, «Рік видання»: 1876. ID 4, «Повернуто?»: Так або Ні — «можливо» не підходить.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> 1 — число; 2 — дата; 3 — так/ні; 4 — текст; 5 — число; 6 — категорія; 7 — дата.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> 320 сторінок.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Читай таблицю по стовпчиках. Для кожного поля спитай: <i>«Що тут має бути — число, дата, текст чи так/ні?»</i> Потім шукай клітинку, яка випадає з ряду.</p>\n    <p style=\"margin:10px 0 0;\">Наприклад, у полі «Сторінок» усі значення — числа, крім одного. Саме воно й помилкове.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти знаходиш дві помилки з чотирьох, добираєш тип для полів 1–4 і відповідаєш на Крок 4.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Бази даних уміють не допускати помилок ще під час введення. Для цього задають <b>правило перевірки (validation rule)</b>: якщо значення йому не відповідає, програма попереджає і не зберігає запис.</p>\n    <p style=\"margin:10px 0 0;\">Придумай правило для поля «Рік видання». Які числа воно має приймати? Від якої помилки воно захистить — наприклад, від року з майбутнього чи від слів замість числа?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The validation rule stops a wrong value.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Дані та інформація</b> і <b>Що таке типи даних</b> — два короткі інтерактивні уроки. Виконуй за бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв кожен • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/digital_literacy/data-and-information/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Дані та інформація ↗</a>\n    <a href=\"https://itnauka.org/services/coding/types/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;\">Типи даних ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u9-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Який тип даних краще для поля «Номер телефону»?</label>\n    <select id=\"g4-u9-q1\" name=\"g4-u9-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Число — там самі цифри</option>\n      <option>Текст — номери не рахують, а ще там буває «+» і пробіли</option>\n      <option>Дата</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Текст. Номери телефонів не додають і не порівнюють за величиною, а знак «+» і нуль на початку числовий тип може загубити.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u9-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Один рядок з усіма даними про одного читача — це…</label>\n    <select id=\"g4-u9-q2\" name=\"g4-u9-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Поле</option>\n      <option>Запис</option>\n      <option>Значення</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Запис (record): рядок збирає всі дані про один об'єкт.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u9-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. У поле «Сторінок» записали слово «триста». Що найімовірніше станеться?</label>\n    <select id=\"g4-u9-q3\" name=\"g4-u9-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Програма сама перетворить його на 300</option>\n      <option>Значення збережеться як текст, і сортування чи підрахунок будуть неправильні</option>\n      <option>Таблиця зникне</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Програма не здогадається, що «триста» означає 300. Деякі бази даних одразу покажуть помилку, а електронна таблиця просто збереже текст — і розрахунки з цим полем зіб'ються.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку на прикладі:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Для поля „Сторінок“ потрібен тип ___, бо ___. Якщо записати „300 сторінок“, то ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я пояснюю різницю між даними та інформацією на прикладі.</li>\n      <li style=\"margin:8px 0;\">Я знаходжу й виправляю чотири невідповідні значення.</li>\n      <li style=\"margin:8px 0;\">Я правильно добираю тип щонайменше для 6 із 7 полів і відповідаю на питання за записом ID 4.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> дві помилки, типи для полів 1–4 і відповідь на Крок 4.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> записи до Кроків 1–4 у зошиті або в LMS.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>data / information</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">дані / інформація</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>field</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">поле, стовпчик</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>record</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">запис, рядок</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>value</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">значення</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>data type</b></td><td style=\"padding:8px 10px;\">тип даних</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The table has fields and records. This field needs a number data type because it stores a count.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-2","grade":4,"module":2,"number":2,"title":"Кодування, типи файлів і розмір даних","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок10_Гра1_Який-це-файл.html","title":"Який це файл?","description":"сортування карток","data":{"id":"m2g10a","lesson":10,"tag":"ФАЙЛИ","icon":"📁","type":"sort","title":"Який це файл?","file":"М2_Урок10_Гра1_Який-це-файл.html","conceptName":"типи файлів","concept":"Розширення в кінці назви підказує тип файлу. Текст: .txt, .docx. Зображення: .png, .jpg. Звук: .mp3, .wav. Відео: .mp4. Проєкт Scratch: .sb3. Картинка, яку згенерував ШІ, — це теж файл .png чи .jpg.","skill":"розпізнавати тип файлу за його розширенням","data":{"categories":[{"id":"txt","label":"📝 Текст","hint":"текстові файли: .txt, .docx"},{"id":"img","label":"🖼 Зображення","hint":"зображення: .png, .jpg"},{"id":"snd","label":"🎵 Звук","hint":"звук: .mp3, .wav"},{"id":"vid","label":"🎬 Відео","hint":"відео: .mp4"},{"id":"prg","label":"🐱 Проєкт Scratch","hint":"проєкти Scratch: .sb3"}],"items":[{"text":"доповідь.docx","cat":"txt","explain":".docx — текстовий документ.","hint":"подивись на літери після крапки"},{"text":"нотатки.txt","cat":"txt","explain":".txt — простий текстовий файл.","hint":"подивись на розширення"},{"text":"фото_кота.jpg","cat":"img","explain":".jpg — файл зображення.","hint":"це картинка"},{"text":"схема.png","cat":"img","explain":".png — файл зображення.","hint":"це картинка"},{"text":"пісня.mp3","cat":"snd","explain":".mp3 — звуковий файл.","hint":"це можна слухати"},{"text":"дзвінок.wav","cat":"snd","explain":".wav — звуковий файл.","hint":"це можна слухати"},{"text":"урок_біології.mp4","cat":"vid","explain":".mp4 — відеофайл.","hint":"це можна дивитися як фільм"},{"text":"гра_котик.sb3","cat":"prg","explain":".sb3 — проєкт, який відкривається у Scratch.","hint":"це відкривають у Scratch"},{"text":"картинка_від_ШІ.png","cat":"img","explain":"Картинка, згенерована ШІ, — це звичайний файл зображення, .png чи .jpg.","hint":"ШІ-картинка — це теж картинка"},{"text":"розклад.docx","cat":"txt","explain":".docx — текстовий документ.","hint":"подивись на розширення"}]}},"after":{"index":2,"heading":"📁 Тип файлу і розширення"}},{"path":"app/games/М2_Урок10_Гра2_Сходинки-розміру.html","title":"Сходинки розміру","description":"послідовність кроків","data":{"id":"m2g10b","lesson":10,"tag":"РОЗМІР","icon":"🪜","type":"order","title":"Сходинки розміру","file":"М2_Урок10_Гра2_Сходинки-розміру.html","conceptName":"розмір файлів","concept":"Розмір файлу вимірюють у байтах: кілобайти (КБ), мегабайти (МБ). 1 МБ — це приблизно 1000 КБ. Текст крихітний, зображення більші, звук ще більший, а відео — найважче. Стиснення робить файл меншим.","skill":"порівнювати розміри файлів і пояснювати, чому вони різні","data":{"rounds":[{"title":"Розстав файли від найменшого до найбільшого","steps":["лист.txt — 2 КБ","гра.sb3 — 350 КБ","світлина.png — 4,8 МБ","пісня.mp3 — 8,5 МБ","фільм.mp4 — 120 МБ"],"hint":"спочатку кілобайти, потім мегабайти; 1 МБ — це близько 1000 КБ","explain":"Текст найлегший, далі проєкт Scratch, зображення, звук, а відео — найважче."},{"title":"Розстав за розміром: від найменшого","steps":["нотатка.txt — 1 КБ","іконка.png — 60 КБ","доповідь.docx — 200 КБ","музика.mp3 — 5 МБ","мультик.mp4 — 90 МБ"],"hint":"порівнюй одиниці: КБ менші за МБ","explain":"Спочатку всі кілобайтові файли від меншого до більшого, потім мегабайтові."},{"title":"Розстав за розміром: від найбільшого до найменшого","steps":["відео.mp4 — 150 МБ","подкаст.mp3 — 12 МБ","плакат.png — 3 МБ","гравці.sb3 — 400 КБ","список.txt — 3 КБ"],"hint":"тепер починаємо з найважчого файлу","explain":"Відео найбільше, далі звук, зображення, проєкт і крихітний текст."}]}},"after":{"index":3,"heading":"📏 Чому розміри такі різні"}},{"path":"app/games/М2_Урок10_Гра3_Нулі-та-одиниці.html","title":"Нулі та одиниці","description":"сценарний вибір","data":{"id":"m2g10c","lesson":10,"tag":"БІТИ","icon":"🔢","type":"quiz","title":"Нулі та одиниці","file":"М2_Урок10_Гра3_Нулі-та-одиниці.html","conceptName":"двійковий код","concept":"Комп'ютер зберігає все — текст, картинки, звук, відео — як послідовність нулів та одиниць. Найменша частинка такої інформації — біт: він може бути 0 або 1. Піксель — це точка зображення; чим більше пікселів, тим детальніша картинка і більший файл.","skill":"пояснювати, що файли зберігаються двійковим кодом, а розмір зображення залежить від пікселів","data":{"questions":[{"q":"Що таке біт?","options":["Найменша частинка даних: 0 або 1","Маленька програма","Частина екрана"],"correct":0,"explain":"Біт — це найменша одиниця даних. Він має лише два стани: 0 чи 1."},{"q":"Як комп'ютер зберігає пісню?","options":["У вигляді нот","Як послідовність нулів та одиниць","У вигляді малюнка"],"correct":1,"explain":"Усе в комп'ютері — двійковий код: і пісня, і текст, і відео."},{"q":"Що таке піксель?","options":["Одна точка зображення","Програма для малювання","Тип файлу"],"correct":0,"explain":"Зображення складається з точок — пікселів. Роздільна здатність каже, скільки їх."},{"q":"Дві фотографії одного двору. Одна має більше пікселів. Яка вона?","options":["Детальніша і файл більший","Менш детальна і файл менший","Ніяк не відрізняється"],"correct":0,"explain":"Більше пікселів — детальніша картинка, але й файл важчий."},{"q":"Навіщо стискають файли?","options":["Щоб файл займав менше місця","Щоб файл відкривався довше","Щоб змінити тип файлу"],"correct":0,"explain":"Стиснення зменшує розмір файлу — його легше зберігати й надсилати."},{"q":"ШІ згенерував картинку для пам'ятки. Якого типу буде файл?","options":["Особливий тип «ШІ»","Звичайне зображення: .png або .jpg","Текстовий .txt"],"correct":1,"explain":"ШІ-картинка — це теж файл зображення. Магічного типу «ШІ» не існує."}]}},"after":{"index":1,"heading":"💡 Нулі й одиниці"}}],"legacyTitle":"Урок 10. Кодування, типи файлів і розмір даних","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 10</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Кодування, типи файлів і розмір даних</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Encoding, File Types and Data Size</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: чому фото чи відео займає набагато більше місця, ніж текст?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я визначаю тип файлу (<b>file type</b>) за розширенням.</li>\n      <li style=\"margin:6px 0;\">Я прогнозую, який файл більший, і перевіряю свій прогноз.</li>\n      <li style=\"margin:6px 0;\">Я пояснюю, як <b>resolution</b> і стиснення змінюють розмір файлу та якість.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">💡 Нулі й одиниці</h2>\n  <p style=\"margin:0 0 12px;\">Фото, пісня, текст і гра на екрані виглядають зовсім по-різному. Але всередині комп'ютера все це зберігається однаково — як дані. Комп'ютери представляють дані двома станами, які ми позначаємо <b>0</b> і <b>1</b>. Це <b>двійковий код (binary)</b>, а одна така цифра називається <b>біт (bit)</b>.</p>\n  <p style=\"margin:0 0 12px;\">Щоб зберегти щось складне, потрібно багато бітів. Чим більше деталей у файлі, тим більше бітів — і тим більший <b>розмір файлу (file size)</b>.</p>\n\n  <figure style=\"margin:18px 0 20px;background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px;\">\n    <img src=\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Nexus_one_screen_microscope.jpg?width=800\" alt=\"Екран смартфона під мікроскопом: видно окремі червоні, зелені та сині точки\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;max-height:410px;object-fit:contain;border-radius:8px;\">\n    <figcaption style=\"margin-top:9px;font-size:15px;line-height:1.45;color:#3D4757;\">Екран під мікроскопом. Картинка, яку ми бачимо суцільною, складена з дрібних точок — пікселів, і колір кожної треба зберегти у файлі. Фото: <a href=\"https://commons.wikimedia.org/wiki/File:Nexus_one_screen_microscope.jpg\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;\">Matthew Rollings, Wikimedia Commons</a>, CC BY 3.0.</figcaption>\n  </figure>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📁 Тип файлу і розширення</h2>\n  <p style=\"margin:0 0 12px;\">Назва файлу часто закінчується крапкою і кількома літерами — це <b>розширення (file extension)</b>. Воно підказує, у якому форматі збережено файл і якою програмою його відкрити.</p>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 230px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\">📄 <b>.txt, .docx</b> — текст</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\">🖼️ <b>.png, .jpg</b> — зображення</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\">🎵 <b>.mp3, .wav</b> — звук</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\">🎬 <b>.mp4</b> — відео</p></div>\n    <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:14px 16px;\"><p style=\"margin:0;\">🎮 <b>.sb3</b> — проєкт Scratch</p></div>\n  </div>\n  <p style=\"margin:0 0 12px;\">Розширення — лише підказка. Якщо перейменувати фото з <b>.jpg</b> на <b>.txt</b>, воно не стане текстом: вміст файлу не зміниться, просто програма не зрозуміє, як його відкрити.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📏 Чому розміри такі різні</h2>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Текст</b> зберігає лише знаки, тому зазвичай потребує набагато менше даних, ніж фото, звук чи відео.</li>\n    <li style=\"margin:8px 0;\"><b>Зображення</b> складається з пікселів, і для кожного треба зберегти колір. Кількість пікселів називають <b>роздільною здатністю (resolution)</b>.</li>\n    <li style=\"margin:8px 0;\"><b>Звук і відео</b> змінюються щомиті: у відео — десятки кадрів-картинок щосекунди. Тому це зазвичай найбільші файли.</li>\n  </ul>\n\n  <svg viewBox=\"0 0 860 260\" role=\"img\" aria-labelledby=\"g4u10a-t g4u10a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u10a-t\">Та сама картинка з різною роздільною здатністю</title>\n    <desc id=\"g4u10a-d\">Три однакові квадрати з жовтим колом. Перший поділено на 4 на 4 — 16 пікселів. Другий на 8 на 8 — 64 пікселі. Третій на 16 на 16 — 256 пікселів. Що більше пікселів, то чіткіша картинка і то більше даних треба зберегти.</desc>\n    <g fill=\"#FFF9DB\" stroke=\"#0033A0\" stroke-width=\"2\">\n      <rect x=\"60\" y=\"40\" width=\"160\" height=\"160\"></rect><rect x=\"350\" y=\"40\" width=\"160\" height=\"160\"></rect><rect x=\"640\" y=\"40\" width=\"160\" height=\"160\"></rect>\n    </g>\n    <g fill=\"#FFD700\"><circle cx=\"140\" cy=\"120\" r=\"55\"></circle><circle cx=\"430\" cy=\"120\" r=\"55\"></circle><circle cx=\"720\" cy=\"120\" r=\"55\"></circle></g>\n    <g stroke=\"#0033A0\" stroke-width=\"1\" fill=\"none\" opacity=\"0.6\">\n      <path d=\"M100 40V200M60 80H220M140 40V200M60 120H220M180 40V200M60 160H220\"></path>\n      <path d=\"M370 40V200M350 60H510M390 40V200M350 80H510M410 40V200M350 100H510M430 40V200M350 120H510M450 40V200M350 140H510M470 40V200M350 160H510M490 40V200M350 180H510\"></path>\n      <path d=\"M650 40V200M640 50H800M660 40V200M640 60H800M670 40V200M640 70H800M680 40V200M640 80H800M690 40V200M640 90H800M700 40V200M640 100H800M710 40V200M640 110H800M720 40V200M640 120H800M730 40V200M640 130H800M740 40V200M640 140H800M750 40V200M640 150H800M760 40V200M640 160H800M770 40V200M640 170H800M780 40V200M640 180H800M790 40V200M640 190H800\"></path>\n    </g>\n    <g font-size=\"16\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\">\n      <text x=\"140\" y=\"228\">16 пікселів</text><text x=\"430\" y=\"228\">64 пікселі</text><text x=\"720\" y=\"228\">256 пікселів</text>\n    </g>\n    <text x=\"430\" y=\"252\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">більше пікселів → чіткіша картинка → більше даних</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Файл можна зменшити двома способами. Можна знизити роздільну здатність — зробити менше пікселів. А можна застосувати <b>стиснення (compression)</b>: програма зберігає дані коротше, інколи жертвуючи дрібними деталями. Менший файл швидше пересилати, але якість може погіршитися. Тому версію обирають за метою: для сайту, для друку чи для листа.</p>\n\n  <div style=\"background:#FFF2F2;border-left:5px solid #C0392B;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Важливо.</b> «ШІ» — не тип файлу: картинка, створена штучним інтелектом, зберігається як звичайний .png чи .jpg. І не завантажуй шкільні фото чи відео на незнайомі сайти для стиснення — лише в програми, які дозволив учитель.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: закодуй картинку</h2>\n  <p style=\"margin:0 0 12px;\">Намалюй у зошиті сітку 5×5. Зафарбуй клітинки, де стоїть <b>1</b>, а клітинки з <b>0</b> залиш білими. Рядки йдуть згори вниз.</p>\n  <div style=\"background:#F0F4F8;border-radius:8px;padding:12px 16px;margin:12px 0;font-family:'Courier New',monospace;font-size:18px;line-height:1.5;\">1 0 0 0 1<br>0 1 0 1 0<br>0 0 1 0 0<br>0 1 0 1 0<br>1 0 0 0 1</div>\n  <p style=\"margin:0 0 12px;\">Яку літеру видно на сітці? Скільки нулів і одиниць знадобилося, щоб її зберегти? А скільки знадобилося б для сітки 10×10?</p>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\">Літера X. Знадобилося 25 цифр — по одній на клітинку. Для сітки 10×10 — уже 100. А кольорова картинка потребує ще більше, бо для кожного пікселя треба зберегти не «чорне чи біле», а колір.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">Учитель зібрав файли зі шкільного свята:</p>\n  <p style=\"margin:0 0 12px;font-family:'Courier New',monospace;font-size:17px;line-height:1.7;\">school_report.txt • choir_song.mp3 • class_photo.png • anthem_video.mp4 • quiz_game.sb3</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Для кожного файлу запиши розширення й тип: текст, зображення, звук, відео чи проєкт гри.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Спрогнозуй, у якому порядку вони йдуть за розміром — від найменшого до найбільшого. Запиши прогноз і одне речення, чому ти так думаєш. Лише потім відкрий таблицю справжніх розмірів або подивись розміри у властивостях файлів, якщо вчитель дав папку.</p>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Відкрити таблицю розмірів — після прогнозу</summary>\n    <div style=\"overflow-x:auto;margin:12px 0 0;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:420px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">school_report.txt</td><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">2 КБ</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">quiz_game.sb3</td><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">350 КБ</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">class_photo.png</td><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">4,8 МБ</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">choir_song.mp3</td><td style=\"padding:8px 10px;border-bottom:1px solid #D9E2F0;\">8,5 МБ</td></tr>\n          <tr><td style=\"padding:8px 10px;\">anthem_video.mp4</td><td style=\"padding:8px 10px;\">120 МБ</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:10px 0 0;\">МБ — набагато більша одиниця, ніж КБ. У твоїх файлів числа можуть бути іншими: розмір залежить від тривалості, роздільної здатності та стиснення.</p>\n  </details>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Порівняй прогноз із таблицею. Який прогноз справдився, а який ні? Запиши один сюрприз.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4.</b> На флешці мало місця. Запиши: як зменшити <b>class_photo.png</b>? Що станеться з якістю? Чи годиться стиснене фото для великого плаката? Як зменшити <b>choir_song.mp3</b>?</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити Кроки 1 і 4</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> .txt — текст; .mp3 — звук; .png — зображення; .mp4 — відео; .sb3 — проєкт гри Scratch.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Фото: зменшити роздільну здатність або стиснути, наприклад зберегти як .jpg. Якість знизиться, для великого плаката таке фото може бути розмитим. Пісню: вирізати лише потрібну частину або зберегти з нижчою якістю звуку.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Для прогнозу порахуй «деталі» у файлі: текст — це лише літери; фото — мільйони кольорових точок; відео — багато фото щосекунди разом зі звуком.</p>\n    <p style=\"margin:10px 0 0;\">Типи файлів підкаже список розширень вище. Завдання виконано, якщо ти робиш Кроки 1 і 2.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Дві версії плаката.</b> Версія А — poster_print.png, 15 МБ, дуже висока якість. Версія Б — poster_web.jpg, 180 КБ, стиснена. Яку поставиш на шкільний сайт, щоб сторінка швидко відкривалася на телефоні? Яку віддаси в друкарню для великого банера? Поясни обидва вибори.</p>\n    <p style=\"margin:10px 0 0;\"><b>Двійкові картки.</b> Картки мають 8, 4, 2 і 1 крапку. Відкрита картка — 1, закрита — 0. Число 5 — це картки 4 і 1: <b>0101</b>. Як записати 6? А 9?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The photo is larger because it has more pixels.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Піксель Арт</b> — закодуй малюнок по клітинках. <b>Бітовий конвертер</b> — подивись, як число виглядає двійковим кодом. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">5–20 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/offline_activities/pixelart/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Піксель Арт ↗</a>\n    <a href=\"https://itnauka.org/tools/bit_converter/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;\">Бітовий конвертер ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u10-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Який файл зазвичай найменший?</label>\n    <select id=\"g4-u10-q1\" name=\"g4-u10-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Коротке відео .mp4</option>\n      <option>Коротка записка .txt</option>\n      <option>Фото .png</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Записка .txt. Текст зазвичай потребує набагато менше даних. Але слово «зазвичай» важливе: дуже довгий текст може бути більшим за крихітну картинку.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u10-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Що таке роздільна здатність зображення?</label>\n    <select id=\"g4-u10-q2\" name=\"g4-u10-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Швидкість, з якою відкривається картинка</option>\n      <option>Кількість пікселів у зображенні</option>\n      <option>Назва програми для малювання</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Кількість пікселів. Більше пікселів — чіткіша картинка й більший файл.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u10-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Картинку створив ШІ. Яке розширення матиме файл?</label>\n    <select id=\"g4-u10-q3\" name=\"g4-u10-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Особливе розширення .ai</option>\n      <option>Звичайне розширення зображення, наприклад .png чи .jpg</option>\n      <option>Жодного розширення</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Звичайне розширення зображення. ШІ — спосіб створити вміст, а не тип файлу, тож для такої картинки діють ті самі правила розміру й стиснення.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Фото займає більше місця, ніж текст, бо ___. Щоб зменшити фото, можна ___, але тоді ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я правильно визначаю тип усіх п'яти файлів.</li>\n      <li style=\"margin:8px 0;\">Мій прогноз розміру записаний до перевірки й має пояснення.</li>\n      <li style=\"margin:8px 0;\">Я називаю спосіб зменшити фото й пояснюю, що станеться з якістю.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> Кроки 1 і 2.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> записи до Кроків 1–4 у зошиті.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>file type</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">тип файлу</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>file extension</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">розширення файлу</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>file size</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">розмір файлу</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>resolution</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">роздільна здатність</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>compression</b></td><td style=\"padding:8px 10px;\">стиснення</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>A video file is usually larger than a text file. If we reduce the resolution, the file size decreases.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-3","grade":4,"module":2,"number":3,"title":"Бази даних і форми: структура, збирання та приватність","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок11_Гра1_Питати-чи-не-питати.html","title":"Питати чи не питати?","description":"сортування карток","data":{"id":"m2g11a","lesson":11,"tag":"ФОРМА","icon":"📋","type":"sort","title":"Питати чи не питати?","file":"М2_Урок11_Гра1_Питати-чи-не-питати.html","conceptName":"мінімізація даних","concept":"Форма має збирати лише ті дані, які справді потрібні для її мети. Це правило називають мінімізацією даних. Домашню адресу, телефон, паролі й фото без потреби не збирають. Обов'язкові поля позначають зірочкою *.","skill":"вирішувати, які дані форма може збирати, а які — зайві","data":{"categories":[{"id":"ok","label":"✅ Потрібно для мети","hint":"без цього форма не виконає свою мету"},{"id":"no","label":"🚫 Зайве — не збираємо","hint":"це особисте або не потрібне для мети"}],"items":[{"text":"Форма читацького гуртка питає: «Твоє ім'я»","cat":"ok","explain":"Ім'я потрібне, щоб знати, хто в гуртку.","hint":"чи треба гуртку знати, хто ти?"},{"text":"Форма читацького гуртка питає: «Твоя домашня адреса»","cat":"no","explain":"Адреса не потрібна для читацького гуртка. Зайві особисті дані не збирають.","hint":"чи потрібна адреса, щоб читати книги?"},{"text":"Форма питає: «Твій клас»","cat":"ok","explain":"Клас потрібен, щоб організувати зустрічі гуртка.","hint":"це допомагає організувати гурток"},{"text":"Форма питає: «Пароль від твоєї пошти»","cat":"no","explain":"Паролі взагалі нікому не повідомляють. Формі він тим паче не потрібен.","hint":"пароль — це секрет"},{"text":"Форма питає: «Улюблений жанр книг»","cat":"ok","explain":"Це потрібно саме для мети читацького гуртка — обирати цікаві книги.","hint":"це пов'язано з метою гуртка"},{"text":"Форма питає: «Телефон твоїх батьків»","cat":"no","explain":"Це зайві особисті дані. Для справ з батьками є вчитель.","hint":"це особисті дані, і без них можна обійтися"},{"text":"Форма питає: «Скільки книг ти прочитав цього місяця?»","cat":"ok","explain":"Це допомагає гуртку планувати роботу. Дані стосуються мети.","hint":"це корисно для мети гуртка"},{"text":"Форма питає: «Твоє фото для анкети»","cat":"no","explain":"Фото тут непотрібне. Збираємо лише те, без чого не обійтися.","hint":"чи можна обійтися без цього?"}]}},"after":{"index":3,"heading":"🛡 Збирай лише потрібне"}},{"path":"app/games/М2_Урок11_Гра2_Як-влаштована-форма.html","title":"Як влаштована форма","description":"сценарний вибір","data":{"id":"m2g11b","lesson":11,"tag":"АНКЕТА","icon":"⭐","type":"quiz","title":"Як влаштована форма","file":"М2_Урок11_Гра2_Як-влаштована-форма.html","conceptName":"форма і таблиця","concept":"Форма збирає відповіді й одразу складає їх у таблицю. Питання форми стає полем таблиці, заповнена анкета однієї людини — записом, а відповідь на питання — значенням. Зірочка * позначає обов'язкове поле.","skill":"пояснювати, як відповіді з форми перетворюються на таблицю","data":{"questions":[{"q":"Питання форми «Твоє ім'я?» стане в таблиці…","options":["полем — стовпчиком «Ім'я»","записом","значенням"],"correct":0,"explain":"Кожне питання форми — це поле (стовпчик) у таблиці."},{"q":"Однокласник заповнив анкету цілком. У таблиці це буде…","options":["нове поле","один запис — рядок","тип даних"],"correct":1,"explain":"Одна заповнена анкета — один запис, тобто рядок у таблиці."},{"q":"Відповідь «синій» на питання про улюблений колір — це…","options":["поле","запис","значення"],"correct":2,"explain":"Конкретна відповідь у комірці — це значення."},{"q":"Що означає зірочка * біля поля форми?","options":["Поле необов'язкове","Поле обов'язкове — без нього форму не надішлеш","Поле для вчителя"],"correct":1,"explain":"Зірочка позначає обов'язкове поле. Інші поля можна пропустити."},{"q":"Яка перевага форми перед опитуванням на папері?","options":["Відповіді одразу збираються в таблицю","Форму не треба продумувати","Форма завжди коротша"],"correct":0,"explain":"Форма одразу збирає відповіді в таблицю — швидко й без переписування."},{"q":"Який недолік форми?","options":["Вона працює без інтернету","У формі не можна пояснити свою відповідь, як у розмові","Форма повільніша за папір"],"correct":1,"explain":"У розмові можна уточнити відповідь, а форма дає лише готові варіанти чи коротке поле."}]}},"after":{"index":1,"heading":"📋 Форма і таблиця"}}],"legacyTitle":"Урок 11. Бази даних і форми: структура, збирання, приватність","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 11</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Бази даних і форми: структура, збирання та приватність</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Databases and Forms: Structure, Collection and Privacy</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як зібрати формою потрібні дані — і не зібрати зайвих?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я порівнюю паперову та цифрову базу даних.</li>\n      <li style=\"margin:6px 0;\">Я називаю переваги й недоліки збирання даних формою (<b>form</b>).</li>\n      <li style=\"margin:6px 0;\">Я проєктую безпечну форму лише з потрібними полями.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📋 Форма і таблиця</h2>\n  <p style=\"margin:0 0 12px;\">Анкета в бібліотеці, реєстрація в гуртку, опитування класу — усе це <b>форми (forms)</b>. Форма — шаблон із питаннями й місцями для відповідей. Кожен, хто її заповнює, відповідає на ті самі питання.</p>\n  <p style=\"margin:0 0 14px;\">У нашому прикладі відповіді з форми зберігаються в таблиці: кожне питання стає <b>полем</b>, кожна заповнена анкета — <b>записом</b>, а кожна відповідь — <b>значенням</b>. Інші системи можуть зберігати дані інакше, але ідея та сама: форма допомагає зібрати однакові дані від багатьох людей.</p>\n  <p style=\"margin:0 0 14px;\">Форми бувають паперові й цифрові. Паперові анкети хтось має вручну переписати в таблицю, а цифрова форма зберігає відповіді одразу — і їх можна швидко відсортувати.</p>\n\n  <svg viewBox=\"0 0 860 280\" role=\"img\" aria-labelledby=\"g4u11a-t g4u11a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u11a-t\">Від форми до таблиці</title>\n    <desc id=\"g4u11a-d\">Ліворуч форма гуртка з трьома питаннями: ім'я (обов'язкове), клас (обов'язкове), хобі (необов'язкове). Стрілка «Надіслати» веде праворуч до таблиці. У таблиці кожне питання стало стовпчиком-полем, а кожна анкета — рядком-записом. В однієї дитини хобі не вказано — клітинка порожня.</desc>\n    <rect x=\"10\" y=\"20\" width=\"280\" height=\"240\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <rect x=\"10\" y=\"20\" width=\"280\" height=\"44\" rx=\"12\" fill=\"#0033A0\"></rect>\n    <text x=\"150\" y=\"48\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\">📋 ФОРМА</text>\n    <g font-size=\"15\" font-family=\"Arial, sans-serif\">\n      <text x=\"30\" y=\"92\" font-weight=\"700\" fill=\"#1A1A1A\">Ім'я *</text>\n      <rect x=\"30\" y=\"100\" width=\"240\" height=\"30\" rx=\"5\" fill=\"#F0F4F8\" stroke=\"#D9E2F0\"></rect><text x=\"42\" y=\"121\" fill=\"#0033A0\">Марко</text>\n      <text x=\"30\" y=\"154\" font-weight=\"700\" fill=\"#1A1A1A\">Клас *</text>\n      <rect x=\"30\" y=\"162\" width=\"240\" height=\"30\" rx=\"5\" fill=\"#F0F4F8\" stroke=\"#D9E2F0\"></rect><text x=\"42\" y=\"183\" fill=\"#0033A0\">4-А</text>\n      <text x=\"30\" y=\"216\" font-weight=\"700\" fill=\"#3D4757\">Хобі (необов'язково)</text>\n      <rect x=\"30\" y=\"224\" width=\"240\" height=\"26\" rx=\"5\" fill=\"#F0F4F8\" stroke=\"#D9E2F0\"></rect><text x=\"42\" y=\"243\" fill=\"#0033A0\">шахи</text>\n    </g>\n    <path d=\"M298 140 H366\" fill=\"none\" stroke=\"#B38600\" stroke-width=\"4\"></path>\n    <polygon points=\"364,131 380,140 364,149\" fill=\"#B38600\"></polygon>\n    <text x=\"338\" y=\"124\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"700\" fill=\"#7A5A00\" font-family=\"Arial, sans-serif\">Надіслати</text>\n    <rect x=\"386\" y=\"20\" width=\"464\" height=\"240\" rx=\"12\" fill=\"#FFFFFF\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n    <text x=\"618\" y=\"50\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\" font-family=\"Arial, sans-serif\">🗂 ТАБЛИЦЯ</text>\n    <rect x=\"402\" y=\"66\" width=\"432\" height=\"36\" rx=\"6\" fill=\"#0033A0\"></rect>\n    <g font-size=\"15\" font-weight=\"700\" fill=\"#FFFFFF\" font-family=\"Arial, sans-serif\"><text x=\"420\" y=\"90\">Ім'я</text><text x=\"570\" y=\"90\">Клас</text><text x=\"700\" y=\"90\">Хобі</text></g>\n    <rect x=\"402\" y=\"106\" width=\"432\" height=\"34\" rx=\"6\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <g font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">\n      <text x=\"420\" y=\"129\">Марко</text><text x=\"570\" y=\"129\">4-А</text><text x=\"700\" y=\"129\">шахи</text>\n      <text x=\"420\" y=\"167\">Ліна</text><text x=\"570\" y=\"167\">4-Б</text><text x=\"700\" y=\"167\">—</text>\n      <text x=\"420\" y=\"203\">Остап</text><text x=\"570\" y=\"203\">4-А</text><text x=\"700\" y=\"203\">футбол</text>\n    </g>\n    <text x=\"618\" y=\"244\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">питання → поле, анкета → запис</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Поля форми бувають <b>обов'язкові (required)</b> — без них форма не надішлеться; їх часто позначають зірочкою *. А бувають <b>необов'язкові (optional)</b> — їх можна пропустити.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚖️ Переваги й недоліки форм</h2>\n  <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%, 300px),1fr));gap:12px;margin:16px 0;\">\n    <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0 0 8px;font-weight:700;color:#155C32;\">✅ Переваги</p>\n      <ul style=\"margin:0;padding-left:20px;\">\n        <li style=\"margin:5px 0;\">Усі відповідають на ті самі питання.</li>\n        <li style=\"margin:5px 0;\">Відповіді одразу впорядковані в таблиці.</li>\n        <li style=\"margin:5px 0;\">Готові варіанти зменшують помилки введення.</li>\n      </ul>\n    </div>\n    <div style=\"background:#FFF2F2;border:1px solid #E6B0AA;border-radius:10px;padding:14px 16px;\">\n      <p style=\"margin:0 0 8px;font-weight:700;color:#96271B;\">⚠️ Недоліки</p>\n      <ul style=\"margin:0;padding-left:20px;\">\n        <li style=\"margin:5px 0;\">Твоєї відповіді може не бути серед варіантів.</li>\n        <li style=\"margin:5px 0;\">Незрозуміле питання дає неправильні відповіді.</li>\n        <li style=\"margin:5px 0;\">Збій програми чи мережі — і відповідь не збережеться.</li>\n        <li style=\"margin:5px 0;\">Форма може просити більше, ніж треба.</li>\n      </ul>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 8px;\">Багато недоліків можна зменшити, якщо добре скласти питання:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\">Одне питання — про одну річ. «Який твій клас і улюблений предмет?» краще розділити на два.</li>\n    <li style=\"margin:6px 0;\">Де можна, дай готові варіанти, а для решти — пункт «Інше».</li>\n    <li style=\"margin:6px 0;\">Прочитай форму очима того, хто її заповнюватиме: чи все зрозуміло без пояснень?</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛡 Збирай лише потрібне</h2>\n  <p style=\"margin:0 0 12px;\">Той, хто створює форму, відповідає за дані, які вона збирає. Головне правило — <b>мінімізація даних (data minimisation)</b>: питати лише те, без чого справді не обійтися. Поля «про всяк випадок» не додають.</p>\n  <p style=\"margin:0 0 12px;\">Домашня адреса, номер телефону дитини, паролі, статки родини — такі дані формі гуртка не потрібні. Якщо таблицю з ними хтось украде чи випадково перешле, це може зашкодити людям. Чим менше чутливих даних, тим безпечніша база.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: знайди зайве поле</h2>\n  <p style=\"margin:0 0 12px;\">Форма запису до гуртка малювання просить:</p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:5px 0;\">Ім'я та прізвище</li>\n    <li style=\"margin:5px 0;\">Клас</li>\n    <li style=\"margin:5px 0;\">Домашня адреса</li>\n    <li style=\"margin:5px 0;\">Чи малював чи малювала раніше фарбами? (Так/Ні)</li>\n    <li style=\"margin:5px 0;\">Улюблений колір</li>\n  </ol>\n  <p style=\"margin:0 0 12px;\">Яке поле порушує мінімізацію даних? Яке можна зробити необов'язковим?</p>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\">Поле 3 — домашня адреса: для запису на гурток вона не потрібна, її варто прибрати. Поле 5 — улюблений колір — можна зробити необов'язковим.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">У школі відкривається «Клуб юних кіберзахисників». Спроєктуй для нього форму реєстрації.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Порівняй паперову анкету й цифрову базу даних. Запиши по одній перевазі й одному недоліку для кожної. Подумай: чи потрібні електрика й пристрій? Як швидко знайти одного учня серед ста?</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Ось поля, які пропонують додати. Обери лише потрібні й безпечні. Для кожного обраного запиши тип даних і позначку required чи optional.</p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:5px 0;\">Ім'я учня</li>\n    <li style=\"margin:5px 0;\">Клас</li>\n    <li style=\"margin:5px 0;\">Чи працював чи працювала раніше за комп'ютером?</li>\n    <li style=\"margin:5px 0;\">Пароль від пошти</li>\n    <li style=\"margin:5px 0;\">Номер телефону учня</li>\n    <li style=\"margin:5px 0;\">Чого хочеш навчитися в клубі?</li>\n  </ol>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Заповни свою форму вигаданими даними: Олексій, 4-Б, працював за комп'ютером, хоче навчитися захищати паролі. Запиши цей запис рядком таблиці.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4.</b> Знайди у своїй формі одне питання, на яке можуть відповісти неправильно чи незрозуміло. Перепиши його точніше або додай варіанти відповіді.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Паперова: працює без електрики, але в ній повільно шукати, і її легко загубити. Цифрова: швидко шукати й сортувати, але потрібні пристрій і живлення, а збій може забрати дані.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Ім'я — текст, required. Клас — категорія, required. Досвід — так/ні, optional. Чого хочеш навчитися — текст, optional. Пароль і номер телефону учня не збираємо: клубу вони не потрібні, а їхній витік небезпечний.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4, приклад.</b> «Скільки тобі років?» у вільному полі дає «10», «десять», «майже 11». Краще — список варіантів або числове поле.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">До кожного поля з Кроку 2 постав питання: <i>«Без цього вчитель не зможе провести заняття?»</i> Якщо зможе — поле не потрібне або optional.</p>\n    <p style=\"margin:10px 0 0;\">Запис Олексія може виглядати так: <b>Олексій | 4-Б | Так | захищати паролі</b>. Чотири поля — один запис.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти робиш Кроки 2 і 3.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Взаємний огляд приватності.</b> Обміняйтеся з сусідом чи сусідкою своїми формами. Знайдіть поле, яке можна прибрати або зробити optional, і поясніть чому.</p>\n    <p style=\"margin:10px 0 0;\"><b>Правило перевірки.</b> Хтось пропонує поле «Вік». Які числа форма має приймати, а які відхиляти?</p>\n    <p style=\"margin:10px 0 0;\"><b>Телефон мами.</b> Учитель хоче знати, як повідомити про скасоване заняття. Запропонуй спосіб без збирання телефонів батьків у форму.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>To protect privacy, we collect only the data we need.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Комірник</b> — простий табличний редактор: створи поля своєї форми й додай запис Олексія. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">15–20 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/tools/komirnyk/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;\">Відкрити Комірник ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u11-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке мінімізація даних?</label>\n    <select id=\"g4-u11-q1\" name=\"g4-u11-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Збирати якомога більше про всяк випадок</option>\n      <option>Збирати лише те, що справді потрібно</option>\n      <option>Не користуватися базами даних</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Збирати лише потрібне. Менше чутливих даних — менше шкоди, якщо таблиця потрапить не туди.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u11-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Яке поле в анкеті гуртка робототехніки варто зробити optional?</label>\n    <select id=\"g4-u11-q2\" name=\"g4-u11-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Ім'я учня</option>\n      <option>Улюблені конструктори</option>\n      <option>Клас</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Улюблені конструктори. Ім'я й клас потрібні, щоб скласти групи, а вподобання — за бажанням.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u11-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Що з цього — недолік форми?</label>\n    <select id=\"g4-u11-q3\" name=\"g4-u11-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Усі відповідають на ті самі питання</option>\n      <option>Потрібної відповіді може не бути серед варіантів</option>\n      <option>Відповіді одразу впорядковані</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Інші два — переваги форми. Щоб зменшити цей недолік, додають варіант «Інше» з полем для власної відповіді.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Однокласник додав у форму бібліотеки обов'язкові поля «Домашня адреса» і «Телефон батьків». Переконай його:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Ці поля варто прибрати, бо ___. Бібліотеці досить ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я порівнюю паперову й цифрову базу даних: перевага й недолік кожної.</li>\n      <li style=\"margin:8px 0;\">Моя форма має лише потрібні поля з типами даних і позначками required/optional.</li>\n      <li style=\"margin:8px 0;\">Я записую тестовий запис із вигаданими даними й покращую одне питання.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> Кроки 2 і 3.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> записи до Кроків 1–4 у зошиті.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>form</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">форма, анкета</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>database</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">база даних</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>paper-based / digital</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">паперовий / цифровий</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>required / optional</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">обов'язковий / необов'язковий</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>privacy</b></td><td style=\"padding:8px 10px;\">приватність</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>A form collects the same data from many people. We collect only the data we need.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-4","grade":4,"module":2,"number":4,"title":"Сортування, пошук і запит до бази даних","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок12_Гра1_Яке-це-сортування.html","title":"Яке це сортування?","description":"сортування карток","data":{"id":"m2g12a","lesson":12,"tag":"РЯДКИ","icon":"🔀","type":"sort","title":"Яке це сортування?","file":"М2_Урок12_Гра1_Яке-це-сортування.html","conceptName":"порядок сортування","concept":"Сортування за зростанням: від меншого до більшого, від А до Я. За спаданням — навпаки. Якщо порядок не підкоряється правилу — список не відсортований.","skill":"впізнавати сортування за зростанням і за спаданням","data":{"categories":[{"id":"up","label":"⬆️ За зростанням","hint":"від меншого до більшого або від А до Я"},{"id":"down","label":"⬇️ За спаданням","hint":"від більшого до меншого або від Я до А"},{"id":"no","label":"🌀 Не відсортовано","hint":"порядок дотримано не всюди"}],"items":[{"text":"2, 5, 9, 14","cat":"up","explain":"Кожне наступне число більше. Це зростання.","hint":"перевір кожну пару сусідів"},{"text":"банан, груша, яблуко","cat":"up","explain":"Б → Г → Я: порядок абетки. Це зростання.","hint":"подивись на перші літери за абеткою"},{"text":"20, 11, 7, 3","cat":"down","explain":"Кожне наступне число менше. Це спадання.","hint":"числа меншають чи зростають?"},{"text":"Оля, Марко, Іван, Андрій","cat":"down","explain":"О → М → І → А: від кінця абетки до початку. Це спадання.","hint":"рухаємося абеткою назад чи вперед?"},{"text":"8, 3, 10, 1","cat":"no","explain":"8 > 3, але потім 3 < 10 — порядок ламається. Список не відсортований.","hint":"перевір кожну пару сусідів"},{"text":"груша, яблуко, банан","cat":"no","explain":"Г → Я — добре, але після Я йде Б — порядок зламано.","hint":"перевір усі пари сусідів"},{"text":"1, 2, 4, 4, 9","cat":"up","explain":"Числа не меншають (4 і 4 — однакові, це не порушення). Це зростання.","hint":"однакові сусіди не ламають зростання"},{"text":"вишня, абрикоса, груша","cat":"no","explain":"В → А — назад абеткою, а А → Г — уперед. Єдиного порядку немає.","hint":"перевір кожну пару сусідів за абеткою"}]}},"after":{"index":1,"heading":"🔤 Сортування"}},{"path":"app/games/М2_Урок12_Гра2_Пастки-даних.html","title":"Пастки даних","description":"сценарний вибір","data":{"id":"m2g12b","lesson":12,"tag":"ПАСТКИ","icon":"🪤","type":"quiz","title":"Пастки даних","file":"М2_Урок12_Гра2_Пастки-даних.html","conceptName":"брудні дані й фільтр","concept":"Комп'ютер сортує чесно за правилами, тому «брудні» дані дають дивні результати. Пробіл на початку слова сортується першим. Число, записане як текст, порівнюється по літерах: «10» стоїть перед «9», бо 1 < 9. Фільтр лише тимчасово ховає рядки — скинеш його, і все повернеться.","skill":"помічати «брудні» дані, що псують сортування, і правильно користуватися фільтром","data":{"questions":[{"q":"У списку імен « Аня» (з пробілом на початку) опинилась першою. Чому?","options":["Це помилка комп'ютера","Пробіл сортується раніше за літери","Аня — найкоротше ім'я"],"correct":1,"explain":"Для комп'ютера пробіл — такий самий символ, і він іде раніше за літери. Тому зайві пробіли — «брудні» дані."},{"q":"Стовпчик зберігає числа як текст. Як відсортуються «9» і «10»?","options":["9, потім 10","«10», потім «9» — текст порівнюють по символах","Випадково"],"correct":1,"explain":"Як текст порівнюються перші символи: «1» менше за «9», тож «10» виходить перед «9». Числа треба зберігати як числа."},{"q":"Ти застосував фільтр «лише казки». Що сталося з іншими книгами?","options":["Вони видалені назавжди","Вони тимчасово сховані","Вони перейшли в іншу таблицю"],"correct":1,"explain":"Фільтр тільки ховає рядки, які не підходять під критерій. Дані нікуди не зникають."},{"q":"Як повернути всі рядки після фільтра?","options":["Закрити програму без збереження","Скинути фільтр","Ввести все наново"],"correct":1,"explain":"Кнопка «скинути фільтр» повертає всі рядки. Нічого не втрачається."},{"q":"Що таке критерій у пошуку?","options":["Умова, за якою шукаємо, наприклад «автор — Нечуй-Левицький»","Назва таблиці","Пароль від бази даних"],"correct":0,"explain":"Критерій — це умова: яке значення і в якому полі ми шукаємо."},{"q":"Запит «знайди книги, де сторінок більше за 100» — це…","options":["питання до бази даних із критерієм","новий запис","видалення зайвих книг"],"correct":0,"explain":"Запит — це питання до бази з чітким критерієм. База повертає лише записи, що підходять."}]}},"after":{"index":4,"heading":"🧹 Коли дані неохайні"}},{"path":"app/games/М2_Урок12_Гра3_Знайди-книгу.html","title":"Знайди книгу в каталозі","description":"послідовність кроків","data":{"id":"m2g12c","lesson":12,"tag":"ПОШУК","icon":"🔍","type":"order","title":"Знайди книгу в каталозі","file":"М2_Урок12_Гра3_Знайди-книгу.html","conceptName":"пошук і фільтр","concept":"Щоб знайти запис у таблиці: визнач критерій, застосуй фільтр або пошук, знайди запис. Після роботи скинь фільтр, щоб побачити всю таблицю знову.","skill":"послідовно шукати запис у таблиці за критерієм","data":{"rounds":[{"title":"Завдання: знайди в каталозі всі книги Лесі Українки","steps":["Відкрий таблицю каталогу","Визнач критерій: поле «Автор», значення «Леся Українка»","Застосуй фільтр за цим критерієм","Переглянь записи, що лишилися","Скинь фільтр, щоб повернути всю таблицю"],"hint":"спочатку подумай, ЩО шукаємо, і лише потім фільтруй","explain":"Критерій — перед фільтром. А після роботи фільтр скидають, щоб таблиця знову була повною."},{"title":"Завдання: визнач, яка книга каталогу найтовстіша","steps":["Знайди поле «Сторінки»","Переконайся, що воно має тип «число»","Відсортуй його за спаданням","Подивись на перший запис — це найтовстіша книга"],"hint":"числа, записані як текст, сортуються хибно","explain":"Спочатку перевіряємо тип поля, бо «10» як текст стане перед «9». Потім сортуємо за спаданням."}]}},"after":{"index":2,"heading":"🔎 Пошук і фільтр"}}],"legacyTitle":"Урок 12. Сортування, пошук і запит до бази даних","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 12</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Сортування, пошук і запит до бази даних</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Sorting, Searching and Querying a Database</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як за допомогою бази даних відповісти на одне запитання?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я сортую (<b>sort</b>) дані за алфавітом і за числом — за зростанням і спаданням.</li>\n      <li style=\"margin:6px 0;\">Я знаходжу потрібні записи й відповідаю на одне запитання.</li>\n      <li style=\"margin:6px 0;\">Я помічаю, коли неохайні дані псують сортування.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔤 Сортування</h2>\n  <p style=\"margin:0 0 12px;\">Уяви бібліотеку, де тисячі книжок лежать купою. Щоб щось знайти, спершу треба навести лад. <b>Сортування (sorting)</b> змінює порядок записів: усі рядки лишаються в таблиці, але шикуються за правилом.</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>За алфавітом (alphabetical):</b> від А до Я — за зростанням (<b>ascending</b>), від Я до А — за спаданням (<b>descending</b>).</li>\n    <li style=\"margin:8px 0;\"><b>За числом (numerical):</b> від меншого до більшого — за зростанням, від більшого до меншого — за спаданням.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Сортування саме по собі відповідає на питання «хто перший» і «хто останній». Відсортуй книжки за кількістю сторінок за спаданням — і найтовща опиниться нагорі.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔎 Пошук і фільтр</h2>\n  <p style=\"margin:0 0 12px;\">Інколи треба не впорядкувати все, а знайти лише потрібне. Для цього є пошук і фільтр.</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Пошук (find)</b> знаходить у таблиці потрібне слово чи число.</li>\n    <li style=\"margin:8px 0;\"><b>Фільтр (filter)</b> показує лише записи, які відповідають умові, а решту тимчасово ховає. Нічого не видаляється: фільтр можна скинути (<b>reset</b>), і всі записи повернуться.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Умову, за якою відбираємо записи, називають <b>критерієм (criterion)</b>: «Жанр = Фентезі» або «Сторінок більше за 200». Запитання до бази даних англійською називають <b>query</b>. У різних програмах сортування, пошук і фільтр виглядають як різні кнопки, але мета в них одна — отримати відповідь.</p>\n\n  <svg viewBox=\"0 0 860 290\" role=\"img\" aria-labelledby=\"g4u12a-t g4u12a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u12a-t\">Сортування і фільтр</title>\n    <desc id=\"g4u12a-d\">Ліворуч початкова таблиця з чотирьох книжок. Посередині вони ж, відсортовані за назвою від А до Я: книжок так само чотири, змінився лише порядок. Праворуч фільтр «Жанр = Фентезі»: видно лише дві книжки, дві інші тимчасово сховані.</desc>\n    <g font-family=\"Arial, sans-serif\">\n      <rect x=\"6\" y=\"14\" width=\"260\" height=\"44\" rx=\"8\" fill=\"#F0F4F8\"></rect>\n      <text x=\"136\" y=\"42\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#0033A0\">Початкова таблиця</text>\n      <rect x=\"298\" y=\"14\" width=\"260\" height=\"44\" rx=\"8\" fill=\"#0033A0\"></rect>\n      <text x=\"428\" y=\"42\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#FFFFFF\">Сортування А → Я</text>\n      <rect x=\"590\" y=\"14\" width=\"264\" height=\"44\" rx=\"8\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n      <text x=\"722\" y=\"42\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"700\" fill=\"#7A5A00\">Фільтр: Фентезі</text>\n    </g>\n    <g font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">\n      <rect x=\"6\" y=\"68\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#D9E2F0\"></rect><text x=\"18\" y=\"92\">Райлі • Фантастика</text>\n      <rect x=\"6\" y=\"110\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#D9E2F0\"></rect><text x=\"18\" y=\"134\">Казки • Фентезі</text>\n      <rect x=\"6\" y=\"152\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#D9E2F0\"></rect><text x=\"18\" y=\"176\">Дракони • Фентезі</text>\n      <rect x=\"6\" y=\"194\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#D9E2F0\"></rect><text x=\"18\" y=\"218\">Космос • Фантастика</text>\n\n      <rect x=\"298\" y=\"68\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#EAF0FC\" stroke=\"#0033A0\"></rect><text x=\"310\" y=\"92\">Дракони • Фентезі</text>\n      <rect x=\"298\" y=\"110\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#EAF0FC\" stroke=\"#0033A0\"></rect><text x=\"310\" y=\"134\">Казки • Фентезі</text>\n      <rect x=\"298\" y=\"152\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#EAF0FC\" stroke=\"#0033A0\"></rect><text x=\"310\" y=\"176\">Космос • Фантастика</text>\n      <rect x=\"298\" y=\"194\" width=\"260\" height=\"36\" rx=\"6\" fill=\"#EAF0FC\" stroke=\"#0033A0\"></rect><text x=\"310\" y=\"218\">Райлі • Фантастика</text>\n\n      <rect x=\"590\" y=\"68\" width=\"264\" height=\"36\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#B38600\"></rect><text x=\"602\" y=\"92\">Казки • Фентезі</text>\n      <rect x=\"590\" y=\"110\" width=\"264\" height=\"36\" rx=\"6\" fill=\"#FFFFFF\" stroke=\"#B38600\"></rect><text x=\"602\" y=\"134\">Дракони • Фентезі</text>\n      <rect x=\"590\" y=\"152\" width=\"264\" height=\"78\" rx=\"6\" fill=\"#F8FAFC\" stroke=\"#D9E2F0\" stroke-dasharray=\"6 5\"></rect><text x=\"722\" y=\"196\" text-anchor=\"middle\" fill=\"#3D4757\">2 записи сховано</text>\n    </g>\n    <g font-size=\"15\" font-weight=\"700\" font-family=\"Arial, sans-serif\" text-anchor=\"middle\">\n      <text x=\"428\" y=\"262\" fill=\"#0033A0\">4 записи, інший порядок</text>\n      <text x=\"722\" y=\"262\" fill=\"#7A5A00\">2 записи, порядок той самий</text>\n    </g>\n  </svg>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧭 План: як відповісти на запитання</h2>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Знайди поле.</b> Про що питають — про сторінки, жанр чи рейтинг?</li>\n    <li style=\"margin:8px 0;\"><b>Обери дію.</b> «Хто найбільший чи перший?» — сортуй. «Які саме?» або «Скільки?» — фільтруй за критерієм. «Де це слово?» — шукай.</li>\n    <li style=\"margin:8px 0;\"><b>Перевір очима.</b> Переглянь записи, що потрапили в результат, і переконайся, що вони справді відповідають умові.</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧹 Коли дані неохайні</h2>\n  <p style=\"margin:0 0 12px;\">Комп'ютер порівнює значення символ за символом, починаючи з першого. Тому дрібна помилка введення може зіпсувати весь порядок.</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Зайвий пробіл на початку.</b> У багатьох програмах пробіл іде раніше за будь-яку літеру, тож назва з пробілом стрибне на перше місце.</li>\n    <li style=\"margin:8px 0;\"><b>Число, записане як текст.</b> Тоді «10» порівнюється як слово, що починається з «1», і може опинитися перед «9».</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Такі дані називають неохайними (dirty data). Перш ніж сортувати, їх перевіряють і виправляють — інакше відповідь на запитання може бути хибною.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">Ось вигаданий каталог нових книжок. Знак ␣ означає пробіл.</p>\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:560px;font-size:16px;\">\n      <thead><tr>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">ID</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Назва</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Жанр</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Сторінок</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Рейтинг</th>\n      </tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Пригоди робота Райлі</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Фантастика</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">120</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">9,5</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">␣Космічні таємниці</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Фантастика</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">280</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">8,9</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">3</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Казки Карпатських гір</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Фентезі</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">95</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">10</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">4</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Штучний інтелект у школі</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Енциклопедія</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">150</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">9,2</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">5</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Дракони та лицарі</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Фентезі</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">310</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">9,8</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Сортування за алфавітом.</b> Яка книжка стане першою, якщо відсортувати назви від А до Я? Чому? Виправ помилку й запиши правильний порядок усіх п'яти назв.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Сортування за числом.</b> Запиши книжки за кількістю сторінок за спаданням. Яка книжка найтовща?</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Фільтр.</b> Застосуй фільтр «Жанр = Фентезі». Які книжки лишаться на екрані?</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Відповідь на запитання.</b> Скільки книжок мають рейтинг більший за 9? Запиши критерій, який ти використовуєш, і відповідь.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 5.</b> Як повернути таблицю до початкового вигляду з усіма записами?</p>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>А якщо запитати ШІ?</b> Помічник зі штучним інтелектом може запропонувати критерій пошуку. Але переглянути записи й перевірити, чи відповідь справді правильна, маєш ти сам чи сама.</p>\n  </div>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Першою стане «␣Космічні таємниці» через пробіл. Після виправлення: Дракони та лицарі → Казки Карпатських гір → Космічні таємниці → Пригоди робота Райлі → Штучний інтелект у школі.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> 310, 280, 150, 120, 95. Найтовща — «Дракони та лицарі».</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> «Казки Карпатських гір» і «Дракони та лицарі».</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Критерій: рейтинг &gt; 9. Відповідь: 4 книжки (усі, крім «Космічних таємниць»).</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 5.</b> Скинути фільтр (reset / «Очистити фільтр»).</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Випиши на окремі папірці назви книжок і розклади їх на столі. Так сортувати легше, ніж подумки.</p>\n    <p style=\"margin:10px 0 0;\">Для числового сортування дивись лише на стовпчик «Сторінок»: знайди найбільше число, потім наступне.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти робиш Кроки 2, 3 і 4.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Два запити.</b> Учителька шукає коротку казку на один вечір. Порівняй: запит А — «Жанр = Фентезі»; запит Б — «Жанр = Фентезі <b>і</b> Сторінок &lt; 100». Який поверне більше книжок? Який корисніший для учительки? Чому?</p>\n    <p style=\"margin:10px 0 0;\"><b>Пастка тексту.</b> Уяви, що рейтинг записано як текст: «9,5», «8,9», «10», «9,2», «9,8». Відсортуй їх за спаданням як слова — за першим символом. Де опиниться «10»? Що треба змінити в полі, щоб сортування стало правильним?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>Sorting changes the order. A filter hides the records that do not match.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Комірник</b> — внеси каталог і посортуй його. <b>Шукаємо в Інтернеті</b> — потренуйся звужувати пошук точнішою умовою. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–20 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/tools/komirnyk/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Комірник ↗</a>\n    <a href=\"https://itnauka.org/services/security_and_safety/search_engine/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;\">Шукаємо в Інтернеті ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u12-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що відбувається із записами під час фільтрування?</label>\n    <select id=\"g4-u12-q1\" name=\"g4-u12-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Вони назавжди видаляються</option>\n      <option>Ті, що не відповідають умові, тимчасово ховаються</option>\n      <option>Вони шикуються за алфавітом</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Тимчасово ховаються. Фільтр нічого не видаляє й не переставляє — його можна скинути.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u12-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Як упорядкувати числа від найбільшого до найменшого?</label>\n    <select id=\"g4-u12-q2\" name=\"g4-u12-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>За зростанням (ascending)</option>\n      <option>За спаданням (descending)</option>\n      <option>За алфавітом</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">За спаданням: 100, 50, 10. За зростанням — навпаки.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u12-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Треба дізнатися, яка книжка найкоротша. Що найзручніше?</label>\n    <select id=\"g4-u12-q3\" name=\"g4-u12-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Відсортувати «Сторінок» за зростанням</option>\n      <option>Відсортувати назви від Я до А</option>\n      <option>Відфільтрувати жанр «Фентезі»</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Відсортувати «Сторінок» за зростанням — найкоротша книжка буде першою.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Поясни різницю на прикладі олівців у пеналі:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Сортування — це коли я ___. Фільтр — це коли я ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я правильно сортую двома способами: за алфавітом і за числом.</li>\n      <li style=\"margin:8px 0;\">Я знаходжу помилку з пробілом і пояснюю, чому вона псує порядок.</li>\n      <li style=\"margin:8px 0;\">Я відповідаю на запитання Кроку 4 й записую критерій.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> Кроки 2, 3 і 4.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> записи до Кроків 1–5 у зошиті.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>sort</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">сортувати</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>ascending / descending</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">за зростанням / за спаданням</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>alphabetical / numerical</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">за алфавітом / за числом</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>filter</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">фільтр</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>criterion</b></td><td style=\"padding:8px 10px;\">критерій, умова</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>We can sort the titles alphabetically in ascending order. The database helps me answer one question.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-5","grade":4,"module":2,"number":5,"title":"Датчики, автоматичне введення і реєстратори даних","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок13_Гра1_Ручне-чи-автоматичне.html","title":"Ручне чи автоматичне введення?","description":"сортування карток","data":{"id":"m2g13a","lesson":13,"tag":"ВВЕД","icon":"🌡️","type":"sort","title":"Ручне чи автоматичне введення?","file":"М2_Урок13_Гра1_Ручне-чи-автоматичне.html","conceptName":"автоматичне введення","concept":"Коли дані вводить людина — це ручне введення. Коли пристрій вимірює щось сам, без людини, — це автоматичне введення. Його забезпечують датчики: температури, світла, руху, нахилу, звуку.","skill":"розрізняти ручне й автоматичне введення даних","data":{"categories":[{"id":"man","label":"✋ Ручне введення","hint":"дані вводить людина"},{"id":"auto","label":"🤖 Автоматичне введення","hint":"вимірює датчик сам, без людини"}],"items":[{"text":"Набір тексту на клавіатурі","cat":"man","explain":"Людина натискає клавіші — це ручне введення.","hint":"хто вводить дані: людина чи прилад?"},{"text":"Датчик світла у вуличному ліхтарі","cat":"auto","explain":"Датчик сам «бачить», що стемніло, і вмикає лампу.","hint":"хто тут працює: людина чи прилад?"},{"text":"Клацання мишкою","cat":"man","explain":"Мишкою керує людина — це ручне введення.","hint":"мишку рухає людина"},{"text":"Датчик руху, що відчиняє двері в супермаркеті","cat":"auto","explain":"Датчик сам помічає людину й відчиняє двері.","hint":"ніхто нічого не натискає"},{"text":"Диктування голосом у телефоні","cat":"man","explain":"Говорить людина — це ручне введення, хоч і голосом.","hint":"дані дає людина"},{"text":"Датчик нахилу повертає екран смартфона","cat":"auto","explain":"Смартфон сам вимірює нахил і повертає зображення.","hint":"пристрій вимірює сам"},{"text":"Учень записує показники термометра в зошит","cat":"man","explain":"Записує людина — це ручне введення.","hint":"хто пише в зошит?"},{"text":"Метеостанція записує температуру кожні 10 хвилин","cat":"auto","explain":"Реєстратор працює сам, у будь-який час, без людини.","hint":"прилад працює сам, навіть уночі"}]}},"after":{"index":1,"heading":"🌡 Як комп'ютер «відчуває» світ"}},{"path":"app/games/М2_Урок13_Гра2_Ланцюг-датчика.html","title":"Датчик → дані → програма → виведення","description":"послідовність кроків","data":{"id":"m2g13b","lesson":13,"tag":"СЕНСОР","icon":"🔗","type":"order","title":"Датчик → дані → програма → виведення","file":"М2_Урок13_Гра2_Ланцюг-датчика.html","conceptName":"sensor → data → program → output","concept":"Датчик вимірює щось у світі й дає показник — число. Програма перевіряє правило, наприклад «якщо більше 25 °C». І тоді пристрій виведення діє: світить екран, вмикається вентилятор, лунає звук.","skill":"показувати шлях від датчика через програму до пристрою виведення","data":{"rounds":[{"title":"Розстав кроки: теплиця з вентилятором","steps":["Датчик вимірює температуру в теплиці","Дані: показник 28 °C","Програма перевіряє: 28 більше за 25?","Виведення: вентилятор вмикається"],"hint":"спочатку вимірювання, потім правило, наприкінці — дія","explain":"Датчик → показник → перевірка правила → дія пристрою виведення."},{"title":"Розстав кроки: вуличний ліхтар","steps":["Датчик світла вимірює, наскільки темно","Дані: показник «темно»","Програма перевіряє правило: стемніло — увімкнути","Виведення: лампа ліхтаря світить"],"hint":"показник іде відразу після вимірювання","explain":"Той самий ланцюг: датчик → дані → програма → виведення."},{"title":"Розстав кроки: двері супермаркету","steps":["Датчик руху помічає людину біля дверей","Дані: показник «рух поруч»","Програма дає команду відчинити","Виведення: двері відчиняються"],"hint":"що відбувається найпершим?","explain":"Датчик руху → показник → команда програми → двері відчинились."}]}},"after":{"index":1,"heading":"🌡 Як комп'ютер «відчуває» світ"}},{"path":"app/games/М2_Урок13_Гра3_Чого-датчик-не-знає.html","title":"Чого датчик не знає","description":"сценарний вибір","data":{"id":"m2g13c","lesson":13,"tag":"ПУЛЬС","icon":"❤️","type":"quiz","title":"Чого датчик не знає","file":"М2_Урок13_Гра3_Чого-датчик-не-знає.html","conceptName":"межі датчиків","concept":"Датчик вимірює фізичні величини: температуру, пульс, рух, яскравість. Емоцію чи намір він виміряти не може — система лише здогадується, і здогадка буває хибною. Дані з датчиків на тілі — особисті, їх збирають лише за згодою.","skill":"пояснювати, чому показники датчика — це не знання про почуття людини","data":{"questions":[{"q":"Годинник показав швидкий пульс у друга. Що можна сказати точно?","options":["Він наляканий","Серце б'ється швидко, а причина може бути різною","Він бреше"],"correct":1,"explain":"Датчик виміряв лише пульс. Страх, радість чи біг після перерви — це вже припущення."},{"q":"Програма «визначає настрій» за усмішкою. Чи можна їй довіряти на 100 %?","options":["Так, усмішка завжди означає радість","Ні, усмішка не завжди означає, що людині весело","Так, якщо програма дорога"],"correct":1,"explain":"Програма лише робить припущення за фізичними сигналами, і воно може бути помилковим."},{"q":"Як найкраще дізнатися про почуття людини?","options":["Запитати саму людину","Подивитися лише на показники приладів","Вгадати за фото"],"correct":0,"explain":"Про почуття краще запитати саму людину, а не покладатися лише на прилад."},{"q":"Метеостанція записує температуру й вітер кожні 10 хвилин. Як називається такий пристрій?","options":["Реєстратор даних","Принтер","Динамік"],"correct":0,"explain":"Пристрій, що записує показники один за одним протягом годин чи днів, — реєстратор даних."},{"q":"Що в теплиці є пристроєм виведення?","options":["Датчик температури","Екран зі значком тривоги","Число 28 °C"],"correct":1,"explain":"Екран показує результат — це виведення. Датчик — введення, а число — дані."},{"q":"Фітнес-браслет збирає дані про твоє тіло. Хто має дати згоду на це?","options":["Ніхто, це просто годинник","Ти разом із батьками","Будь-хто в класі"],"correct":1,"explain":"Дані з датчиків на тілі — особисті. Їх збирають лише за згодою людини та її батьків."}]}},"after":{"index":2,"heading":"🧠 Чого датчик не вимірює"}}],"legacyTitle":"Урок 13. Датчики, автоматичне введення і реєстратори даних","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 13</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Датчики, автоматичне введення і реєстратори даних</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Sensors, Automatic Input and Data Loggers</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як комп'ютер отримує дані про світ без людини — і чого датчик виміряти не може?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я розрізняю ручне й автоматичне введення (<b>automatic input</b>).</li>\n      <li style=\"margin:6px 0;\">Я записую в таблицю щонайменше 5 показників датчика (<b>readings</b>).</li>\n      <li style=\"margin:6px 0;\">Я показую шлях <b>sensor → data → program → output</b>.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🌡 Як комп'ютер «відчуває» світ</h2>\n  <p style=\"margin:0 0 12px;\">Коли ти друкуєш на клавіатурі чи клацаєш мишкою — це <b>ручне введення (manual input)</b>: дані вводить людина. Але вуличний ліхтар сам «знає», що стемніло, а термостат — що в кімнаті спекотно. Тут працює <b>автоматичне введення (automatic input)</b>.</p>\n  <p style=\"margin:0 0 12px;\">Його забезпечують <b>датчики (sensors)</b> — пристрої, які вимірюють щось у навколишньому світі: температуру, світло, звук, рух чи нахил. Кожен замір дає число — <b>показник (reading)</b>.</p>\n  <p style=\"margin:0 0 12px;\">Пристрій, що записує показники один за одним протягом годин чи днів, називають <b>реєстратором даних (data logger)</b>. Програма опрацьовує ці дані й дає команду <b>пристрою виведення (output device)</b>: показати щось на екрані, засвітити лампочку, подати звук чи ввімкнути вентилятор.</p>\n\n  <p style=\"margin:0 0 8px;\">Датчики є всюди навколо тебе:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\">💡 вуличний ліхтар — датчик світла вмикає лампу, коли стемніє;</li>\n    <li style=\"margin:6px 0;\">🚪 двері в супермаркеті — датчик руху відчиняє їх перед покупцем;</li>\n    <li style=\"margin:6px 0;\">📱 смартфон — датчик нахилу повертає зображення, коли ти повертаєш телефон;</li>\n    <li style=\"margin:6px 0;\">🌦 метеостанція — реєстратор записує температуру й вітер кожні кілька хвилин.</li>\n  </ul>\n\n  <figure style=\"margin:18px 0 20px;background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px;\">\n    <img src=\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Bbc_micro_bit.jpg?width=800\" alt=\"Плата micro:bit, вид із боку мікросхем, динаміка та золотих контактів\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;max-height:410px;object-fit:contain;border-radius:8px;\">\n    <figcaption style=\"margin-top:9px;font-size:15px;line-height:1.45;color:#3D4757;\">Зворотний бік micro:bit. Тут мікросхеми з датчиками температури, світла й руху, динамік і контакти для зовнішніх пристроїв. Фото: <a href=\"https://commons.wikimedia.org/wiki/File:Bbc_micro_bit.jpg\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;\">SimonWaldherr, Wikimedia Commons</a>, CC BY-SA 4.0.</figcaption>\n  </figure>\n\n  <svg viewBox=\"0 0 860 230\" role=\"img\" aria-labelledby=\"g4u13a-t g4u13a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u13a-t\">Шлях даних від датчика до пристрою виведення</title>\n    <desc id=\"g4u13a-d\">Чотири кроки. Датчик вимірює температуру в теплиці. Дані: показник 28 градусів. Програма перевіряє правило: якщо температура більша за 25 градусів, увімкнути вентилятор. Виведення: вентилятор вмикається, на екрані з'являється попередження.</desc>\n    <g font-family=\"Arial, sans-serif\">\n      <rect x=\"6\" y=\"20\" width=\"196\" height=\"170\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"104\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">1. SENSOR</text>\n      <text x=\"104\" y=\"98\" text-anchor=\"middle\" font-size=\"30\">🌡️</text>\n      <text x=\"104\" y=\"140\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">вимірює</text>\n      <text x=\"104\" y=\"162\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">температуру</text>\n\n      <path d=\"M204 105 H214\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path><polygon points=\"212,97 224,105 212,113\" fill=\"#0033A0\"></polygon>\n\n      <rect x=\"226\" y=\"20\" width=\"196\" height=\"170\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n      <text x=\"324\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\">2. DATA</text>\n      <text x=\"324\" y=\"106\" text-anchor=\"middle\" font-size=\"30\" font-weight=\"700\" fill=\"#0033A0\">28 °C</text>\n      <text x=\"324\" y=\"150\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">показник</text>\n      <text x=\"324\" y=\"172\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">(reading)</text>\n\n      <path d=\"M424 105 H434\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path><polygon points=\"432,97 444,105 432,113\" fill=\"#0033A0\"></polygon>\n\n      <rect x=\"446\" y=\"20\" width=\"196\" height=\"170\" rx=\"12\" fill=\"#0033A0\"></rect>\n      <text x=\"544\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\">3. PROGRAM</text>\n      <text x=\"544\" y=\"104\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFFFFF\">якщо більше</text>\n      <text x=\"544\" y=\"126\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFFFFF\">за 25 °C —</text>\n      <text x=\"544\" y=\"148\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFD700\">увімкни</text>\n      <text x=\"544\" y=\"170\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFD700\">вентилятор</text>\n\n      <path d=\"M644 105 H654\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path><polygon points=\"652,97 664,105 652,113\" fill=\"#0033A0\"></polygon>\n\n      <rect x=\"666\" y=\"20\" width=\"188\" height=\"170\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n      <text x=\"760\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\">4. OUTPUT</text>\n      <text x=\"760\" y=\"98\" text-anchor=\"middle\" font-size=\"30\">🌀</text>\n      <text x=\"760\" y=\"140\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">вентилятор,</text>\n      <text x=\"760\" y=\"162\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">попередження</text>\n\n      <text x=\"430\" y=\"218\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">датчик → дані → програма → пристрій виведення</text>\n    </g>\n  </svg>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧠 Чого датчик не вимірює</h2>\n  <p style=\"margin:0 0 12px;\">Датчики вимірюють фізичні величини: температуру, пульс, рух, яскравість. Деякі системи обіцяють, що за такими сигналами чи за виразом обличчя «розпізнають емоції».</p>\n  <div style=\"background:#FFF2F2;border-left:5px solid #C0392B;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\">Датчик не вимірює емоцію чи намір безпосередньо. Система може лише <b>робити припущення</b> за фізичними сигналами — і таке припущення може бути помилковим. Швидкий пульс буває і від страху, і від радості, і після бігу. А усмішка не завжди означає, що людині весело.</p>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Тож про почуття людини краще запитати саму людину, а не покладатися лише на прилад. І пам'ятай: дані з датчиків на тілі — особисті, їх не збирають без згоди людини та її батьків.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: нахили micro:bit</h2>\n  <p style=\"margin:0 0 12px;\">У micro:bit є датчик руху — акселерометр. Він вимірює нахил і перетворює його на числа. Програма перевіряє показники:</p>\n  <div style=\"background:#F0F4F8;border-radius:8px;padding:12px 16px;margin:12px 0;font-family:'Courier New',monospace;font-size:16px;line-height:1.6;\">ЯКЩО нахил ліворуч &gt; 30° → показати стрілку ←<br>ЯКЩО нахил праворуч &gt; 30° → показати стрілку →<br>ІНАКШЕ → показати усмішку ☺</div>\n  <p style=\"margin:0 0 12px;\">Що з'явиться на екрані, якщо micro:bit лежить рівно на столі?</p>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\">Усмішка. Нахилу немає, тож жодна з умов не виконується і спрацьовує «ІНАКШЕ».</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">Екологічний гурток просить стежити за температурою в шкільній теплиці. Твій micro:bit буде датчиком і реєстратором.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Відкрий симулятор MakeCode для micro:bit через <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">каталог перевірених сервісів ↗</a> (розділ про мікроконтролери) або під'єднай справжню плату за інструкцією вчителя. Знайди, як змінювати температуру в симуляторі.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Зроби 5 замірів за різних умов: холодно, прохолодно, нормально, тепло, спекотно. Запиши показники в таблицю в зошиті:</p>\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:460px;font-size:16px;\">\n      <thead><tr>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Замір</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Умова</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Показник, °C</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що на екрані</th>\n      </tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">холодно</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">прохолодно</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">3</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">нормально</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">4</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">тепло</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">5</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">спекотно</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">___</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> Склади програму або запиши алгоритм у зошиті: якщо температура 25 °C чи більше — показати значок тривоги, інакше — галочку. Заповни стовпчик «Що на екрані».</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4.</b> Порівняй: датчик записує температуру сам, а учень ходить до теплиці з термометром щогодини. Запиши одну перевагу автоматичного збирання й одну причину, чому дані датчика можуть бути ненадійними.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити Кроки 3 і 4</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Температура — вхід (input) від датчика; значок на екрані — виведення (output). Заміри 4–5 зазвичай дають тривогу, 1–3 — галочку, залежно від чисел.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Переваги: датчик працює вночі й у вихідні, не втомлюється, записує точний час. Ненадійність: сіла батарейка, датчик стоїть на сонці чи біля батареї, пил, збій зв'язку.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">У MakeCode знадобляться: блок <b>постійно</b> (forever) з «Основного» (Basic), блок <b>якщо… то… інакше</b> з «Логіки» (Logic) і круглий блок <b>температура (°C)</b> із «Введення» (Input).</p>\n    <p style=\"margin:10px 0 0;\">Якщо симулятор не відкривається, скористайся готовими показниками: 12, 17, 21, 26, 31 °C. Завдання виконано, якщо ти заповнюєш таблицю й робиш Крок 3 на папері.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Як часто робити заміри (<b>sampling interval</b>)? Порівняй два реєстратори в теплиці: перший міряє щотри секунди, другий — раз на чотири години.</p>\n    <p style=\"margin:10px 0 0;\">Чи помітить другий раптову спеку опівдні? Що станеться з пам'яттю й батарейкою першого? Запропонуй свій інтервал і поясни вибір.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The data logger records a reading every ten minutes.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>micro:bit для вчителів та учнів</b> — розбір плати, її входів, виходів і датчиків із прикладами програм. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">15–20 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/microbit/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;\">Відкрити розділ micro:bit ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u13-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що з цього — автоматичне введення?</label>\n    <select id=\"g4-u13-q1\" name=\"g4-u13-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Набір тексту на клавіатурі</option>\n      <option>Датчик світла у вуличному ліхтарі</option>\n      <option>Клацання мишкою</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Датчик світла: він вимірює сам, без людини. Клавіатура й мишка — ручне введення.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u13-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Годинник показав швидкий пульс. Що можна сказати точно?</label>\n    <select id=\"g4-u13-q2\" name=\"g4-u13-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Людина налякана</option>\n      <option>Серце б'ється швидко, а причина може бути різною</option>\n      <option>Людина бреше</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Датчик виміряв лише пульс. Страх, радість чи біг — це вже припущення, і воно може бути хибним.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u13-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Що в теплиці є пристроєм виведення?</label>\n    <select id=\"g4-u13-q3\" name=\"g4-u13-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Датчик температури</option>\n      <option>Екран зі значком тривоги</option>\n      <option>Число 28 °C</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Екран. Датчик — пристрій введення, а число — дані.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Опиши шлях від датчика вологості ґрунту до автоматичного поливу:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Датчик вимірює ___ → дані: ___ → програма перевіряє ___ → пристрій виведення ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">У моїй таблиці щонайменше 5 показників датчика.</li>\n      <li style=\"margin:8px 0;\">Мій алгоритм реагує на температуру, і я називаю в ньому input та output.</li>\n      <li style=\"margin:8px 0;\">Я називаю перевагу датчика і одну причину ненадійних даних.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> таблиця з готовими показниками й алгоритм на папері.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> таблицю замірів і алгоритм або знімок програми.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>sensor</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">датчик</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>reading</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">показник, замір</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>data logger</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">реєстратор даних</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>input / output device</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">пристрій введення / виведення</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>automatic / manual</b></td><td style=\"padding:8px 10px;\">автоматичний / ручний</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>A sensor measures temperature automatically. The screen is an output device.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-6","grade":4,"module":2,"number":6,"title":"Моделі й симуляції: припущення, змінні та обмеження","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок14_Гра1_Припущення-чи-обмеження.html","title":"Припущення чи обмеження?","description":"сортування карток","data":{"id":"m2g14a","lesson":14,"tag":"МОДЕЛЬ","icon":"🌍","type":"sort","title":"Припущення чи обмеження?","file":"М2_Урок14_Гра1_Припущення-чи-обмеження.html","conceptName":"припущення й обмеження","concept":"Припущення — спрощення, яке автори моделі приймають заздалегідь: «ліс рівний». Обмеження — те, чого модель не вміє або не враховує: «модель не знає про річки». Жодна модель не є точною копією світу, тому її результат — прогноз, а не гарантія.","skill":"розрізняти припущення та обмеження моделі","data":{"categories":[{"id":"as","label":"🧩 Припущення","hint":"спрощення, прийняте заздалегідь"},{"id":"lim","label":"🚧 Обмеження","hint":"те, чого модель не враховує чи не вміє"}],"items":[{"text":"Модель пожежі вважає: «ліс рівний, у ньому немає річок і пагорбів»","cat":"as","explain":"Це спрощення, прийняте заздалегідь, — припущення.","hint":"це прийняли на віру ще до запуску"},{"text":"Модель пожежі не знає, що буде, якщо прилетить пожежний вертоліт","cat":"lim","explain":"Такого правила в моделі немає — це обмеження.","hint":"цього в моделі просто немає"},{"text":"Глобус вважає: «Земля — ідеальна куля»","cat":"as","explain":"Це спрощення, на якому тримається модель Землі, — припущення.","hint":"це спрощення, прийняте заздалегідь"},{"text":"На глобусі не видно вулиць твого міста","cat":"lim","explain":"Глобус не вміє показувати дрібні деталі — це обмеження.","hint":"модель цього не показує"},{"text":"Модель лісу вважає: «усі дерева — однакові сосни»","cat":"as","explain":"Це заздалегідь прийняте спрощення — припущення.","hint":"це спрощення ще до запуску"},{"text":"Модель лісу не враховує, що буковий ліс спалахує повільніше","cat":"lim","explain":"Модель не знає про різні дерева — це обмеження.","hint":"модель цього не враховує"},{"text":"Навігатор вважає: «машина їде зі сталою швидкістю»","cat":"as","explain":"Це спрощення, прийняте для розрахунку, — припущення.","hint":"це прийняли заздалегідь"},{"text":"Навігатор не знає, що на дорозі щойно сталася аварія","cat":"lim","explain":"Модель не враховує подію — це обмеження.","hint":"модель про це не знає"}]}},"after":{"index":3,"heading":"⚖️ Припущення й обмеження"}},{"path":"app/games/М2_Урок14_Гра2_Чесний-експеримент.html","title":"Чесний експеримент із моделлю","description":"послідовність кроків","data":{"id":"m2g14b","lesson":14,"tag":"ДОСЛІД","icon":"🔬","type":"order","title":"Чесний експеримент із моделлю","file":"М2_Урок14_Гра2_Чесний-експеримент.html","conceptName":"як досліджувати модель","concept":"Досліджуючи модель, змінюй лише один параметр за раз — інакше не зрозуміло, що вплинуло на результат. Кожен запуск записуй у таблицю. А якщо можна — порівняй результат із реальністю.","skill":"планувати експеримент із моделлю: один параметр, записи, порівняння","data":{"rounds":[{"title":"Порядок дій: досліджуємо, як вологість впливає на пожежу","steps":["Запиши припущення моделі та її параметри","Зафіксуй початкові значення: вітер 45 км/год, вологість 15 %, густота 9","Зміни лише один параметр: вологість з 15 % до 90 %","Запусти модель і запиши новий output у таблицю","Порівняй результати двох запусків і зроби висновок"],"hint":"перед запуском змінюємо лише ОДИН параметр","explain":"Змінився один параметр — видно, що саме він змінив результат. Усе записуємо в таблицю."},{"title":"Порядок дій: перевіряємо, чи модель схожа на реальність","steps":["Отримай результат моделі","Знайди реальне спостереження чи дані для порівняння","Порівняй: результат схожий чи дуже різний?","Якщо дуже різний — шукай, яке припущення підвело"],"hint":"спочатку результат, потім порівняння з реальністю","explain":"Схожий результат — модель корисна. Дуже різний — перевір припущення моделі."}]}},"after":{"index":2,"heading":"🔬 Як чесно досліджувати модель"}},{"path":"app/games/М2_Урок14_Гра3_Прогноз-моделі.html","title":"Прогноз моделі","description":"сценарний вибір","data":{"id":"m2g14c","lesson":14,"tag":"ПРОГНОЗ","icon":"🔥","type":"quiz","title":"Прогноз моделі","file":"М2_Урок14_Гра3_Прогноз-моделі.html","conceptName":"input → model → output","concept":"У симуляції ми задаємо вхідні параметри, модель застосовує свої правила, і ми бачимо результат — output. Модель спрощує світ, тому працює швидко й безпечно: ліс не треба підпалювати по-справжньому. Але результат — прогноз, а не гарантія.","skill":"передбачати результат моделі за її правилом і параметрами","data":{"questions":[{"q":"Правило поливу: «ЯКЩО вологість < 30 % І дощу не буде → полив УВІМКНЕНО, ІНАКШЕ → ВИМКНЕНО». Вологість 25 %, синоптики обіцяють дощ. Який output?","options":["Полив увімкнено, бо ґрунт сухий","Полив вимкнено, бо буде дощ"],"correct":1,"explain":"Ґрунт сухий, але друга частина умови не виконується: дощ буде. Працює «ІНАКШЕ» — полив вимкнено."},{"q":"Та сама модель поливу. Вологість 20 %, дощу не буде. Який output?","options":["Полив увімкнено","Полив вимкнено"],"correct":0,"explain":"Обидві частини умови виконані: 20 < 30 і дощу не буде. Полив увімкнено."},{"q":"Модель пожежі: спокійно (вітер 0), вологість 80 %, дерев мало. Найімовірніший результат?","options":["Вогонь швидко згасає","Вогонь охоплює весь ліс за хвилину"],"correct":0,"explain":"Без вітру, з вологим повітрям і рідким лісом вогонь швидко згасає."},{"q":"Модель пожежі: вітер 45 км/год, вологість 15 %, густий ліс. Найімовірніший результат?","options":["Вогонь поширюється дуже швидко","Вогонь згасає одразу"],"correct":0,"explain":"Сильний вітер, сухість і густий ліс допомагають вогню. Прогноз — дуже швидке поширення."},{"q":"Навіщо вчені досліджують пожежу на моделі, а не в справжньому лісі?","options":["Модель дозволяє безпечно й швидко перевірити багато варіантів","Модель завжди дає точну правду","Справжні ліси вже не горять"],"correct":0,"explain":"Підпалювати ліс небезпечно. Модель спрощує світ, тож варіанти перевіряють швидко й безпечно."},{"q":"Чи завжди правильна відповідь моделі ШІ?","options":["Так, ШІ знає все","Ні, модель має обмеження й може помилятися"],"correct":1,"explain":"ШІ — теж модель. Якщо в навчальних даних були прогалини чи помилки, відповідь може бути хибною."}]}},"after":{"index":1,"heading":"🌍 Що таке модель"}}],"legacyTitle":"Урок 14. Моделі й симуляції: припущення, змінні та обмеження","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 14</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Моделі й симуляції: припущення, змінні та обмеження</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Models and Simulations: Assumptions, Variables and Limitations</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: навіщо потрібні моделі, якщо вони завжди спрощують світ?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я пояснюю зв'язок <b>input → model → output</b>.</li>\n      <li style=\"margin:6px 0;\">Я змінюю один параметр і записую, як змінився результат.</li>\n      <li style=\"margin:6px 0;\">Я називаю припущення (<b>assumption</b>) і обмеження (<b>limitation</b>) моделі.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🌍 Що таке модель</h2>\n  <p style=\"margin:0 0 12px;\">Учені хочуть знати, як лісова пожежа поширюватиметься під час сильного вітру. Підпалювати ліс для досліду — небезпечно й неможливо, а чекати на справжню пожежу, щоб подивитися, — надто пізно. Тому вчені будують модель і досліджують її на комп'ютері.</p>\n  <p style=\"margin:0 0 12px;\"><b>Модель (model)</b> — це спрощене представлення системи. Вона залишає лише те, що важливо для нашого питання, і відкидає решту. Глобус — модель Землі: на ньому немає будинків і доріг, зате добре видно океани й материки. Комп'ютерна модель складається з правил і чисел, які описують, як поводиться система.</p>\n  <p style=\"margin:0 0 12px;\"><b>Симуляція (simulation)</b> використовує модель, щоб дослідити, як система поводитиметься за різних умов. Ми задаємо вхідні значення — <b>параметри (parameters)</b>, їх ще називають змінними, — запускаємо модель і дивимося на результат — <b>output</b>. Потім змінюємо один параметр і порівнюємо.</p>\n\n  <svg viewBox=\"0 0 860 230\" role=\"img\" aria-labelledby=\"g4u14a-t g4u14a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u14a-t\">Вхід, модель і результат симуляції пожежі</title>\n    <desc id=\"g4u14a-d\">Ліворуч вхідні параметри: швидкість вітру й сухість лісу. Посередині модель лісу з правилами і припущенням, що ліс рівний, без річок і пагорбів. Праворуч результат: як швидко поширюється вогонь.</desc>\n    <g font-family=\"Arial, sans-serif\">\n      <rect x=\"6\" y=\"20\" width=\"236\" height=\"170\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"124\" y=\"54\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">INPUT • параметри</text>\n      <text x=\"26\" y=\"100\" font-size=\"15\" fill=\"#1A1A1A\">💨 вітер: слабкий / сильний</text>\n      <text x=\"26\" y=\"136\" font-size=\"15\" fill=\"#1A1A1A\">🍂 сухість лісу: 10–90 %</text>\n\n      <path d=\"M246 105 H262\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path><polygon points=\"260,97 272,105 260,113\" fill=\"#0033A0\"></polygon>\n\n      <rect x=\"274\" y=\"20\" width=\"312\" height=\"170\" rx=\"12\" fill=\"#0033A0\"></rect>\n      <text x=\"430\" y=\"54\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\">MODEL • модель лісу</text>\n      <text x=\"430\" y=\"92\" text-anchor=\"middle\" font-size=\"15\" fill=\"#D6E0F5\">правила: як вогонь переходить</text>\n      <text x=\"430\" y=\"114\" text-anchor=\"middle\" font-size=\"15\" fill=\"#D6E0F5\">від дерева до дерева</text>\n      <text x=\"430\" y=\"150\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFD700\">припущення: ліс рівний,</text>\n      <text x=\"430\" y=\"172\" text-anchor=\"middle\" font-size=\"15\" fill=\"#FFD700\">без річок і пагорбів</text>\n\n      <path d=\"M590 105 H606\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path><polygon points=\"604,97 616,105 604,113\" fill=\"#0033A0\"></polygon>\n\n      <rect x=\"618\" y=\"20\" width=\"236\" height=\"170\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n      <text x=\"736\" y=\"54\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\">OUTPUT • результат</text>\n      <text x=\"736\" y=\"100\" text-anchor=\"middle\" font-size=\"30\">🔥</text>\n      <text x=\"736\" y=\"140\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">як швидко й куди</text>\n      <text x=\"736\" y=\"162\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">поширюється вогонь</text>\n\n      <text x=\"430\" y=\"220\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">змінюємо один параметр → дивимося, як змінився результат</text>\n    </g>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Моделями ти користуєшся щодня: прогноз погоди, навігатор, що рахує час у дорозі, гра-симулятор ферми чи автомобіля. Усі вони спрощують світ — і саме тому працюють швидко.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔬 Як чесно досліджувати модель</h2>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Змінюй лише один параметр за раз.</b> Якщо змінити одразу вітер і вологість, не зрозуміло, що саме вплинуло на результат.</li>\n    <li style=\"margin:8px 0;\"><b>Записуй кожен запуск</b> у таблицю: які були параметри і який вийшов output.</li>\n    <li style=\"margin:8px 0;\"><b>Порівнюй із реальністю,</b> якщо можна. Схожий результат — модель корисна. Дуже різний — шукай, яке припущення підвело.</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚖️ Припущення й обмеження</h2>\n  <p style=\"margin:0 0 12px;\">Жодна модель не є точною копією світу. Кожна тримається на двох речах:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Припущення (assumption)</b> — спрощення, яке автори моделі приймають заздалегідь. Наприклад: «ліс рівний, у ньому немає річок і пагорбів».</li>\n    <li style=\"margin:8px 0;\"><b>Обмеження (limitation)</b> — те, чого модель не вміє або не враховує. Наша модель не знає, що буде, якщо прилетить пожежний вертоліт: такого правила в ній немає.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Тож відповідь на питання уроку: модель корисна саме тому, що спрощує. Вона дозволяє безпечно й швидко перевірити багато варіантів. Але її результат — це прогноз, а не гарантія. Ним користуються, пам'ятаючи про припущення.</p>\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>ШІ — теж модель.</b> Чат-боти й генератори картинок навчаються на великій кількості прикладів — навчальних даних (training data). У них теж є припущення й обмеження. Тому відповідь ШІ — не автоматично правда: важливе варто перевіряти за надійними джерелами.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: розумний полив</h2>\n  <p style=\"margin:0 0 12px;\">Модель поливу клумби має два параметри: вологість ґрунту і прогноз дощу. Правило:</p>\n  <div style=\"background:#F0F4F8;border-radius:8px;padding:12px 16px;margin:12px 0;font-family:'Courier New',monospace;font-size:16px;line-height:1.6;\">ЯКЩО вологість &lt; 30 % І дощу не буде → полив УВІМКНЕНО<br>ІНАКШЕ → полив ВИМКНЕНО</div>\n  <p style=\"margin:0 0 12px;\">Датчик показує 25 %, але синоптики обіцяють сильний дощ. Яким буде output?</p>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\">Полив ВИМКНЕНО. Ґрунт сухий, але друга частина умови не виконується: дощ буде. Модель припускає, що прогноз правильний, — і це теж її обмеження.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">Досліди модель лісової пожежі. Вона має три параметри: швидкість вітру, вологість повітря і густоту дерев від 1 до 10. Головне припущення моделі: у лісі ростуть лише однакові сосни, які швидко спалахують.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1.</b> Запиши припущення моделі та її три параметри.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2.</b> Перенеси таблицю в зошит і запиши свій прогноз для сценаріїв 2 і 3. Сценарій 1 заповнено як зразок.</p>\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:560px;font-size:16px;\">\n      <thead><tr>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Сценарій</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Вітер</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Вологість</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Густота</th>\n        <th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Output</th>\n      </tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1 — спокійний</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">0 км/год</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">80 %</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">вогонь швидко згасає</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2 — вітряний</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">45 км/год</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">15 %</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">9</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">______</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">3 — середній</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">10 км/год</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">45 %</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">5</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">______</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3.</b> У сценарії 2 зміни лише один параметр: вологість із 15 % до 90 % — пішла злива. Як зміниться output? Запиши, чому.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4.</b> У справжньому лісі ростуть різні дерева, є річки, дороги й піщані ділянки. Назви одне обмеження моделі й поясни, чому її прогнозу не можна вірити на 100 %.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Сценарій 2 — вогонь поширюється дуже швидко. Сценарій 3 — поширюється повільно, його можна зупинити. Прийнятні й інші формулювання, якщо враховано всі три параметри.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Вогонь поширюватиметься значно повільніше або згасне: вологе дерево важче спалахує. Змінився один параметр — змінився результат.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Модель не враховує різні види дерев, річки й дороги, які зупиняють вогонь. Тому її результат — наближений прогноз.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Згадай глобус. Його <b>припущення</b>: Земля — ідеальна куля. Його <b>обмеження</b>: на ньому не видно вулиць твого міста.</p>\n    <p style=\"margin:10px 0 0;\">Для прогнозу постав собі питання: сильний вітер допомагає вогню чи заважає? А сухість? А густий ліс?</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти заповнюєш сценарій 2 і називаєш одне обмеження.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Фермерам пропонують дві моделі поливу яблуневого саду.</p>\n    <ul style=\"margin:10px 0 0;padding-left:22px;\">\n      <li style=\"margin:5px 0;\"><b>Модель А</b> вимірює вологість біля одного дерева й припускає, що в усьому саду так само.</li>\n      <li style=\"margin:5px 0;\"><b>Модель Б</b> вимірює вологість у п'яти зонах, температуру повітря й прогноз погоди.</li>\n    </ul>\n    <p style=\"margin:10px 0 0;\">Яка модель простіша й дешевша? Яка краще допоможе в посуху? Відповідай словами <i>parameters</i> і <i>limitations</i>.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The simulation lets us test dangerous scenarios safely.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Абстракція для дітей</b> — як модель залишає головне й відкидає зайві деталі. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/computational_thinking/abstraction/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;\">Відкрити урок ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u14-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке симуляція?</label>\n    <select id=\"g4-u14-q1\" name=\"g4-u14-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Фотографія справжнього лісу</option>\n      <option>Дослідження поведінки системи за допомогою моделі</option>\n      <option>Видалення зайвих файлів</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Симуляція використовує модель: ми задаємо параметри й спостерігаємо, що відбувається.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u14-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. «Модель вважає, що всі дерева однакові». Що це?</label>\n    <select id=\"g4-u14-q2\" name=\"g4-u14-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Припущення</option>\n      <option>Результат</option>\n      <option>Параметр</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Припущення: спрощення, яке прийняли заздалегідь. Через нього в моделі з'являється обмеження — вона не враховує різні дерева.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u14-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чи завжди правильна відповідь моделі ШІ?</label>\n    <select id=\"g4-u14-q3\" name=\"g4-u14-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Так, ШІ знає все</option>\n      <option>Ні, модель має обмеження й може помилятися</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Ні. ШІ спирається на закономірності в навчальних даних. Якщо даних бракувало чи в них були помилки, відповідь теж може бути хибною.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Поясни на прикладі гри-симулятора автомобіля:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Input — це ___, модель — це ___, output — це ___. Одне обмеження цієї гри: ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я записую припущення й параметри моделі.</li>\n      <li style=\"margin:8px 0;\">Я заповнюю прогноз для сценаріїв 2 і 3 та пояснюю вплив зміни вологості.</li>\n      <li style=\"margin:8px 0;\">Я називаю одне реальне обмеження моделі.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> сценарій 2 і одне обмеження.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> таблицю сценаріїв і записи до Кроків 3–4.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>model</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">модель, спрощене представлення</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>simulation</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">симуляція</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>parameter</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">параметр, змінна</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>assumption</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">припущення</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>limitation</b></td><td style=\"padding:8px 10px;\">обмеження</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The model has limitations because it does not include rivers or different trees.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-7","grade":4,"module":2,"number":7,"title":"Перевірка ШІ, точні промпти, походження даних і справедливість","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок15_Гра1_Зібери-промпт.html","title":"Зібери промпт","description":"сортування карток","data":{"id":"m2g15a","lesson":15,"tag":"ПРОМПТ","icon":"✍️","type":"sort","title":"Зібери промпт","file":"М2_Урок15_Гра1_Зібери-промпт.html","conceptName":"частини промпту","concept":"Промпт — це запит до ШІ. Корисно подумати про чотири речі: мета (що треба зробити), аудиторія (для кого), формат (як має виглядати відповідь) і обмеження (умови, наприклад «не більше 25 слів»). Точний промпт наближає до потрібної відповіді, але не гарантує правди.","skill":"розпізнавати в промпті мету, аудиторію, формат і обмеження","data":{"categories":[{"id":"goal","label":"🎯 Мета","hint":"що треба зробити"},{"id":"aud","label":"👧 Аудиторія","hint":"для кого"},{"id":"fmt","label":"📐 Формат","hint":"як має виглядати відповідь"},{"id":"con","label":"⛓ Обмеження","hint":"умови й межі"}],"items":[{"text":"«Напиши запрошення на змагання з бігу»","cat":"goal","explain":"Це завдання — що треба зробити. Це мета.","hint":"це відповідь на питання «що зробити?»"},{"text":"«Для учнів і учениць 4 класу»","cat":"aud","explain":"Це для кого — аудиторія.","hint":"це відповідь на питання «для кого?»"},{"text":"«Одне речення»","cat":"fmt","explain":"Це як має виглядати відповідь — формат.","hint":"це опис вигляду відповіді"},{"text":"«Не більше 25 слів»","cat":"con","explain":"Це умова-межа — обмеження.","hint":"це правило-межа"},{"text":"«Склади список ігор для свята»","cat":"goal","explain":"Це завдання — мета.","hint":"що треба зробити?"},{"text":"«Для молодших дітей»","cat":"aud","explain":"Це для кого — аудиторія.","hint":"для кого це?"},{"text":"«Список із трьох пунктів»","cat":"fmt","explain":"Це вигляд відповіді — формат.","hint":"це про вигляд відповіді"},{"text":"«Без вигаданих фактів»","cat":"con","explain":"Це умова, чого робити не можна, — обмеження.","hint":"це умова"}]}},"after":{"index":2,"heading":"✍️ Як уточнити prompt"}},{"path":"app/games/М2_Урок15_Гра2_Перевір-твердження.html","title":"Перевір твердження ШІ","description":"послідовність кроків","data":{"id":"m2g15b","lesson":15,"tag":"ПЕРЕВІР","icon":"🧐","type":"order","title":"Перевір твердження ШІ","file":"М2_Урок15_Гра2_Перевір-твердження.html","conceptName":"перевірка тверджень","concept":"Кожен окремий факт у відповіді ШІ — твердження: дата, число, назва, місце. Важливі твердження звіряють із надійним джерелом: підручником, енциклопедією, офіційним сайтом. Порівнюють слово в слово, особливо числа й дати.","skill":"перевіряти твердження ШІ за надійним джерелом крок за кроком","data":{"rounds":[{"title":"ШІ написав: «Полярні ведмеді живуть у лісах України». Як перевірити?","steps":["Підкресли в реченні кожен окремий факт","Знайди надійне джерело: енциклопедію тварин і атлас природи України","Порівняй слово в слово: де живуть білі ведмеді, а де — бурі","Запиши: «ШІ написав ___, а джерело каже ___»"],"hint":"спочатку розбий відповідь на окремі факти","explain":"Джерела кажуть: білі ведмеді — в Арктиці, в Україні — бурі. Твердження ШІ хибне."},{"title":"ШІ написав: «Нагородження на марафоні — у великій залі о 14:00». Як перевірити?","steps":["Підкресли факти: місце і час нагородження","Знайди надійне джерело: шкільний розклад заходів","Порівняй: розклад каже «актова зала, п'ятниця, 11:30»","Запиши правильний факт і виправ текст"],"hint":"числа й місця порівнюй слово в слово","explain":"ШІ впевнено написав неправду про час і місце. Лише джерело дає правильний факт."}]}},"after":{"index":4,"heading":"🧩 Спробуй: перевір твердження"}},{"path":"app/games/М2_Урок15_Гра3_Факт-чи-вигадка.html","title":"Факт чи вигадка?","description":"сценарний вибір","data":{"id":"m2g15c","lesson":15,"tag":"ФАКТ","icon":"⚖️","type":"quiz","title":"Факт чи вигадка?","file":"М2_Урок15_Гра3_Факт-чи-вигадка.html","conceptName":"надійні джерела й справедливість","concept":"ШІ складає відповіді за закономірностями з текстів, тож може впевнено вигадувати. Якщо в навчальних даних когось бракує, система відтворює однобокість — це упередженість. Промпт цього не виправить: справедливішою систему роблять люди, а важливі рішення про людей ухвалює людина.","skill":"перевіряти відповіді ШІ й пояснювати, чому важливі рішення лишаються за людиною","data":{"questions":[{"q":"ШІ пише: «Полярні ведмеді товаришують із бурими в лісах України». Енциклопедія: білі — в Арктиці, атлас: у Карпатах — бурі. Що скажеш?","options":["Твердження правдиве, ШІ не помиляється","Твердження хибне: ШІ поєднав знайомі слова в правдоподібне речення"],"correct":1,"explain":"ШІ склав правдоподібне, але хибне речення. Саме тому важливі факти перевіряє людина."},{"q":"Програму «Капітан Спорт» навчили на даних гуртка, де були лише хлопці-футболісти. Тепер вона радить у капітани лише їх. Як це називається?","options":["Упередженість через однобокі дані","Швидка робота програми","Гарний промпт"],"correct":0,"explain":"У даних бракувало дівчат та інших видів спорту, і система відтворила цю однобокість. Це упередженість."},{"q":"Як зробити «Капітана Спорта» справедливішим?","options":["Написати ввічливіший промпт","Додати в навчальні дані дівчат та інші види спорту, а рішення лишити за вчителем","Вимкнути програму назавжди"],"correct":1,"explain":"Промпт упередженості не виправить. Допомагають повніші дані, правила й контроль людини."},{"q":"Хто має ухвалювати важливі рішення про людей, наприклад кого призначити капітаном?","options":["Програма, бо вона швидша","Людина, яка перевіряє й відповідає за наслідки"],"correct":1,"explain":"Важливі рішення про людей ухвалює людина. Програма може лише допомагати."},{"q":"Промпт має всі чотири частини: мету, аудиторію, формат і обмеження. Чи можна не перевіряти відповідь?","options":["Так, добрий промпт гарантує правду","Ні, ШІ однаково може помилитися чи не виконати умову"],"correct":1,"explain":"Добрий промпт підвищує шанс на потрібну відповідь, але не гарантує її. Факти й умови перевіряє людина."},{"q":"Запрошення починається зі слів «Привіт, четвертокласники!». Умова промпту: звертатися до всіх дітей однаково. Чи виконано умову?","options":["Так, слів небагато","Ні, краще «Привіт, 4 клас!» — тоді звертання однакове для всіх"],"correct":1,"explain":"«Четвертокласники» лишає когось осторонь. «Привіт, 4 клас!» звертається до всіх однаково."}]}},"after":{"index":4,"heading":"🧩 Спробуй: перевір твердження"}}],"legacyTitle":"Урок 15. Перевірка ШІ, точні промпти, походження даних і справедливість","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 15</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Перевірка ШІ, точні промпти, походження даних і справедливість</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Checking AI, Prompt Constraints, Data Provenance and Fairness</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як перевірити відповідь ШІ і що може зробити людина, щоб система працювала справедливіше?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я перевіряю важливе твердження ШІ за надійним джерелом.</li>\n      <li style=\"margin:6px 0;\">Я уточнюю <b>prompt</b>, додаючи конкретні умови.</li>\n      <li style=\"margin:6px 0;\">Я пояснюю, чому людина має перевіряти результат.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🤖 Звідки ШІ бере відповіді</h2>\n  <p style=\"margin:0 0 12px;\">Чат-бот не «знає» все на світі. Модель ШІ навчилася знаходити закономірності в дуже великій кількості текстів і складає відповідь за цими закономірностями. Тому відповідь може бути корисною й правильною, а може містити помилки чи вигадані подробиці — і звучати при цьому дуже впевнено.</p>\n  <p style=\"margin:0 0 12px;\">Кожен окремий факт у відповіді — це <b>твердження (claim)</b>: дата, число, назва, місце. Важливі твердження звіряють із <b>надійним джерелом (trusted source)</b>: підручником, енциклопедією, офіційним сайтом, шкільним розкладом.</p>\n  <p style=\"margin:0 0 8px;\">Як перевіряти, крок за кроком:</p>\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\">Підкресли у відповіді кожен окремий факт.</li>\n    <li style=\"margin:6px 0;\">Для кожного знайди надійне джерело.</li>\n    <li style=\"margin:6px 0;\">Порівняй слово в слово — особливо числа, дати й назви.</li>\n    <li style=\"margin:6px 0;\">Запиши: «ШІ написав ___, а джерело каже ___».</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✍️ Як уточнити prompt</h2>\n  <p style=\"margin:0 0 12px;\"><b>Промпт (prompt)</b> — це запит, який ми даємо ШІ. Що точніший запит, то ближчою до потрібного буде відповідь. Корисна підказка — подумати про чотири речі:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\"><b>Мета</b> — що треба зробити: написати запрошення, скласти список.</li>\n    <li style=\"margin:6px 0;\"><b>Аудиторія</b> — для кого: для однокласників, для молодших дітей.</li>\n    <li style=\"margin:6px 0;\"><b>Формат</b> — як має виглядати: одне речення, список із трьох пунктів.</li>\n    <li style=\"margin:6px 0;\"><b>Обмеження (constraints)</b> — умови: не більше 25 слів, без вигаданих фактів.</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Це не обов'язкова формула, а підказка: інколи вистачає двох умов, інколи потрібні інші. І навіть найкращий промпт не гарантує правильної відповіді. Результат однаково порівнюють із задумом — тим, що треба було отримати, — і з самим промптом: чи виконано всі умови?</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚖️ Дані й справедливість</h2>\n  <p style=\"margin:0 0 12px;\">Модель навчається на даних, які для неї зібрали люди. Якщо в цих даних когось бракує — наприклад, дівчат, дітей з інших шкіл чи інших видів спорту, — система може відтворити або навіть посилити таку однобокість. Це називають <b>упередженістю (bias)</b>.</p>\n  <p style=\"margin:0 0 12px;\">Промпт цього не виправить. Справедливішою систему роблять люди: збирають повніші дані, додають правила й перевірки, а важливі рішення про людей ухвалюють самі, а не доручають програмі.</p>\n\n  <svg viewBox=\"0 0 860 220\" role=\"img\" aria-labelledby=\"g4u15a-t g4u15a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u15a-t\">Три місця, де людина впливає на результат ШІ</title>\n    <desc id=\"g4u15a-d\">Перший блок: навчальні дані — чи всіх у них враховано. Другий блок: промпт — чи зрозумілі мета й умови. Третій блок: перевірка людиною — чи підтверджують твердження надійні джерела і чи справедливий результат.</desc>\n    <g font-family=\"Arial, sans-serif\">\n      <rect x=\"6\" y=\"20\" width=\"262\" height=\"170\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"137\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">1. Навчальні дані</text>\n      <text x=\"137\" y=\"100\" text-anchor=\"middle\" font-size=\"30\">📚</text>\n      <text x=\"137\" y=\"142\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">чи всіх у них</text>\n      <text x=\"137\" y=\"164\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">враховано?</text>\n      <path d=\"M272 105 H286\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path><polygon points=\"284,97 296,105 284,113\" fill=\"#0033A0\"></polygon>\n      <rect x=\"298\" y=\"20\" width=\"262\" height=\"170\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n      <text x=\"429\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\">2. Промпт</text>\n      <text x=\"429\" y=\"100\" text-anchor=\"middle\" font-size=\"30\">✍️</text>\n      <text x=\"429\" y=\"142\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">чи зрозумілі мета</text>\n      <text x=\"429\" y=\"164\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">та умови?</text>\n      <path d=\"M564 105 H578\" fill=\"none\" stroke=\"#0033A0\" stroke-width=\"3\"></path><polygon points=\"576,97 588,105 576,113\" fill=\"#0033A0\"></polygon>\n      <rect x=\"590\" y=\"20\" width=\"264\" height=\"170\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n      <text x=\"722\" y=\"56\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\">3. Перевірка людиною</text>\n      <text x=\"722\" y=\"100\" text-anchor=\"middle\" font-size=\"30\">🧑‍⚖️</text>\n      <text x=\"722\" y=\"142\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">чи підтверджують джерела?</text>\n      <text x=\"722\" y=\"164\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">чи результат справедливий?</text>\n    </g>\n  </svg>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: перевір твердження</h2>\n  <p style=\"margin:0 0 12px;\">ШІ-помічник написав: <i>«Полярні ведмеді чудово почуваються в лісах України й часто товаришують із бурими ведмедями»</i>.</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\"><b>Джерело А (енциклопедія тварин):</b> «Білі ведмеді живуть в Арктиці, серед льодів».</li>\n    <li style=\"margin:6px 0;\"><b>Джерело Б (атлас природи України):</b> «У Карпатах мешкають бурі ведмеді».</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Чи підтверджують джерела твердження ШІ?</p>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\">Ні. Білі ведмеді живуть в Арктиці, а в Україні — бурі. ШІ поєднав знайомі слова в правдоподібне, але хибне речення. Саме тому важливі факти перевіряє людина.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Ризик для справедливості.</b> Вигадана програма «Капітан Спорт» радить учителеві, кого призначити капітаном команди. Її навчили на даних шкільного футбольного гуртка, де грали лише хлопці. Тепер програма радить лише хлопців-футболістів. Запиши: кого не врахували дані? Чому це несправедливо для класу?</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Промпт.</b> Учитель хоче, щоб ШІ написав коротке запрошення на змагання з бігу. Склади промпт із метою, аудиторією (учні й учениці 4 класу), форматом і двома умовами: не більше 25 слів і звертання до всіх дітей однаково.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Перевірка результату.</b> ШІ відповів так:</p>\n  <div style=\"background:#FFF9DB;border-left:5px solid #B38600;border-radius:8px;padding:14px 16px;margin:12px 0;\">\n    <p style=\"margin:0;\"><i>«Привіт, четвертокласники! Реєструйтеся на шкільний марафон з бігу у вівторок, 8 вересня! Нагородження переможців відбудеться у великій залі о 14:00.»</i></p>\n  </div>\n  <p style=\"margin:0 0 8px;\">Шкільні джерела кажуть:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\"><b>Шкільний календар:</b> «Змагання з бігу для 4 класу — у вівторок, 8 вересня».</li>\n    <li style=\"margin:6px 0;\"><b>Розклад заходів:</b> «Нагородження — в актовій залі в п'ятницю об 11:30».</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Запиши: одне твердження, яке підтверджується; одне, яке суперечить джерелу, і правильний факт; чи виконано обидві умови твого промпту — порахуй слова й подивись на звертання.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Не врахували дівчат і дітей з інших видів спорту. Програма відтворює однобокість даних, тож талановиті учні й учениці не мають шансу.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2, приклад.</b> «Напиши запрошення на шкільні змагання з бігу для учнів і учениць 4 класу. Одне речення, не більше 25 слів. Звертайся до всіх дітей однаково».</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Підтверджується: змагання у вівторок, 8 вересня. Суперечить: нагородження не о 14:00 у великій залі, а в п'ятницю об 11:30 в актовій залі. Слів 20 — ця умова виконана. Але «четвертокласники» звертається лише до хлопців — цю умову не виконано, краще «Привіт, 4 клас!».</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Перевіряй по одному факту. У відповіді ШІ у Кроці 3 їх три: день і дата, час нагородження, місце нагородження. Знайди кожен у джерелах.</p>\n    <p style=\"margin:10px 0 0;\">Для промпту допиши речення: <i>«Напиши ___ для ___. Формат: ___. Умови: ___»</i>.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти перевіряєш два твердження й називаєш, кого не врахувала програма в Кроці 1.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Звідки взялися дані й хто їх збирав, називають <b>походженням даних (data provenance)</b>. Саме воно пояснило проблему «Капітана Спорта».</p>\n    <p style=\"margin:10px 0 0;\">Запропонуй одну зміну, щоб система стала справедливішою:</p>\n    <ul style=\"margin:10px 0 0;padding-left:22px;\">\n      <li style=\"margin:5px 0;\"><b>Дані:</b> які результати додати до навчання?</li>\n      <li style=\"margin:5px 0;\"><b>Інтерфейс:</b> яке нагадування показати вчителеві перед вибором?</li>\n      <li style=\"margin:5px 0;\"><b>Людський контроль:</b> хто ухвалює остаточне рішення і чому не програма?</li>\n    </ul>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>An AI claim must be checked with a trusted source.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Штучний інтелект для дітей</b> — як ШІ вчиться на даних і чому помиляється. <b>Критичне мислення</b> — хто автор, коли створено, чи є джерело. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–20 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/ai/ai_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">ШІ для дітей ↗</a>\n    <a href=\"https://itnauka.org/services/security_and_safety/critical_thinking_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;\">Критичне мислення ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u15-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке упередженість (bias) у ШІ?</label>\n    <select id=\"g4-u15-q1\" name=\"g4-u15-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Повільна робота програми</option>\n      <option>Однобокі результати через дані, у яких когось бракує</option>\n      <option>Уміння говорити лише англійською</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Якщо дані однобокі, система може відтворити цю однобокість у своїх порадах.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u15-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Яка частина промпту задає правило «не більше 25 слів»?</label>\n    <select id=\"g4-u15-q2\" name=\"g4-u15-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Мета</option>\n      <option>Аудиторія</option>\n      <option>Обмеження (constraint)</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Обмеження. Воно задає межі відповіді: обсяг, тон, що не можна робити.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u15-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Промпт має всі чотири частини. Чи можна не перевіряти відповідь?</label>\n    <select id=\"g4-u15-q3\" name=\"g4-u15-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Так, добрий промпт гарантує правду</option>\n      <option>Ні, ШІ однаково може помилитися чи не виконати умову</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Ні. Добрий промпт підвищує шанс на потрібну відповідь, але не гарантує її. Факти й умови перевіряє людина.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Щоб перевірити ШІ, я ___. Щоб система була справедливішою, люди можуть ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я перевіряю щонайменше два твердження ШІ за джерелами й записую правильний факт.</li>\n      <li style=\"margin:8px 0;\">Мій промпт має мету, аудиторію, формат і дві умови.</li>\n      <li style=\"margin:8px 0;\">Я пояснюю один ризик для справедливості в «Капітані Спорті».</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> два перевірені твердження й відповідь на Крок 1.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> записи до Кроків 1–3 у зошиті.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>claim</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">твердження</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>trusted source</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">надійне джерело</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>prompt</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">запит до ШІ</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>constraint</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">обмеження, умова</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>bias / fairness</b></td><td style=\"padding:8px 10px;\">упередженість / справедливість</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I added a constraint to my prompt. I checked the AI claim with a trusted source.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-2-8","grade":4,"module":2,"number":8,"title":"Мультимедійний матеріал із перевіреними джерелами та відповідальним використанням ресурсів","moduleTitle":"Дані, датчики, моделі та ШІ","games":[{"path":"app/games/М2_Урок16_Гра1_Перевір-памятку.html","title":"Перевір пам'ятку","description":"сортування карток","data":{"id":"m2g16a","lesson":16,"tag":"ПАМЯТКА","icon":"🖼️","type":"sort","title":"Перевір пам'ятку","file":"М2_Урок16_Гра1_Перевір-памятку.html","conceptName":"чесна пам'ятка","concept":"Добра пам'ятка: текст перевірено, зображення має підпис джерела (звідки, хто автор, яка ліцензія), посилання перевірене на іншому пристрої, допомога ШІ позначена чесно, а файл не зайво великий.","skill":"відрізняти чесну й перевірену роботу від недбалої","data":{"categories":[{"id":"ok","label":"✅ Чесно й правильно","hint":"так робить відповідальний автор"},{"id":"bad","label":"❌ Помилка","hint":"це треба виправити"}],"items":[{"text":"Під зображенням підписано: джерело, автор, ліцензія","cat":"ok","explain":"Підпис джерела поважає чужу працю. Так і треба.","hint":"чи поважаємо ми автора зображення?"},{"text":"Картинку скопійовано з інтернету без підпису","cat":"bad","explain":"Без підпису джерела це нечесно: наче чужа робота — твоя.","hint":"а де підпис джерела?"},{"text":"Посилання перевірено: відкривається і на планшеті друга","cat":"ok","explain":"Посилання перевіряють і на іншому пристрої. Молодець!","hint":"перевірка на іншому пристрої — це добре"},{"text":"У матеріалі посилання, яке не відкривається","cat":"bad","explain":"Посилання треба натиснути й перевірити. Неробоче — виправити чи прибрати.","hint":"чи працює це посилання?"},{"text":"Голосовий текст перечитано і помилки виправлено","cat":"ok","explain":"Програма могла неправильно розчути слова. Перевірка — обов'язкова.","hint":"чи може програма розчути з помилками?"},{"text":"Надиктований текст вставлено одразу, без перечитування","cat":"bad","explain":"Голосове введення помиляється через шум чи нечітку вимову. Текст треба перечитати.","hint":"чи точно програма все розчула?"},{"text":"Чесно позначено: «Ідею кольорів підказав ШІ»","cat":"ok","explain":"Допомогу ШІ позначають відверто. Це чесно.","hint":"чи чесно це?"},{"text":"Збережено десять однакових копій великої картинки","cat":"bad","explain":"Зайві файли марнують місце на серверах. Зберігаємо лише потрібне.","hint":"чи потрібно стільки копій?"}]}},"after":{"index":3,"heading":"🏷 Зображення, джерело і посилання"}},{"path":"app/games/М2_Урок16_Гра2_Клавіатура-чи-голос.html","title":"Клавіатура чи голос?","description":"сценарний вибір","data":{"id":"m2g16b","lesson":16,"tag":"ГОЛОС","icon":"🎙️","type":"quiz","title":"Клавіатура чи голос?","file":"М2_Урок16_Гра2_Клавіатура-чи-голос.html","conceptName":"точність введення","concept":"Текст можна надрукувати або надиктувати — програма перетворить голос на текст. Голосом часто швидше, але програма може неправильно розчути слова через шум чи нечітку вимову. Тому голосовий текст завжди перечитують і виправляють.","skill":"порівнювати введення з клавіатури й голосом за точністю","data":{"questions":[{"q":"Надруковано: «Сортування сміття рятує чисту воду». Надиктовано: «Сортуваня смітя ратує чи сто во ду». Який спосіб точніший?","options":["Голос","Клавіатура","Обидва однакові"],"correct":1,"explain":"У голосовому варіанті загубилися подвоєні літери, а «чисту воду» розпалося на склади. Клавіатура тут точніша."},{"q":"Чому голосове введення може помилятися?","options":["Через шум, швидку чи нечітку вимову","Бо телефон втомлюється","Воно ніколи не помиляється"],"correct":0,"explain":"Шум і нечітка вимова заважають програмі розчути слова. Тому текст перечитують."},{"q":"Ти надиктував речення голосом. Що робити далі?","options":["Одразу надсилати","Перечитати й виправити помилки","Видалити"],"correct":1,"explain":"Голосовий текст завжди перечитують: точність перевіряє людина."},{"q":"Коли голосове введення особливо зручне?","options":["Коли треба швидко записати ідею, а потім виправити текст","Коли навколо дуже галасливо","Коли потрібен ідеальний текст без перевірки"],"correct":0,"explain":"Голосом швидко, але після цього текст перечитують і виправляють."},{"q":"Що таке мультимедіа?","options":["Довгий текст без картинок","Поєднання кількох режимів: тексту, зображень, звуку, відео, посилань","Жорсткий диск"],"correct":1,"explain":"Кожен спосіб передати інформацію — режим, а їхнє поєднання — мультимедіа."},{"q":"Перш ніж створювати пам'ятку, автор відповідає на два питання. Які?","options":["Яка мета і хто аудиторія","Який колір і який шрифт","Скільки слайдів і який комп'ютер"],"correct":0,"explain":"Мета (навіщо) й аудиторія (для кого) вирішують, які режими важливіші: для малюків — більше картинок, для батьків — чіткий текст."}]}},"after":{"index":2,"heading":"⌨️ Клавіатура чи голос"}},{"path":"app/games/М2_Урок16_Гра3_Створюємо-памятку.html","title":"Створюємо пам'ятку","description":"послідовність кроків","data":{"id":"m2g16c","lesson":16,"tag":"РЕСУРС","icon":"🌱","type":"order","title":"Створюємо пам'ятку","file":"М2_Урок16_Гра3_Створюємо-памятку.html","conceptName":"відповідальне створення матеріалів","concept":"Цифрові дані потребують ресурсів: сервери в дата-центрах працюють цілодобово й споживають електроенергію, деякі охолоджуються водою, а старі пристрої стають електронним сміттям. Тож зберігай потрібне, стискай завеликі файли й не створюй зайвого.","skill":"створювати матеріал із перевіреними джерелами й дбати про розмір файлів","data":{"rounds":[{"title":"Порядок дій: створюємо пам'ятку «Бережемо ресурси»","steps":["Визнач мету й аудиторію пам'ятки","Введи гасло й виправ помилки в тексті","Додай зображення з підписом: джерело, автор, ліцензія","Додай посилання й перевір, чи відкривається воно на іншому пристрої","Перевір розмір файлу: завелике зображення зменши"],"hint":"спочатку подумай ДЛЯ КОГО і НАВІЩО, а вже потім оформлюй","explain":"Мета й аудиторія — першими. Джерело й посилання — перед фінальною перевіркою розміру."},{"title":"Порядок дій: дбаємо про ресурси планети","steps":["Згадай: сервери споживають електроенергію й воду","Видали зайві копії файлів","Стисни завеликі зображення, якщо висока якість не потрібна","Старі пристрої здай на переробку, а не у відро для сміття"],"hint":"один видалений файл планету не врятує, але звичка — корисний внесок","explain":"Зберігання й передавання даних справді потребують ресурсів. Менші файли й переробка — невеликий, але корисний внесок."}]}},"after":{"index":3,"heading":"🏷 Зображення, джерело і посилання"}}],"legacyTitle":"Урок 16. Мультимедійний матеріал із перевіреними джерелами","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 2 &bull; Урок 16</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Мультимедійний матеріал із перевіреними джерелами та відповідальним використанням ресурсів</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">A Multimedia Artefact with Verified Sources and Responsible Resource Use</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як поєднати текст, зображення й посилання так, щоб матеріал був точним, чесним і зручним для читача?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я порівнюю введення з клавіатури (<b>typing</b>) і голосом (<b>speech-to-text</b>) за точністю.</li>\n      <li style=\"margin:6px 0;\">Я створюю матеріал із текстом, зображенням, джерелом і посиланням.</li>\n      <li style=\"margin:6px 0;\">Я перевіряю посилання та стежу, щоб файл не був зайво великим.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🎬 Що таке мультимедіа</h2>\n  <p style=\"margin:0 0 12px;\">Плакат, презентація чи вебсторінка зазвичай поєднують кілька способів передати інформацію: текст, зображення, звук, відео, посилання. Кожен такий спосіб називають <b>режимом (mode)</b>, а їхнє поєднання — <b>мультимедіа (multimedia)</b>.</p>\n  <p style=\"margin:0 0 12px;\">Перш ніж створювати, автор відповідає на два питання. <b>Мета (purpose)</b>: навіщо цей матеріал — пояснити, попередити, запросити? <b>Аудиторія (audience)</b>: хто його читатиме — однокласники, молодші діти чи батьки? Від відповідей залежить, який режим важливіший: для малюків — більше картинок, для батьків — чіткий текст.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⌨️ Клавіатура чи голос</h2>\n  <p style=\"margin:0 0 12px;\">Текст можна надрукувати (<b>typing</b>) або надиктувати: програма перетворить голос на текст (<b>speech-to-text</b>). Голосом часто швидше, але програма може неправильно розчути слова — через шум, швидку чи нечітку вимову. Тому голосовий текст завжди перечитують і виправляють, щоб досягти <b>точності (accuracy)</b>.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🏷 Зображення, джерело і посилання</h2>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Завантажуй (download)</b> зображення лише з надійних джерел, які дозволив учитель, і зберігай у своїй папці з зрозумілою назвою.</li>\n    <li style=\"margin:8px 0;\"><b>Підписуй джерело (source credit):</b> звідки зображення, хто автор, яка ліцензія. Так ми поважаємо чужу працю.</li>\n    <li style=\"margin:8px 0;\"><b>Позначай допомогу ШІ:</b> якщо гасло чи кольори підказав ШІ, чесно про це напиши.</li>\n    <li style=\"margin:8px 0;\"><b>Перевіряй гіперпосилання (hyperlink):</b> натисни його сам чи сама, а потім відкрий матеріал на іншому пристрої чи в іншому вікні — чи посилання працює й там?</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🌱 Дані теж потребують ресурсів</h2>\n  <p style=\"margin:0 0 12px;\">Файли в «хмарі» зберігаються на серверах у дата-центрах. Ці будівлі споживають багато електроенергії, а деякі ще й використовують воду для охолодження. Старі пристрої, які викидають, стають електронним сміттям.</p>\n\n  <svg viewBox=\"0 0 860 210\" role=\"img\" aria-labelledby=\"g4u16a-t g4u16a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u16a-t\">Які ресурси потрібні цифровим даним</title>\n    <desc id=\"g4u16a-d\">Три картки. Електроенергія: сервери в дата-центрах працюють цілодобово. Вода: деякі дата-центри охолоджують водою. Електронне сміття: старі пристрої треба здавати на переробку. Внизу порада: зберігай потрібне, стискай, коли висока якість не потрібна, не створюй зайвого.</desc>\n    <g font-family=\"Arial, sans-serif\">\n      <rect x=\"6\" y=\"14\" width=\"270\" height=\"140\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n      <text x=\"141\" y=\"52\" text-anchor=\"middle\" font-size=\"26\">⚡</text>\n      <text x=\"141\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\">Електроенергія</text>\n      <text x=\"141\" y=\"112\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">сервери працюють</text>\n      <text x=\"141\" y=\"134\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">цілодобово</text>\n      <rect x=\"295\" y=\"14\" width=\"270\" height=\"140\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"430\" y=\"52\" text-anchor=\"middle\" font-size=\"26\">💧</text>\n      <text x=\"430\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">Вода</text>\n      <text x=\"430\" y=\"112\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">деякі дата-центри</text>\n      <text x=\"430\" y=\"134\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">охолоджують водою</text>\n      <rect x=\"584\" y=\"14\" width=\"270\" height=\"140\" rx=\"12\" fill=\"#FFF2F2\" stroke=\"#C0392B\" stroke-width=\"2\"></rect>\n      <text x=\"719\" y=\"52\" text-anchor=\"middle\" font-size=\"26\">♻️</text>\n      <text x=\"719\" y=\"84\" text-anchor=\"middle\" font-size=\"17\" font-weight=\"700\" fill=\"#96271B\">Електронне сміття</text>\n      <text x=\"719\" y=\"112\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">старі пристрої —</text>\n      <text x=\"719\" y=\"134\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\">на переробку</text>\n      <rect x=\"6\" y=\"166\" width=\"848\" height=\"36\" rx=\"10\" fill=\"#E9F4ED\"></rect>\n      <text x=\"430\" y=\"190\" text-anchor=\"middle\" font-size=\"15\" fill=\"#155C32\">зберігай потрібне • стискай, коли висока якість не потрібна • не створюй зайвого</text>\n    </g>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Один видалений файл планету не врятує. Але зберігання й передавання даних справді потребують ресурсів. Менші й доречно стиснені файли зменшують потребу в місці на серверах і в пересиланні. Тож звичка не зберігати зайве й не генерувати десятки непотрібних картинок — невеликий, але корисний внесок.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Спробуй: порівняй два способи введення</h2>\n  <p style=\"margin:0 0 12px;\">Учень записав одне речення двома способами:</p>\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:6px 0;\"><b>Клавіатура:</b> «Сортування сміття рятує чисту воду».</li>\n    <li style=\"margin:6px 0;\"><b>Голос:</b> «Сортуваня смітя ратує чи сто во ду».</li>\n  </ul>\n  <p style=\"margin:0 0 12px;\">Який спосіб точніший? Знайди всі помилки в другому варіанті.</p>\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\">Точніша клавіатура. У голосовому варіанті загубилися подвоєні літери («сортуваня» замість «сортування», «смітя» замість «сміття»), «ратує» замість «рятує», а «чисту воду» розпалося на склади. Голосом швидше — але текст треба перевірити.</p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n  <p style=\"margin:0 0 12px;\">Створи одну сторінку чи один слайд — цифрову пам'ятку для учнів школи. Тема за замовчуванням: «Бережемо ресурси в цифровому світі». Учитель може запропонувати іншу безпечну тему.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Текст.</b> Введи гасло пам'ятки голосом (якщо є мікрофон), а потім те саме — з клавіатури. Запиши в зошит, що розпізнала програма і які помилки були. Залиш у пам'ятці виправлений варіант.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Зображення.</b> Завантаж одне зображення з джерела, яке дозволив учитель. Збережи його у своїй папці, встав у пам'ятку й додай підпис: джерело, автор, ліцензія.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Посилання.</b> Додай гіперпосилання на сторінку, яку дасть учитель. Перевір: чи відкривається воно в тебе? Чи відкривається на іншому пристрої або в іншому вікні? Запиши обидві відповіді.</p>\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Розмір і чесність.</b> Подивись розмір свого файлу. Якщо зображення зайво велике — зменш його й запиши розмір до та після зменшення. Познач, чи допомагав ШІ.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити: зразок підпису й перевірки</summary>\n    <p style=\"margin:10px 0 0;\"><b>Підпис:</b> «Зображення: Wikimedia Commons. Автор: Ім'я Прізвище. Ліцензія: CC BY-SA 4.0».</p>\n    <p style=\"margin:10px 0 0;\"><b>Перевірка посилання:</b> «У мене відкривається — так. На планшеті друга — так». Якщо «ні» — перевір, чи немає в адресі пробілу, зайвої крапки чи кириличної літери замість латинської.</p>\n    <p style=\"margin:10px 0 0;\"><b>Позначка ШІ:</b> «Гасло придумано самостійно» або «Ідею кольорів підказав ШІ».</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Попроси в учителя шаблон пам'ятки з готовими місцями: «Гасло», «Зображення», «Джерело», «Посилання».</p>\n    <p style=\"margin:10px 0 0;\">Якщо мікрофона немає, у Кроці 1 порівняй надрукований текст із голосовим прикладом у блоці «Спробуй».</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо в пам'ятці є виправлене гасло, зображення з підписом джерела й перевірене посилання.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Доступність.</b> Одні читачі погано бачать, інші погано чують. Додай до зображення <b>альтернативний текст (alt text)</b> — коротке словесне пояснення, що на ньому. Програма озвучення прочитає його вголос.</p>\n    <p style=\"margin:10px 0 0;\">Запиши 10-секундний аудіоваріант гасла. Поясни, як поєднання режимів допомагає різним людям зрозуміти твою пам'ятку.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>I tested my link on another device. I added a source credit.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Критичне мислення</b> — хто автор, коли створено, чи є джерело. <b>Факт чи думка</b> — гра на розрізнення перевірюваних фактів і думок. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/security_and_safety/critical_thinking_for_kids/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Критичне мислення ↗</a>\n    <a href=\"https://itnauka.org/games/fact-or-opinion/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#FFFFFF;color:#0033A0;text-decoration:none;font-weight:700;padding:9px 13px;border:2px solid #0033A0;border-radius:8px;\">Факт чи думка ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u16-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке мультимедіа?</label>\n    <select id=\"g4-u16-q1\" name=\"g4-u16-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Довгий текст без картинок</option>\n      <option>Поєднання кількох режимів: тексту, зображень, звуку</option>\n      <option>Жорсткий диск комп'ютера</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Поєднання кількох режимів. Так матеріал стає зрозумілішим для різних людей.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u16-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Навіщо перечитувати текст після голосового введення?</label>\n    <select id=\"g4-u16-q2\" name=\"g4-u16-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Програма могла неправильно розчути слова</option>\n      <option>Щоб текст став довшим</option>\n      <option>Не потрібно, голосове введення завжди точне</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Програма могла помилитися через шум чи нечітку вимову. Точність перевіряє людина.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u16-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Яке твердження точне?</label>\n    <select id=\"g4-u16-q3\" name=\"g4-u16-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Кожен видалений файл рятує планету</option>\n      <option>Зберігання й передавання даних потребують ресурсів, тому зайвого краще не зберігати</option>\n      <option>Цифрові дані не потребують жодної енергії</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге. Сервери споживають енергію, тож доречний розмір файлів і відмова від зайвого — розумна звичка. Але перше твердження перебільшує.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку на прикладі своєї пам'ятки:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Моя пам'ятка точна, бо ___. Чесна, бо ___. Зручна для читача, бо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">У зошиті є порівняння введення з клавіатури і голосом.</li>\n      <li style=\"margin:8px 0;\">У пам'ятці є виправлений текст, зображення з підписом джерела й робоче посилання.</li>\n      <li style=\"margin:8px 0;\">Я записую результат перевірки посилання й позначаю допомогу ШІ, якщо вона була.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> шаблон пам'ятки з гаслом, зображенням, джерелом і посиланням.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> готову пам'ятку й записи до Кроків 1–4.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>multimedia</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">мультимедіа</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>speech-to-text</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">голосове введення</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>accuracy</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">точність</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>source credit</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">підпис джерела</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>hyperlink</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">гіперпосилання</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>download</b></td><td style=\"padding:8px 10px;\">завантажити</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I used speech-to-text, but I checked it for accuracy. I added a source credit to my image.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-1","grade":4,"module":3,"number":1,"title":"Порівнюємо алгоритми для одного завдання","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок17_Гра1_Критерії.html","title":"Чотири критерії","description":"сортування карток","data":{"id":"m3g17a","lesson":17,"tag":"КРИТЕР","icon":"⚖️","type":"sort","title":"Чотири критерії","file":"М3_Урок17_Гра1_Критерії.html","conceptName":"чотири критерії алгоритму","concept":"Гарний алгоритм: правильний (робить саме те, що просять), стислий (без зайвих блоків), зрозумілий (легко прочитати) і легко змінюється. Коротший — не завжди кращий: спершу він має бути правильним.","skill":"оцінювати алгоритм за чотирма критеріями: правильність, стислість, зрозумілість, легкість змін","data":{"categories":[{"id":"ok","label":"✔ Правильний","hint":"робить саме те, що просять"},{"id":"short","label":"✂️ Стислий","hint":"немає зайвих блоків"},{"id":"clear","label":"👀 Зрозумілий","hint":"легко прочитати й пояснити"},{"id":"flex","label":"🔧 Легко змінити","hint":"одна правка — новий результат"}],"items":[{"text":"Алгоритм малює плюс із чотирьох променів, як у завданні","cat":"ok","explain":"Головна перевірка: результат збігається із завданням.","hint":"чи збігається результат із завданням?"},{"text":"Програма дає правильний малюнок і з кроком 30, і з кроком 50","cat":"ok","explain":"Правильний алгоритм працює для різних значень, а не лише раз.","hint":"працює не лише в одному випадку"},{"text":"Цикл прибрав сім зайвих блоків руху","cat":"short","explain":"Повторення сховалося в цикл — блоків менше, сенс той самий.","hint":"те саме — меншою кількістю блоків"},{"text":"Повторення записане одним блоком «повторити 4»","cat":"short","explain":"Один блок циклу замінює довгий ланцюжок однакових блоків.","hint":"без копій однакових блоків"},{"text":"Однокласник читає блоки й одразу пояснює, що робить програма","cat":"clear","explain":"Зрозумілий код читається як розповідь.","hint":"інша людина розуміє без підказок"},{"text":"Порядок блоків легко переказати своїми словами","cat":"clear","explain":"Якщо програму легко розповісти — вона зрозуміла.","hint":"можна пояснити без коду"},{"text":"Щоб змінити довжину променів, міняємо одне число","cat":"flex","explain":"Одна правка — і весь малюнок новий. Це легко змінити.","hint":"скільки правок треба?"},{"text":"Хочемо шість променів — змінюємо лише число повторень","cat":"flex","explain":"Кількість і кут задані числами в одному місці — зміна проста.","hint":"нова фігура за одну правку"}]}},"after":{"index":1,"heading":"🧭 Одне завдання — різні алгоритми"}},{"path":"app/games/М3_Урок17_Гра2_Найкращий-алгоритм.html","title":"Обери найкращий алгоритм","description":"сценарний вибір","data":{"id":"m3g17b","lesson":17,"tag":"ВИБІР","icon":"🏆","type":"quiz","title":"Обери найкращий алгоритм","file":"М3_Урок17_Гра2_Найкращий-алгоритм.html","conceptName":"як порівнювати алгоритми","concept":"Одне завдання можна розв'язати по-різному. Порівнюємо алгоритми за критеріями: правильний? стислий? зрозумілий? легко змінити? Поради чат-бота теж перевіряємо — запуском.","skill":"порівнювати алгоритми для одного завдання й обирати кращий із поясненням чому","data":{"questions":[{"q":"Треба намалювати плюс із чотирьох променів по 30 кроків. Який алгоритм найкращий?","options":["Повторити 4 рази: крок 30, назад 30, поворот 90","11 блоків руху без циклу","Повторити 3 рази: крок 30, назад 30, поворот 90"],"correct":0,"explain":"Він правильний, стислий і його легко змінити: нова довжина — одне число.","wrong":"Три повторення дадуть лише три промені, а довгу програму без циклу важко змінювати."},{"q":"Чат-бот порадив алгоритм із трьома повтореннями. Що зробити спершу?","options":["Запустити й порівняти результат із завданням","Переписати в зошит і здати","Додати блоків, щоб виглядало серйозно"],"correct":0,"explain":"Поради ШІ завжди перевіряємо запуском: три повторення дають три промені замість чотирьох.","wrong":"ШІ може помилятися. Його пораду приймаємо лише після перевірки."},{"q":"Два алгоритми малюють однаковий правильний візерунок. Один має 20 блоків, другий — 6 із циклом. Який легше змінити?","options":["З 20 блоками","З 6 блоками і циклом","Обидва однаково"],"correct":1,"explain":"У циклі зміна одного числа оновлює всю фігуру. У 20 блоках треба правити кожен.","wrong":"Порахуй, скільки правок знадобиться, щоб змінити довжину в кожному варіанті."},{"q":"Ти відкрив(-ла) чужий проєкт. Який перший крок за правилом п'яти кроків?","options":["Одразу щось змінити","Запустити все підряд","Передбачити, що зробить код"],"correct":2,"explain":"Порядок такий: передбач → запусти → досліди → зміни → створи.","wrong":"Спершу подумай, що код зробить, і лише потім запускай і змінюй."},{"q":"Що таке трасування алгоритму?","options":["Читання блоків один за одним із записом змін","Швидкий перегляд коду по діагоналі","Видалення зайвих блоків"],"correct":0,"explain":"При трасуванні ми повільно «виконуємо» блоки самі й записуємо, що змінюється.","wrong":"Трасування — це уважне читання блок за блоком, а не пробіжка очима."},{"q":"Чи завжди коротший алгоритм кращий?","options":["Так, завжди","Ні, спершу він має бути правильним","Так, якщо в ньому є цикл"],"correct":1,"explain":"Короткий, але неправильний алгоритм не розв'язує завдання. Правильність — перший критерій.","wrong":"Згадай алгоритм із трьома повтореннями: короткий, але малює не той плюс."}]}},"after":{"index":1,"heading":"🧭 Одне завдання — різні алгоритми"}},{"path":"app/games/М3_Урок17_Гра3_Читаємо-код.html","title":"Читаємо чужий код","description":"послідовність кроків","data":{"id":"m3g17c","lesson":17,"tag":"ЧИТАЄМО","icon":"🔍","type":"order","title":"Читаємо чужий код","file":"М3_Урок17_Гра3_Читаємо-код.html","conceptName":"п'ять кроків роботи з кодом","concept":"Новий код досліджуємо поетапно: передбач → запусти → досліди → зміни → створи. Так ми розуміємо чужі програми й вчимося на них. Поради ШІ перевіряємо так само.","skill":"досліджувати чужий код за п'ятьма кроками й перевіряти поради ШІ запуском","data":{"rounds":[{"title":"П'ять кроків роботи з новим кодом","steps":["Передбач, що зробить програма","Запусти й подивись","Досліди блоки, які здивували","Зміни одну річ","Створи свою версію"],"hint":"спочатку думаємо, потім запускаємо","explain":"Цей порядок допомагає розібратися в чужому коді й навчитися на ньому."},{"title":"Перевіряємо пораду чат-бота","steps":["Прочитай запропоновані блоки","Передбач результат","Запусти програму","Порівняй із завданням","Виправ, якщо не збігається"],"hint":"пораду ШІ не приймаємо на віру","explain":"ШІ може помилятися, тому його поради завжди перевіряємо запуском."}]}},"after":{"index":2,"heading":"🔁 Як ми працюємо з кодом"}}],"legacyTitle":"Урок 17. Порівнюємо алгоритми для одного завдання","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 17</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Порівнюємо алгоритми для одного завдання</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Comparing Algorithms for the Same Task</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як вибрати найкращий із кількох алгоритмів для одного завдання?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я прогнозую результат алгоритму (<b>predict</b>) і перевіряю прогноз у Scratch.</li>\n      <li style=\"margin:6px 0;\">Я порівнюю алгоритми щонайменше за двома критеріями (<b>criteria</b>).</li>\n      <li style=\"margin:6px 0;\">Я обираю або покращую алгоритм і пояснюю свій вибір.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧭 Одне завдання — різні алгоритми</h2>\n\n  <p style=\"margin:0 0 12px;\">Щоб кіт у Scratch намалював фігуру, можна скласти різні <b>алгоритми (algorithms)</b>. Усі вони можуть дати однаковий малюнок, але відрізнятися довжиною, зрозумілістю і тим, як легко їх змінити.</p>\n\n  <p style=\"margin:0 0 12px;\">Щоб чесно порівняти рішення, домовляються про спільні <b>критерії (criteria)</b>:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Правильний (correct)</b> — робить саме те, що потрібно.</li>\n    <li style=\"margin:8px 0;\"><b>Стислий (concise)</b> — без зайвих повторень однакових команд.</li>\n    <li style=\"margin:8px 0;\"><b>Зрозумілий (clear)</b> — іншій людині легко прочитати, що він робить.</li>\n    <li style=\"margin:8px 0;\"><b>Легко змінити</b> — щоб змінити, наприклад, розмір, треба виправити мало чисел.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Коротший алгоритм не завжди кращий: спершу він має бути правильним. А «менше блоків» ще не означає «швидше працює». Фахівці кажуть <b>efficient</b> («ефективний»), коли програма виконується швидше чи витрачає менше ресурсів, — сьогодні ми порівнюємо простіше, за чотирма критеріями вище.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔁 Як ми працюємо з кодом</h2>\n\n  <p style=\"margin:0 0 12px;\">У цьому модулі кожна програма проходить п'ять кроків. Спершу прогнозуєш у зошиті, а потім перевіряєш і змінюєш програму в самому Scratch. Зошит не замінює запуску: правильність показує лише програма, яка справді працює.</p>\n\n  <svg viewBox=\"0 0 860 190\" role=\"img\" aria-labelledby=\"g4u17a-t g4u17a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u17a-t\">П'ять кроків роботи з кодом</title>\n    <desc id=\"g4u17a-d\">Передбач: що зробить програма. Запусти: перевір у Scratch. Досліди: чому вийшло саме так. Зміни: одну річ і запусти знову. Створи: власний варіант. Стрілка від «Створи» повертається до «Передбач».</desc>\n    <g font-family=\"Arial, sans-serif\" text-anchor=\"middle\">\n      <rect x=\"6\" y=\"20\" width=\"156\" height=\"110\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n      <text x=\"84\" y=\"58\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\">1. Передбач</text>\n      <text x=\"84\" y=\"86\" font-size=\"15\" fill=\"#3D4757\">що зробить</text>\n      <text x=\"84\" y=\"106\" font-size=\"15\" fill=\"#3D4757\">програма?</text>\n      <rect x=\"180\" y=\"20\" width=\"156\" height=\"110\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"258\" y=\"58\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">2. Запусти</text>\n      <text x=\"258\" y=\"86\" font-size=\"15\" fill=\"#3D4757\">перевір</text>\n      <text x=\"258\" y=\"106\" font-size=\"15\" fill=\"#3D4757\">у Scratch</text>\n      <rect x=\"354\" y=\"20\" width=\"156\" height=\"110\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"432\" y=\"58\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">3. Досліди</text>\n      <text x=\"432\" y=\"86\" font-size=\"15\" fill=\"#3D4757\">чому вийшло</text>\n      <text x=\"432\" y=\"106\" font-size=\"15\" fill=\"#3D4757\">саме так?</text>\n      <rect x=\"528\" y=\"20\" width=\"156\" height=\"110\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n      <text x=\"606\" y=\"58\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\">4. Зміни</text>\n      <text x=\"606\" y=\"86\" font-size=\"15\" fill=\"#3D4757\">одну річ —</text>\n      <text x=\"606\" y=\"106\" font-size=\"15\" fill=\"#3D4757\">і знову запусти</text>\n      <rect x=\"702\" y=\"20\" width=\"152\" height=\"110\" rx=\"12\" fill=\"#0033A0\"></rect>\n      <text x=\"778\" y=\"58\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\">5. Створи</text>\n      <text x=\"778\" y=\"86\" font-size=\"15\" fill=\"#D6E0F5\">власний</text>\n      <text x=\"778\" y=\"106\" font-size=\"15\" fill=\"#D6E0F5\">варіант</text>\n    </g>\n    <g fill=\"#0033A0\"><polygon points=\"164,69 176,75 164,81\"></polygon><polygon points=\"338,69 350,75 338,81\"></polygon><polygon points=\"512,69 524,75 512,81\"></polygon><polygon points=\"686,69 698,75 686,81\"></polygon></g>\n    <path d=\"M778 134 V166 H84 V142\" fill=\"none\" stroke=\"#B38600\" stroke-width=\"3\" stroke-dasharray=\"8 6\"></path>\n    <polygon points=\"76,144 84,132 92,144\" fill=\"#B38600\"></polygon>\n    <text x=\"430\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#3D4757\" font-family=\"Arial, sans-serif\">зошит — для прогнозу й записів, Scratch — для запуску й змін</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Порівнювати чесно — означає оцінювати всі алгоритми за тими самими критеріями й для тієї самої мети. Для іншої мети найкращим може виявитися інший алгоритм.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Трасування (trace)</b> допомагає прогнозувати: ти читаєш алгоритм блок за блоком і уявляєш, що робить кіт після кожного. Можна вести пальцем по рядках і малювати олівцем у зошиті.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">Кіт стоїть у центрі й має намалювати знак «плюс» із чотирьох променів по 30 кроків. Троє учнів запропонували алгоритми. Спільний початок для всіх трьох:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Початок (однаковий)</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">очистити</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (0) y: (0)</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">опустити олівець</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Алгоритм А</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (-30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (-30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (-30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (-30) кроків</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Алгоритм Б</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повторити (4)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (-30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Алгоритм В — його запропонував чат-бот</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повторити (3)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (-30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Передбач.</b> Не запускаючи, простеж кожен алгоритм і намалюй у зошиті, що вийде. Запиши, скільки блоків у кожному.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Запусти.</b> Збери в Scratch алгоритм Б (олівець додається кнопкою «Додати розширення» внизу ліворуч). Запусти. Чи збігся малюнок із прогнозом? Потім зміни 4 на 3 — так вийде алгоритм В. Що змінилося?</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Порівняй.</b> Заповни в зошиті матрицю: для кожного алгоритму постав ✔ або ✖ за кожним критерієм.</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Критерій</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">А</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Б</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">В</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Правильний</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Стислий</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Зрозумілий</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Легко змінити</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Обери й покращ.</b> Промені мають стати 60 кроків. Скільки чисел доведеться виправити в А, а скільки в Б? Зроби це в Scratch для Б і запусти. Запиши, який алгоритм обираєш і чому — щонайменше за двома критеріями.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Прогноз.</b> А і Б малюють повний «плюс». В малює лише три промені: четвертий пропущено. А має 11 блоків, Б — 4, В — 4.</p>\n    <p style=\"margin:10px 0 0;\"><b>Матриця.</b> А: правильний ✔, стислий ✖, зрозумілий — важко побачити задум, змінити важко ✖. Б: усі ✔. В: неправильний ✖ — хоч і стислий.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> В А треба виправити 8 чисел, у Б — 2. Найкращий — Б: правильний і легко змінюється. Пропозицію чат-бота довелося перевірити й виправити.</p>\n  </details>\n\n  <div style=\"background:#FFF2F2;border-left:5px solid #C0392B;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Алгоритм від ШІ</b> — лише матеріал для перевірки. Алгоритм В виглядає охайно, але помиляється. Простеж і запусти будь-яку пропозицію, перш ніж їй довіряти.</p>\n  </div>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Збери в Scratch лише алгоритм Б і запусти.</p>\n    <p style=\"margin:10px 0 0;\">Порівняй А і Б за двома критеріями: «правильний» і «легко змінити». Для «легко змінити» порахуй, скільки чисел 30 є в кожному алгоритмі.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти маєш прогноз, запущений алгоритм Б і порівняння за двома критеріями.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Нова мета: вертикальні промені мають бути по 60 кроків, горизонтальні — по 30. Який алгоритм тепер легше пристосувати — А чи Б? Спробуй обидва в Scratch.</p>\n    <p style=\"margin:10px 0 0;\">Поміркуй: інколи «довший» алгоритм зручніший, бо кожен промінь можна налаштувати окремо. Запиши, що ти виграєш і що втрачаєш у кожному варіанті.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>Algorithm B is concise and easy to change.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Алгоритми для дітей</b> — як програмувати роботів точними командами. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/computational_thinking/algorithm/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Алгоритми для дітей ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u17-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Алгоритм найкоротший, але малює не ту фігуру. Він найкращий?</label>\n    <select id=\"g4-u17-q1\" name=\"g4-u17-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Так, бо найкоротший</option>\n      <option>Ні, спершу алгоритм має бути правильним</option>\n      <option>Так, якщо його запропонував ШІ</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Ні. Стислість важлива лише для правильних алгоритмів.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u17-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Що означає «простежити» (trace) алгоритм?</label>\n    <select id=\"g4-u17-q2\" name=\"g4-u17-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Запустити його якомога швидше</option>\n      <option>Пройти блоки по черзі й уявити, що робить виконавець</option>\n      <option>Порахувати кольори блоків</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Пройти блоки по черзі. Так ти прогнозуєш результат ще до запуску.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u17-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чому Б легше змінити, ніж А?</label>\n    <select id=\"g4-u17-q3\" name=\"g4-u17-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Довжину променя записано лише в одному місці циклу</option>\n      <option>Б має більше блоків</option>\n      <option>Б не малює промені</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Довжину в Б записано в циклі один раз (двічі: вперед і назад), а в А — вісім разів.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Я обираю алгоритм ___, бо він ___ і ___. Алгоритм ___ не підходить, бо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Мої прогнози записані до запуску.</li>\n      <li style=\"margin:8px 0;\">Алгоритм Б працює в Scratch, і я змінюю його для променів по 60 кроків.</li>\n      <li style=\"margin:8px 0;\">Моя матриця заповнена, а вибір пояснено щонайменше двома критеріями.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> прогноз, запущений алгоритм Б і порівняння за двома критеріями.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> прогнози й матрицю в зошиті та збережений проєкт Scratch (або знімок екрана) з алгоритмом Б.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>algorithm</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">алгоритм</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>predict / trace</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">прогнозувати / трасувати</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>criterion</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">критерій</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>concise</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">стислий</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>output</b></td><td style=\"padding:8px 10px;\">результат роботи</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I predicted the output. Algorithm B is correct and concise.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-2","grade":4,"module":3,"number":2,"title":"Повторення робить алгоритм коротшим","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок18_Гра1_Скільки-повторень.html","title":"Скільки повторень?","description":"сценарний вибір","data":{"id":"m3g18a","lesson":18,"tag":"ПОВТОР","icon":"🔁","type":"quiz","title":"Скільки повторень?","file":"М3_Урок18_Гра1_Скільки-повторень.html","conceptName":"цикл «повторити N»","concept":"Якщо група блоків повторюється, її можна сховати в цикл «повторити N». Усередині — тіло циклу (група, що повторюється), а число N — кількість повторень.","skill":"визначати, що входить у тіло циклу і скільки разів його повторити","data":{"questions":[{"q":"Програма малює квадрат: крок 50, поворот 90. Скільки разів повторити цю пару?","options":["3","4","5"],"correct":1,"explain":"У квадрата чотири сторони, тож пару «крок + поворот» повторюємо 4 рази.","wrong":"Порахуй сторони квадрата — стільки ж і повторень."},{"q":"У програмі «сходинки» група з трьох блоків повторюється чотири рази — 12 блоків. Скільки блоків лишиться після скорочення?","options":["12","4","5"],"correct":2,"explain":"Прапорець + «повторити 4» + три блоки тіла циклу = 5 блоків замість 12.","wrong":"Блоки тіла не зникають — лишається одна група в циклі, а не чотири копії."},{"q":"У візерунку «зубці» стояло «повторити 3». Його змінили на «повторити 5». Скільки зубців буде?","options":["3","5","8"],"correct":1,"explain":"Число в циклі — це кількість повторень: 5 повторень — 5 зубців.","wrong":"Число в блоці «повторити» — це й є кількість повторень."},{"q":"Що має бути всередині блока «повторити»?","options":["Група блоків, що повторюється","Усі блоки програми підряд","Лише перший блок програми"],"correct":0,"explain":"У тілі циклу — лише та група, яка справді повторюється.","wrong":"Початкові налаштування лишаються поза циклом, а всередині — те, що повторюється."},{"q":"Перший блок групи, що повторюється, лишили поза циклом. Що станеться?","options":["Малюнок зсунеться: перший елемент буде зайвим","Нічого не зміниться","Програма не запуститься"],"correct":0,"explain":"Один елемент виконається без циклу, а решта — у циклі: візерунок зміститься.","wrong":"Блок поза циклом виконається окремо, ще раз — уся група в циклі."},{"q":"«Повторити 4» і чотири однакові групи блоків дають той самий малюнок. У чому різниця?","options":["Малюнок той самий, але число в циклі змінити простіше","Цикл малює швидше","Групи блоків не можна повторювати"],"correct":0,"explain":"Результат однаковий, але цикл коротший і його легко змінити.","wrong":"Результат справді однаковий — подумай, який варіант легше редагувати."}]}},"after":{"index":1,"heading":"🔁 Блок «повторити»"}},{"path":"app/games/М3_Урок18_Гра2_Скороти-програму.html","title":"Скороти програму","description":"послідовність кроків","data":{"id":"m3g18b","lesson":18,"tag":"СКОРОЧ","icon":"✂️","type":"order","title":"Скороти програму","file":"М3_Урок18_Гра2_Скороти-програму.html","conceptName":"як скоротити програму циклом","concept":"Алгоритм скорочення: знайди повтор → визнач межі групи → залиш одну групу в циклі → впиши кількість повторень → запусти й порівняй зі старою програмою.","skill":"скорочувати програму циклом за п'ятьма кроками й перевіряти, що результат не змінився","data":{"rounds":[{"title":"Як скоротити програму циклом","steps":["Знайди групу блоків, що повторюється","Визнач, де група починається і закінчується","Залиш одну групу в циклі «повторити»","Впиши кількість повторень","Запусти й порівняй зі старою програмою"],"hint":"спершу шукаємо, що саме повторюється","explain":"Після скорочення програма має робити те саме — це перевіряємо запуском."},{"title":"Збери цикл для квадрата","steps":["Коли натиснуто прапорець","Опусти олівець","Повторити 4 рази","Крок 50","Поворот на 90 градусів"],"hint":"тіло циклу — крок і поворот","explain":"Тіло циклу «крок 50, поворот 90» виконається 4 рази, і олівець накреслить квадрат."}]}},"after":{"index":2,"heading":"✂️ Як скоротити програму"}},{"path":"app/games/М3_Урок18_Гра3_У-цикл-чи-поза.html","title":"У цикл чи поза циклом?","description":"сортування карток","data":{"id":"m3g18c","lesson":18,"tag":"ЦИКЛ","icon":"🧩","type":"sort","title":"У цикл чи поза циклом?","file":"М3_Урок18_Гра3_У-цикл-чи-поза.html","conceptName":"що кладемо в цикл","concept":"У тіло циклу йде лише те, що повторюється. Блоки підготовки — стартова позиція, очищення, колір олівця — виконуються один раз і стоять поза циклом, перед ним.","skill":"розподіляти блоки: тіло циклу — усередину, підготовку — перед циклом","data":{"categories":[{"id":"in","label":"🔁 Усередині циклу","hint":"те, що повторюється"},{"id":"out","label":"🚪 Поза циклом","hint":"один раз на старті"}],"items":[{"text":"Перейти на стартову позицію","cat":"out","explain":"Стартова позиція ставиться один раз, перед циклом.","hint":"це підготовка, не повторення"},{"text":"Крок 50","cat":"in","explain":"Крок — частина групи, що повторюється.","hint":"малюємо сторону щоразу"},{"text":"Очистити малюнок","cat":"out","explain":"Очищуємо сцену один раз на старті.","hint":"робиться один раз"},{"text":"Поворот на 90 градусів","cat":"in","explain":"Поворот повторюється разом із кроком.","hint":"частина повторюваної групи"},{"text":"Опустити олівець","cat":"out","explain":"Олівець опускаємо один раз, перед малюванням.","hint":"підготовка до малювання"},{"text":"Наступний образ","cat":"in","explain":"Зміна образу в циклі створює анімацію ходьби.","hint":"повторюється для анімації"},{"text":"Змінити колір олівця на початку","cat":"out","explain":"Колір обираємо один раз до циклу.","hint":"один раз, до малювання"},{"text":"Чекати 0,1 секунди","cat":"in","explain":"Пауза всередині циклу робить рух помітним для ока.","hint":"повторюється з кожним кроком"}]}},"after":{"index":4,"heading":"⚠️ Типові помилки під час скорочення"}}],"legacyTitle":"Урок 18. Повторення робить алгоритм коротшим","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 18</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Повторення робить алгоритм коротшим</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Repetition Makes Algorithms More Concise</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як один блок «повторити» замінює довгий ланцюжок однакових команд?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я знаходжу послідовність команд, яка повторюється (<b>repetition</b>).</li>\n      <li style=\"margin:6px 0;\">Я замінюю її блоком «повторити» в Scratch і перевіряю, що малюнок не змінився.</li>\n      <li style=\"margin:6px 0;\">Я змінюю кількість повторень і прогнозую новий результат.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔁 Блок «повторити»</h2>\n\n  <p style=\"margin:0 0 12px;\">Коли в програмі кілька разів підряд стоїть та сама група блоків, її можна записати один раз і сказати: «повтори це». Для цього в Scratch є блок <b>«повторити (N)» (repeat)</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">У блоці «повторити N разів» дві частини:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Тіло циклу (loop body)</b> — блоки всередині, які повторюються.</li>\n    <li style=\"margin:8px 0;\"><b>Кількість повторень (repeat count)</b> — число у віконці.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Так влаштований саме цикл «повторити N разів». На наступному уроці ти побачиш цикл «завжди» — у нього кількості немає.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✂️ Як скоротити програму</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Знайди повтор.</b> Шукай групу блоків, яка йде кілька разів підряд без змін.</li>\n    <li style=\"margin:8px 0;\"><b>Визнач межі.</b> Де група починається і де закінчується? Перевір, що наступна група точно така сама.</li>\n    <li style=\"margin:8px 0;\"><b>Залиш одну групу</b> і поклади її всередину «повторити».</li>\n    <li style=\"margin:8px 0;\"><b>Впиши кількість</b> — скільки разів група стояла підряд.</li>\n    <li style=\"margin:8px 0;\"><b>Запусти й порівняй.</b> Малюнок має бути таким самим, як до скорочення.</li>\n  </ol>\n\n  <p style=\"margin:0 0 12px;\">Приклад: сходинки. Довга версія має 12 блоків — три однакові групи по чотири. Коротка — 5 блоків.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Було: одна сходинка, повторена тричі</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (20) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↺ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (20) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n      <div style=\"border-left:6px solid #9AA5B1;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;font-style:italic;color:#3D4757;\">…і ще двічі ті самі 4 блоки</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Стало</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повторити (3)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (20) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">поворот ↺ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (20) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Короткий код легше читати і змінювати: щоб сходинок стало п'ять, досить виправити одне число. Але коротший код не стає правильним сам собою — його теж треба запустити й перевірити.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки під час скорочення</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">У цикл потрапила не вся група: наприклад, забули останній поворот — і кожен наступний зубець з'їжджає.</li>\n    <li style=\"margin:8px 0;\">Один блок першої групи лишився поза циклом і виконується лише раз.</li>\n    <li style=\"margin:8px 0;\">Кількість повторень переплутали з кількістю блоків у тілі.</li>\n    <li style=\"margin:8px 0;\">Усередину циклу поклали й блоки початку — сцена очищується перед кожним зубцем.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Усі ці помилки видно одразу, якщо порівняти малюнок до і після скорочення. Тому запуск — обов'язковий крок.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Порада.</b> У Scratch «Дублювати» копіює блок разом з усім, що прикріплено під ним. Тому дублюй, узявшись за перший блок групи.</p>\n\n  <p style=\"margin:0 0 12px;\">Кіт малює паркан. Один зубець — це вісім блоків:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Початок</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">очистити</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (-150) y: (0)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повернути в напрямку (90)</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">опустити олівець</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Один зубець</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↺ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (15) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↻ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">поворот ↺ на (90) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перемістити на (15) кроків</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Збери довгу версію.</b> Склади початок і один зубець. Потім клацни правою кнопкою по першому блоку зубця → «Дублювати» і прикріпи копію знизу. Зроби так, щоб зубців стало три. Запусти. Порахуй усі блоки.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Знайди повтор.</b> Які блоки повторюються? Скільки разів? Запиши в зошит.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Скороти.</b> Залиш один зубець, решту видали, а зубець поклади в «повторити». Запусти. Чи такий самий паркан? Порахуй блоки знову.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Зміни.</b> Спрогнозуй, що буде, якщо написати «повторити (6)». Запиши прогноз, потім запусти. Запиши, що очікував побачити і що побачив насправді. Збережи проєкт.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 1–3.</b> Довга версія: 5 блоків початку + 24 блоки зубців = 29. Коротка: 5 + 1 + 8 = 14. Паркан однаковий.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Шість зубців; паркан подовжиться вдвічі й усе ще поміститься на сцені.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Почни з простішого: квадрат із восьми блоків (чотири рази «перемістити на (50) кроків» і «поворот ↻ на (90) градусів»). Заміни їх на «повторити (4)» з двома блоками всередині.</p>\n    <p style=\"margin:10px 0 0;\">Потім спробуй паркан із двох зубців.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо короткий квадрат працює так само, як довгий, і ти пояснюєш, що таке тіло циклу і кількість повторень.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Ламану лінію /\\/\\/\\ можна скоротити двома способами: повторювати пару блоків «вгору-вниз» або окремо «вгору» і «вниз». Спробуй обидва в Scratch. Який варіант зрозуміліший і чому?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The loop body repeats three times.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Виявлення шаблонів</b> — потренуйся помічати, що повторюється. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/computational_thinking/patterns/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Виявлення шаблонів ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u18-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке тіло циклу?</label>\n    <select id=\"g4-u18-q1\" name=\"g4-u18-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Число у віконці</option>\n      <option>Блоки всередині «повторити»</option>\n      <option>Кіт, який малює</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Блоки всередині циклу. Число у віконці — кількість повторень.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u18-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. У «повторити (3)» замінили 3 на 5. Скільки зубців буде в паркані?</label>\n    <select id=\"g4-u18-q2\" name=\"g4-u18-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>3</option>\n      <option>5</option>\n      <option>8</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">5 — тіло виконається п'ять разів.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u18-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Програма стала коротшою. Що зробити далі?</label>\n    <select id=\"g4-u18-q3\" name=\"g4-u18-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Нічого, коротка — отже правильна</option>\n      <option>Запустити й порівняти з очікуваним результатом</option>\n      <option>Видалити ще кілька блоків</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Запустити й порівняти. Коротший код теж може помилятися, наприклад якщо в тіло потрапили не всі блоки.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Блок „повторити“ робить програму коротшою, бо ___. Змінити її тепер легше, бо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Моя коротка програма в Scratch малює той самий паркан, що й довга.</li>\n      <li style=\"margin:8px 0;\">У зошиті записано, скільки блоків було до скорочення і скільки стало після.</li>\n      <li style=\"margin:8px 0;\">Я прогнозую результат для «повторити (6)» і порівнюю з тим, що вийшло.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> короткий квадрат із «повторити (4)» і пояснення двох частин циклу.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережені проєкти «до» і «після» (або знімки екрана) та записи лічби блоків і прогнозу.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>repetition</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">повторення</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>repeat block</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">блок «повторити»</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>loop body</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">тіло циклу</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>repeat count</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">кількість повторень</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>concise</b></td><td style=\"padding:8px 10px;\">стислий</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The repeat block makes my program concise. I changed the repeat count to 6.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-3","grade":4,"module":3,"number":3,"title":"Цикл «завжди»: повторення без визначеної кількості","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок19_Гра1_Один-раз-чи-завжди.html","title":"Один раз чи завжди?","description":"сортування карток","data":{"id":"m3g19a","lesson":19,"tag":"ЗАВЖДИ","icon":"♾️","type":"sort","title":"Один раз чи завжди?","file":"М3_Урок19_Гра1_Один-раз-чи-завжди.html","conceptName":"початковий стан і цикл «завжди»","concept":"У грі з циклом «завжди» є дві частини: початковий стан (позиція, напрямок, образ) ставиться один раз на старті, перед циклом. Усередині «завжди» — лише те, що повторюється: крок, відбиття, анімація, пауза.","skill":"відділяти початковий стан від дій, що повторюються в циклі «завжди»","data":{"categories":[{"id":"once","label":"1️⃣ Один раз на старті","hint":"початковий стан, перед циклом"},{"id":"loop","label":"♾️ Усередині «завжди»","hint":"повторюється весь час"}],"items":[{"text":"Перейти до x: −180, y: −50","cat":"once","explain":"Якби це було всередині «завжди», рибка щоразу поверталася б і тремтіла на місці.","hint":"стартова позиція"},{"text":"Направитися в бік 90 градусів","cat":"once","explain":"Напрямок задаємо один раз, перед циклом.","hint":"початковий напрямок"},{"text":"Крок 5","cat":"loop","explain":"Рух повторюється, тому крок — всередині «завжди».","hint":"рибка пливе весь час"},{"text":"Відбитися від межі","cat":"loop","explain":"Відбиття перевіряється на кожному повторенні.","hint":"працює постійно"},{"text":"Наступний образ","cat":"loop","explain":"Зміна образів у циклі створює анімацію плавників.","hint":"анімація повторюється"},{"text":"Показатися","cat":"once","explain":"Спрайт показуємо один раз на старті.","hint":"одноразова дія"},{"text":"Чекати 0,1 секунди","cat":"loop","explain":"Без паузи в циклі спрайт мчить швидше, ніж встигає око.","hint":"повторюється з кожним кроком"},{"text":"Очистити графічні ефекти","cat":"once","explain":"Ефекти скидаємо один раз, щоб гра починалася чисто.","hint":"частина початкового стану"}]}},"after":{"index":4,"heading":"⚠️ Типові помилки з «завжди»"}},{"path":"app/games/М3_Урок19_Гра2_Цикл-завжди.html","title":"Цикл «завжди»","description":"сценарний вибір","data":{"id":"m3g19b","lesson":19,"tag":"НЕСКІНЧ","icon":"🐟","type":"quiz","title":"Цикл «завжди»","file":"М3_Урок19_Гра2_Цикл-завжди.html","conceptName":"цикл «завжди»","concept":"«Завжди» повторює блоки без кінця. Його обирають, коли кількість повторень невідома. Зупиняють кнопкою «Стоп» або блоком «зупинити все». Блоки, що стоять під циклом «завжди», ніколи не виконаються.","skill":"пояснювати, коли потрібен цикл «завжди», як його зупинити і де мають стояти блоки","data":{"questions":[{"q":"Коли обирають цикл «завжди»?","options":["Коли кількість повторень невідома заздалегідь","Коли треба повторити рівно 4 рази","Коли в програмі взагалі немає руху"],"correct":0,"explain":"«Завжди» — для дій без заздалегідь відомої кількості: плавання, миготіння, гойдання.","wrong":"Якщо кількість відома — простіше «повторити N». «Завжди» — коли вона невідома."},{"q":"Як зупинити цикл «завжди»?","options":["Кнопкою «Стоп» або блоком «зупинити все»","Він зупиниться сам через хвилину","Видалити блок під час роботи програми"],"correct":0,"explain":"«Завжди» не має лічильника, тому зупиняємо його «Стоп» або «зупинити все».","wrong":"Цикл без лічильника сам не завершиться — йому потрібна зовнішня зупинка."},{"q":"Рибка тремтить на місці: блок «перейти до x: −180» стоїть всередині «завжди». Яке виправлення?","options":["Винести перехід перед цикл","Додати ще один «завжди»","Збільшити крок до 50"],"correct":0,"explain":"На кожному повторенні рибку повертає на старт. Початковий стан — перед циклом.","wrong":"Подумай: що робить перехід на старт щоразу, коли цикл повторюється?"},{"q":"Що станеться з блоками, які стоять під циклом «завжди»?","options":["Вони ніколи не виконаються","Виконаються один раз наприкінці","Виконаються через 10 секунд"],"correct":0,"explain":"«Завжди» не закінчується, тож черга ніколи не доходить до блоків під ним.","wrong":"Щоб блок після циклу виконався, цикл має колись завершитися. А «завжди» — ні."},{"q":"Усередині «завжди» забули блок «чекати 0,1». Що побачимо на сцені?","options":["Спрайт мчить так швидко, що рух не видно","Нічого не зміниться","Спрайт рухатиметься повільніше"],"correct":0,"explain":"Без паузи цикл виконується тисячі разів на секунду — око не встигає.","wrong":"Пауза сповільнює повторення до швидкості, помітної для ока."},{"q":"Куди ставлять початковий стан: позицію, напрямок, образ?","options":["Перед циклом «завжди»","Усередині «завжди»","Після циклу «завжди»"],"correct":0,"explain":"Початковий стан потрібен один раз на старті, тому він стоїть перед циклом.","wrong":"Усередині циклу він повторювався б без кінця, а після — не виконався б узагалі."}]}},"after":{"index":1,"heading":"♾️ Цикл, який не знає, скільки разів"}}],"legacyTitle":"Урок 19. Цикл «завжди» і початковий стан","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 19</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Цикл «завжди»: повторення без визначеної кількості</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Indefinite Loops: Forever in Interactive Programs</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: що в програмі має відбутися один раз, а що — повторюватися постійно?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я пояснюю, чим цикл «завжди» (<b>forever</b>) відрізняється від «повторити N разів».</li>\n      <li style=\"margin:6px 0;\">Я вирішую, які блоки виконуються один раз, а які повторюються.</li>\n      <li style=\"margin:6px 0;\">Я створюю в Scratch анімацію з циклом «завжди» і способом повернути все на початок.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">♾️ Цикл, який не знає, скільки разів</h2>\n\n  <p style=\"margin:0 0 12px;\">Цикл «повторити N разів» закінчується, коли тіло виконано N разів. А <b>цикл із невизначеною кількістю повторень (indefinite loop)</b> повторює тіло, доки програму не зупинять. У Scratch це блок <b>«завжди» (forever)</b>. Його ще називають безкінечним циклом, але насправді він зупиняється — коли натискаєш червону кнопку «Стоп» або коли спрацьовує блок «зупинити все».</p>\n\n  <p style=\"margin:0 0 12px;\">«Завжди» потрібен, коли ми не знаємо заздалегідь, скільки триватиме дія:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">рибка плаває, поки гра відкрита;</li>\n    <li style=\"margin:8px 0;\">програма постійно перевіряє, чи не торкнувся герой стіни;</li>\n    <li style=\"margin:8px 0;\">годинник на екрані оновлюється щосекунди.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">«Завжди» працює в багатьох знайомих програмах: гра весь час перевіряє, чи натиснуто клавішу; світлофор без кінця перемикає кольори; micro:bit у блоці <i>forever</i> постійно показує температуру.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">1️⃣ Один раз чи постійно</h2>\n\n  <p style=\"margin:0 0 12px;\">Добра програма розрізняє два види дій. <b>Початковий стан (initialise)</b> — позицію, напрямок, образ — задають один раз, на старті. А поведінку, яка має тривати, кладуть у «завжди».</p>\n\n  <p style=\"margin:0 0 12px;\">Початкові блоки часто ставлять перед «завжди» в тому самому скрипті. Але можна зробити й окремий скрипт, що запускається тим самим зеленим прапорцем. Головне — правильно вирішити, що виконується один раз, а що повторюється.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Приклад: рибка в акваріумі</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (-180) y: (-50)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повернути в напрямку (90)</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">завжди</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (5) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">якщо на межі, відбити</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">наступний образ</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">чекати (0.1) секунд</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Перші два блоки після прапорця виконуються один раз. Чотири блоки всередині «завжди» повторюються, поки програма працює. Блок «чекати» не дає рибці мчати надто швидко й робить анімацію спокійною для очей.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">Зупинити «завжди» можна двома способами. Червона кнопка «Стоп» над сценою зупиняє всі скрипти. А блок «зупинити [все]» програма виконує сама — наприклад, коли гравець дійшов до фінішу.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки з «завжди»</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Початкові блоки опинилися всередині «завжди» — виконавець щоразу повертається на старт.</li>\n    <li style=\"margin:8px 0;\">Блоки поставили <b>під</b> «завжди». Вони ніколи не виконаються: цикл не закінчується, і програма до них не дійде.</li>\n    <li style=\"margin:8px 0;\">Немає затримки — анімація мчить так швидко, що її важко роздивитися.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Створи сцену «Акваріум»: рибка постійно плаває від стінки до стінки, а пробіл повертає її на старт.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Передбач і збери.</b> Додай спрайт-рибку (наприклад, Fish) і фон підводного світу. Перш ніж збирати скрипт із прикладу, запиши в зошит, які блоки виконаються один раз, а які повторюватимуться. Збери й запусти. Чи справдився прогноз?</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Дослід.</b> Перетягни блок «перейти до x: (-180) y: (-50)» всередину «завжди», на самий верх тіла. Спрогнозуй, що зміниться, запусти, запиши. Потім поверни блок на місце.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Повернення на старт.</b> Додай окремий скрипт:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [пробіл]</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (-180) y: (-50)</div>\n      <div style=\"border-left:6px solid #CF63CF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">грати звук [Bubbles]</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Запусти прапорцем, почекай, натисни пробіл. Що відбувається з рибкою потім — вона стоїть чи пливе далі? Чому?</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Поясни.</b> Запиши одним реченням, чому для рибки потрібен саме «завжди», а не «повторити (10)». Збережи проєкт.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Рибка щоразу повертається на старт і лише тремтить на місці: початковий стан тепер повторюється, а мав виконатися один раз.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Рибка переноситься на старт і пливе далі: цикл «завжди» в першому скрипті не зупинявся.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Ми не знаємо, скільки часу гравець дивитиметься на акваріум, тож рибка має плавати, доки програма працює.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Збери найкоротшу версію: «коли натиснуто зелений прапорець» → «завжди» → усередині «перемістити на (5) кроків» і «якщо на межі, відбити».</p>\n    <p style=\"margin:10px 0 0;\">Запусти й зупини червоною кнопкою. Поясни, що повторюється і хто зупинив цикл.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо рибка плаває в циклі «завжди», а ти пояснюєш, чому він потрібен.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Заміни «завжди» на «повторити (1000)». Чим відрізняється поведінка? А чим відрізняється те, що кожен варіант <b>каже</b> читачеві коду?</p>\n    <p style=\"margin:10px 0 0;\">Додай другу рибку з іншою швидкістю. Кожна має свій «завжди» — вони рухаються одночасно.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The forever loop repeats until the program stops.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u19-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Коли зупиняється цикл «завжди»?</label>\n    <select id=\"g4-u19-q1\" name=\"g4-u19-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Після 100 повторень</option>\n      <option>Коли програму зупиняють</option>\n      <option>Ніколи, навіть після «Стоп»</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Коли програму зупиняють: червоною кнопкою або блоком «зупинити все».</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u19-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Де краще задати початкову позицію рибки?</label>\n    <select id=\"g4-u19-q2\" name=\"g4-u19-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Усередині «завжди»</option>\n      <option>Один раз на старті, до повторюваної частини</option>\n      <option>У кінці програми</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Один раз на старті. Усередині «завжди» вона повторювалася б і заважала руху.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u19-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Для чого потрібен «завжди», а не «повторити (N)»?</label>\n    <select id=\"g4-u19-q3\" name=\"g4-u19-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Коли відомо, скільки разів повторити</option>\n      <option>Коли дія має тривати, доки працює програма</option>\n      <option>Коли треба виконати дію один раз</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Коли дія триває, доки працює програма, і кількості заздалегідь не знаємо.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку на прикладі акваріума:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Один раз на старті виконується ___. Постійно повторюється ___, бо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Моя рибка в Scratch плаває в циклі «завжди».</li>\n      <li style=\"margin:8px 0;\">Я записую результат досліду з блоком усередині «завжди».</li>\n      <li style=\"margin:8px 0;\">Пробіл повертає рибку на старт, а я пояснюю, чому потрібен саме «завжди».</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> рибка плаває в найкоротшій версії, пояснення, що повторюється.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережений проєкт (або знімок екрана) і записи прогнозу та досліду.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>indefinite loop</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">цикл із невизначеною кількістю повторень</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>forever</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">завжди</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>initialise</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">задати початковий стан</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>continuous</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">безперервний</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>event</b></td><td style=\"padding:8px 10px;\">подія</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The forever loop keeps the fish swimming. The start position runs once.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-4","grade":4,"module":3,"number":4,"title":"Цикл із лічильником","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок20_Гра1_Долети-до-квітки.html","title":"Долети до квітки","description":"сценарний вибір","data":{"id":"m3g20a","lesson":20,"tag":"РАХУЄМО","icon":"🐝","type":"quiz","title":"Долети до квітки","file":"М3_Урок20_Гра1_Долети-до-квітки.html","conceptName":"як визначити кількість повторень","concept":"Кількість повторень рахуємо так: мета поділити на крок за одне повторення. До квітки 120 кроків, за повторення бджілка пролітає 30 — отже, 120 : 30 = 4 повторення.","skill":"обчислювати кількість повторень циклу за формулою «мета : крок»","data":{"questions":[{"q":"Бджілці до квітки 120 кроків. За одне повторення вона пролітає 30. Скільки повторень потрібно?","options":["3","4","5"],"correct":1,"explain":"120 поділити на 30 — буде 4 повторення.","wrong":"Поділи відстань до квітки на крок за одне повторення."},{"q":"Що буде, якщо поставити «повторити 2»?","options":["Бджілка долетить лише на 60 кроків — замало","Долетить якраз до квітки","Пролетить повз квітку"],"correct":0,"explain":"2 помножити на 30 — це 60 кроків, лише половина шляху.","wrong":"Порахуй: 2 повторення по 30 кроків — скільки це разом?"},{"q":"А якщо поставити «повторити 5»?","options":["Це якраз","Пролетить на 150 — повз квітку на 30 кроків","Взагалі не злетить"],"correct":1,"explain":"5 помножити на 30 — це 150, на 30 кроків далі за квітку.","wrong":"Порахуй: 5 повторень по 30 кроків — скільки це разом?"},{"q":"Мета — пролетіти 180 кроків, крок 30 за раз. Скільки повторень?","options":["5","6","7"],"correct":1,"explain":"180 поділити на 30 — буде 6 повторень.","wrong":"Поділи мету на крок: 180 : 30."},{"q":"Програма з «повторити 4» і кроком 30 недолітає на 30 кроків. Яке виправлення найбезпечніше?","options":["Змінити 4 на 5 повторень","Змінити крок на 35","Прибрати цикл зовсім"],"correct":0,"explain":"Змінюємо одну річ — кількість повторень. Крок уже перевірений, його не чіпаємо.","wrong":"Зміна кроку зіпсує вже перевірені частини. Міняй лише одне число."},{"q":"Годинник б'є 5 разів, ти стрибаєш 10 разів, спортсмен біжить 3 кола. Що спільного?","options":["Усе це повторення з відомою кількістю — цикл із лічильником","Усе це цикл «завжди»","Це взагалі не повторення"],"correct":0,"explain":"Кількість відома наперед, тож у програмі це був би цикл «повторити N».","wrong":"Чи відомо заздалегідь, скільки разів повториться кожна дія?"}]}},"after":{"index":3,"heading":"🧠 Як знайти потрібну кількість"}},{"path":"app/games/М3_Урок20_Гра2_Таблиця-трасування.html","title":"Таблиця трасування","description":"послідовність кроків","data":{"id":"m3g20b","lesson":20,"tag":"ТАБЛИЦЯ","icon":"📋","type":"order","title":"Таблиця трасування","file":"М3_Урок20_Гра2_Таблиця-трасування.html","conceptName":"трасування циклу","concept":"У таблиці трасування записуємо кожну ітерацію: номер, що зробило тіло циклу і скільки всього. Так видно, як росте лічильник, і легко перевірити, чи вистачить повторень.","skill":"заповнювати таблицю трасування циклу і перевіряти цикл перед запуском","data":{"rounds":[{"title":"Трасуємо «повторити 4: крок 30»","steps":["Ітерація 1: +30, всього 30","Ітерація 2: +30, всього 60","Ітерація 3: +30, всього 90","Ітерація 4: +30, всього 120"],"hint":"лічильник росте на 30 за кожну ітерацію","explain":"Після четвертої ітерації — 120 кроків. Саме стільки треба бджілці до квітки."},{"title":"Перевіряємо цикл із лічильником","steps":["Постав спрайт на старт","Передбач, де він фінішує","Запусти програму","Порівняй фініш із передбаченням","Якщо не збіглося — зміни лише кількість повторень"],"hint":"передбач → запусти → порівняй","explain":"Початковий стан, передбачення і порівняння — три кроки чесної перевірки циклу."}]}},"after":{"index":4,"heading":"📋 Таблиця трасування"}},{"path":"app/games/М3_Урок20_Гра3_Повторити-чи-завжди.html","title":"Повторити чи завжди?","description":"сортування карток","data":{"id":"m3g20c","lesson":20,"tag":"ПРИКЛАДИ","icon":"🔢","type":"sort","title":"Повторити чи завжди?","file":"М3_Урок20_Гра3_Повторити-чи-завжди.html","conceptName":"вибір циклу","concept":"Кількість повторень відома наперед — бери «повторити N». Кількість невідома або дія триває, поки грають у гру, — бери «завжди».","skill":"обирати між «повторити N» і «завжди» залежно від того, чи відома кількість повторень","data":{"categories":[{"id":"n","label":"🔢 «Повторити N»","hint":"кількість відома"},{"id":"inf","label":"♾️ «Завжди»","hint":"кількість невідома"}],"items":[{"text":"Зробити 10 стрибків","cat":"n","explain":"Кількість відома: 10. Це «повторити 10».","hint":"точно знаємо скільки"},{"text":"Світлофон миготить, поки грає музика","cat":"inf","explain":"Невідомо, скільки разів блимне, — це «завжди».","hint":"залежить від музики"},{"text":"Пробігти 3 кола стадіону","cat":"n","explain":"Три кола — відома кількість.","hint":"3 — конкретне число"},{"text":"Серце б'ється","cat":"inf","explain":"Серце не має запрограмованої кількості ударів.","hint":"без кінця і лічильника"},{"text":"Годинник б'є 5 разів","cat":"n","explain":"П'ять ударів — кількість відома.","hint":"5 — конкретне число"},{"text":"Рибка плаває, поки не натиснуто «Стоп»","cat":"inf","explain":"Невідомо, коли натиснуть «Стоп», — це «завжди».","hint":"зупинка не від циклу"},{"text":"Намалювати 6 пелюсток квітки","cat":"n","explain":"Шість пелюсток — відома кількість.","hint":"6 — конкретне число"},{"text":"Човник гойдається на хвилях увесь рівень гри","cat":"inf","explain":"Поки триває рівень — кількість невідома.","hint":"триває, поки граємо"}]}},"after":{"index":3,"heading":"🧠 Як знайти потрібну кількість"}}],"legacyTitle":"Урок 20. Цикл із лічильником і таблиця трасування","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 20</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Цикл із лічильником</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Count-Controlled Loops</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як обрати кількість повторень, щоб отримати саме потрібний результат?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я обираю кількість повторень (<b>repeat count</b>) за метою.</li>\n      <li style=\"margin:6px 0;\">Я заповнюю таблицю трасування для кожної ітерації (<b>iteration</b>).</li>\n      <li style=\"margin:6px 0;\">Я виправляю цикл у Scratch, щоб бджілка долетіла до квітки.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔢 Цикл, який знає, скільки разів</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Цикл із лічильником (count-controlled loop)</b> — це «повторити (N)». Тіло виконується N разів, після чого програма переходить до наступного блоку. Кожне виконання тіла називають <b>ітерацією (iteration)</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">На відміну від «завжди», такий цикл має відомий кінець. Тому його обирають, коли точно знаємо, скільки треба кроків, стрибків чи сторін.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🎯 Як обрати кількість</h2>\n\n  <p style=\"margin:0 0 12px;\">Зручно міркувати так: скільки треба всього і скільки робить одна ітерація? Якщо до мети 180 кроків, а за раз кіт проходить 30, потрібно 6 ітерацій. Таке міркування — спосіб передбачити результат, а не окрема задача з математики: головне — потім перевірити в Scratch.</p>\n\n  <p style=\"margin:0 0 12px;\">Якщо кількість замала, виконавець не дійде до мети. Якщо завелика — проскочить її.</p>\n\n  <p style=\"margin:0 0 12px;\">Цикли з лічильником є й у житті: 10 стрибків на скакалці, 3 кола навколо стадіону, 5 ударів годинника. Щоразу ми знаємо кількість наперед — і знаємо, коли зупинитися.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧠 Як знайти потрібну кількість</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Визнач, що робить одна ітерація.</b> Скільки кроків, стрибків чи сторін додає тіло циклу за один раз?</li>\n    <li style=\"margin:8px 0;\"><b>Визнач мету.</b> Скільки потрібно всього?</li>\n    <li style=\"margin:8px 0;\"><b>Поміркуй і спрогнозуй</b> кількість: скільки разів одна ітерація вміщується в мету?</li>\n    <li style=\"margin:8px 0;\"><b>Запусти й перевір.</b> Якщо результат не той, повернися до першого кроку, а не змінюй число навмання.</li>\n  </ol>\n\n  <p style=\"margin:0 0 12px;\"><b>Розібраний приклад.</b> Кіт має поставити штампом 5 квіток уздовж доріжки, а між квітками — 60 кроків. Одна ітерація: «штамп» і «перемістити на (60) кроків». Квіток 5 — отже, 5 повторень. Прогноз: п'ять відбитків, останній — за 240 кроків від першого. Запуск це підтверджує.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📋 Таблиця трасування</h2>\n\n  <p style=\"margin:0 0 12px;\">Таблиця трасування показує, що відбувається на кожній ітерації. Ось приклад для циклу «повторити (3)» з тілом «перемістити на (40) кроків» і «штамп»:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Ітерація</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що робить тіло</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пройдено всього</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">крок 40, штамп</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">40</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">крок 40, штамп</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">80</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">3</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">крок 40, штамп</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">120</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Після третьої ітерації цикл закінчується, і на сцені три відбитки.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Змінили довжину кроку замість кількості повторень — бджілка долетіла, але одним великим стрибком.</li>\n    <li style=\"margin:8px 0;\">Забули «чекати» в тілі — політ триває мить, і не видно, скільки було ітерацій.</li>\n    <li style=\"margin:8px 0;\">Забули повернути виконавця на старт — кожен новий запуск починається там, де він зупинився минулого разу.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Бджілка має долетіти до квітки, що чекає за 120 кроків праворуч. Але програміст помилився:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Скрипт бджілки (з помилкою)</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (-120) y: (0)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повернути в напрямку (90)</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">чекати (1) секунд</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повторити (2)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (30) кроків</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">чекати (0.3) секунд</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Додай спрайти Bee і Flower. Квітку постав у точку x: 0, y: 0.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Передбач і запусти.</b> Спрогнозуй, де зупиниться бджілка. Збери скрипт і запусти. Запиши, скільки кроків вона пролетіла і скільки лишилося.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Виправ.</b> Обчисли потрібну кількість повторень, зміни число в циклі й запусти знову. Долетіла?</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Трасуй.</b> Заповни в зошиті таблицю для виправленої програми:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:460px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Ітерація</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що робить тіло</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пролетіла всього</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Лишилося до квітки</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">крок 30</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">30</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">90</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">…</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Перевір межі.</b> Постав по черзі 3 і 5. Що буде? Запиши, яке число замале, яке завелике. Поверни правильне й збережи проєкт.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔌 Якщо в класі є micro:bit</h2>\n\n  <p style=\"margin:0 0 12px;\">Ті самі цикли працюють і на справжньому пристрої. У MakeCode (через каталог itnauka.org/outer/) склади: <i>on start</i> → <i>repeat (3) times</i> → усередині <i>show icon ♥</i>, <i>pause (500)</i>, <i>clear screen</i>. Спрогнозуй, скільки разів мигне серце, і перевір на платі чи в симуляторі. Потім додай блок <i>forever</i> з іншою іконкою: чим поводження двох циклів відрізняється?</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> 2 × 30 = 60 кроків, до квітки лишається 60.</p>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 2–3.</b> Потрібно 4 повторення: 30, 60, 90, 120 — лишилося 90, 60, 30, 0.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> 3 — замало, бджілка зупиниться за 30 кроків до квітки. 5 — забагато, вона пролетить квітку на 30 кроків.</p>\n    <p style=\"margin:10px 0 0;\"><b>micro:bit.</b> Серце мигне тричі, і цикл закінчиться. Іконка в <i>forever</i> показуватиметься, доки пристрій працює.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Два рядки таблиці вже заповнено — продовж їх до кінця, щоразу додаючи 30.</p>\n    <p style=\"margin:10px 0 0;\">Змінюй число в циклі й запускай, доки бджілка не сяде на квітку. Потім поясни, чому підійшло саме це число.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо цикл виправлено, а таблиця заповнена.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Нова мета: квітка за 150 кроків, бджілка летить по 25. Обчисли кількість повторень до запуску, а потім перевір одним запуском.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The loop repeats four times. Each iteration moves 30 steps.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u20-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке ітерація?</label>\n    <select id=\"g4-u20-q1\" name=\"g4-u20-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Одне виконання тіла циклу</option>\n      <option>Кількість блоків у програмі</option>\n      <option>Назва спрайта</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Одне виконання тіла циклу.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u20-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Кіт робить 20 кроків за ітерацію. Скільки повторень, щоб пройти 100?</label>\n    <select id=\"g4-u20-q2\" name=\"g4-u20-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>4</option>\n      <option>5</option>\n      <option>20</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">5: 20, 40, 60, 80, 100.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u20-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чим «повторити (N)» відрізняється від «завжди»?</label>\n    <select id=\"g4-u20-q3\" name=\"g4-u20-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Нічим</option>\n      <option>Він закінчується після N ітерацій</option>\n      <option>Він ніколи не закінчується</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Він закінчується після N ітерацій, і програма йде далі.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Щоб обрати кількість повторень, я ___. Якщо число замале, ___; якщо завелике, ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Бджілка в моїй програмі точно долітає до квітки.</li>\n      <li style=\"margin:8px 0;\">Моя таблиця трасування заповнена для всіх ітерацій.</li>\n      <li style=\"margin:8px 0;\">Я перевіряю замалу й завелику кількість і пояснюю результат.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> виправлений цикл і таблиця трасування.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережений проєкт (або знімок екрана) і таблицю трасування.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>count-controlled loop</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">цикл із лічильником</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>iteration</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">ітерація</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>repeat count</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">кількість повторень</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>target</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">ціль</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>trace table</b></td><td style=\"padding:8px 10px;\">таблиця трасування</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The bee needs four iterations to reach the target.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-5","grade":4,"module":3,"number":5,"title":"Вкладені повторення і складні візерунки","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок21_Гра1_Розетка.html","title":"Розетка з трикутників","description":"сценарний вибір","data":{"id":"m3g21a","lesson":21,"tag":"РОЗЕТКА","icon":"🌸","type":"quiz","title":"Розетка з трикутників","file":"М3_Урок21_Гра1_Розетка.html","conceptName":"вкладені цикли і кути","concept":"У розетці цикл у циклі: внутрішній малює одну фігуру, зовнішній повторює її й повертає олівець. Кути рахуємо з кола 360°: для фігури — 360 поділити на її сторони, між фігурами — 360 поділити на кількість фігур.","skill":"розраховувати кути у вкладених циклах і пояснювати роль внутрішнього та зовнішнього циклів","data":{"questions":[{"q":"Внутрішній цикл малює трикутник: повторити 3 рази «крок 60, поворот». Який кут повороту?","options":["120 градусів","90 градусів","60 градусів"],"correct":0,"explain":"360 поділити на 3 сторони — 120 градусів.","wrong":"Повний розворот — 360 градусів. Поділи на кількість сторін фігури."},{"q":"Зовнішній цикл повторює трикутник 8 разів. На який кут повертати між трикутниками?","options":["45 градусів","60 градусів","30 градусів"],"correct":0,"explain":"360 поділити на 8 — 45 градусів між сусідніми трикутниками.","wrong":"Поділи повний кут 360 на кількість фігур у розетці."},{"q":"Скільки разів виконається блок «крок 60», якщо зовнішній цикл — 8, а внутрішній — 3?","options":["11 разів","24 рази","8 разів"],"correct":1,"explain":"8 помножити на 3 — 24 рази.","wrong":"Внутрішній цикл виконується при кожному повторенні зовнішнього: множимо."},{"q":"Куди поставити поворот на 45 градусів у розетці з трикутників?","options":["У зовнішній цикл, після внутрішнього","Усередині внутрішнього циклу","Перед усіма циклами"],"correct":0,"explain":"Поворот між фігурами — дія зовнішнього циклу, після кожного трикутника.","wrong":"Якщо поворот опиниться у внутрішньому циклі, зіпсується сам трикутник."},{"q":"Хочемо розетку з 12 трикутників. Який кут між ними?","options":["30 градусів","45 градусів","12 градусів"],"correct":0,"explain":"360 поділити на 12 — 30 градусів.","wrong":"Поділи 360 на кількість трикутників."},{"q":"Ти змінив(-ла) і кількість фігур, і кут одночасно — візерунок зламався. Як краще експериментувати?","options":["Змінювати одну річ і перевіряти","Змінювати все одразу","Видалити внутрішній цикл"],"correct":0,"explain":"Одна зміна за раз — тоді видно, що саме вплинуло на візерунок.","wrong":"Коли міняємо все одразу, не зрозуміти, яка зміна зламала візерунок."}]}},"after":{"index":1,"heading":"🪆 Цикл у циклі"}},{"path":"app/games/М3_Урок21_Гра2_Цикл-у-циклі.html","title":"Цикл у циклі","description":"послідовність кроків","data":{"id":"m3g21b","lesson":21,"tag":"ГНІЗДО","icon":"🪆","type":"order","title":"Цикл у циклі","file":"М3_Урок21_Гра2_Цикл-у-циклі.html","conceptName":"структура вкладених циклів","concept":"Зовнішній цикл відповідає за повторення фігури, внутрішній — за саму фігуру. Як тренування: 3 підходи (зовнішній) по 10 присідань (внутрішній).","skill":"збирати програму з вкладеними циклами у правильному порядку","data":{"rounds":[{"title":"Збери розетку з 8 трикутників","steps":["Коли натиснуто прапорець","Опусти олівець","Зовнішній цикл: повторити 8 разів","Внутрішній цикл: повторити 3 рази — крок 60, поворот 120","Після трикутника поверни на 45","Кінець зовнішнього циклу"],"hint":"спершу малюється один трикутник, потім поворот","explain":"Внутрішній цикл малює трикутник, зовнішній повторює його 8 разів із поворотом 45 градусів."},{"title":"Тренування: 3 підходи по 10 присідань","steps":["Зовнішній цикл: повторити 3 рази","Внутрішній цикл: повторити 10 разів","Присісти","Кінець внутрішнього циклу","Відпочити","Кінець зовнішнього циклу"],"hint":"підходи — зовнішній цикл, присідання — внутрішній","explain":"Вкладені цикли — як підходи у спорті: маленький цикл усередині великого."}]}},"after":{"index":4,"heading":"🔍 Як знайти вкладений цикл у чужій програмі"}}],"legacyTitle":"Урок 21. Вкладені повторення і складні візерунки","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 21</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Вкладені повторення і складні візерунки</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Nested Repetition and Complex Patterns</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як цикл усередині циклу допомагає намалювати складний візерунок?</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #B38600;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Урок-виклик.</b> Вкладені цикли — поглиблення понад обов'язкову програму 4 класу. Якщо складно, маршрут «Потрібна допомога?» дає ту саму ідею простіше.</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я знаходжу внутрішній (<b>inner</b>) і зовнішній (<b>outer</b>) цикл і пояснюю, що створює кожен.</li>\n      <li style=\"margin:6px 0;\">Я прогнозую, що намалює одне повторення зовнішнього циклу.</li>\n      <li style=\"margin:6px 0;\">Я створюю в Scratch власний візерунок із вкладеними циклами.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🪆 Цикл у циклі</h2>\n\n  <p style=\"margin:0 0 12px;\">Цикл може лежати всередині іншого циклу. Це <b>вкладений цикл (nested loop)</b>. Зазвичай ролі такі:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Внутрішній цикл</b> малює невелику фігуру — наприклад, трикутник.</li>\n    <li style=\"margin:8px 0;\"><b>Зовнішній цикл</b> повторює цю фігуру й між повтореннями трохи змінює положення — наприклад, повертає кота.</li>\n  </ul>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Розетка з восьми трикутників</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">очистити</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (0) y: (0)</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">опустити олівець</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повторити (8)</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">повторити (3)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">перемістити на (60) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">поворот ↻ на (120) градусів</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">поворот ↻ на (45) градусів</div>\n    </div>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⏱ У якому порядку виконуються блоки</h2>\n\n  <p style=\"margin:0 0 12px;\">Коли зовнішній цикл починає своє перше повторення, внутрішній виконується повністю — усі три сторони трикутника. Лише потім кіт повертається на 45° і зовнішній цикл починає друге повторення. І так вісім разів.</p>\n\n  <p style=\"margin:0 0 12px;\">Тому зручно прогнозувати так: «Що намалює <b>одне</b> повторення зовнішнього циклу?» Тут — один трикутник і поворот. Решта — те саме, але повернуте.</p>\n\n  <p style=\"margin:0 0 12px;\">Чому саме 45°? Вісім трикутників мають обійти повне коло, а повне коло — 360°. Якщо трикутників шість, поворот буде 60°.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔍 Як знайти вкладений цикл у чужій програмі</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Знайди блок «повторити», усередині якого лежить ще один «повторити».</li>\n    <li style=\"margin:8px 0;\">Прочитай внутрішній цикл окремо: що він робить сам по собі?</li>\n    <li style=\"margin:8px 0;\">Подивись, які блоки стоять у зовнішньому циклі <b>після</b> внутрішнього: вони виконуються між повтореннями фігури.</li>\n  </ol>\n\n  <p style=\"margin:0 0 12px;\">Вкладені повторення трапляються й у житті. Зарядка: 3 підходи, а в кожному 10 присідань. Тиждень: 5 навчальних днів, і щодня кілька уроків. Зовнішнє повторення — підходи чи дні, внутрішнє — присідання чи уроки.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Ще один приклад — сітка зірок.</b> Зовнішній цикл повторюється 3 рази — це рядки. Внутрішній — 5 разів: «штамп» і крок праворуч — це зірки в рядку. Після внутрішнього циклу кіт повертається ліворуч і спускається на рядок нижче. Виходить 3 рядки по 5 зірок.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧁 Рецепт власного візерунка</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Обери фігуру</b> для внутрішнього циклу. У правильної фігури з N сторін кут повороту — 360 : N. Трикутник: 3 і 120°. Квадрат: 4 і 90°. Шестикутник: 6 і 60°.</li>\n    <li style=\"margin:8px 0;\"><b>Обери, скільки копій</b> фігури буде в розетці, — це кількість повторень зовнішнього циклу.</li>\n    <li style=\"margin:8px 0;\"><b>Обчисли поворот між копіями:</b> 360 : кількість копій. Для 8 копій — 45°, для 12 — 30°.</li>\n    <li style=\"margin:8px 0;\"><b>Збери, запусти, зміни одне число</b> — і подивись, як зміниться візерунок.</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Поворот зовнішнього циклу поклали всередину внутрішнього — фігури перекошуються.</li>\n    <li style=\"margin:8px 0;\">Змінили кілька чисел одночасно — і не зрозуміло, яка зміна що зробила.</li>\n    <li style=\"margin:8px 0;\">Кількість фігур і кут повороту не узгоджені: вісім трикутників по 60° не замикають коло.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Передбач.</b> Намалюй у зошиті, що з'явиться після першого повторення зовнішнього циклу. Підпиши, який цикл внутрішній, а який зовнішній, і що створює кожен.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Запусти повільно.</b> Збери розетку. Щоб побачити порядок, додай у внутрішній цикл блок «чекати (0.3) секунд» після кроку. Запусти й простеж: чи збігся перший трикутник із прогнозом? Без затримки Scratch малює миттєво, і порядок побачити неможливо, а з нею видно кожну сторону. Коли все зрозуміло, затримку можна прибрати.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Змінюй по одному.</b> Спершу зміни лише зовнішній цикл: 8 → 6 і 45° → 60°. Запусти. Потім зміни лише внутрішній: трикутник на квадрат (4 повторення, 90°). Після кожної зміни запиши, що очікував побачити і що вийшло.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Створи свій візерунок.</b> Придумай власну розетку, сітку чи «танець» спрайта з вкладеними циклами. Збережи проєкт і зроби знімок екрана.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Одне повторення зовнішнього циклу — трикутник і поворот на 45°. Внутрішній цикл створює трикутник, зовнішній — розставляє вісім трикутників по колу.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> 6 і 60° — розетка з шести трикутників. Квадрат замість трикутника — розетка з квадратів.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Почни з одного циклу: «повторити (3)» → «перемістити на (60) кроків», «поворот ↻ на (120) градусів». Запусти — це трикутник.</p>\n    <p style=\"margin:10px 0 0;\">Тепер обгорни весь цей цикл ще одним: «повторити (4)», а після внутрішнього циклу додай «поворот ↻ на (90) градусів». Що вийшло?</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо твоя розетка з чотирьох трикутників працює, а ти показуєш, де внутрішній цикл.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Скільки разів?</b> Скільки разів виконається блок «перемістити на (60) кроків» у розетці? Порахуй двома способами: трасуванням і міркуванням «3 сторони в кожному з 8 трикутників». Зауваж: так рахувати можна, лише коли цикли прості й блок стоїть у внутрішньому тілі.</p>\n    <p style=\"margin:10px 0 0;\"><b>Скороти довгу програму.</b> Візьми розетку, де вісім трикутників записано окремими циклами один під одним, і перепиши з вкладеним циклом. Що стало легше читати?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The inner loop draws a triangle. The outer loop repeats it eight times.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u21-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що робить внутрішній цикл у розетці?</label>\n    <select id=\"g4-u21-q1\" name=\"g4-u21-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Малює один трикутник</option>\n      <option>Повертає кота між трикутниками</option>\n      <option>Очищує сцену</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Малює один трикутник.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u21-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Коли кіт робить поворот на 45°?</label>\n    <select id=\"g4-u21-q2\" name=\"g4-u21-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Після кожної сторони</option>\n      <option>Після кожного трикутника</option>\n      <option>Лише один раз на початку</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Після кожного трикутника — це блок зовнішнього циклу.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u21-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Зовнішній цикл повторюється 5 разів. Скільки трикутників буде?</label>\n    <select id=\"g4-u21-q3\" name=\"g4-u21-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>3</option>\n      <option>5</option>\n      <option>15</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">5 — по одному на кожне повторення зовнішнього циклу.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Поясни на своєму візерунку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Внутрішній цикл створює ___. Зовнішній цикл ___. Одне повторення зовнішнього циклу малює ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Мій прогноз першого повторення записаний до запуску.</li>\n      <li style=\"margin:8px 0;\">Я змінюю по одному значенню й записую результат.</li>\n      <li style=\"margin:8px 0;\">Мій власний візерунок із вкладеними циклами працює й збережений.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> розетка з чотирьох трикутників і показаний внутрішній цикл.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережений проєкт або знімок екрана з візерунком і записи прогнозу.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>nested loop</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">вкладений цикл</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>inner loop</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">внутрішній цикл</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>outer loop</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">зовнішній цикл</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>pattern</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">візерунок</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>iteration</b></td><td style=\"padding:8px 10px;\">ітерація</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>One outer iteration draws one triangle and turns 45 degrees.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-6","grade":4,"module":3,"number":6,"title":"Змінні, лічильники та значення датчиків (розширення)","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок22_Гра1_Надати-чи-змінити.html","title":"Надати чи змінити?","description":"сортування карток","data":{"id":"m3g22a","lesson":22,"tag":"ЗМІННА","icon":"📦","type":"sort","title":"Надати чи змінити?","file":"М3_Урок22_Гра1_Надати-чи-змінити.html","conceptName":"два способи роботи зі змінною","concept":"Змінна — коробка з наліпкою-назвою та значенням усередині. «Надати значення» кладе в коробку точне число — це роблять на старті. «Змінити на» додає або віднімає — це лічильник подій.","skill":"обирати між «надати значення» і «змінити на» залежно від ситуації","data":{"categories":[{"id":"set","label":"🎯 «Надати значення»","hint":"точне число, на старті"},{"id":"chg","label":"➕ «Змінити на»","hint":"додати чи відняти"}],"items":[{"text":"На старті гри поставити бали на 0","cat":"set","explain":"Стартове значення — точне число: надати 0.","hint":"початок гри"},{"text":"Додати 1 бал за клік","cat":"chg","explain":"Клік додає до вже накопиченого: змінити на 1.","hint":"рахуємо події"},{"text":"Скинути лічильник перед новою грою","cat":"set","explain":"Без «надати 0» лічильник продовжить з минулої гри.","hint":"почати з чистого аркуша"},{"text":"Відняти 1 життя після зіткнення","cat":"chg","explain":"Змінити на −1 — відняти одиницю від поточного значення.","hint":"віднімаємо"},{"text":"Поставити 3 життя на початку рівня","cat":"set","explain":"Точне стартове число: надати 3.","hint":"стартове значення"},{"text":"Додати 2 бали за зібрану монету","cat":"chg","explain":"Монета додає до балансу: змінити на 2.","hint":"накопичуємо"},{"text":"Записати в змінну «рекорд» число 100","cat":"set","explain":"Кладемо точне число: надати 100.","hint":"конкретне значення"},{"text":"Зменшувати час на 1 щосекунди","cat":"chg","explain":"Щосекунди віднімаємо: змінити на −1.","hint":"змінюється поступово"}]}},"after":{"index":2,"heading":"✏️ «Надати значення» і «змінити на»"}},{"path":"app/games/М3_Урок22_Гра2_Лічильник-кліків.html","title":"Лічильник кліків","description":"сценарний вибір","data":{"id":"m3g22b","lesson":22,"tag":"ЛІЧИЛЬНИК","icon":"🖱️","type":"quiz","title":"Лічильник кліків","file":"М3_Урок22_Гра2_Лічильник-кліків.html","conceptName":"змінна-лічильник","concept":"Лічильник рахує події: на старті «надати 0», на кожну подію — «змінити на 1». Назва змінної має пояснювати, що вона зберігає: «бали», «життя», «кліки» — добре; «а», «змінна1» — погано.","skill":"прогнозувати значення змінної-лічильника і добирати змінним зрозумілі назви","data":{"questions":[{"q":"Змінна — це…","options":["Коробка з наліпкою-назвою та значенням усередині","Звуковий блок","Кнопка на сцені"],"correct":0,"explain":"Назва — це наліпка на коробці, значення — те, що лежить усередині.","wrong":"Уяви коробку: зовні наліпка з назвою, усередині — значення."},{"q":"Яка назва змінної найкраща для рахунку в грі?","options":["бали","а","змінна1"],"correct":0,"explain":"«Бали» одразу пояснює, що зберігає змінна.","wrong":"Назва має пояснювати зміст, а «а» і «змінна1» нічого не кажуть."},{"q":"У змінній «бали» було 4. Виконали «змінити бали на 1». Скільки стане?","options":["5","4","1"],"correct":0,"explain":"«Змінити на 1» — додати одиницю: 4 + 1 = 5.","wrong":"«Змінити на» не замінює значення, а додає до нього."},{"q":"П'ять кліків, кожен робить «змінити кліки на 2». Яке значення, якщо на старті було 0?","options":["7","10","2"],"correct":1,"explain":"П'ять разів по 2 — це 10.","wrong":"Помнож кількість кліків на приріст за клік."},{"q":"Гру запустили вдруге, а лічильник продовжив з минулого разу. Чого бракує?","options":["Блока «надати кліки значення 0» на старті","Звуку кліку","Ще одного спрайта"],"correct":0,"explain":"Змінна пам'ятає значення між запусками. На старті її треба скинути.","wrong":"Згадай: чим починається кожен чесний лічильник?"},{"q":"Звідки змінна «таймер» у Scratch бере значення?","options":["Датчик оновлює її сам","Її вигадує гравець","Вона завжди дорівнює 0"],"correct":0,"explain":"Деякі змінні наповнюють датчики: таймер, гучність, координати вказівника.","wrong":"Таймер тікає сам, без наших кліків, — це значення від датчика."}]}},"after":{"index":2,"heading":"✏️ «Надати значення» і «змінити на»"}},{"path":"app/games/М3_Урок22_Гра3_Збери-клікер.html","title":"Збери клікер","description":"послідовність кроків","data":{"id":"m3g22c","lesson":22,"tag":"КЛІКЕР","icon":"👆","type":"order","title":"Збери клікер","file":"М3_Урок22_Гра3_Збери-клікер.html","conceptName":"схема гри з лічильником","concept":"У грі з лічильником два скрипти: під прапорцем — «надати 0» (старт), під подією — «змінити на 1» (рахунок). Так само працюють життя: надати 3, а при зіткненні — змінити на −1.","skill":"збирати скрипти зі змінною-лічильником у правильному порядку","data":{"rounds":[{"title":"Гра-клікер","steps":["Коли натиснуто прапорець","Надати змінній «кліки» значення 0","Коли спрайт натиснуто","Змінити «кліки» на 1","Включити звук Pop"],"hint":"надати 0 — один раз, змінюємо — на кожен клік","explain":"Прапорець скидає лічильник, а клік його збільшує і грає звук."},{"title":"Життя в грі","steps":["Коли натиснуто прапорець","Надати «життя» значення 3","Коли спрайт торкається перешкоди","Змінити «життя» на −1","Якщо життя = 0 — зупинити все"],"hint":"старт → подія → зміна → перевірка","explain":"Починаємо з трьох життів, кожне зіткнення віднімає одне, нуль — кінець гри."}]}},"after":{"index":2,"heading":"✏️ «Надати значення» і «змінити на»"}}],"legacyTitle":"Урок 22. Змінні, лічильники та значення датчиків","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 22</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Змінні, лічильники та значення датчиків (розширення)</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Variables, Counters and Sensor Values (Extension)</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як програма запам'ятовує число, що змінюється, — наприклад, бали в грі?</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #B38600;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Урок-розширення.</b> Змінні — поглиблення понад обов'язкову програму 4 класу. Якщо тобі потрібна основа, обирай маршрут «Потрібна допомога?»: він працює з уже знайомим циклом «повторити».</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я пояснюю, що зберігає змінна (<b>variable</b>) і навіщо їй назва.</li>\n      <li style=\"margin:6px 0;\">Я розрізняю блоки «надати значення» (<b>set</b>) і «змінити на» (<b>change</b>).</li>\n      <li style=\"margin:6px 0;\">За зразком я додаю в Scratch змінну-лічильник і перевіряю, як вона змінюється.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📦 Що таке змінна</h2>\n\n  <p style=\"margin:0 0 12px;\">Уяви коробку з наліпкою «бали». Усередині лежить одне число — <b>значення (value)</b>. Число можна замінити або збільшити, а наліпка лишається та сама. Це і є <b>змінна (variable)</b>: місце в пам'яті програми з назвою, де зберігається значення, яке може змінюватися.</p>\n\n  <p style=\"margin:0 0 12px;\">Назва потрібна, щоб програма й людина розуміли, що саме лежить у коробці. «Бали», «життя», «кліки» — добрі назви. «а» чи «змінна1» — погані: за місяць ніхто не згадає, що там.</p>\n\n  <p style=\"margin:0 0 12px;\">У Scratch змінні створюють у категорії «Змінні» кнопкою «Створити змінну». Поки поруч із змінною стоїть позначка, її значення видно на сцені — це зручно для перевірки.</p>\n\n  <p style=\"margin:0 0 12px;\">Змінні є в кожній знайомій грі: бали, кількість життів, номер рівня, монети, час до кінця раунду. Усе це числа, які змінюються під час гри, — і програма пам'ятає кожне під своєю назвою.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✏️ «Надати значення» і «змінити на»</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>«надати [бали] значення (0)»</b> кладе в коробку точне число, а старе викидає. Так задають початкове значення.</li>\n    <li style=\"margin:8px 0;\"><b>«змінити [бали] на (1)»</b> додає число до того, що вже є. Було 4 — стане 5. Можна додати й від'ємне число: «змінити на (-1)» зменшує значення.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Змінна-<b>лічильник (counter)</b> рахує події: кліки, спіймані яблука, пройдені рівні. На старті лічильнику надають значення 0, а потім щоразу змінюють на 1.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Як перевірити змінну.</b> Дивись на її значення на сцені після кожної дії. Якщо число змінюється не так, як ти очікуєш, — шукай блок, який його змінює.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🌡 Значення, що змінюються самі</h2>\n\n  <p style=\"margin:0 0 12px;\">Деякі значення програма отримує не від гравця, а від світу — від датчиків. У Scratch є «таймер», що сам рахує секунди, а micro:bit має значення температури чи освітленості. Програма може показати таке значення або використати його, щоб вирішити, що робити далі.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Забули задати початкове значення — лічильник продовжує рахувати з минулої гри.</li>\n    <li style=\"margin:8px 0;\">Переплутали «надати» і «змінити»: замість +1 значення щоразу стає 1.</li>\n    <li style=\"margin:8px 0;\">Дві змінні з незрозумілими назвами — і незрозуміло, яка що рахує.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">Створи гру-клікер: щоразу, коли клацаєш по коту, лічильник збільшується.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Скрипт 1</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #FF8C1A;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">надати [кліки] значення (0)</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Скрипт 2</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли спрайт натиснуто</div>\n      <div style=\"border-left:6px solid #FF8C1A;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити [кліки] на (1)</div>\n      <div style=\"border-left:6px solid #CF63CF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">грати звук [Pop]</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Створи змінну.</b> У категорії «Змінні» натисни «Створити змінну» і назви її «кліки». Переконайся, що її значення видно на сцені.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Передбач і запусти.</b> Збери обидва скрипти. Запиши в зошит, яким буде значення після старту і після п'яти кліків. Перевір, клацаючи повільно й рахуючи вголос.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Дослід.</b> Від'єднай блок «надати [кліки] значення (0)» від прапорця. Запусти двічі й поклацай. Що відбувається з лічильником на другому запуску? Запиши й поверни блок на місце.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Зміни.</b> Заміни «змінити на (1)» на «змінити на (2)». Спрогнозуй значення після п'яти кліків і перевір. Збережи проєкт.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> Після старту — 0, після п'яти кліків — 5.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Без початкового значення лічильник продовжує рахувати з числа, на якому зупинився. Тому 0 на старті обов'язковий.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> 10: щоразу додається 2.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Ця доріжка — без змінних, з уже знайомим циклом. Збери скрипт: «коли натиснуто зелений прапорець» → «встановити розмір (100) %» → «повторити (5)» → усередині «змінити розмір на (10)» і «чекати (0.5) секунд».</p>\n    <p style=\"margin:10px 0 0;\">Спрогнозуй, яким буде розмір кота після циклу, і перевір. Потім зміни кількість повторень на 3.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти прогнозуєш і перевіряєш результат для двох кількостей повторень.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Змінна + умова.</b> Гра «Ловець яблук»: яблуко падає згори, миска ловить. Додай у скрипт яблука: «якщо торкається [Bowl]? то» → «змінити [бали] на (1)» і поверни яблуко нагору.</p>\n    <p style=\"margin:10px 0 0;\"><b>Трасування.</b> Гра почалася з 0, гравець спіймав 7 яблук, а за пропущене програма віднімає 2. Скільки балів? Запиши кожен крок.</p>\n    <p style=\"margin:10px 0 0;\">Покажи на сцені «таймер»: «завжди» → «говорити (таймер)». Що відбувається зі значенням?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The variable stores the score. We set it to zero at the start.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Що таке змінні</b> — інтерактивний урок про змінні в програмуванні. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/coding/variables/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Що таке змінні ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u22-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що робить «надати [бали] значення (0)»?</label>\n    <select id=\"g4-u22-q1\" name=\"g4-u22-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Додає 0 до балів</option>\n      <option>Кладе в змінну точне значення 0</option>\n      <option>Видаляє змінну</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Кладе точне значення 0, старе зникає.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u22-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Бали були 4. Виконали «змінити [бали] на (1)». Скільки стало?</label>\n    <select id=\"g4-u22-q2\" name=\"g4-u22-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>1</option>\n      <option>4</option>\n      <option>5</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">5: «змінити на» додає до того, що вже є.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u22-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Навіщо на старті надавати лічильнику значення 0?</label>\n    <select id=\"g4-u22-q3\" name=\"g4-u22-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб нова гра не продовжувала старий рахунок</option>\n      <option>Щоб програма працювала швидше</option>\n      <option>Щоб змінна зникла зі сцени</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб кожна гра починалася з нуля.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Змінна „кліки“ зберігає ___. На старті я ___, а після кожного кліку ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Мій клікер у Scratch рахує кліки й починає з нуля.</li>\n      <li style=\"margin:8px 0;\">Мої прогнози значень записано до запуску.</li>\n      <li style=\"margin:8px 0;\">Я пояснюю різницю між «надати значення» і «змінити на».</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> прогноз і перевірка розміру кота для двох кількостей повторень.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережений проєкт (або знімок екрана) і записи прогнозів.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>variable</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">змінна</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>value</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">значення</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>set / change</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">надати / змінити на</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>counter</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">лічильник</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>sensor value</b></td><td style=\"padding:8px 10px;\">значення датчика</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The counter starts at zero. Each click changes it by one.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-7","grade":4,"module":3,"number":7,"title":"Прогнозування, тестування і налагодження циклів","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок23_Гра1_Знайди-помилку.html","title":"Знайди помилку","description":"сценарний вибір","data":{"id":"m3g23a","lesson":23,"tag":"ЖУК","icon":"🐞","type":"quiz","title":"Знайди помилку","file":"М3_Урок23_Гра1_Знайди-помилку.html","conceptName":"що таке баг","concept":"Баг — це розбіжність між очікуваним результатом (що програма має робити) і фактичним (що вона робить насправді). Шукаємо його трасуванням і змінюємо одну річ за раз.","skill":"знаходити типові помилки в циклах і пропонувати виправлення","data":{"questions":[{"q":"Панда тремтить на місці: блок «перейти до x: −150» стоїть всередині «завжди». Яке виправлення?","options":["Винести перехід перед цикл","Поставити крок 100","Додати ще один цикл «завжди»"],"correct":0,"explain":"На кожному повторенні панду повертає на старт. Початковий стан — перед циклом.","wrong":"Подумай, що робить перехід на старт, якщо він повторюється без кінця."},{"q":"Програма має намалювати п'ятикутник, але стоїть «повторити 3» із поворотом 72. Що не так?","options":["Треба повторити 5 разів","Кут має бути 90","П'ятикутник намалювати неможливо"],"correct":0,"explain":"Кут правильний: 360 : 5 = 72. Помилка в кількості повторень: треба 5.","wrong":"Перевір кут: 360 поділити на 5 — це якраз 72. Отже, справа не в куті."},{"q":"Сніжинка з шести променів намалювала шестикутник. У циклі є поворот 60, але немає «перемістити на −50». Чого бракує?","options":["Повернення олівця в центр після кожного променя","Звуку сніжинки","Більшого кута повороту"],"correct":0,"explain":"Без повернення в центр промені з'єднуються в шестикутник.","wrong":"Промінь = вперед + назад. Чи повертається олівець у центр?"},{"q":"Баг — це…","options":["Розбіжність між очікуваним і фактичним результатом","Будь-яке червоне повідомлення комп'ютера","Комаха в системному блоці"],"correct":0,"explain":"Є очікуваний результат і фактичний. Якщо вони різні — це баг.","wrong":"Згадай: expected — що чекаємо, actual — що сталося. Різниця між ними…"},{"q":"Знайшов(-ла) підозріле місце в коді. Скільки змін робити за один раз?","options":["Одну — і одразу перевірити","Усі одразу","Жодної, легше все переписати"],"correct":0,"explain":"Одна зміна за раз: тоді точно відомо, що саме виправило помилку.","wrong":"Якщо змінити все одразу, не зрозумієш, яка зміна допомогла."},{"q":"ШІ порадив виправлення для бага. Як із ним вчинити?","options":["Відтворити помилку, внести зміну, повторити тест","Скопіювати й одразу здати вчителю","Проігнорувати: ШІ завжди помиляється"],"correct":0,"explain":"Пораду ШІ перевіряємо повторним тестом: відтворили, змінили, перевірили.","wrong":"Поради ШІ бувають корисними, але лише після перевірки тестом."}]}},"after":{"index":1,"heading":"🐞 Помилка — це розбіжність"}},{"path":"app/games/М3_Урок23_Гра2_Кроки-налагодження.html","title":"Кроки налагодження","description":"послідовність кроків","data":{"id":"m3g23b","lesson":23,"tag":"ШУКАЄМО","icon":"🔧","type":"order","title":"Кроки налагодження","file":"М3_Урок23_Гра2_Кроки-налагодження.html","conceptName":"порядок налагодження","concept":"Налагодження — це пошук і виправлення багів за планом: передбач → запусти → ізолюй підозрілу частину → читай блок за блоком → зміни одну річ → запиши результат.","skill":"налагоджувати програму за шістьма кроками і записувати тест-кейси","data":{"rounds":[{"title":"Знайшли баг — що далі?","steps":["Передбач очікуваний результат","Запусти й зафіксуй фактичний","Ізолюй підозрілу частину програми","Читай блоки один за одним","Зміни одну річ і повтори тест","Запиши, що було не так"],"hint":"спочатку передбачаємо, наприкінці — записуємо","explain":"Записаний баг легко не повторити в наступному проєкті."},{"title":"Тест-кейс для циклу","steps":["Запиши, що програма МАЄ зробити","Запусти програму","Запиши, що вона зробила НАСПРАВДІ","Порівняй два записи","Якщо збігається — тест пройдено"],"hint":"очікуване проти фактичного","explain":"Тест-кейс — це пара: очікуваний результат і фактичний. Збіг — тест пройдено."}]}},"after":{"index":2,"heading":"🔍 Пошук крок за кроком"}}],"legacyTitle":"Урок 23. Прогнозування, тестування і налагодження циклів","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 23</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Прогнозування, тестування і налагодження циклів</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Predicting, Testing and Debugging Loops</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як знайти й виправити помилку в програмі, а не вгадувати?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я записую очікуваний (<b>expected</b>) і фактичний (<b>actual</b>) результат.</li>\n      <li style=\"margin:6px 0;\">Я знаходжу причину помилки, перевіряючи програму частинами.</li>\n      <li style=\"margin:6px 0;\">Я виправляю щонайменше дві програми в Scratch і перевіряю їх повторно.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🐞 Помилка — це розбіжність</h2>\n\n  <p style=\"margin:0 0 12px;\">Помилку в програмі називають <b>bug</b>, а її пошук і виправлення — <b>налагодженням (debug)</b>. Помилка — це розбіжність між тим, що ми <b>очікували (expected)</b>, і тим, що побачили <b>насправді (actual)</b>. Тому спершу треба чітко записати, що програма має зробити.</p>\n\n  <p style=\"margin:0 0 12px;\">Перевірка однієї ситуації — це <b>тестовий випадок (test case)</b>: «натискаю прапорець — очікую квадрат зі стороною 50». Тест або пройдено (pass), або ні (fail).</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔍 Пошук крок за кроком</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Передбач:</b> запиши очікуваний результат.</li>\n    <li style=\"margin:8px 0;\"><b>Запусти:</b> подивись і запиши фактичний.</li>\n    <li style=\"margin:8px 0;\"><b>Ізолюй (isolate):</b> знайди, в якій частині проблема. У Scratch клацання по окремому скрипту чи блоку запускає лише його. Можна й тимчасово від'єднати частину блоків і запустити решту: чи зникла помилка?</li>\n    <li style=\"margin:8px 0;\"><b>Читай блок за блоком:</b> що робить кожен блок і чи мав би?</li>\n    <li style=\"margin:8px 0;\"><b>Зміни одну річ</b> і запусти знову. Під час систематичного пошуку помилки корисно змінювати одну річ за раз: тоді видно, що саме допомогло.</li>\n    <li style=\"margin:8px 0;\"><b>Запиши</b> причину, виправлення і чи пройдено тест.</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔁 Де ховаються помилки в циклах</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Неправильна кількість</b> повторень — фігура не замикається або малюється зайве.</li>\n    <li style=\"margin:8px 0;\"><b>Блок не на своєму місці:</b> те, що мало статися раз, опинилося в циклі — або навпаки.</li>\n    <li style=\"margin:8px 0;\"><b>Бракує блоку</b> в тілі — наприклад, повернення назад.</li>\n    <li style=\"margin:8px 0;\"><b>Немає початкового стану:</b> другий запуск починається не там, де перший.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📋 Як записати тест</h2>\n\n  <p style=\"margin:0 0 12px;\">Приклад для іншої програми: кіт має намалювати квадрат, але в циклі поворот на 80°.</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:560px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Причина</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Виправлення</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пройдено?</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">замкнений квадрат</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">лінії не сходяться</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">кут 80° замість 90°</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">поставити 90°</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">так, після повторного запуску</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Зверни увагу: у рядку немає слів «щось не так». Кожна клітинка конкретна — тому інша людина зможе повторити тест і перевірити виправлення. І тобі самому чи самій через тиждень одразу видно, що вже перевіряли.</p>\n\n  <div style=\"background:#FFF2F2;border-left:5px solid #C0392B;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Порада від ШІ?</b> Чат-бот може підказати, що виправити. Але поради не приймають на віру: спершу відтвори помилку, потім внеси зміну й запусти тест знову.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">Збери три програми точно за зразком — разом із помилками. Для кожної мету вказано.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Програма 1. Мета: панда біжить праворуч, перебираючи лапками</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (-150) y: (0)</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">завжди</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перейти до x: (-150) y: (0)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (10) кроків</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">наступний образ</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">чекати (0.2) секунд</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Програма 2. Мета: замкнений п'ятикутник</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">очистити</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">опустити олівець</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повторити (3)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (60) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">поворот ↻ на (72) градусів</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Програма 3. Мета: сніжинка з 6 променів від центру, потім кіт ховається</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">очистити</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (0) y: (0)</div>\n      <div style=\"border-left:6px solid #0FBD8C;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">опустити олівець</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повторити (6)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (50) кроків</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">поворот ↻ на (60) градусів</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">сховатися</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Для кожної програми заповни рядок таблиці тестування:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:620px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Програма</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Причина</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Виправлення</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пройдено?</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">3</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Передбач і запусти.</b> Для кожної програми спершу запиши, що бачиш у меті, потім запусти й запиши, що вийшло.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Ізолюй.</b> Прочитай блоки по одному. Який блок робить не те або якого бракує?</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Виправ одну річ.</b> Внеси одну зміну й запусти знову. Якщо не допомогло — поверни як було і шукай далі.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Перевір і збережи.</b> Коли тест пройдено, постав «так» і збережи проєкт. Виправ щонайменше дві програми з трьох.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Програма 1.</b> Бачу: панда тремтить на місці. Причина: «перейти до…» стоїть усередині «завжди» і щоразу повертає її на старт. Виправлення: прибрати цей блок із циклу.</p>\n    <p style=\"margin:10px 0 0;\"><b>Програма 2.</b> Бачу: три сторони, фігура не замкнена. Причина: замала кількість. Виправлення: «повторити (5)».</p>\n    <p style=\"margin:10px 0 0;\"><b>Програма 3.</b> Бачу: шестикутник замість променів. Причина: у тілі бракує повернення в центр. Виправлення: після «перемістити на (50)» додати «перемістити на (-50) кроків».</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Почни з програми 2 — у ній помилка в одному числі. Порахуй, скільки сторін у п'ятикутника.</p>\n    <p style=\"margin:10px 0 0;\">Для програми 1 підказка: котрий блок стоїть у програмі двічі? Чи має він повторюватися?</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо ти виправляєш програми 1 і 2 та заповнюєш для них таблицю.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Зроби навмисну помилку в одній зі своїх програм і дай однокласникові чи однокласниці разом із тестовим випадком: «натискаю прапорець — очікую…». Чи вдасться знайти помилку за твоїм тестом?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>I expected a pentagon, but the actual output was three sides. I fixed the repeat count.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u23-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що записують першим, коли тестують програму?</label>\n    <select id=\"g4-u23-q1\" name=\"g4-u23-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Виправлення</option>\n      <option>Очікуваний результат</option>\n      <option>Кількість блоків</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Очікуваний результат — без нього не видно, що є помилкою.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u23-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Навіщо під час пошуку помилки змінювати одну річ за раз?</label>\n    <select id=\"g4-u23-q2\" name=\"g4-u23-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб швидше закінчити</option>\n      <option>Щоб знати, яка зміна допомогла</option>\n      <option>Так вимагає Scratch</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб бачити, яка саме зміна допомогла чи зашкодила.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u23-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чат-бот радить змінити 3 на 4. Що робити?</label>\n    <select id=\"g4-u23-q3\" name=\"g4-u23-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Одразу змінити й не перевіряти</option>\n      <option>Відтворити помилку, змінити й запустити тест знову</option>\n      <option>Ігнорувати будь-які поради</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Відтворити помилку, внести зміну й повторити тест.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Щоб не вгадувати, я спершу ___, потім ___, а тоді змінюю ___ і ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Я виправляю щонайменше дві програми, і вони працюють за метою.</li>\n      <li style=\"margin:8px 0;\">Для кожної заповнено очікуване, фактичне, причину й виправлення.</li>\n      <li style=\"margin:8px 0;\">Після виправлення тест запущено ще раз і позначено «пройдено».</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> виправлені програми 1 і 2 з рядками таблиці.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> виправлені проєкти (або знімки екрана) і таблицю тестування.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>bug / debug</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">помилка / налагодження</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>expected / actual</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">очікуваний / фактичний</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>test case</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">тестовий випадок</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>isolate</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">ізолювати, відокремити</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>fix</b></td><td style=\"padding:8px 10px;\">виправлення</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I expected a snowflake, but the actual output was a hexagon.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-8","grade":4,"module":3,"number":8,"title":"Декомпозиція, підзавдання і підпрограми","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок24_Гра1_Назви-дієсловом.html","title":"Назви блок дієсловом","description":"сортування карток","data":{"id":"m3g24a","lesson":24,"tag":"ДІЄСЛОВО","icon":"🏷️","type":"sort","title":"Назви блок дієсловом","file":"М3_Урок24_Гра1_Назви-дієсловом.html","conceptName":"назви власних блоків","concept":"Власний блок називаємо дієсловом, яке каже, що блок робить: «стрибнути», «зібрати кристал», «налаштувати старт». Назви «блок1» чи «штука» нічого не пояснюють.","skill":"оцінювати назви власних блоків: добра назва — дієслово з чіткою метою","data":{"categories":[{"id":"good","label":"✅ Добра назва","hint":"дієслово + чітка мета"},{"id":"bad","label":"❌ Погана назва","hint":"нічого не пояснює"}],"items":[{"text":"стрибнути","cat":"good","explain":"Дієслово одразу каже, що робить блок.","hint":"одне слово — одна дія"},{"text":"блок1","cat":"bad","explain":"З назви «блок1» не зрозуміло, що всередині.","hint":"що робить цей блок?"},{"text":"зібрати кристал","cat":"good","explain":"Чітка мета дієсловом — добра назва.","hint":"видно мету"},{"text":"штука","cat":"bad","explain":"«Штука» не пояснює дію взагалі.","hint":"незрозуміло, що робить"},{"text":"налаштувати старт","cat":"good","explain":"Одразу ясно: блок готує початковий стан.","hint":"дієслово + мета"},{"text":"робити щось","cat":"bad","explain":"«Щось» — це не мета. Назва має бути конкретною.","hint":"що саме робить?"},{"text":"оголосити перемогу","cat":"good","explain":"Дієслово з чіткою метою — добра назва.","hint":"зрозуміло призначення"},{"text":"мій блок","cat":"bad","explain":"«Мій блок» не каже, що він робить.","hint":"дія не названа"}]}},"after":{"index":2,"heading":"📦 Підпрограма"}},{"path":"app/games/М3_Урок24_Гра2_Створи-блок.html","title":"Створи власний блок","description":"послідовність кроків","data":{"id":"m3g24b","lesson":24,"tag":"БЛОК","icon":"🧱","type":"order","title":"Створи власний блок","file":"М3_Урок24_Гра2_Створи-блок.html","conceptName":"декомпозиція і підпрограми","concept":"Велике завдання розбиваємо на підзавдання — це декомпозиція. Підзавдання оформлюємо власним блоком (підпрограмою): описуємо один раз, а викликаємо скільки завгодно.","skill":"створювати власний блок у Scratch і викликати його в програмі","data":{"rounds":[{"title":"Як створити підпрограму в Scratch","steps":["Відкрий розділ «Мої блоки»","Натисни «Створити блок»","Назви дієсловом: «стрибнути»","У блоці «визначити стрибнути» склади команди","Виклич блок у потрібних місцях програми"],"hint":"описуємо один раз, викликаємо багато","explain":"«Визначити» — це опис блока, а виклик — його використання у скриптах."},{"title":"Наповни й застосуй блок «стрибнути»","steps":["Визнач блок «стрибнути»","Змінити y на 40","Чекати 0,2 секунди","Змінити y на −40","Виклич «стрибнути» у скрипті гравця"],"hint":"угору → пауза → униз","explain":"Спрайт підстрибує на 40, чекає й повертається. Один блок — і стрибок доступний усюди."}]}},"after":{"index":2,"heading":"📦 Підпрограма"}}],"legacyTitle":"Урок 24. Декомпозиція, підзавдання і підпрограми","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 24</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Декомпозиція, підзавдання і підпрограми</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Decomposition, Subtasks and Sub-Routines</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як розбити велику програму на частини й навчити Scratch нової команди?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я розбиваю завдання на підзавдання (<b>subtasks</b>) і називаю їх дієсловами.</li>\n      <li style=\"margin:6px 0;\">Я створюю в Scratch власний блок — підпрограму (<b>sub-routine</b>) — і перевіряю його окремо.</li>\n      <li style=\"margin:6px 0;\">Я викликаю свій блок у головній програмі й використовую його двічі.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Декомпозиція</h2>\n\n  <p style=\"margin:0 0 12px;\">Велике завдання легше виконати, якщо розбити його на менші. Це <b>декомпозиція (decomposition)</b>. Кожна частина — <b>підзавдання (subtask)</b> — стає окремим маленьким алгоритмом, який можна зробити й перевірити.</p>\n\n  <p style=\"margin:0 0 12px;\">Підзавдання зручно називати дієсловами: «налаштувати старт», «керувати ракетою», «зібрати кристал». Дієслово одразу каже, що частина <b>робить</b>.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📦 Підпрограма</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Підпрограма (sub-routine)</b> — це група команд із назвою. Її описують один раз, а потім <b>викликають (call)</b> за назвою стільки разів, скільки потрібно. Як у танці: рух «оберт» описали один раз, а в танці кажуть просто «оберт» — і всі знають, що робити.</p>\n\n  <p style=\"margin:0 0 12px;\">Деякі підзавдання зручно оформити як підпрограму — особливо ті, що мають чітку мету або потрібні в кількох місцях. Не кожне підзавдання мусить ставати окремим блоком.</p>\n\n  <p style=\"margin:0 0 12px;\">У Scratch підпрограму створюють у категорії «Мої блоки»: «Створити блок» → назва → «Гаразд». З'являється блок-шапка «визначити [назва]». Під нею кладуть команди, а новий блок з'являється в палітрі — його можна ставити в будь-який скрипт.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Приклад: власний блок «стрибнути»</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FF6680;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">визначити [стрибнути]</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити y на (40)</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">чекати (0.2) секунд</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити y на (-40)</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Виклик</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [пробіл]</div>\n      <div style=\"border-left:6px solid #FF6680;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">стрибнути</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Головна програма стала коротшою і зрозумілішою: з назви «стрибнути» видно, що відбувається, навіть не заглядаючи всередину.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Що варто зробити окремим блоком?</b> Постав три запитання. Чи має ця частина чітку мету, яку можна назвати дієсловом? Чи знадобиться вона в кількох місцях? Чи можна перевірити її окремо від решти? Якщо на два питання відповідь «так», — це добрий кандидат на підпрограму.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Назва блоку не каже, що він робить: «блок1» замість «налаштувати старт».</li>\n    <li style=\"margin:8px 0;\">Блок створили, але ніде не викликали — він нічого не робить.</li>\n    <li style=\"margin:8px 0;\">У блок поклали забагато різних дій — його важко перевірити й використати ще раз.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">Гра «Космічний патруль»: ракета літає ліворуч-праворуч і збирає кристали. Сьогодні ти будуєш її основу.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Карта декомпозиції.</b> Розбий гру на чотири підзавдання й назви кожне дієсловом. Запиши карту в зошит чи документ:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:420px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Підзавдання</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що воно робить</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1. налаштувати старт</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">ракета внизу по центру, дивиться вгору, видима</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2. ______</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">рух ракети стрілками</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">3. ______</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">кристал зникає, звучить сигнал</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">4. ______</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">повідомлення, коли гру виграно</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Створи блок.</b> Додай спрайт Rocketship. Створи власний блок «налаштувати старт»:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FF6680;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">визначити [налаштувати старт]</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (0) y: (-120)</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">повернути в напрямку (0)</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">показати</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Перевір окремо.</b> Перетягни ракету мишею кудись убік, а тоді клацни по блоку-шапці «визначити [налаштувати старт]». Ракета повернулася на місце? Отже, підпрограма працює сама по собі.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Виклич двічі.</b> Збери головну програму й запусти:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #FF6680;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">налаштувати старт</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [r]</div>\n      <div style=\"border-left:6px solid #FF6680;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">налаштувати старт</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [стрілка праворуч]</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити x на (10)</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [стрілка ліворуч]</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити x на (-10)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Політай ракетою й натисни «r». Той самий блок спрацював і на старті, і за клавішею — це і є повторне використання (reusable). Збережи проєкт.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1, приклад.</b> 2 — керувати ракетою; 3 — зібрати кристал; 4 — оголосити перемогу.</p>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 3–4.</b> Клацання по шапці запускає підпрограму окремо. Кнопка «r» викликає ту саму підпрограму — змінювати старт тепер треба лише в одному місці.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Створи власний блок «стрибнути» з прикладу і виклич його пробілом.</p>\n    <p style=\"margin:10px 0 0;\">Потім додай виклик ще й на клацання по спрайту: «коли спрайт натиснуто» → «стрибнути».</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо блок «стрибнути» працює з двох різних подій.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Рефакторинг.</b> Якщо в програмі двічі стоїть однакова група блоків (наприклад, ривок: «змінити x на (40)», «грати звук», «змінити x на (-40)»), винеси її у власний блок «зробити ривок». Порівняй: що тепер легше змінити?</p>\n    <p style=\"margin:10px 0 0;\">Спробуй блок із параметром: під час створення натисни «Додати поле введення (число або текст)» і зроби «стрибнути на (висота)».</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>I called my custom block twice. It is reusable.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>Декомпозиція для дітей</b> — як розкладати велике завдання на частини. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/services/computational_thinking/decomposition/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Декомпозиція для дітей ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u24-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке декомпозиція?</label>\n    <select id=\"g4-u24-q1\" name=\"g4-u24-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Видалення зайвих блоків</option>\n      <option>Розбиття завдання на менші частини</option>\n      <option>Запуск програми двічі</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Розбиття завдання на менші частини — підзавдання.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u24-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Чому підпрограма зручна?</label>\n    <select id=\"g4-u24-q2\" name=\"g4-u24-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Її описують раз і викликають багато разів</option>\n      <option>Вона працює без виклику</option>\n      <option>Вона робить програму довшою</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Описуємо раз, викликаємо скільки треба; змінюємо в одному місці.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u24-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Яка назва для блоку найкраща?</label>\n    <select id=\"g4-u24-q3\" name=\"g4-u24-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>блок1</option>\n      <option>налаштувати старт</option>\n      <option>аааа</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">«налаштувати старт»: дієслово каже, що блок робить.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Мою гру розбито на ___. Мій блок „налаштувати старт“ ___, і я викликаю його ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Моя карта декомпозиції має чотири підзавдання, названі дієсловами.</li>\n      <li style=\"margin:8px 0;\">Мій власний блок «налаштувати старт» працює, і я перевіряю його окремо.</li>\n      <li style=\"margin:8px 0;\">Блок викликається у двох місцях програми.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> блок «стрибнути», що працює з двох подій.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> карту декомпозиції та збережений проєкт (або знімок екрана) з власним блоком.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>decomposition</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">декомпозиція</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>subtask</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">підзавдання</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>sub-routine / custom block</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">підпрограма / власний блок</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>call</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">викликати</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>reusable</b></td><td style=\"padding:8px 10px;\">придатний для повторного використання</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I broke the game into four subtasks. My custom block sets up the start.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-9","grade":4,"module":3,"number":9,"title":"Введення, виведення, події та різні результати","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок25_Гра1_Введення-чи-виведення.html","title":"Введення чи виведення?","description":"сортування карток","data":{"id":"m3g25a","lesson":25,"tag":"ВИХІД","icon":"🎛️","type":"sort","title":"Введення чи виведення?","file":"М3_Урок25_Гра1_Введення-чи-виведення.html","conceptName":"введення і виведення","concept":"Введення — це сигнал у програму: клавіша, клацання, датчик. Виведення — результат, який програма показує: рух, звук, зміна образу.","skill":"розрізняти введення (сигнали до програми) і виведення (результати програми)","data":{"categories":[{"id":"in","label":"📥 Введення","hint":"сигнал до програми"},{"id":"out","label":"📤 Виведення","hint":"результат програми"}],"items":[{"text":"Натискання клавіші A","cat":"in","explain":"Клавіша — сигнал від людини до програми.","hint":"людина дає сигнал"},{"text":"Спрайт змінює колір","cat":"out","explain":"Зміна кольору — результат, який ми бачимо.","hint":"програма показує результат"},{"text":"Клацання мишею по спрайту","cat":"in","explain":"Клацання — введення, подія для скрипта.","hint":"дія користувача"},{"text":"Звук Meow","cat":"out","explain":"Звук — це виведення, відповідь програми.","hint":"програма відповідає"},{"text":"Датчик руху спрацював","cat":"in","explain":"Датчик дає програмі введення автоматично.","hint":"сигнал із датчика"},{"text":"Спрайт стрибнув угору","cat":"out","explain":"Стрибок — видимий результат роботи скрипта.","hint":"бачимо результат"},{"text":"Нахил планшета","cat":"in","explain":"Нахил — сигнал, який програма отримує.","hint":"сигнал до програми"},{"text":"Напис «Рівень 2» на екрані","cat":"out","explain":"Напис — виведення інформації для гравця.","hint":"програма повідомляє"}]}},"after":{"index":1,"heading":"⌨️ Введення і виведення"}},{"path":"app/games/М3_Урок25_Гра2_Диско-пульт.html","title":"Диско-пульт","description":"сценарний вибір","data":{"id":"m3g25b","lesson":25,"tag":"ПУЛЬТ","icon":"🎚️","type":"quiz","title":"Диско-пульт","file":"М3_Урок25_Гра2_Диско-пульт.html","conceptName":"події і паралельні скрипти","concept":"Блок-шапка — це подія, що запускає скрипт: «коли клавішу натиснуто», «коли спрайт натиснуто». Кілька скриптів можуть працювати паралельно, кожен чекає на свою подію.","skill":"прив'язувати події до результатів і тестувати кожне введення окремо","data":{"questions":[{"q":"У «Диско-пульті» клавіша A змінює колір, B вмикає звук, клацання — стрибок. Ти натиснув(-ла) B. Що станеться?","options":["Зазвучить звук Meow","Зміниться колір","Спрайт стрибне"],"correct":0,"explain":"Кожна подія має свій результат: B — це звук.","wrong":"Перевір схему пульта: A — колір, B — звук, клацання — стрибок."},{"q":"Блок «коли я отримую повідомлення» — це…","options":["Сигнал від іншого скрипта всередині проєкту","Повідомлення від друга в інтернеті","Введення з клавіатури"],"correct":0,"explain":"Повідомлення надсилає інший скрипт, а не людина й не інтернет.","wrong":"Це внутрішній сигнал між скриптами, а не листування."},{"q":"У проєкті три скрипти реагують на різні клавіші. Як вони працюють?","options":["Паралельно: кожен чекає на свою подію","Працює лише перший у списку","По черзі, один за одним"],"correct":0,"explain":"Скрипти з різними подіями-шапками незалежні й працюють паралельно.","wrong":"Кожен скрипт слухає свою подію й не чекає на інші."},{"q":"Після повторного запуску спрайт лишився біля краю сцени. Чого бракує?","options":["Початкового стану під прапорцем: позиція, образ, очистити ефекти","Ще однієї клавіші","Більше звуків"],"correct":0,"explain":"Прапорець має повертати все на старт: позицію, образ, ефекти.","wrong":"Згадай: програма має починатися однаково після кожного запуску."},{"q":"Як правильно тестувати «Диско-пульт»?","options":["Кожне введення окремо: спершу A, потім B, потім клацання","Натиснути все одразу","Не тестувати, якщо виглядає гарно"],"correct":0,"explain":"Окреме тестування показує, яке саме введення працює не так.","wrong":"Якщо натиснути все одразу, не зрозумієш, яка подія дала збій."},{"q":"Клавіша A і клавіша B роблять одне й те саме. Що перевірити?","options":["Чи не продубльовано скрипт: у різних подій мають бути різні результати","Це нормально, так і задумано","Час видалити обидва скрипти"],"correct":0,"explain":"Дві події — один результат: скоріш за все, скрипт скопіювали й забули змінити.","wrong":"За планом кожна клавіша має свою дію. Шукай дублікат скрипта."}]}},"after":{"index":2,"heading":"⚡ Події"}},{"path":"app/games/М3_Урок25_Гра3_Ланцюг-події.html","title":"Ланцюг події","description":"послідовність кроків","data":{"id":"m3g25c","lesson":25,"tag":"ПОДІЯ","icon":"🔗","type":"order","title":"Ланцюг події","file":"М3_Урок25_Гра3_Ланцюг-події.html","conceptName":"ланцюг: введення → подія → скрипт → виведення","concept":"Інтерактивна програма працює ланцюгом: введення (дія користувача) запускає подію (блок-шапку), подія запускає скрипт, скрипт дає виведення (результат на сцені).","skill":"вибудовувати ланцюг «введення → подія → скрипт → виведення»","data":{"rounds":[{"title":"Як працює інтерактивна програма","steps":["Введення: натиснуто клавішу A","Подія: блок-шапка «коли клавішу A натиснуто»","Скрипт: блоки дії","Виведення: спрайт змінює колір"],"hint":"від дії користувача до результату на сцені","explain":"Введення запускає подію, подія — скрипт, скрипт дає виведення."},{"title":"Стрибок за клацанням","steps":["Клацання по спрайту","Подія «коли спрайт натиснуто»","Змінити y на 30, чекати, змінити y на −30","Спрайт стрибає на сцені"],"hint":"клацання → подія → рух → стрибок","explain":"Клацання запускає подію, скрипт рухає спрайт угору й униз — бачимо стрибок."}]}},"after":{"index":1,"heading":"⌨️ Введення і виведення"}}],"legacyTitle":"Урок 25. Введення, виведення, події та різні результати","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 25</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Введення, виведення, події та різні результати</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Inputs, Outputs, Events and Different Results</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як зробити, щоб різні дії користувача давали різні результати?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я розрізняю введення (<b>input</b>), подію (<b>event</b>) і виведення (<b>output</b>).</li>\n      <li style=\"margin:6px 0;\">Я планую таблицю «введення — подія — скрипт — результат».</li>\n      <li style=\"margin:6px 0;\">Я створюю в Scratch програму з трьома різними введеннями й перевіряю кожне окремо.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⌨️ Введення і виведення</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Введення (input)</b> — те, що програма отримує ззовні: натиснута клавіша, клацання мишею, дотик до екрана, значення датчика, відповідь на запитання. <b>Виведення (output)</b> — те, що програма робить у відповідь: рух, новий образ, звук, текст на екрані.</p>\n\n  <p style=\"margin:0 0 12px;\">Різні введення можуть давати різні результати: клавіша A змінює колір кота, клавіша B вмикає звук, клацання змушує кота підстрибнути.</p>\n\n  <p style=\"margin:0 0 12px;\">Введення й виведення є в багатьох пристроях: натискаєш кнопку джойстика — герой стрибає; торкаєшся екрана телефону — відкривається застосунок; датчик руху помічає людину — двері відчиняються. Щоразу є сигнал на вході й дія на виході.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚡ Події</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Подія (event)</b> — те, що запускає скрипт. У Scratch скрипти починаються з блоків-подій: «коли натиснуто зелений прапорець», «коли натиснуто клавішу [a]», «коли спрайт натиснуто», «коли я отримую [повідомлення]».</p>\n\n  <p style=\"margin:0 0 12px;\">Не кожна подія пов'язана з введенням людини. Зелений прапорець — це старт програми. А «оповістити [повідомлення]» — внутрішній сигнал: один скрипт програми повідомляє іншим, що час діяти. Тому схема нижче зручна для клавіш і клацань, але не описує всі випадки.</p>\n\n  <svg viewBox=\"0 0 860 230\" role=\"img\" aria-labelledby=\"g4u25a-t g4u25a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u25a-t\">Введення, подія, скрипт і результат</title>\n    <desc id=\"g4u25a-d\">Приклад: введення — натиснута клавіша A. Подія — «коли натиснуто клавішу a». Скрипт — змінити ефект кольору. Виведення — кіт змінює колір. Нижче примітка: подія «коли я отримую повідомлення» запускається не людиною, а іншим скриптом програми.</desc>\n    <g font-family=\"Arial, sans-serif\" text-anchor=\"middle\">\n      <rect x=\"6\" y=\"20\" width=\"196\" height=\"130\" rx=\"12\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n      <text x=\"104\" y=\"54\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\">INPUT</text>\n      <text x=\"104\" y=\"90\" font-size=\"26\">⌨️</text>\n      <text x=\"104\" y=\"126\" font-size=\"15\" fill=\"#3D4757\">клавіша A</text>\n      <rect x=\"226\" y=\"20\" width=\"196\" height=\"130\" rx=\"12\" fill=\"#FFF4D6\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n      <text x=\"324\" y=\"54\" font-size=\"17\" font-weight=\"700\" fill=\"#7A5A00\">EVENT</text>\n      <text x=\"324\" y=\"92\" font-size=\"15\" fill=\"#3D4757\">коли натиснуто</text>\n      <text x=\"324\" y=\"114\" font-size=\"15\" fill=\"#3D4757\">клавішу [a]</text>\n      <rect x=\"446\" y=\"20\" width=\"196\" height=\"130\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"544\" y=\"54\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">SCRIPT</text>\n      <text x=\"544\" y=\"92\" font-size=\"15\" fill=\"#3D4757\">змінити ефект</text>\n      <text x=\"544\" y=\"114\" font-size=\"15\" fill=\"#3D4757\">[колір] на (25)</text>\n      <rect x=\"666\" y=\"20\" width=\"188\" height=\"130\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n      <text x=\"760\" y=\"54\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\">OUTPUT</text>\n      <text x=\"760\" y=\"90\" font-size=\"26\">🐱</text>\n      <text x=\"760\" y=\"126\" font-size=\"15\" fill=\"#3D4757\">кіт змінив колір</text>\n    </g>\n    <g fill=\"#0033A0\"><polygon points=\"206,79 220,85 206,91\"></polygon><polygon points=\"426,79 440,85 426,91\"></polygon><polygon points=\"646,79 660,85 646,91\"></polygon></g>\n    <rect x=\"6\" y=\"168\" width=\"848\" height=\"48\" rx=\"10\" fill=\"#F0F4F8\"></rect>\n    <text x=\"430\" y=\"198\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">Не кожна подія — введення людини: «коли я отримую [повідомлення]» запускає інший скрипт програми.</text>\n  </svg>\n\n  <p style=\"margin:0 0 12px;\">Кілька скриптів можуть працювати одночасно. Поки кіт підстрибує після клацання, можна натиснути A — і він змінить колір просто в повітрі. Scratch запускає кожен скрипт від його власної події, тож скрипти не чекають одне на одного. Тому кожну подію зручно планувати й перевіряти окремо.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🏁 Початковий стан</h2>\n\n  <p style=\"margin:0 0 12px;\">Коли різні клавіші змінюють колір, образ і положення кота, після кількох натискань він може опинитися будь-де й будь-якого кольору. Тому на старті програма повертає все як було: позицію, образ, ефекти. Це скрипт початкового стану (initialise) під зеленим прапорцем.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧪 Як тестувати кожне введення</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Натисни прапорець — програма в початковому стані.</li>\n    <li style=\"margin:8px 0;\">Спробуй лише одне введення й порівняй із рядком таблиці.</li>\n    <li style=\"margin:8px 0;\">Знову натисни прапорець і переходь до наступного введення.</li>\n    <li style=\"margin:8px 0;\">Наостанок спробуй кілька введень поспіль — чи не заважають вони одне одному?</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Дві події запускають той самий результат — і користувач не бачить різниці між кнопками.</li>\n    <li style=\"margin:8px 0;\">Немає початкового стану — після кількох натискань усе «з'їхало», а прапорець цього не виправляє.</li>\n    <li style=\"margin:8px 0;\">Перевіряють усі клавіші одразу — і не зрозуміло, яка з них працює неправильно.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">Створи «Диско-пульт»: кіт по-різному реагує на три введення.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Сплануй.</b> Перенеси таблицю в зошит і заповни стовпчики «Скрипт» та «Очікую»:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:620px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Введення</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Подія</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Скрипт</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">клавіша A</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">коли натиснуто клавішу [a]</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">клавіша B</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">коли натиснуто клавішу [b]</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">клацання по коту</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">коли спрайт натиснуто</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Початковий стан.</b> Збери скрипт старту:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (0) y: (0)</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити образ на [costume1]</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">очистити графічні ефекти</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Три скрипти.</b> Збери скрипти за своїм планом. Наприклад:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [a]</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити ефект [колір] на (25)</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [b]</div>\n      <div style=\"border-left:6px solid #CF63CF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">грати звук [Meow] до кінця</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли спрайт натиснуто</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити y на (30)</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">чекати (0.3) секунд</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити y на (-30)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Тестуй по одному.</b> Перевір кожне введення окремо й заповни стовпчик «Бачу». Потім натисни прапорець: чи повернувся кіт у початковий стан? Якщо щось не так, повернися до рядка таблиці й перевір скрипт саме цього введення. Збережи проєкт.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 3–4.</b> A змінює колір кота на один крок, B вмикає нявкання, клацання — підстрибування. Результати мають бути різними й відповідати плану.</p>\n    <p style=\"margin:10px 0 0;\"><b>Прапорець</b> повертає кота в центр, до першого образу й звичайного кольору.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Зроби лише два введення: клавішу A і клацання по коту. Скрипти візьми з прикладу.</p>\n    <p style=\"margin:10px 0 0;\">Для кожного запиши в зошит, що очікуєш, натисни й порівняй.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо два введення дають різні результати, а прапорець повертає кота на старт.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Повідомлення між спрайтами.</b> Додай другий спрайт. У кота зроби: «коли натиснуто клавішу [пробіл]» → «оповістити [танцюй]». У другого спрайта: «коли я отримую [танцюй]» → кілька змін образу. Спрогнозуй, що відбудеться, і перевір. Хто тут дає введення, а хто — подію?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>Key A is the input. The cat changes colour — that is the output.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u25-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що з цього — введення?</label>\n    <select id=\"g4-u25-q1\" name=\"g4-u25-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Звук нявкання</option>\n      <option>Натиснута клавіша B</option>\n      <option>Новий образ кота</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Натиснута клавіша. Звук і образ — виведення.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u25-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Що запускає скрипт у Scratch?</label>\n    <select id=\"g4-u25-q2\" name=\"g4-u25-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Подія: блок-шапка на початку скрипту</option>\n      <option>Колір блоків</option>\n      <option>Кількість спрайтів</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Подія — блок-шапка: прапорець, клавіша, клацання, повідомлення.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u25-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. «Коли я отримую [танцюй]» — це введення від людини?</label>\n    <select id=\"g4-u25-q3\" name=\"g4-u25-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Так, завжди</option>\n      <option>Ні, це сигнал від іншого скрипту програми</option>\n      <option>Це виведення</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Ні. Це внутрішнє повідомлення: його надсилає інший скрипт.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Щоб різні дії давали різні результати, я ___. Клавіша A запускає подію ___, а результат — ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Моя програма має три введення з різними результатами.</li>\n      <li style=\"margin:8px 0;\">Таблицю «очікую — бачу» заповнено для кожного введення.</li>\n      <li style=\"margin:8px 0;\">Прапорець повертає кота в початковий стан.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> два введення з різними результатами і скрипт старту.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережений проєкт (або знімок екрана) і таблицю планування та тестів.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>input / output</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">введення / виведення</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>event</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">подія</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>trigger</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">запускати</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>key press / click</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">натискання клавіші / клацання</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>initialise</b></td><td style=\"padding:8px 10px;\">задати початковий стан</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>Different inputs give different outputs. The green flag resets the cat.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-10","grade":4,"module":3,"number":10,"title":"Коментарі в коді та систематичне тестування частин програми","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок26_Гра1_Коментарі.html","title":"Добрий коментар","description":"сортування карток","data":{"id":"m3g26a","lesson":26,"tag":"КОМЕНТАР","icon":"💬","type":"sort","title":"Добрий коментар","file":"М3_Урок26_Гра1_Коментарі.html","conceptName":"навіщо потрібні коментарі","concept":"Коментар пояснює МЕТУ коду, а не переказує блоки. Добрий коментар відповідає на «навіщо?», поганий — повторює те, що й так видно, або застарів і вводить в оману.","skill":"відрізняти коментарі, що пояснюють мету, від переказів блоків і застарілих нотаток","data":{"categories":[{"id":"good","label":"✅ Добрий коментар","hint":"пояснює мету"},{"id":"bad","label":"❌ Поганий коментар","hint":"переказує блоки чи застарів"}],"items":[{"text":"«Ставимо ракету на старт, щоб кожна гра починалася однаково»","cat":"good","explain":"Пояснено, навіщо цей блок, а не що він робить.","hint":"відповідає на «навіщо?»"},{"text":"«перейти до x: 0 y: −100»","cat":"bad","explain":"Це просто переказ блока — він і так видимий у коді.","hint":"повторює блок слово в слово"},{"text":"«Тут перевіряємо, чи врятовано кота»","cat":"good","explain":"Коментар пояснює мету частини коду.","hint":"ясно, навіщо ця частина"},{"text":"«додає 1»","cat":"bad","explain":"Це видно з самого блока; мета не пояснена.","hint":"не каже навіщо"},{"text":"«Повторюємо, поки не зберемо всі кристали»","cat":"good","explain":"Пояснено умову завершення — мету циклу.","hint":"мета циклу"},{"text":"Коментар обіцяє рух, але блоки руху вже видалили","cat":"bad","explain":"Застарілий коментар вводить в оману — гірше, ніж його відсутність.","hint":"код змінився, коментар — ні"},{"text":"«Пауза потрібна, щоб гравець встиг прочитати підказку»","cat":"good","explain":"Мета паузи пояснена.","hint":"навіщо пауза"},{"text":"«крутий блок»","cat":"bad","explain":"«Крутий» не пояснює ані дію, ані мету.","hint":"ні дії, ні мети"}]}},"after":{"index":1,"heading":"💬 Навіщо коментарі"}},{"path":"app/games/М3_Урок26_Гра2_Тестуй-частинами.html","title":"Тестуй частинами","description":"сценарний вибір","data":{"id":"m3g26b","lesson":26,"tag":"ЧАСТИНИ","icon":"🧪","type":"quiz","title":"Тестуй частинами","file":"М3_Урок26_Гра2_Тестуй-частинами.html","conceptName":"систематичне тестування","concept":"Великий проєкт тестуємо частинами за планом: Старт, Керування, Фініш. Кожну частину перевіряємо окремо, а коментарі допомагають іншій людині розібратися в проєкті.","skill":"тестувати проєкт частинами за планом і знаходити пропущені блоки","data":{"questions":[{"q":"Проєкт «Рятувальна ракета» має частини: Старт, Керування, Фініш. Як його тестувати?","options":["Кожну частину окремо за планом","Усе одразу наприкінці","Не тестувати, якщо запускається"],"correct":0,"explain":"Тестування частинами швидко показує, де саме проблема.","wrong":"Якщо тестувати все одразу, не зрозумієш, яка частина дала збій."},{"q":"Фініш: «завжди → якщо торкається → звук Win». Але сигнал грає без кінця. Чого бракує?","options":["Блока «зупинити все» після звуку","Більшої гучності","Ще одного звуку"],"correct":0,"explain":"Без «зупинити все» умова «торкається» спрацьовує знову й знову.","wrong":"Цикл «завжди» не завершиться сам — звук повторюватиметься без кінця."},{"q":"Що коментар має пояснювати насамперед?","options":["Мету: навіщо ця частина коду","Кожен блок слово в слово","Ім'я автора програми"],"correct":0,"explain":"Коментар відповідає на «навіщо?», а не переказує «що?».","wrong":"Переказ блоків не потрібен — їх і так видно. Шукай відповідь на «навіщо?»."},{"q":"Спершу добираємо зрозумілі назви змінних і блоків. А коментарі…","options":["Додаємо там, де мета не очевидна","Пишемо під кожним блоком","Не потрібні взагалі"],"correct":0,"explain":"Зрозумілі назви — основа, коментарі — для місць, де мета не очевидна.","wrong":"Коментар під кожним блоком — шум. Коментуємо те, що не очевидно."},{"q":"Як додати коментар до блока в Scratch?","options":["Права кнопка по блоку → «Додати коментар»","Потрійний клік по блоку","Перетягнути блок на сцену"],"correct":0,"explain":"У Scratch коментар додають через контекстне меню блока.","wrong":"Згадай контекстне меню: права кнопка миші по блоку."},{"q":"Ти передаєш проєкт однокласнику(-ці). Що допоможе розібратися в ньому?","options":["Коментарі про мету частин і план тестування","Якнайбільше спрайтів","Складні назви блоків"],"correct":0,"explain":"При передачі проєкту коментарі й план тестування — карта для іншої людини.","wrong":"Постав себе на місце людини, яка бачить проєкт уперше: що їй допоможе?"}]}},"after":{"index":3,"heading":"🧪 Тестуємо частинами"}}],"legacyTitle":"Урок 26. Коментарі в коді та систематичне тестування","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 26</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Коментарі в коді та систематичне тестування частин програми</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Code Comments and Systematic Testing of Program Parts</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як зробити програму зрозумілою для іншої людини й перевірити її частина за частиною?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я прикріплюю щонайменше три корисні коментарі (<b>comments</b>) до скриптів Scratch.</li>\n      <li style=\"margin:6px 0;\">Я складаю план тестування частин програми й записую очікуване й фактичне.</li>\n      <li style=\"margin:6px 0;\">Я пояснюю свою програму однокласникові чи однокласниці, користуючись коментарями.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">💬 Навіщо коментарі</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Коментар (comment)</b> — це нотатка поруч із кодом. Програма її не виконує, зате людина, яка відкриє проєкт, одразу розуміє, що робить скрипт і навіщо. Такою людиною можеш бути ти сам чи сама через місяць.</p>\n\n  <p style=\"margin:0 0 12px;\">Добрий коментар пояснює <b>мету (purpose)</b> — навіщо цей скрипт, — а не переказує блоки.</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:460px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Погано</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Добре</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«перейти до x: 0 y: -100»</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«Ставимо ракету на старт, щоб кожна гра починалася однаково»</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«якщо торкається»</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«Перевіряємо, чи долетіла ракета до платформи — тоді перемога»</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Коментарі не замінюють зрозумілих назв. Спрайт «Ракета» кращий за «Спрайт1» — навіть без жодного коментаря. Так само й з іншим: власний блок «налаштувати старт» зрозуміліший за «блок1», а змінна «бали» — за «а».</p>\n\n  <p style=\"margin:0 0 12px;\">Коментар особливо потрібен, коли скрипт робить щось неочевидне: чекає певний час, перевіряє умову, спрацьовує за повідомленням від іншого спрайта. Там, де все ясно з назв, досить короткої позначки або й зовсім без коментаря.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🖱 Як додати коментар у Scratch</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Клацни правою кнопкою по блоку.</li>\n    <li style=\"margin:8px 0;\">Обери «Додати коментар».</li>\n    <li style=\"margin:8px 0;\">Напиши коротко, навіщо цей скрипт. Коментар прикріпиться до блоку й рухатиметься разом із ним.</li>\n  </ol>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧪 Тестуємо частинами</h2>\n\n  <p style=\"margin:0 0 12px;\">Велику програму перевіряють не всю одразу, а частинами — <b>компонентами</b>: старт, керування, фініш. Для кожної частини складають <b>план тестування (test plan)</b>: що робимо, що очікуємо, що бачимо. Якщо одна частина не пройшла тест, одразу видно, де шукати помилку.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Передавання проєкту (handover).</b> Коли проєкт отримує інша людина, вона читає назви й коментарі. Якщо без твоїх пояснень їй зрозуміло, що робить кожна частина, — коментарі написано добре.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Коментар повторює блок слово в слово — нічого нового він не пояснює.</li>\n    <li style=\"margin:8px 0;\">Коментар застарів: код змінили, а коментар ні.</li>\n    <li style=\"margin:8px 0;\">Тестують усю гру відразу — і незрозуміло, яка частина зламалася.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\">Гра «Рятувальна ракета»: ракета стартує внизу, летить стрілками вгору-вниз, а коли торкнеться платформи нагорі — звучить сигнал і гра закінчується. Додай спрайти Rocketship і платформу (наприклад, Button2 угорі сцени). Збери скрипти ракети:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Старт</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (0) y: (-120)</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити образ на [rocketship-a]</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Керування</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [стрілка вгору]</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити y на (10)</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто клавішу [стрілка вниз]</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">змінити y на (-10)</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Фініш</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">завжди</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">якщо &lt;торкається [Button2]?&gt; то</div>\n      <div style=\"border-left:6px solid #CF63CF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">грати звук [Win] до кінця</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Назви.</b> Перейменуй спрайти: «Ракета» і «Платформа» (поле з назвою під сценою). Онови назву в блоці «торкається». Зрозумілі назви — перший крок до зрозумілої програми, ще до будь-яких коментарів.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Коментарі.</b> Додай до трьох частин — Старт, Керування, Фініш — по одному коментарю про мету.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. План тестування.</b> Заповни таблицю, запускаючи кожну частину окремо:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:580px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Частина</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що роблю</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пройдено?</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Старт</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">натискаю прапорець</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Керування</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">тисну стрілки</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Фініш</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">довожу ракету до платформи</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">сигнал, гра зупиняється</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Виправ і передай.</b> Одна частина тест не пройде. Виправ її й запусти тест знову. Потім поміняйтеся проєктами з сусідом чи сусідкою: хай пояснить твою програму лише за коментарями. Збережи проєкт.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Фініш не проходить: сигнал грає без кінця, а гра не зупиняється, бо в «завжди» немає блоку зупинки.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Після «грати звук [Win] до кінця» додай «зупинити [все]». Тест фінішу тепер пройдено.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Додай лише два коментарі: до Старту й до Фінішу. Скористайся рамкою: «Цей скрипт потрібен, щоб ___».</p>\n    <p style=\"margin:10px 0 0;\">Протестуй дві частини: Старт і Фініш.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо є два коментарі про мету, а фініш виправлено.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Огляд коментарів.</b> Оціни коментарі однокласника за шкалою «пояснює мету / переказує блок». Запропонуй одне покращення, нічого не змінюючи в коді.</p>\n    <p style=\"margin:10px 0 0;\">Напиши коментар-<b>припущення</b> (assumption): «Припускаємо, що платформа завжди нагорі». Коли таке припущення корисне для того, хто змінюватиме гру?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>This comment explains the purpose of the script.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u26-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що має пояснювати добрий коментар?</label>\n    <select id=\"g4-u26-q1\" name=\"g4-u26-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Навіщо цей код</option>\n      <option>Які кольори блоків</option>\n      <option>Скільки блоків у скрипті</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Навіщо код, тобто його мету.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u26-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Навіщо тестувати програму частинами?</label>\n    <select id=\"g4-u26-q2\" name=\"g4-u26-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб швидше закінчити урок</option>\n      <option>Щоб знати, яка частина зламалася</option>\n      <option>Щоб додати більше коментарів</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб одразу бачити, де шукати помилку.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u26-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Код змінили, а коментар ні. Що не так?</label>\n    <select id=\"g4-u26-q3\" name=\"g4-u26-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Нічого</option>\n      <option>Коментар тепер може вводити в оману</option>\n      <option>Програма перестане працювати</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Застарілий коментар вводить в оману — його оновлюють разом із кодом.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Мої коментарі пояснюють ___. Я тестую частинами, бо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">У моєму проєкті щонайменше три коментарі про мету, прикріплені до скриптів.</li>\n      <li style=\"margin:8px 0;\">План тестування заповнено, а зламану частину виправлено й перевірено знову.</li>\n      <li style=\"margin:8px 0;\">Мою програму пояснили за коментарями.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> два коментарі про мету й виправлений фініш.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережений проєкт із коментарями (або знімок екрана) і план тестування.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>comment</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">коментар</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>purpose</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">мета</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>test plan</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">план тестування</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>expected / actual</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">очікуваний / фактичний</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>component</b></td><td style=\"padding:8px 10px;\">частина програми</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>My comment explains why the rocket starts at the bottom.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-3-11","grade":4,"module":3,"number":11,"title":"Надійні програми й кібербезпекове мислення","moduleTitle":"Алгоритми та програмування в Scratch","games":[{"path":"app/games/М3_Урок27_Гра1_Межі.html","title":"Підходить чи ні?","description":"сортування карток","data":{"id":"m3g27a","lesson":27,"tag":"МЕЖІ","icon":"🚦","type":"sort","title":"Підходить чи ні?","file":"М3_Урок27_Гра1_Межі.html","conceptName":"перевірка введення","concept":"Кіт питає: «Скільки кроків? (10–100)». Програма перевіряє відповідь ПЕРЕД використанням: більше 9 і менше 101. Межі 10 і 100 підходять, а їхні сусіди 9 і 101 — ні.","skill":"визначати, які значення проходять перевірку «більше 9 і менше 101», а які — неочікувані","data":{"categories":[{"id":"ok","label":"✅ Підходить","hint":"від 10 до 100"},{"id":"no","label":"⚠️ Неочікуване","hint":"відхилити й попросити ще раз"}],"items":[{"text":"50","cat":"ok","explain":"50 — між 10 і 100, підходить.","hint":"в межах"},{"text":"100","cat":"ok","explain":"Межа 100 підходить: умова «менше ніж 101».","hint":"верхня межа"},{"text":"10","cat":"ok","explain":"Межа 10 підходить: умова «більше ніж 9».","hint":"нижня межа"},{"text":"25","cat":"ok","explain":"25 — у межах від 10 до 100.","hint":"в межах"},{"text":"77","cat":"ok","explain":"77 — у межах від 10 до 100.","hint":"в межах"},{"text":"«швидко»","cat":"no","explain":"Слово замість числа — програма відхиляє й просить ще раз.","hint":"це не число"},{"text":"−10","cat":"no","explain":"Від'ємне число поза межами — відхиляємо.","hint":"менше за 10"},{"text":"999","cat":"no","explain":"999 набагато більше за 100 — відхиляємо.","hint":"за верхньою межею"},{"text":"9","cat":"no","explain":"9 — сусід нижньої межі: умова «більше ніж 9» не пропускає.","hint":"на одиницю менше межі"},{"text":"101","cat":"no","explain":"101 — сусід верхньої межі: умова «менше ніж 101» не пропускає.","hint":"на одиницю більше межі"}]}},"after":{"index":2,"heading":"✅ Перевірка введення"}},{"path":"app/games/М3_Урок27_Гра2_Безпечна-дія.html","title":"Безпечна дія","description":"сценарний вибір","data":{"id":"m3g27b","lesson":27,"tag":"ЗАХИСТ","icon":"🛡️","type":"quiz","title":"Безпечна дія","file":"М3_Урок27_Гра2_Безпечна-дія.html","conceptName":"захисне мислення","concept":"Захисне мислення: зупинись → перевір → запитай дорослого → повідом. Програми перевіряють неочікуване введення, а ми — підозрілі пропозиції. Усе в іграх вигадане: ніколи не вводь справжні паролі й особисті дані.","skill":"обирати безпечну дію в підозрілих ситуаціях і пояснювати навіщо","data":{"questions":[{"q":"Гра пропонує: «1000 монет безкоштовно, просто натисни!». Твоя дія?","options":["Не натискати; зупинитися й показати дорослому","Натиснути швидше, поки не зникло","Розповісти всім друзям"],"correct":0,"explain":"Безкоштовні монети — класична пастка. Зупинись, перевір, запитай дорослого.","wrong":"Згадай правило: зупинись → перевір → запитай дорослого → повідом."},{"q":"Застосунок «Ліхтарик» просить доступ до контактів. Що це?","options":["Зайвий дозвіл: ліхтарику контакти не потрібні — відхилити","Нормально для будь-якої програми","Привітання від друзів"],"correct":0,"explain":"Застосунку дають лише ті дозволи, що потрібні для його роботи.","wrong":"Подумай: навіщо ліхтарику твої контакти?"},{"q":"Планшет просить оновлення. Як вчинити?","options":["Оновлювати разом із дорослим","Ігнорувати оновлення завжди","Видалити всі програми"],"correct":0,"explain":"Оновлення важливі для безпеки, але робимо їх разом із дорослим.","wrong":"Оновлення латають дірки в безпеці — ігнорувати їх небезпечно."},{"q":"Проєкт робився три тижні й лежить в одній копії на одному планшеті. Що порадиш?","options":["Зберегти ще одну копію в іншому місці","Нічого, однієї копії досить","Видалити старі версії"],"correct":0,"explain":"Резервна копія врятує працю, якщо планшет зламається або загубиться.","wrong":"Одна копія — це ризик втратити три тижні праці."},{"q":"Коли програма має перевіряти відповідь користувача?","options":["Перед тим, як її використовувати","Після того, як сталася помилка","Ніколи"],"correct":0,"explain":"Перевірка перед використанням не пускає неочікувані дані в програму.","wrong":"Після помилки перевіряти пізно — пошкодження вже сталося."},{"q":"Введення «999» не пройшло перевірку. Які два способи реагування?","options":["Відхилити й попросити ще раз АБО підставити безпечне значення за замовчуванням","Одразу закрити програму","Погодитися мовчки"],"correct":0,"explain":"Надійна програма або просить повторити, або бере безпечне значення.","wrong":"Згадай два чемні способи: попросити ще раз або обрати безпечне значення."}]}},"after":{"index":4,"heading":"🛡 Захисне мислення поза програмою"}},{"path":"app/games/М3_Урок27_Гра3_Правило-безпеки.html","title":"Правило безпеки","description":"послідовність кроків","data":{"id":"m3g27c","lesson":27,"tag":"ПРАВИЛО","icon":"🚸","type":"order","title":"Правило безпеки","file":"М3_Урок27_Гра3_Правило-безпеки.html","conceptName":"правило чотирьох кроків","concept":"Підозріла ситуація — діємо за правилом: зупинись → перевір → запитай дорослого → повідом. Програми роблять схоже: запитали → отримали → перевірили → використали.","skill":"застосовувати правило безпеки і порядок перевірки введення в програмі","data":{"rounds":[{"title":"Підозріла пропозиція в інтернеті","steps":["Зупинись","Перевір: чи це схоже на правду?","Запитай дорослого","Повідом про підозріле"],"hint":"не поспішай натискати","explain":"Чотири кроки захищають від пасток: зупинись, перевір, запитай дорослого, повідом."},{"title":"Програма отримала відповідь користувача","steps":["Запитай: «Скільки кроків? (10–100)»","Отримай відповідь","Перевір межі: більше 9 і менше 101","Якщо ні — попроси ще раз або візьми безпечне значення","Використовуй перевірене число"],"hint":"перевірка — перед використанням","explain":"Надійна програма ніколи не використовує відповідь без перевірки."}]}},"after":{"index":4,"heading":"🛡 Захисне мислення поза програмою"}}],"legacyTitle":"Урок 27. Надійні програми й кібербезпекове мислення","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 3 &bull; Урок 27</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Надійні програми й кібербезпекове мислення</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Robust Programs and Cybersecurity Thinking</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: що має зробити програма, коли людина вводить не те, чого чекали?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я знаходжу неочікуване введення (<b>unexpected input</b>).</li>\n      <li style=\"margin:6px 0;\">Я додаю в Scratch перевірку введення (<b>validate</b>) і безпечну реакцію.</li>\n      <li style=\"margin:6px 0;\">Я обираю безпечну дію в ситуаціях із підозрілим посиланням, дозволом, оновленням і резервною копією.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧱 Надійна програма</h2>\n\n  <p style=\"margin:0 0 12px;\">Люди помиляються: натискають не ту клавішу, пишуть слово замість числа, вводять надто велике значення. <b>Надійна програма</b> поводиться передбачувано навіть тоді.</p>\n\n  <p style=\"margin:0 0 12px;\">Уяви: кіт питає «Скільки кроків зробити? (від 10 до 100)». Хтось пише «швидко», «-10» чи «999». Без перевірки програма може дати неправильний або неочікуваний результат: кіт вилетить за край сцени або не зрушить із місця.</p>\n\n  <p style=\"margin:0 0 12px;\">Надійність зустрічається всюди: банкомат просить повторити PIN, якщо його введено неправильно; форма на сайті підсвічує порожнє обов'язкове поле; ліфт не рушає, поки відчинені двері. Кожен пристрій перевіряє, перш ніж діяти.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевірка введення</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Перевірка (validation)</b> — це умова, яку програма перевіряє <b>перед</b> тим, як використати введення. Якщо введення підходить — працюємо з ним. Якщо ні — безпечно реагуємо. Є два поширені способи:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Відхилити й попросити ще раз:</b> «Потрібне число від 10 до 100». Часто це найкращий варіант — людина сама виправляє помилку.</li>\n    <li style=\"margin:8px 0;\"><b>Узяти безпечне значення за замовчуванням (safe default)</b> і повідомити про це: «Беру 20 кроків».</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Перевірку ставлять одразу після введення, до першого використання значення. Якщо перевірити пізніше, неправильне значення встигне зашкодити: кіт спершу вилетить за край, а вже потім програма скаже про помилку.</p>\n\n  <p style=\"margin:0 0 12px;\">Який спосіб кращий, залежить від ситуації. Безпечне значення зручне в грі, але там, де помилка важлива, краще попросити ввести ще раз.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Перевірка введення</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #FFBF00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">коли натиснуто зелений прапорець</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">перейти до x: (-150) y: (0)</div>\n      <div style=\"border-left:6px solid #5CB1D6;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">запитати (Скільки кроків? Від 10 до 100) і чекати</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">якщо &lt;&lt;(відповідь) &gt; (9)&gt; і &lt;(відповідь) &lt; (101)&gt;&gt; то</div>\n      <div style=\"border-left:6px solid #4C97FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">перемістити на (відповідь) кроків</div>\n      <div style=\"border-left:6px solid #FFAB19;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">інакше</div>\n      <div style=\"border-left:6px solid #9966FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">говорити (Потрібне число від 10 до 100. Натисни прапорець і спробуй ще.) (3) секунд</div>\n    </div>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🎯 Перевіряй межі</h2>\n\n  <p style=\"margin:0 0 12px;\">Помилки найчастіше ховаються на межах. Якщо дозволено від 10 до 100, перевір не лише 50, а й самі межі — 10 і 100 — і числа поруч за ними: 9 і 101. Межі мають пройти, а сусідні числа — ні. Такі тести показують, чи правильно записано умову: «більше за 9» і «більше або дорівнює 10» — одне й те саме для цілих чисел, а от «більше за 10» вже відкидає 10.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛡 Захисне мислення поза програмою</h2>\n\n  <p style=\"margin:0 0 12px;\">Той самий принцип — перевір, перш ніж діяти, — захищає й у житті. Коли щось здається дивним, діє правило чотирьох кроків: <b>зупинись → перевір → запитай дорослого → повідом</b> (report).</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🐱 Працюємо в Scratch: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a> або запусти Scratch на шкільному комп'ютері. Готовий проєкт збережи: <b>Файл → Зберегти на ваш комп'ютер</b>.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Знайди неочікуване.</b> Кіт чекає число від 10 до 100. Для кожного введення запиши «підходить» чи «неочікуване»: 50, швидко, -10, 999, 100.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Збери й запусти.</b> Збери скрипт перевірки введення. Спершу перевір одне правильне число.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Тестуй.</b> Для кожного введення з Кроку 1 запиши, що очікуєш, запусти й запиши, що бачиш. Додай ще два рядки для меж — 9 і 10 — і перевір їх так само:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:460px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Введення</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пройдено?</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">50</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">швидко</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">-10</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">999</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">100</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Безпечна дія.</b> Для кожної ситуації запиши безпечну дію одним коротким реченням:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Посилання.</b> У грі пишуть: «Натисни тут — отримаєш 1000 монет безкоштовно!»</li>\n    <li style=\"margin:8px 0;\"><b>Дозвіл.</b> Застосунок-ліхтарик просить доступ до контактів.</li>\n    <li style=\"margin:8px 0;\"><b>Оновлення.</b> Шкільний планшет пропонує встановити оновлення системи.</li>\n    <li style=\"margin:8px 0;\"><b>Резервна копія.</b> Над проєктом у Scratch працювали три тижні, а збережено лише одну копію.</li>\n  </ul>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Підходять 50 і 100. Неочікувані: «швидко» (не число), -10 і 999 (поза межами).</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> 50, 100 і межа 10 — кіт іде; 9 — уже ні. «Швидко», -10, 999 — кіт каже, що потрібне число від 10 до 100, і не рухається.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> Посилання: не натискати, показати дорослому. Дозвіл: відхилити — ліхтарику контакти не потрібні. Оновлення: сказати вчителеві чи батькам — оновлення зазвичай варто встановлювати, але разом із дорослим. Копія: зберегти ще одну копію, наприклад у шкільній папці.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Збери скрипт перевірки введення з прикладу.</p>\n    <p style=\"margin:10px 0 0;\">Протестуй лише два введення: 50 і «швидко». Запиши, що очікуєш і що бачиш.</p>\n    <p style=\"margin:10px 0 0;\">Для Кроку 4 обери дві ситуації. Завдання виконано, якщо обидва тести записано, а для двох ситуацій названо безпечну дію.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Питати, доки не вийде.</b> Заміни «якщо… інакше» на цикл «повторювати, доки &lt;умова&gt;», щоб кіт питав знову, доки не отримає правильне число.</p>\n    <p style=\"margin:10px 0 0;\"><b>Модель «загроза — захист».</b> Для власного проєкту Scratch назви одну можливу проблему (наприклад, неочікуване введення чи втрату файлу) і захист від неї.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The program validates the input before using it.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u27-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що таке перевірка введення?</label>\n    <select id=\"g4-u27-q1\" name=\"g4-u27-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Перевірка, чи працює комп'ютер</option>\n      <option>Перевірка даних перед тим, як їх використати</option>\n      <option>Видалення програми</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Перевірка даних перед використанням.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u27-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Користувач увів «швидко» замість числа. Що найкраще?</label>\n    <select id=\"g4-u27-q2\" name=\"g4-u27-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Нічого не робити</option>\n      <option>Пояснити, що потрібне число, і дати ввести ще раз</option>\n      <option>Закрити програму</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Пояснити й дати ще одну спробу. Інколи підходить безпечне значення за замовчуванням.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u27-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Незнайомий сайт обіцяє «безкоштовні монети». Що робити?</label>\n    <select id=\"g4-u27-q3\" name=\"g4-u27-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Натиснути, поки діє акція</option>\n      <option>Зупинитися й показати дорослому</option>\n      <option>Переслати друзям</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Зупинитися, перевірити й запитати дорослого.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Коли людина вводить не те, програма має ___. У житті я діятиму так само: ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Моя програма перевіряє введення й безпечно реагує на неочікуване.</li>\n      <li style=\"margin:8px 0;\">Таблиця тестування заповнена щонайменше для чотирьох введень.</li>\n      <li style=\"margin:8px 0;\">Для кожної ситуації названо безпечну дію.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> два записані тести й безпечні дії для двох ситуацій.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> збережений проєкт (або знімок екрана), таблицю тестування і записи до Кроку 4.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>unexpected input</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">неочікуване введення</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>validate</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">перевіряти</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>safe default</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">безпечне значення за замовчуванням</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>permission</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">дозвіл</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>report</b></td><td style=\"padding:8px 10px;\">повідомити</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The program validates the input. If the input is unexpected, it asks again.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-1","grade":4,"module":4,"number":1,"title":"Керовані системи, сервісні роботи та роль людини","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок28_Гра1_Керована-система.html","title":"Всередині керованої системи","description":"сортування карток","data":{"id":"m4g28a","lesson":28,"tag":"СИСТЕМА","icon":"⚙️","type":"sort","title":"Всередині керованої системи","file":"М4_Урок28_Гра1_Керована-система.html","conceptName":"введення → опрацювання → виведення","concept":"Керована система отримує дані зі світу (датчик або кнопка — введення), опрацьовує їх за програмою і щось робить (виведення). Інколи виведення рухає виконавчий пристрій — мотор, клапан, замок.","skill":"розпізнавати введення, опрацювання і виведення в керованих системах","data":{"categories":[{"id":"in","label":"📥 Введення","hint":"датчик або кнопка"},{"id":"proc","label":"🧠 Опрацювання","hint":"програма перевіряє правило"},{"id":"out","label":"📤 Виведення","hint":"екран, звук, рух"}],"items":[{"text":"Датчик температури в теплиці","cat":"in","explain":"Датчик дає системі дані зі світу — це введення.","hint":"звідки система дізнається про спеку?"},{"text":"Правило «якщо тепліше за 28 °C — відчинити кватирку»","cat":"proc","explain":"Програма перевіряє правило — це опрацювання.","hint":"програма думає"},{"text":"Мотор відчиняє кватирку","cat":"out","explain":"Мотор — виконавчий пристрій, він змінює щось у світі. Це виведення.","hint":"система діє"},{"text":"Кнопка виклику ліфта","cat":"in","explain":"Кнопка — теж введення, не лише датчики.","hint":"людина натискає"},{"text":"Розумний світлофор рахує машини камерою","cat":"in","explain":"Камера збирає дані — введення.","hint":"збір даних"},{"text":"Програма вирішує подовжити зелене світло","cat":"proc","explain":"Рішення за програмою — опрацювання.","hint":"перевірка правила"},{"text":"Світлофор перемикається на зелений","cat":"out","explain":"Зміна світла — виведення, видиме людям.","hint":"результат назовні"},{"text":"Комп'ютер у шахах аналізує твій хід","cat":"proc","explain":"Аналіз ходу — це опрацювання за програмою.","hint":"обчислення"},{"text":"Датчик відстані лікарняного робота помічає людину","cat":"in","explain":"Датчик відстані — введення.","hint":"дані зі світу"},{"text":"Робот-кур'єр зупиняє колеса перед перешкодою","cat":"out","explain":"Зупинка моторів — дія системи, виведення.","hint":"робот діє"}]}},"after":{"index":1,"heading":"⚙️ Що таке керована система"}},{"path":"app/games/М4_Урок28_Гра2_Системі-чи-людині.html","title":"Системі чи людині?","description":"сортування карток","data":{"id":"m4g28b","lesson":28,"tag":"РОЛІ","icon":"🤝","type":"sort","title":"Системі чи людині?","file":"М4_Урок28_Гра2_Системі-чи-людині.html","conceptName":"роль людини в керованих системах","concept":"Завдання ділять на три групи: А — можна повністю доручити системі; Б — система робить, людина перевіряє; В — вирішує лише людина. Складні й відповідальні рішення лишаються за людьми.","skill":"розподіляти завдання між системою та людиною з поясненням","data":{"categories":[{"id":"a","label":"🤖 А. Повністю системі","hint":"просте й безпечне"},{"id":"b","label":"👀 Б. Система + перевірка людини","hint":"система робить, людина стежить"},{"id":"c","label":"🧑 В. Лише людина","hint":"відповідальне рішення"}],"items":[{"text":"Відчиняти кватирку в теплиці, коли спекотно","cat":"a","explain":"Просте правило, помилка не небезпечна — можна доручити системі.","hint":"просте правило"},{"text":"Перемикати світлофор уночі, коли машин мало","cat":"a","explain":"Нічний режим — передбачувана ситуація для автоматики.","hint":"передбачувана ситуація"},{"text":"Довезти посилку до під'їзду","cat":"b","explain":"Робот везе, а оператор стежить і допомагає в разі чого.","hint":"оператор на зв'язку"},{"text":"Зупинити потяг метро, якщо на колії людина","cat":"b","explain":"Система гальмує миттєво, а люди перевіряють і відповідають за наслідки.","hint":"система гальмує, люди перевіряють"},{"text":"Вирішувати, кого з пацієнтів лікар огляне першим","cat":"c","explain":"Це рішення про здоров'я людей — його ухвалює лікар.","hint":"про життя й здоров'я"},{"text":"Поставити оцінку за твір","cat":"c","explain":"Оцінювання творчості — відповідальність учителя.","hint":"розуміє лише людина"},{"text":"Відчинити й зачинити двері ліфта","cat":"a","explain":"Просте повторюване правило — справляється система.","hint":"просте й повторюване"},{"text":"Обрати ліки для лікування","cat":"c","explain":"Ліки призначає лікар — це відповідальне рішення людини.","hint":"вирішує лікар"}]}},"after":{"index":1,"heading":"⚙️ Що таке керована система"}},{"path":"app/games/М4_Урок28_Гра3_Хто-відповідає.html","title":"Хто відповідає?","description":"сценарний вибір","data":{"id":"m4g28c","lesson":28,"tag":"ВІДПОВ","icon":"👩‍🔧","type":"quiz","title":"Хто відповідає?","file":"М4_Урок28_Гра3_Хто-відповідає.html","conceptName":"відповідальність і безпечний стан","concept":"Робот не відповідає за свої дії так, як людина. Відповідальність несуть люди й організації: інженери, власники, оператори. Добра система в разі збою переходить у безпечний стан — зупиняється й кличе людину.","skill":"пояснювати, хто відповідає за керовані системи і навіщо їм безпечний стан","data":{"questions":[{"q":"Робот-кур'єр наїхав на велосипед. Хто відповідає?","options":["Сам робот","Люди й компанія, що створили й застосовують робота","Ніхто"],"correct":1,"explain":"За системи відповідають люди й організації: ті, хто проєктує, застосовує й контролює.","wrong":"Робот лише виконує програму. Подумай, хто її створив і хто стежить за роботою."},{"q":"Навіщо думати наперед, що зробить система, якщо зламається?","options":["Щоб вона перейшла в безпечний стан","Щоб вона працювала швидше","Це не потрібно"],"correct":0,"explain":"У разі збою система має не зашкодити: зупинитися й покликати людину.","wrong":"Безпечний стан — це, наприклад, зупинка й виклик людини на допомогу."},{"q":"Що з цього може бути введенням керованої системи?","options":["Датчик або кнопка","Лише мотор","Лише екран"],"correct":0,"explain":"Введення — датчик або кнопка. Мотор — виконавчий пристрій на виході.","wrong":"Введення дає дані системі. Мотор і екран — це виведення."},{"q":"Система працює за правилом «якщо тепліше за 28 °C — відчинити». Її слабке місце?","options":["Не впорається з тим, чого правило не передбачило","Вона завжди помиляється","Їй потрібен інтернет"],"correct":0,"explain":"Правило передбачуване, але рідкісна ситуація може його зламати.","wrong":"Правило працює точно, але лише в тому, що передбачили розробники."},{"q":"Система зі штучним інтелектом навчилася на прикладах. Що про неї правда?","options":["Розпізнає складніші ситуації, але може помилитися несподівано","Ніколи не помиляється","Не потребує перевірки людьми"],"correct":0,"explain":"ШІ справляється зі складним, але помиляється несподівано — люди перевіряють обидва види систем.","wrong":"ШІ не ідеальний: він може помилитися, тому люди його перевіряють."},{"q":"Де працюють сервісні роботи?","options":["У доставці, транспорті, лікарнях і небезпечних місцях","Лише на заводах","Лише в іграх"],"correct":0,"explain":"Сервісні роботи допомагають людям поза заводом: посилки, метро, ліки, огляд руїн.","wrong":"Робот на заводі — промисловий. Сервісні допомагають людям у місті, лікарні, на вулиці."}]}},"after":{"index":3,"heading":"⚖️ Користь, ризики й відповідальність"}}],"legacyTitle":"Урок 28. Керовані системи, сервісні роботи та роль людини","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 28</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Керовані системи, сервісні роботи та роль людини</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Control Systems, Service Robots and Human Oversight</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як керована система отримує дані зі світу й діє — і хто відповідає за її роботу?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я описую керовану систему (<b>control system</b>) як введення → опрацювання → виведення.</li>\n      <li style=\"margin:6px 0;\">Я називаю, де працюють сервісні роботи (<b>service robots</b>), і яку користь та ризики вони несуть.</li>\n      <li style=\"margin:6px 0;\">Я пояснюю, які рішення лишаються за людьми.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚙️ Що таке керована система</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Керована система (control system)</b> отримує дані зі світу, опрацьовує їх за програмою і щось робить у відповідь. Введенням (input) може бути датчик — температури, світла, руху — або звичайна кнопка. Виведенням (output) — екран, звук, світло чи рух.</p>\n\n  <p style=\"margin:0 0 12px;\">Деякі виведення керують <b>виконавчими пристроями (actuators)</b> — моторами, клапанами, замками, які змінюють щось у фізичному світі. Тож загальна схема така: введення чи датчик → опрацювання за програмою → виведення, яке інколи рухає виконавчий пристрій.</p>\n\n  <svg viewBox=\"0 0 860 250\" role=\"img\" aria-labelledby=\"g4u28a-t g4u28a-d\" style=\"display:block;width:100%;height:auto;margin:16px 0;\">\n    <title id=\"g4u28a-t\">Керована система розумної теплиці</title>\n    <desc id=\"g4u28a-d\">Введення: датчик вимірює температуру повітря. Опрацювання: програма перевіряє правило «якщо тепліше за 28 градусів — відчинити кватирку». Виведення: мотор відчиняє кватирку. Унизу смуга: люди й організації проєктують систему, налаштовують правило і стежать за її роботою.</desc>\n    <g font-family=\"Arial, sans-serif\" text-anchor=\"middle\">\n      <rect x=\"6\" y=\"20\" width=\"262\" height=\"140\" rx=\"12\" fill=\"#EAF0FC\" stroke=\"#0033A0\" stroke-width=\"2\"></rect>\n      <text x=\"137\" y=\"54\" font-size=\"17\" font-weight=\"700\" fill=\"#0033A0\">INPUT • введення</text>\n      <text x=\"137\" y=\"94\" font-size=\"28\">🌡️</text>\n      <text x=\"137\" y=\"128\" font-size=\"15\" fill=\"#3D4757\">датчик температури</text>\n      <rect x=\"298\" y=\"20\" width=\"262\" height=\"140\" rx=\"12\" fill=\"#0033A0\"></rect>\n      <text x=\"429\" y=\"54\" font-size=\"17\" font-weight=\"700\" fill=\"#FFFFFF\">PROCESS • програма</text>\n      <text x=\"429\" y=\"94\" font-size=\"15\" fill=\"#FFFFFF\">якщо тепліше за 28 °C —</text>\n      <text x=\"429\" y=\"118\" font-size=\"15\" fill=\"#FFD700\">відчинити кватирку</text>\n      <rect x=\"590\" y=\"20\" width=\"264\" height=\"140\" rx=\"12\" fill=\"#E9F4ED\" stroke=\"#1B6B3A\" stroke-width=\"2\"></rect>\n      <text x=\"722\" y=\"54\" font-size=\"17\" font-weight=\"700\" fill=\"#155C32\">OUTPUT • виведення</text>\n      <text x=\"722\" y=\"94\" font-size=\"28\">🪟</text>\n      <text x=\"722\" y=\"128\" font-size=\"15\" fill=\"#3D4757\">мотор відчиняє кватирку</text>\n    </g>\n    <g fill=\"#0033A0\"><polygon points=\"272,84 286,90 272,96\"></polygon><polygon points=\"564,84 578,90 564,96\"></polygon></g>\n    <rect x=\"6\" y=\"180\" width=\"848\" height=\"56\" rx=\"10\" fill=\"#FFF9DB\" stroke=\"#B38600\" stroke-width=\"2\"></rect>\n    <text x=\"430\" y=\"214\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1A1A1A\" font-family=\"Arial, sans-serif\">👩‍🔧 Люди проєктують систему, задають правило і стежать за її роботою</text>\n  </svg>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🤖 Сервісні роботи</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Сервісні роботи (service robots)</b> допомагають людям поза заводом:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">🚚 <b>доставка</b> — роботи-кур'єри везуть посилки тротуаром;</li>\n    <li style=\"margin:8px 0;\">🚆 <b>громадський транспорт</b> — потяги метро без машиніста, розумні світлофори;</li>\n    <li style=\"margin:8px 0;\">🏥 <b>охорона здоров'я</b> — роботи возять ліки між палатами;</li>\n    <li style=\"margin:8px 0;\">☢️ <b>небезпечні місця</b> — роботи оглядають зруйновані будівлі, куди людині йти небезпечно.</li>\n  </ul>\n\n  <figure style=\"margin:18px 0 20px;background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px;\">\n    <img src=\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Robotic_Arm_Polishing_Guitars_at_Martin_Guitar_Factory.jpg?width=800\" alt=\"Жовта роботизована рука тримає корпус гітари біля полірувального круга на фабриці\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;max-height:410px;object-fit:contain;border-radius:8px;\">\n    <figcaption style=\"margin-top:9px;font-size:15px;line-height:1.45;color:#3D4757;\">А це не сервісний, а <b>промисловий робот</b> — теж керована система: роботизована рука на фабриці полірує гітару за програмою, яку задали інженери. Фото: <a href=\"https://commons.wikimedia.org/wiki/File:Robotic_Arm_Polishing_Guitars_at_Martin_Guitar_Factory.jpg\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;\">Henrysz, Wikimedia Commons</a>, CC BY 4.0.</figcaption>\n  </figure>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚖️ Користь, ризики й відповідальність</h2>\n\n  <p style=\"margin:0 0 12px;\">Керовані системи не втомлюються, працюють точно й можуть бути там, де людині небезпечно. Але вони роблять лише те, що передбачили розробники. Датчик може забруднитися, правило — не врахувати рідкісну ситуацію. Тому для кожної системи думають: <b>що вона зробить, якщо щось зламається?</b> Добре, коли вона переходить у безпечний стан — наприклад, робот зупиняється й кличе людину на допомогу.</p>\n\n  <p style=\"margin:0 0 12px;\">Робот не відповідає за свої дії так, як людина. Відповідальність за проєктування, застосування й контроль систем несуть люди й організації: інженери, власники, ті, хто стежить за роботою. Систем, у яких працює штучний інтелект, це теж стосується.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📌 Правило чи штучний інтелект?</h2>\n\n  <p style=\"margin:0 0 12px;\">Одні системи працюють за <b>правилом</b>: «якщо тепліше за 28 °C — відчинити кватирку». Вони передбачувані, але не впораються з тим, чого правило не передбачило. Інші використовують <b>штучний інтелект</b>, що навчився на прикладах: він може розпізнавати складніші ситуації, але інколи помиляється несподівано. В обох випадках люди перевіряють, як працює система, і вирішують, де її можна застосовувати.</p>\n\n  <p style=\"margin:0 0 12px;\">Такі системи створюють <b>інформатики (computer scientists)</b> разом з інженерами, лікарями, транспортниками — усіма, хто знає, як має працювати справжнє місце.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">Розглянь п'ять систем:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>1. Робот-кур'єр</b> везе замовлення тротуаром, бачить перешкоди камерами.</li>\n    <li style=\"margin:8px 0;\"><b>2. Розумний світлофор</b> рахує машини й змінює тривалість зеленого.</li>\n    <li style=\"margin:8px 0;\"><b>3. Лікарняний робот</b> возить ліки між палатами, об'їжджає людей за датчиками відстані.</li>\n    <li style=\"margin:8px 0;\"><b>4. Розумна теплиця</b> вимірює температуру й відчиняє кватирки.</li>\n    <li style=\"margin:8px 0;\"><b>5. Комп'ютерний суперник</b> у шахах аналізує твої ходи й відповідає своїми.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Картка системи.</b> Обери одну систему, крім теплиці, і заповни в зошиті картку:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:420px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Поле</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Моя система</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Введення (input / sensor)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Опрацювання (правило)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Виведення (output)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Користь</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Ризик</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Що робить, якщо зламалася</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Хто з людей відповідає</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Хто вирішує?</b> Розподіли завдання на три групи: <b>А</b> — можна повністю доручити системі; <b>Б</b> — система робить, людина перевіряє; <b>В</b> — вирішує лише людина.</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">відчиняти кватирку в теплиці, коли спекотно;</li>\n    <li style=\"margin:8px 0;\">вирішувати, кого з пацієнтів лікар огляне першим;</li>\n    <li style=\"margin:8px 0;\">довезти посилку до під'їзду;</li>\n    <li style=\"margin:8px 0;\">перемикати світлофор уночі, коли машин мало;</li>\n    <li style=\"margin:8px 0;\">поставити оцінку за твір;</li>\n    <li style=\"margin:8px 0;\">зупинити потяг метро, якщо на колії людина.</li>\n  </ul>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1, приклад для кур'єра.</b> Введення: камери й датчики відстані. Опрацювання: «якщо попереду перешкода — зупинитися». Виведення: мотори коліс. Користь: доставка без водія. Ризик: не помітить дитину чи яму. Якщо зламався — зупиняється і повідомляє оператора. Відповідають компанія-власник і оператори.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 2.</b> А: кватирка, світлофор уночі. Б: посилка до під'їзду, аварійна зупинка потяга (система гальмує, люди перевіряють і відповідають). В: черговість пацієнтів, оцінка за твір. Інші відповіді теж можливі, якщо ти пояснюєш, що станеться в разі помилки.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Заповни картку лише для теплиці, дивлячись на схему: введення, опрацювання, виведення і хто з людей відповідає.</p>\n    <p style=\"margin:10px 0 0;\">Для Кроку 2 розподіли три завдання: кватирку, оцінку за твір і посилку.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо картка правильна, а для одного завдання пояснено роль людини.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\">Порівняй дві версії світлофора: <b>за правилом</b> («зелений — 30 секунд») і <b>з ШІ</b>, що вчиться на камерах. Яка може краще впоратися із заторами? Які нові ризики з'являються в другої — наприклад, помилки розпізнавання чи збирання відео з людьми?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>A control system uses a sensor, a program and an output. People are responsible for it.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u28-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що може бути введенням керованої системи?</label>\n    <select id=\"g4-u28-q1\" name=\"g4-u28-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Лише камера</option>\n      <option>Датчик або кнопка</option>\n      <option>Лише мотор</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Датчик або кнопка. Мотор — це виконавчий пристрій на виході.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u28-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Робот-кур'єр наїхав на велосипед. Хто відповідає?</label>\n    <select id=\"g4-u28-q2\" name=\"g4-u28-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Сам робот</option>\n      <option>Люди й компанія, що створили й застосовують робота</option>\n      <option>Ніхто</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Люди й організації, які проєктують, застосовують і контролюють систему.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u28-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Навіщо думати, що зробить система, коли зламається?</label>\n    <select id=\"g4-u28-q3\" name=\"g4-u28-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб вона перейшла в безпечний стан</option>\n      <option>Щоб вона працювала швидше</option>\n      <option>Це не потрібно</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб навіть у разі збою вона не зашкодила, наприклад зупинилася й покликала людину.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку на прикладі своєї системи. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Система отримує ___, опрацьовує ___ і робить ___. Відповідають за неї ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Моя картка системи заповнена правильно: введення, опрацювання, виведення.</li>\n      <li style=\"margin:8px 0;\">Я називаю користь, ризик і безпечну реакцію на збій.</li>\n      <li style=\"margin:8px 0;\">Я розподіляю завдання за ролями й пояснюю роль людини щонайменше в одному.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> картка теплиці й три розподілені завдання.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> картку системи й розподіл завдань у зошиті.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>control system</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">керована система</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>sensor / actuator</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">датчик / виконавчий пристрій</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>service robot</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">сервісний робот</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>automation</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">автоматизація</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>human oversight</b></td><td style=\"padding:8px 10px;\">нагляд людини</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The greenhouse uses a temperature sensor. A person checks the system.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-2","grade":4,"module":4,"number":2,"title":"micro:bit: входи, виходи і датчики","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок29_Гра1_Введення-виведення-microbit.html","title":"Введення чи виведення?","description":"сортування карток","data":{"id":"m4g29a","lesson":29,"tag":"ПЛАТА","icon":"🔌","type":"sort","title":"Введення чи виведення?","file":"М4_Урок29_Гра1_Введення-виведення-microbit.html","conceptName":"входи й виходи micro:bit","concept":"На micro:bit введення — це кнопки A і B, датчик руху, освітленість і температура. Виведення — екран 5×5 і звук. Контакти внизу плати можуть працювати і як введення, і як виведення.","skill":"розрізняти введення, виведення та подвійну роль контактів micro:bit","data":{"categories":[{"id":"in","label":"📥 Введення","hint":"плата отримує"},{"id":"out","label":"📤 Виведення","hint":"плата показує чи грає"},{"id":"both","label":"🔄 І те, й інше","hint":"залежить від програми"}],"items":[{"text":"Кнопка A","cat":"in","explain":"Кнопки A і B реагують на натискання — це введення.","hint":"натискає людина"},{"text":"Датчик руху (accelerometer)","cat":"in","explain":"Датчик помічає струшування й нахил — введення.","hint":"відчуває рух"},{"text":"Рівень освітленості","cat":"in","explain":"Освітленість — показник, який плата зчитує.","hint":"вимірює світло довкола"},{"text":"Температура біля плати","cat":"in","explain":"Температуру вимірює датчик усередині процесора — це введення.","hint":"показник із датчика"},{"text":"Сенсорний логотип (V2)","cat":"in","explain":"Дотик до логотипа — подія-введення у плати V2.","hint":"реагує на дотик"},{"text":"Мікрофон (V2)","cat":"in","explain":"Мікрофон чує гучність — це введення, є лише у V2.","hint":"чує звук"},{"text":"Екран із 25 світлодіодів (5×5)","cat":"out","explain":"Екран показує іконки, числа, текст — це виведення.","hint":"показує результат"},{"text":"Звук: мелодії й сигнали","cat":"out","explain":"Звук — виведення. На V1 він чутний лише через навушники від контактів.","hint":"плата грає"},{"text":"Золоті контакти (pins) внизу плати","cat":"both","explain":"Контакти під'єднують зовнішні пристрої і можуть бути і входом, і виходом.","hint":"під'єднують пристрої"}]}},"after":{"index":2,"heading":"🧭 Що є введенням, а що виведенням"}},{"path":"app/games/М4_Урок29_Гра2_Кишеньковий-помічник.html","title":"Кишеньковий помічник","description":"сценарний вибір","data":{"id":"m4g29b","lesson":29,"tag":"РЕАКЦІЯ","icon":"🃏","type":"quiz","title":"Кишеньковий помічник","file":"М4_Урок29_Гра2_Кишеньковий-помічник.html","conceptName":"введення, подія, показник, виведення","concept":"Програма чекає на подію: кнопку A натиснуто, плату струснули. Подія запускає блоки, а інколи програма зчитує показник — число від датчика. Результат видно на виході: іконка, число, звук.","skill":"пояснювати ланцюг «введення → подія → блоки → виведення» і тестувати кожне введення окремо","data":{"questions":[{"q":"У програмі: «on button A pressed → show icon ♥». Що тут подія?","options":["Кнопку A натиснуто","Серце на екрані","Кнопка A"],"correct":0,"explain":"Кнопка — це введення, а подія — «кнопку A натиснуто». Серце — виведення.","wrong":"Подія — це те, що сталося, а не сама деталь плати і не результат."},{"q":"Що таке показник (reading)?","options":["Число від датчика, яке програма зчитує","Назва програми","Перша кнопка на платі"],"correct":0,"explain":"Показник — число від датчика, наприклад освітленість від 0 до 255.","wrong":"Показник дає датчик: освітленість, температура."},{"q":"Програма в симуляторі грає звук, а на платі — тиша. Чому це може бути?","options":["Це плата V1 без вбудованого динаміка","Програма зламалася","Кнопка A не працює"],"correct":0,"explain":"Вбудований динамік є лише у V2. На V1 звук чути через навушники, під'єднані до контактів.","wrong":"Перевір, яка версія плати: динамік і мікрофон є лише у V2."},{"q":"Дві кнопки показують однакову іконку. У чому проблема?","options":["Не видно, яке введення спрацювало","Це нормально і зручно","Плата зламалася"],"correct":0,"explain":"Різні введення мають давати помітно різні результати — інакше тест нічого не скаже.","wrong":"Як перевірити кожну кнопку, якщо обидві роблять одне й те саме?"},{"q":"micro:bit показує освітленість числом 200. Що означає це число?","options":["Умовні одиниці від 0 до 255 — більше значить світліше","Температуру в градусах","Кількість кнопок"],"correct":0,"explain":"Освітленість micro:bit — умовні одиниці від 0 до 255, а не люкси.","wrong":"Освітленість має свою шкалу: від 0 до 255."},{"q":"Як правильно тестувати помічника з трьома введеннями?","options":["Кожне введення окремо й записувати «Бачу»","Усі три одразу","Лише на платі, симулятор не потрібен"],"correct":0,"explain":"Тестуємо по одному: A, потім B, потім SHAKE — і заповнюємо таблицю.","wrong":"Якщо натиснути все одразу, не зрозумієш, яке введення спрацювало."}]}},"after":{"index":3,"heading":"⚡ Введення, подія, дані, виведення"}},{"path":"app/games/М4_Урок29_Гра3_Від-кнопки-до-іконки.html","title":"Від кнопки до іконки","description":"послідовність кроків","data":{"id":"m4g29c","lesson":29,"tag":"ПОДІЇ","icon":"⚡","type":"order","title":"Від кнопки до іконки","file":"М4_Урок29_Гра3_Від-кнопки-до-іконки.html","conceptName":"порядок роботи з micro:bit","concept":"Спочатку плануємо й передбачаємо, потім збираємо програму в MakeCode, тестуємо кожне введення в симуляторі й лише тоді завантажуємо на справжню плату кнопкою Download.","skill":"вибудовувати ланцюг події й правильний порядок роботи над програмою","data":{"rounds":[{"title":"Ланцюг програми-помічника","steps":["Введення: кнопка A","Подія: on button A pressed","Блоки програми","Виведення: іконка на екрані 5×5"],"hint":"від деталі плати до результату на екрані","explain":"Кнопка — введення, подія запускає блоки, а результат — виведення на екран."},{"title":"Як працюємо над проєктом","steps":["Сплануй: що очікуєш від кожного введення","Збери програму в MakeCode","Тестуй кожне введення окремо в симуляторі","Завантаж на плату кнопкою Download","Повтори тести на справжній платі"],"hint":"план → симулятор → плата","explain":"Симулятор і плата можуть відрізнятися: на V1, наприклад, немає вбудованого динаміка."}]}},"after":{"index":2,"heading":"🧭 Що є введенням, а що виведенням"}}],"legacyTitle":"Урок 29. micro:bit: входи, виходи і датчики","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 29</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">micro:bit: входи, виходи і датчики</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">micro:bit: Inputs, Outputs and Sensors</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як micro:bit перетворює натискання, рух і світло на видимий результат?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я знаходжу на micro:bit введення (<b>inputs</b>) і виведення (<b>outputs</b>).</li>\n      <li style=\"margin:6px 0;\">Я створюю програму з трьома введеннями й щонайменше двома різними виведеннями.</li>\n      <li style=\"margin:6px 0;\">Я перевіряю кожне введення окремо й записую результат.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔌 Маленький комп'ютер</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>micro:bit</b> — маленький комп'ютер розміром із банківську картку. Його програмують у MakeCode блоками, а потім запускають у <b>симуляторі (simulator)</b> на екрані або на справжній платі.</p>\n\n  <figure style=\"margin:18px 0 20px;background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px;\">\n    <img src=\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Microbit.jpg?width=800\" alt=\"Лицьовий бік плати micro:bit: сітка світлодіодів 5×5, кнопки A і B та золоті контакти\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;max-height:410px;object-fit:contain;border-radius:8px;\">\n    <figcaption style=\"margin-top:9px;font-size:15px;line-height:1.45;color:#3D4757;\">Лицьовий бік micro:bit: екран із 25 світлодіодів (5×5), кнопки A та B, унизу — контакти. Фото: <a href=\"https://commons.wikimedia.org/wiki/File:Microbit.jpg\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;\">Adelaidev2008t, Wikimedia Commons</a>, CC BY-SA 4.0.</figcaption>\n  </figure>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧭 Що є введенням, а що виведенням</h2>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:520px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Частина плати</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що робить</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Роль</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">кнопки A і B</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">реагують на натискання</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">введення</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">датчик руху (accelerometer)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">помічає струшування й нахил</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">введення</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">рівень освітленості</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">показує, наскільки світло довкола</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">введення (показник)</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">температура</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">приблизна температура біля плати</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">введення (показник)</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">екран 5×5 (LED display)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">показує іконки, числа, текст</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">виведення</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">звук</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">мелодії й сигнали</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">виведення</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">контакти (pins)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">під'єднують зовнішні пристрої</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">і введення, і виведення</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Дві цікаві деталі. Освітленість micro:bit вимірює тими самими світлодіодами екрана — окремого датчика світла там немає. А температуру вимірює датчик усередині процесора, тож показник може бути трохи вищим за температуру повітря, коли плата довго працює.</p>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #B38600;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Яка у тебе плата?</b> У школі можуть бути micro:bit V1 або V2. Кнопки A і B, екран 5×5, датчик руху, рівень освітленості й температура є в обох. А <b>сенсорний логотип, мікрофон і вбудований динамік</b> є лише у V2. На V1 звук чути лише через навушники чи динамік, під'єднаний до контактів. Якщо програма використовує ці можливості, перевір, яка плата перед тобою.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚡ Введення, подія, дані, виведення</h2>\n\n  <p style=\"margin:0 0 12px;\">Програма чекає на <b>подію (event)</b>: натиснули кнопку A, струснули плату. Подія запускає блоки. Інколи програма ще й зчитує <b>показник (reading)</b> — число від датчика. Результат видно на виході: іконка, число, звук.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Приклад</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button A pressed</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">show icon ♥</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Тут введення — кнопка A, подія — «кнопку A натиснуто», виведення — серце на екрані.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Два введення показують однакову іконку — не видно, яке спрацювало.</li>\n    <li style=\"margin:8px 0;\">Число з датчика проскакує бігучим рядком надто швидко — додай паузу або покажи коротше значення.</li>\n    <li style=\"margin:8px 0;\">Програма працює в симуляторі, але на платі V1 немає звуку — бо там немає вбудованого динаміка.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🔌 Працюємо в MakeCode для micro:bit: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a>. Програму перевіряй у симуляторі ліворуч, а на станції з платою — кнопкою <b>Download</b> завантаж її на справжній micro:bit.</p>\n\n  <p style=\"margin:0 0 12px;\">Створи «кишенькового помічника», який по-різному реагує на три введення.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Сплануй.</b> Перенеси таблицю в зошит і заповни стовпчик «Очікую»:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:480px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Введення</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Подія</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">кнопка A</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">on button A pressed</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">кнопка B</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">on button B pressed</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">струшування</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">on shake</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Збери.</b> Наприклад:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button A pressed</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">show icon ☺</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button B pressed</div>\n      <div style=\"border-left:6px solid #E63022;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">play tone Middle C for 1 beat</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">show icon ♪</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on shake</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">show number (light level)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Тестуй по одному.</b> У симуляторі натисни A, потім B, потім натисни кнопку SHAKE. Після кожного введення заповни «Бачу». Для освітленості в симуляторі повзунок світла змінюй мишею.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Станція з платою.</b> Коли прийде твоя черга, натисни <b>Download</b> і завантаж програму на справжній micro:bit. Повтори три тести. Чи все працює так само? Запиши відмінності. Збережи проєкт з назвою «Помічник».</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 2–3.</b> A — усмішка, B — короткий звук і нота, струшування — число освітленості (від 0 до 255). Усі три результати різні.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> На V1 звуку не буде без навушників — тому ми додали ще й іконку ♪. Показник світла на справжній платі залежить від лампи в класі.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Зроби два введення: кнопки A і B з різними іконками.</p>\n    <p style=\"margin:10px 0 0;\">Протестуй кожну кнопку окремо й заповни таблицю.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо дві кнопки дають різні результати, а ти пояснюєш, що тут введення, а що виведення.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Поріг.</b> Додай: <i>forever</i> → <i>if (light level) &lt; (50) then show icon ☾ else clear screen</i>. Коли в класі темніє, з'являється місяць. Чому поріг 50 може не підійти в іншому класі?</p>\n    <p style=\"margin:10px 0 0;\">Якщо є V2: зроби реакцію на дотик до логотипа (<i>on logo pressed</i>).</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>Button A is an input. The LED display is an output.</i></p>\n  </details>\n\n  <div style=\"background:#EAF0FC;border-left:5px solid #0033A0;border-radius:10px;padding:16px 18px;margin:22px 0;\">\n    <h2 style=\"margin:0 0 8px;font-size:20px;color:#0033A0;\">🌐 Спробуй інтерактивно</h2>\n    <p style=\"margin:0 0 10px;\"><b>micro:bit для вчителів та учнів</b> — розбір плати, її входів, виходів і датчиків. За бажанням.</p>\n    <p style=\"margin:0 0 10px;font-size:15px;color:#3D4757;\">10–15 хв • потрібен інтернет</p>\n    <a href=\"https://itnauka.org/microbit/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"display:inline-block;background:#0033A0;color:#FFFFFF;text-decoration:none;font-weight:700;padding:10px 14px;border-radius:8px;margin:0 8px 8px 0;\">Розділ micro:bit ↗</a>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u29-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що з цього — виведення micro:bit?</label>\n    <select id=\"g4-u29-q1\" name=\"g4-u29-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Кнопка B</option>\n      <option>Екран зі світлодіодів</option>\n      <option>Датчик руху</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Екран. Кнопка й датчик руху — введення.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u29-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Для чого контакти (pins) внизу плати?</label>\n    <select id=\"g4-u29-q2\" name=\"g4-u29-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Лише для виведення</option>\n      <option>Для під'єднання пристроїв — і на вхід, і на вихід</option>\n      <option>Для зарядки телефона</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Контакти можуть працювати і як введення, і як виведення.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u29-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. На платі не чути звуку, хоча в симуляторі він був. Чому це може бути?</label>\n    <select id=\"g4-u29-q3\" name=\"g4-u29-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Плата V1 без вбудованого динаміка</option>\n      <option>Програма зламалася</option>\n      <option>Кнопка A не працює</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Можливо, це V1: вбудований динамік є лише у V2.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Поясни свою програму. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Введення — ___, подія — ___, дані — ___, а виведення — ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Моя програма має три введення й щонайменше два різні виведення.</li>\n      <li style=\"margin:8px 0;\">Кожне введення перевірено окремо, таблиця заповнена.</li>\n      <li style=\"margin:8px 0;\">Програму перевірено на справжній платі на станції або цю перевірку заплановано з учителем.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> дві кнопки з різними результатами і таблиця.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> проєкт MakeCode (посилання, файл .hex або знімок екрана) і таблицю тестів.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>input / output</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">введення / виведення</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>button</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">кнопка</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>accelerometer</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">датчик руху</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>reading</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">показник</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>LED display</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">світлодіодний екран</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>simulator</b></td><td style=\"padding:8px 10px;\">симулятор</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>When I press button A, the display shows a smile.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-3","grade":4,"module":4,"number":3,"title":"Цикли у фізичних обчисленнях","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок30_Гра1_forever-чи-repeat.html","title":"forever чи repeat?","description":"сортування карток","data":{"id":"m4g30a","lesson":30,"tag":"РЕЖИМ","icon":"🔁","type":"sort","title":"forever чи repeat?","file":"М4_Урок30_Гра1_forever-чи-repeat.html","conceptName":"вибір циклу для пристрою","concept":"Питання просте: чи знаємо ми, скільки разів має відбутися дія? Знаємо — repeat. Дія має тривати, доки працює пристрій, — forever.","skill":"обирати між forever і repeat для задач фізичного пристрою","data":{"categories":[{"id":"f","label":"♾️ forever","hint":"триває весь час"},{"id":"r","label":"🔢 repeat (N)","hint":"кількість відома"}],"items":[{"text":"Весь час показувати температуру","cat":"f","explain":"Стежити треба, доки працює пристрій, — це forever.","hint":"безперервне стеження"},{"text":"Мигнути попередженням рівно 4 рази","cat":"r","explain":"Кількість відома наперед — repeat (4).","hint":"чотири — конкретне число"},{"text":"Стежити за освітленістю в класі","cat":"f","explain":"Моніторинг триває весь час — forever.","hint":"постійне стеження"},{"text":"Прозвучати сигналом тричі при старті","cat":"r","explain":"Тричі — відома кількість, repeat (3).","hint":"три — конкретне число"},{"text":"У грі миттєво реагувати на нахил плати","cat":"f","explain":"Гра триває — нахил перевіряємо безперервно в forever.","hint":"весь час гри"},{"text":"Показати десять блимань при запуску","cat":"r","explain":"Десять — відома кількість, repeat (10).","hint":"десять разів"},{"text":"Оновлювати показник світла щосекунди","cat":"f","explain":"Оновлення триває, доки пристрій увімкнений, — forever.","hint":"постійно"},{"text":"Сигнал тривоги рівно 5 спалахів","cat":"r","explain":"П'ять спалахів — скінченний цикл, repeat (5).","hint":"п'ять — конкретне число"}]}},"after":{"index":1,"heading":"🔁 Два цикли — дві задачі"}},{"path":"app/games/М4_Урок30_Гра2_Пауза-й-частота.html","title":"Пауза й частота","description":"сценарний вибір","data":{"id":"m4g30b","lesson":30,"tag":"ПАУЗА","icon":"⏱️","type":"quiz","title":"Пауза й частота","file":"М4_Урок30_Гра2_Пауза-й-частота.html","conceptName":"блок pause і безпечні налаштування","concept":"Пауза в мілісекундах (1000 мс = 1 секунда) визначає, як часто пристрій оновлює результат. Паузу обирають за задачею. Безпека: між спалахами — щонайменше 300 мс, звук — тихий і короткий, не в нескінченному циклі.","skill":"обирати паузу за задачею й дотримуватися безпечних налаштувань","data":{"questions":[{"q":"Скільки це — 1000 мс?","options":["1 секунда","10 секунд","1 хвилина"],"correct":0,"explain":"1000 мілісекунд — це одна секунда.","wrong":"«Мілі» означає тисячна частка: 1000 мс = 1 с."},{"q":"У моніторі температури паузу змінили з 1000 на 3000 мс. Що станеться?","options":["Число оновлюватиметься рідше — раз на три секунди","Число зникне зовсім","Плата вимкнеться"],"correct":0,"explain":"Довша пауза — рідші оновлення, зате число встигаєш прочитати.","wrong":"Пауза — це проміжок між оновленнями. Більша пауза — рідше оновлюється."},{"q":"Для гри, де треба миттєво реагувати на нахил, яка пауза краща?","options":["Коротша","Довша","Пауза не має значення"],"correct":0,"explain":"Коротша пауза — пристрій швидше помічає зміни. Паузу обирають за задачею.","wrong":"Подумай, що важливіше для гри: читабельність числа чи швидка реакція?"},{"q":"Яка мінімальна пауза між спалахами на екрані?","options":["300 мс","10 мс","Пауза не потрібна"],"correct":0,"explain":"Щонайменше 300 мс: швидке миготіння неприємне, а для деяких людей шкідливе.","wrong":"Згідно з правилом безпеки — щонайменше 300 мілісекунд."},{"q":"Сигнал мав мигнути 4 рази, а мигає без кінця. Що найімовірніше не так?","options":["Стоїть forever замість repeat (4)","Забагато пауз","Не та іконка"],"correct":0,"explain":"forever не закінчується ніколи. Сигнал із відомою кількістю — це repeat.","wrong":"Кількість відома (4), отже потрібен цикл із лічильником, а не безкінечний."},{"q":"Число на екрані змінюється так швидко, що його не прочитати. Що додати?","options":["Паузу в циклі","Ще один цикл forever","Більше чисел"],"correct":0,"explain":"Пауза дає очам час прочитати показник.","wrong":"Проблема в швидкості оновлення — її сповільнює пауза."}]}},"after":{"index":2,"heading":"⏱ Пауза й частота оновлення"}},{"path":"app/games/М4_Урок30_Гра3_Сигнал-і-монітор.html","title":"Збери сигнал і монітор","description":"послідовність кроків","data":{"id":"m4g30c","lesson":30,"tag":"СПАЛАХ","icon":"🚨","type":"order","title":"Збери сигнал і монітор","file":"М4_Урок30_Гра3_Сигнал-і-монітор.html","conceptName":"два режими «Кліматичного патруля»","concept":"У пристрої може бути кілька скриптів: forever-монітор стежить за датчиком увесь час, а repeat-сигнал подає точну кількість спалахів за подією.","skill":"збирати forever-монітор і repeat-сигнал у правильному порядку блоків","data":{"rounds":[{"title":"Режим Б — сигнал за кнопкою A","steps":["on button A pressed","repeat (4) times","show icon ⚠","pause (ms) (300)","clear screen","pause (ms) (300)"],"hint":"подія → цикл → спалах → пауза → очистити → пауза","explain":"Чотири повторення: іконка, пауза, очистити, пауза. Паузи по 300 мс — безпечне миготіння."},{"title":"Режим А — монітор температури","steps":["forever","show number (temperature)","pause (ms) (1000)"],"hint":"стежимо весь час, раз на секунду","explain":"Температура змінюється повільно, тож оновлення раз на секунду цілком достатньо."}]}},"after":{"index":1,"heading":"🔁 Два цикли — дві задачі"}}],"legacyTitle":"Урок 30. Цикли у фізичних обчисленнях","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 30</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Цикли у фізичних обчисленнях</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Loops in Physical Computing</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: коли пристрою потрібен цикл «завжди», а коли — «повторити N разів»?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я обираю для фізичного завдання цикл <b>forever</b> або <b>repeat</b> і пояснюю вибір.</li>\n      <li style=\"margin:6px 0;\">Я створюю дві робочі програми: з безперервним і зі скінченним циклом.</li>\n      <li style=\"margin:6px 0;\">Я виправляю цикл, що поводиться не так, і перевіряю його знову.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔁 Два цикли — дві задачі</h2>\n\n  <p style=\"margin:0 0 12px;\">На micro:bit ті самі цикли, що й у Scratch, мають англійські назви:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>forever</b> — повторює тіло, доки плата працює. Підходить, щоб <b>безперервно (continuous)</b> стежити за датчиком чи оновлювати екран.</li>\n    <li style=\"margin:8px 0;\"><b>repeat (N) times</b> — цикл із лічильником: <b>скінченний (finite)</b>, закінчується після N повторень. Підходить для сигналу, який має прозвучати чи мигнути певну кількість разів.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Питання для вибору просте: <i>чи знаємо ми, скільки разів має відбутися дія?</i> Знаємо — repeat. Дія має тривати весь час — forever.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⏱ Пауза й частота оновлення</h2>\n\n  <p style=\"margin:0 0 12px;\">У циклі часто ставлять блок <b>pause (ms)</b> — паузу в мілісекундах (1000 мс = 1 секунда). Він визначає, як часто пристрій оновлює результат:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>коротша пауза</b> — показник оновлюється частіше, пристрій швидше реагує на зміни (responsive);</li>\n    <li style=\"margin:8px 0;\"><b>довша пауза</b> — оновлюється рідше, зате число встигаєш прочитати.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Для термометра в класі температура змінюється повільно, тож оновлення раз на секунду — цілком достатньо. Для гри, де треба миттєво реагувати на нахил, пауза має бути коротшою. Тож паузу обирають за задачею.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔆 Безпечні налаштування</h2>\n\n  <p style=\"margin:0 0 12px;\">Пристроєм користуються люди поруч, тож налаштовуй його дбайливо. Між спалахами — щонайменше 300 мс: швидке миготіння неприємне, а для деяких людей і шкідливе. Звук — тихий і короткий, не в нескінченному циклі. Сигнал має привертати увагу, а не заважати всьому класу.</p>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #B38600;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Яка у тебе плата?</b> У школі можуть бути micro:bit V1 або V2. Кнопки A і B, екран 5×5, датчик руху, рівень освітленості й температура є в обох. А <b>сенсорний логотип, мікрофон і вбудований динамік</b> є лише у V2. На V1 звук чути лише через навушники чи динамік, під'єднаний до контактів. Якщо програма використовує ці можливості, перевір, яка плата перед тобою.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Сигнал тривоги поклали в forever — він не закінчується ніколи, хоча мав прозвучати 4 рази.</li>\n    <li style=\"margin:8px 0;\">Показ числа без паузи — цифри змінюються так швидко, що їх важко прочитати.</li>\n    <li style=\"margin:8px 0;\">Блимання без пауз між «показати» і «очистити» — екран миготить надто часто; тримай паузи від 300 мс.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🔌 Працюємо в MakeCode для micro:bit: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a>. Програму перевіряй у симуляторі ліворуч, а на станції з платою — кнопкою <b>Download</b> завантаж її на справжній micro:bit.</p>\n\n  <p style=\"margin:0 0 12px;\">Пристрій «Кліматичний патруль» має два режими.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Обери цикл.</b> Для кожної задачі запиши в зошит: forever чи repeat — і чому. <b>А:</b> весь час показувати температуру. <b>Б:</b> коли натиснуто кнопку A, мигнути попередженням рівно 4 рази.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Збери два скрипти.</b> Передбач, як поводитиметься кожен, і збери:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Режим А — монітор</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #00AA00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">forever</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">show number (temperature (°C))</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">pause (ms) (1000)</div>\n    </div>\n  </div>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Режим Б — сигнал</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button A pressed</div>\n      <div style=\"border-left:6px solid #00AA00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">repeat (4) times</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">show icon ⚠</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">pause (ms) (300)</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">clear screen</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">pause (ms) (300)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Виправ цикл.</b> Однокласник зробив сигнал так — і попередження не зупиняється:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button B pressed</div>\n      <div style=\"border-left:6px solid #00AA00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">forever</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">show icon ⚠</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">pause (ms) (300)</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">clear screen</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">pause (ms) (300)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Спершу запиши, що очікуєш, потім запусти в симуляторі. Знайди причину, виправ і перевір знову.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Тестуй.</b> Заповни таблицю для обох режимів:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:540px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Режим</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що роблю</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пройдено?</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">А</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">змінюю температуру повзунком</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Б</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">натискаю A</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Б (виправлений)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">натискаю B</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Якщо є плата, завантаж програму й перевір на ній. Збережи проєкт.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> А — forever: стежити треба весь час. Б — repeat (4): кількість відома наперед.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> У коді кнопки B стоїть forever замість repeat (4), тому сигнал ніколи не закінчується. Виправлення: замінити на repeat (4) times.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 4.</b> А: число змінюється разом із повзунком (раз на секунду). Б: чотири мигання, потім екран порожній — і знову показ температури.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Збери лише режим Б — сигнал із repeat (4) times — і порахуй мигання.</p>\n    <p style=\"margin:10px 0 0;\">Потім зміни 4 на 2 і перевір.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо сигнал мигає рівно стільки разів, скільки вказано, а ти пояснюєш, чому тут repeat.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Дослідження паузи.</b> Спробуй у режимі А паузи 200, 1000 і 3000 мс. Коли число найлегше читати? Коли пристрій найшвидше помічає зміну? Запиши, яку паузу обираєш і чому.</p>\n    <p style=\"margin:10px 0 0;\">Чи впливає пауза на заряд батареї? Це залежить від програми й самої плати: екран і звук витрачають енергію, а часті обчислення — теж. Спробуй з'ясувати в документації micro:bit разом із дорослим.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The forever loop monitors the sensor. The repeat loop plays a finite signal.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u30-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Який цикл обрати, щоб весь час показувати освітленість?</label>\n    <select id=\"g4-u30-q1\" name=\"g4-u30-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>repeat (4) times</option>\n      <option>forever</option>\n      <option>Жодного</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">forever: стежити треба, доки працює пристрій.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u30-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Що зміниться, якщо паузу в моніторі збільшити з 1000 до 3000 мс?</label>\n    <select id=\"g4-u30-q2\" name=\"g4-u30-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Число оновлюватиметься рідше</option>\n      <option>Число зникне</option>\n      <option>Плата вимкнеться</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Число оновлюватиметься рідше — раз на три секунди.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u30-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Сигнал мав мигнути 4 рази, а мигає без кінця. Що найімовірніше не так?</label>\n    <select id=\"g4-u30-q3\" name=\"g4-u30-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Стоїть forever замість repeat</option>\n      <option>Забагато пауз</option>\n      <option>Не та іконка</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Замість repeat (4) стоїть forever.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Для ___ я обираю forever, бо ___. Для ___ — repeat, бо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Обидва мої режими працюють: forever-монітор і repeat-сигнал.</li>\n      <li style=\"margin:8px 0;\">Вибір циклу для кожної задачі пояснено в зошиті.</li>\n      <li style=\"margin:8px 0;\">Зламаний цикл виправлено, і таблиця тестів заповнена.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> сигнал із repeat і пояснення вибору.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> проєкт MakeCode (посилання, .hex або знімок екрана) і таблицю тестів.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>forever loop</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">цикл «завжди»</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>count-controlled loop</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">цикл із лічильником</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>monitor</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">стежити</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>signal</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">сигнал</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>finite / continuous</b></td><td style=\"padding:8px 10px;\">скінченний / безперервний</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I chose a forever loop to monitor the temperature.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-4","grade":4,"module":4,"number":4,"title":"Збирання й інтерпретація даних датчика","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок31_Гра1_Чесні-дані.html","title":"Чесні дані","description":"сценарний вибір","data":{"id":"m4g31a","lesson":31,"tag":"ЗАМІР","icon":"📏","type":"quiz","title":"Чесні дані","file":"М4_Урок31_Гра1_Чесні-дані.html","conceptName":"показник з контекстом","concept":"Число з датчика стає доказом, лише коли поруч одиниці, час і умови. Два заміри в тому самому місці можуть трохи відрізнятися — це звичайно. Один замір може бути випадковим, тому роблять щонайменше п'ять.","skill":"оцінювати, чи дані датчика записано чесно: з одиницями, часом, умовами й повторними замірами","data":{"questions":[{"q":"У таблиці записано просто «180». Що з цим записом не так?","options":["Невідомо одиниці, час і місце заміру","Нічого, числа достатньо","Число завелике"],"correct":0,"explain":"Без одиниць, часу й умов число не стає доказом.","wrong":"Чи можеш ти сказати за цим числом, де, коли й в яких одиницях його виміряли?"},{"q":"Два заміри поспіль в одному місці: 120 і 124. Що це найімовірніше?","options":["Звичайна невелика різниця між замірами","Датчик зламаний","Помилка програми"],"correct":0,"explain":"Будь-яке вимірювання має обмежену точність — невелика різниця звичайна.","wrong":"Чи велика різниця між 120 і 124? Світло справді може трохи змінюватися."},{"q":"Чому роблять щонайменше п'ять замірів?","options":["Один замір може бути випадковим","Так вимагає плата","Щоб таблиця була довшою"],"correct":0,"explain":"Кілька замірів показують закономірність, а повторні — наскільки числам можна довіряти.","wrong":"Подумай: чи можна довіряти одному-єдиному числу?"},{"q":"Який висновок обережний?","options":["«Сьогодні о 10:00 біля вікна показник був найвищим»","«Біля вікна завжди найсвітліше»","«Датчики взагалі не працюють»"],"correct":0,"explain":"Обережний висновок каже лише те, що показують дані: де, коли, скільки.","wrong":"Ми міряли один раз одного дня — чи можна казати «завжди»?"},{"q":"Перший показник одразу після запуску програми виявився дивним. Що зробити?","options":["Зробити пробний замір і не записувати його","Записати його як є","Перевернути плату"],"correct":0,"explain":"Датчику світла треба мить, щоб почати міряти, тому перший замір — пробний.","wrong":"Датчику потрібна мить, щоб «розпочати роботу». Перший замір — тренувальний."},{"q":"Один замір не вдався: хтось закрив плату рюкзаком. Як записати?","options":["Записати пропуск і пояснити","Вигадати схоже число","Просто пропустити рядок"],"correct":0,"explain":"Пропуски записують чесно — вигадані числа псують усе дослідження.","wrong":"Чесні дані: якщо замір не вдався, так і пишемо, а не вигадуємо."}]}},"after":{"index":1,"heading":"📏 Показник — це не вся правда"}},{"path":"app/games/М4_Урок31_Гра2_Від-заміру-до-висновку.html","title":"Від заміру до висновку","description":"послідовність кроків","data":{"id":"m4g31b","lesson":31,"tag":"ВИСНОВОК","icon":"📊","type":"order","title":"Від заміру до висновку","file":"М4_Урок31_Гра2_Від-заміру-до-висновку.html","conceptName":"шлях даних: таблиця → діаграма → висновок","concept":"Таблицю легко записати, діаграму легко прочитати. Діаграма показує «де більше», а пояснення «чому» шукай в умовах. Висновок говорить лише те, що показали дані, й називає обмеження.","skill":"вибудовувати дослідження: пробний замір, серія замірів, діаграма, обережний висновок","data":{"rounds":[{"title":"Досліджуємо освітленість у класі","steps":["Збери програму-вимірювач","Зроби пробний замір (не записуй його)","Зроби щонайменше 5 замірів у різних місцях","Побудуй діаграму з підписаними осями","Запиши обережний висновок і обмеження"],"hint":"пробний замір не потрапляє в таблицю","explain":"Спочатку датчик «розігрівається», потім чесні заміри, діаграма і висновок саме за цими даними."},{"title":"Як читати діаграму","steps":["Прочитай підписи осей","Знайди найвищий і найнижчий стовпчик","Порівняй їх з умовами в таблиці","Сформулюй, де показник більший","«Чому» пояснюй через умови, не вигадуй"],"hint":"спершу осі, потім стовпчики","explain":"Діаграма показує «де більше», а «чому» ховається в умовах: місце, час, лампа, сонце."}]}},"after":{"index":3,"heading":"📊 Від таблиці до діаграми"}}],"legacyTitle":"Урок 31. Збирання й інтерпретація даних датчика","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 31</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Збирання й інтерпретація даних датчика</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Collecting and Interpreting Sensor Data</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: що можуть — і чого не можуть — сказати нам числа з датчика?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я збираю в таблицю щонайменше 5 показників датчика з одиницями, часом і умовами.</li>\n      <li style=\"margin:6px 0;\">Я будую просту діаграму (<b>chart</b>) за своїми даними.</li>\n      <li style=\"margin:6px 0;\">Я роблю обережний висновок і називаю обмеження (<b>limitation</b>).</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📏 Показник — це не вся правда</h2>\n\n  <p style=\"margin:0 0 12px;\">Датчик дає число — <b>показник (reading)</b>. Але саме число мало що каже. Щоб воно стало доказом, потрібні:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>одиниці (unit):</b> градуси, відсотки чи умовні одиниці. Освітленість micro:bit — від 0 до 255, це умовні одиниці, а не люкси;</li>\n    <li style=\"margin:8px 0;\"><b>час:</b> коли зроблено замір;</li>\n    <li style=\"margin:8px 0;\"><b>умови:</b> де стояла плата, чи горіла лампа, чи падало сонце.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Будь-яке вимірювання має обмежену точність. Два заміри в тому самому місці можуть трохи відрізнятися. Це не обов'язково помилка: світло справді може змінюватися — пройшла хмара, хтось затулив плату рукою.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔍 Як відрізнити зміну від випадковості</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Зроби <b>кілька замірів</b> в одних умовах: якщо числа близькі, їм можна більше довіряти.</li>\n    <li style=\"margin:8px 0;\">Роби заміри через <b>рівні проміжки (interval)</b>, щоб їх можна було порівнювати.</li>\n    <li style=\"margin:8px 0;\">Записуй <b>пропуски</b>: якщо замір не вдався, так і напиши, а не вигадуй число.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\"><b>Чому щонайменше п'ять замірів?</b> Один замір може виявитися випадковим. Кілька замірів у різних умовах показують закономірність, а повторні заміри в тих самих умовах — наскільки числам можна довіряти.</p>\n\n  <p style=\"margin:0 0 12px;\">Коли змінюються умови й показник змінюється помітно більше, ніж між повторними замірами, — це вже справжня <b>зміна (variation)</b>.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📊 Від таблиці до діаграми</h2>\n\n  <p style=\"margin:0 0 12px;\">Таблицю легко записати, а діаграму легко прочитати. Стовпчикова діаграма показує, де показник більший, одним поглядом. Підпиши осі: знизу — місце чи час, збоку — показник і одиниці.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Як читати діаграму:</b> спершу прочитай підписи осей, потім знайди найвищий і найнижчий стовпчик, а тоді порівняй їх із умовами в таблиці. Діаграма показує «де більше», а пояснення «чому» шукай в умовах.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Приклад.</b> Дві пари поміряли біля вікна й отримали 180 і 150. Хто помилився? Можливо, ніхто: пари міряли в різний час, одна затулила плату рукою, або плати стояли під різним кутом до світла. Тому умови записують так само ретельно, як і число.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Обережний висновок</b> говорить лише те, що показують дані: «Біля вікна о 10:00 показник був найвищим — 210». Не «біля вікна завжди найсвітліше»: ми міряли один раз одного дня.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Число без одиниць і умов — ніхто не знає, що воно означає.</li>\n    <li style=\"margin:8px 0;\">Висновок ширший за дані: один день замірів — не «завжди».</li>\n    <li style=\"margin:8px 0;\">Перший показник одразу після запуску програми неточний: датчику світла треба мить, щоб почати міряти. Зроби пробний замір і не записуй його.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🔌 Працюємо в MakeCode для micro:bit: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a>. Програму перевіряй у симуляторі ліворуч, а на станції з платою — кнопкою <b>Download</b> завантаж її на справжній micro:bit.</p>\n\n  <p style=\"margin:0 0 12px;\">Дослідіть освітленість у різних місцях класу.</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <p style=\"margin:0 0 8px;font-weight:700;\">Програма-вимірювач</p>\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button A pressed</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">show number (light level)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Збери програму.</b> Збери вимірювач і зроби один пробний замір.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Збери дані.</b> Зроби щонайменше 5 замірів у різних місцях: біля вікна, на парті, під партою, біля лампи, у шафі. У кожному місці — по два заміри поспіль. У симуляторі змінюй світло повзунком і записуй, яку умову імітуєш.</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:560px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">№</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Місце / умова</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Час</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Замір 1</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Замір 2</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Одиниці</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">1</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">біля вікна</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">умовні, 0–255</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">2</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">…</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Діаграма.</b> Побудуй стовпчикову діаграму: місця внизу, показник збоку. На папері в клітинку або в електронній таблиці.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Висновок.</b> Запиши один обережний висновок і одне обмеження ваших даних.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити: зразок висновку</summary>\n    <p style=\"margin:10px 0 0;\"><b>Висновок:</b> «Найвищий показник — біля вікна (205 і 210), найнижчий — у шафі (12 і 15). Повторні заміри в кожному місці майже однакові».</p>\n    <p style=\"margin:10px 0 0;\"><b>Обмеження:</b> «Ми міряли один раз, у сонячний день; у хмарний день числа можуть бути іншими. Одиниці умовні, тож порівнювати з іншими приладами не можна».</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Зроби 5 замірів у трьох місцях — по одному в двох і три в одному.</p>\n    <p style=\"margin:10px 0 0;\">Діаграму можна замінити підкресленням у таблиці: найбільше число — зеленим, найменше — червоним.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо є 5 показників з умовами й один висновок.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Звірка з еталоном (calibration).</b> Якщо в школі є люксметр чи застосунок-вимірювач, поміряйте ним у тих самих місцях. Чи зростають обидва показники разом? Наскільки вони близькі?</p>\n    <p style=\"margin:10px 0 0;\"><b>Інтервал.</b> Автоматизуй заміри: <i>forever</i> → <i>show number (light level)</i> → <i>pause (ms) (5000)</i>. Спостерігай хвилину біля вікна. Що змінюється, якщо паузу скоротити?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>Every reading needs a unit and a context.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u31-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Показник «180» без жодних підписів. Що з ним не так?</label>\n    <select id=\"g4-u31-q1\" name=\"g4-u31-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Нічого</option>\n      <option>Невідомо, які одиниці, коли й де його виміряли</option>\n      <option>Він завеликий</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Без одиниць і умов число не стає доказом.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u31-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Два заміри поспіль: 120 і 124. Що це найімовірніше?</label>\n    <select id=\"g4-u31-q2\" name=\"g4-u31-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Датчик зламаний</option>\n      <option>Звичайна невелика різниця між замірами</option>\n      <option>Помилка програми</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Невелика різниця — звичайна для вимірювань.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u31-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Який висновок обережний?</label>\n    <select id=\"g4-u31-q3\" name=\"g4-u31-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>«Біля вікна завжди найсвітліше»</option>\n      <option>«Сьогодні о 10:00 біля вікна показник був найвищим»</option>\n      <option>«Датчики не працюють»</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Другий: він каже лише те, що показують наші дані.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Мої дані показують, що ___. Але вони не можуть сказати ___, бо ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">У моїй таблиці щонайменше 5 показників з одиницями, часом і умовами.</li>\n      <li style=\"margin:8px 0;\">Моя діаграма підписана й відповідає таблиці.</li>\n      <li style=\"margin:8px 0;\">Я записую обережний висновок і одне обмеження.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> 5 показників з умовами й один висновок.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> таблицю, діаграму і висновок; проєкт-вимірювач (знімок екрана).</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>sensor reading</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">показник датчика</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>unit</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">одиниця виміру</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>interval</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">проміжок між замірами</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>variation</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">зміна показників</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>chart</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">діаграма</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>limitation</b></td><td style=\"padding:8px 10px;\">обмеження</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>The reading near the window was the highest today.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-5","grade":4,"module":4,"number":5,"title":"Людиноцентричний дизайн, доступність і потреба спільноти","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок32_Гра1_Критерій-чи-обмеження.html","title":"Критерій чи обмеження?","description":"сортування карток","data":{"id":"m4g32a","lesson":32,"tag":"КРИТЕРІЙ","icon":"📐","type":"sort","title":"Критерій чи обмеження?","file":"М4_Урок32_Гра1_Критерій-чи-обмеження.html","conceptName":"критерії й обмеження","concept":"Критерій успіху — вимірна вимога, яку можна перевірити: «сигнал видно з 2 метрів». Обмеження — те, чого робити не можна: «без камери», «не збирає особистих даних».","skill":"відрізняти вимірні критерії успіху від обмежень проєкту","data":{"categories":[{"id":"crit","label":"✅ Критерій успіху","hint":"можна перевірити: вийшло чи ні"},{"id":"lim","label":"⛔ Обмеження","hint":"чого робити не можна"}],"items":[{"text":"Сигнал видно з відстані 2 метри","cat":"crit","explain":"Це можна перевірити лінійкою — вимірний критерій.","hint":"є число для перевірки"},{"text":"Без камери","cat":"lim","explain":"Це заборона — обмеження проєкту.","hint":"чого не можна"},{"text":"Вмикається однією кнопкою","cat":"crit","explain":"Чітка дія, яку можна перевірити, — критерій.","hint":"можна перевірити"},{"text":"Не збирає імен чи особистих даних","cat":"lim","explain":"Захист приватності — обмеження.","hint":"заборона"},{"text":"Сигнал з'являється за 1 секунду після натискання","cat":"crit","explain":"Є час для перевірки — вимірний критерій.","hint":"є число"},{"text":"Працює без телефона","cat":"lim","explain":"Це умова-обмеження, а не перевірка успіху.","hint":"умова, не перевірка"},{"text":"Звук — не довше 1 секунди","cat":"crit","explain":"Тривалість можна виміряти — критерій.","hint":"можна виміряти"},{"text":"Без мікрофонних записів","cat":"lim","explain":"Заборона на запис — обмеження.","hint":"чого не можна"}]}},"after":{"index":4,"heading":"📐 Критерії та обмеження"}},{"path":"app/games/М4_Урок32_Гра2_Спершу-людина.html","title":"Спершу людина","description":"сценарний вибір","data":{"id":"m4g32b","lesson":32,"tag":"ПОТРЕБА","icon":"👤","type":"quiz","title":"Спершу людина","file":"М4_Урок32_Гра2_Спершу-людина.html","conceptName":"людиноцентричний дизайн","concept":"Добрий проєкт починається з питання: хто користувач і що йому потрібно? Інструмент обирають потім — і інколи найкраще рішення зовсім без комп'ютера. ШІ доречний, лише коли дає справжню користь.","skill":"починати проєкт із користувача та потреби й оцінювати рішення за критеріями й обмеженнями","data":{"questions":[{"q":"З чого починається людиноцентричний дизайн?","options":["З користувача та його потреби","З вибору плати","З кольору корпусу"],"correct":0,"explain":"Спершу людина й потреба, інструмент — потім.","wrong":"Якщо почати з технології, можна зробити те, що нікому не потрібно."},{"q":"Який критерій вимірний?","options":["«Сигнал видно з відстані 2 метри»","«Пристрій гарний»","«Усім сподобається»"],"correct":0,"explain":"«Видно з 2 метрів» можна перевірити. «Гарний» — це смак, а не критерій.","wrong":"Вимірний критерій містить число або чітку дію, яку можна перевірити."},{"q":"Чому ШІ-камера, що постійно знімає Оленку, — невдале рішення?","options":["Вона збирає зайві особисті дані, а просте рішення працює без неї","Бо ШІ завжди поганий","Бо камери важкі"],"correct":0,"explain":"ШІ доречний, лише коли дає користь, якої не дають простіші способи.","wrong":"Постав чотири питання: приватність, надійність, потреба, вибір людини."},{"q":"Чому в сигнальному пристрої поєднують світло і вібрацію чи звук?","options":["Щоб рішення не залежало від одного відчуття — це доступність","Щоб було голосніше","Щоб витратити більше батареї"],"correct":0,"explain":"Хтось погано чує, хтось погано бачить — кілька способів сигналу охоплюють більше людей.","wrong":"Згадай Оленку: вона не почує звук. Їй потрібен інший спосіб сигналу."},{"q":"Навіщо потрібен паперовий прототип?","options":["Показати задум і зібрати відгук ще до програмування","Замінити робочий пристрій назавжди","Для оцінки за малювання"],"correct":0,"explain":"Відгук на паперовий прототип допомагає виправити задум рано, до коду.","wrong":"Прототип — це перша версія для перевірки, а не фінальний виріб."},{"q":"Тактильна плитка й біла тростина — приклад чого?","options":["Рішення, народженого з потреби людей, — і жодної електроніки","Невдалого дизайну","Штучного інтелекту"],"correct":0,"explain":"Найкраще рішення інколи зовсім не цифрове — головне, щоб воно відповідало потребі.","wrong":"Ці речі працюють десятиліттями й не потребують батарейок. Це дизайн від потреби."}]}},"after":{"index":1,"heading":"👤 Спершу людина"}},{"path":"app/games/М4_Урок32_Гра3_Від-потреби-до-прототипу.html","title":"Від потреби до прототипу","description":"послідовність кроків","data":{"id":"m4g32c","lesson":32,"tag":"ОЛЕНКА","icon":"📝","type":"order","title":"Від потреби до прототипу","file":"М4_Урок32_Гра3_Від-потреби-до-прототипу.html","conceptName":"шлях проєкту для користувача","concept":"Проєкт для людини будуємо поетапно: дізналися про потребу → записали критерії й обмеження → порівняли цифрове, нецифрове й ШІ-рішення → намалювали прототип → зібрали відгук.","skill":"вибудовувати проєкт від потреби користувача до паперового прототипу з відгуком","data":{"rounds":[{"title":"Проєкт для Оленки (вигаданий персонаж)","steps":["Уважно прочитай опис користувача","Запиши потребу: «Користувач — …, потреба — …»","Сформулюй три вимірні критерії й обмеження","Порівняй цифрове, нецифрове й ШІ-рішення","Намалюй паперовий прототип обраного","Покажи партнерові й запиши відгук"],"hint":"спершу хто і що потрібно, наприкінці — відгук","explain":"Кожен крок спирається на попередній: без потреби немає критеріїв, без критеріїв — чесного вибору."},{"title":"Питання користувачеві","steps":["Що тобі зараз важко?","Коли саме це трапляється?","Що вже пробували? Що допомогло?","Чого ти точно НЕ хочеш?"],"hint":"останнє питання — про межі та приватність","explain":"Відповіді стають потребою, критеріями та обмеженнями — основою всього проєкту."}]}},"after":{"index":6,"heading":"📝 Паперовий прототип"}}],"legacyTitle":"Урок 32. Людиноцентричний дизайн, доступність і потреба спільноти","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 32</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Людиноцентричний дизайн, доступність і потреба спільноти</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Human-Centred Design, Accessibility and a Community Need</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: чому проєкт починають із людини та її потреби, а не з вибору технології?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я формулюю потребу користувача (<b>user need</b>) і три вимірні критерії успіху.</li>\n      <li style=\"margin:6px 0;\">Я порівнюю цифрове, нецифрове і ШІ-рішення та обираю найдоречніше.</li>\n      <li style=\"margin:6px 0;\">Я роблю паперовий прототип і отримую відгук.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">👤 Спершу людина</h2>\n\n  <p style=\"margin:0 0 12px;\">Легко почати з думки «зроблю щось на micro:bit!». Але добрий проєкт починається з питання: <b>хто користувач (user) і що йому потрібно?</b> Лише потім обирають інструмент — і інколи найкращим виявляється зовсім не комп'ютер.</p>\n\n  <figure style=\"margin:18px 0 20px;background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px;\">\n    <img src=\"https://commons.wikimedia.org/wiki/Special:Redirect/file/Tactile_Paving_colours_and_Materials.jpg?width=800\" alt=\"Зразки тактильної тротуарної плитки різних кольорів і фактур поруч із білою тростиною\" loading=\"lazy\" style=\"display:block;width:100%;height:auto;max-height:410px;object-fit:contain;border-radius:8px;\">\n    <figcaption style=\"margin-top:9px;font-size:15px;line-height:1.45;color:#3D4757;\">Тактильна плитка й біла тростина: рішення, яке народилося з потреби людей, що погано бачать. Ніякої електроніки — і воно працює. Фото: <a href=\"https://commons.wikimedia.org/wiki/File:Tactile_Paving_colours_and_Materials.jpg\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;\">KavehN, Wikimedia Commons</a>, CC BY-SA 4.0.</figcaption>\n  </figure>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">♿ Доступність</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Доступність (accessibility)</b> означає, що рішенням можуть користуватися якомога більше людей із різними потребами: хтось погано чує, хтось погано бачить, комусь важко натискати дрібні кнопки. Часто допомагає кілька способів сигналу одночасно — світло і вібрація, іконка і звук. Так рішення не залежить від одного відчуття.</p>\n\n  <p style=\"margin:0 0 12px;\">Людиноцентричний дизайн поруч із нами: субтитри у відео, пандуси біля входу, великі кнопки в ліфті з позначками для пальців. Кожне з цих рішень придумали, розпитавши людей про їхні труднощі.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">💬 Як розпитати користувача</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Що тобі зараз важко? Коли саме це трапляється?</li>\n    <li style=\"margin:8px 0;\">Що вже пробували робити, щоб стало легше? Що з цього допомогло?</li>\n    <li style=\"margin:8px 0;\">Чого ти точно <b>не</b> хочеш — наприклад, щоб усі помічали чи щоб знімала камера?</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\">Відповіді на ці питання й стають потребою, критеріями та обмеженнями. Якщо справжнього користувача немає, як у нас, відповідаємо за вигаданого персонажа, уважно читаючи його опис.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📐 Критерії та обмеження</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Критерій успіху (criterion)</b> — вимірна вимога: «сигнал видно з відстані 2 метри», «вимикається однією кнопкою». Так пізніше можна перевірити: вийшло чи ні.</li>\n    <li style=\"margin:8px 0;\"><b>Обмеження (constraint)</b> — те, чого робити не можна або що обов'язково врахувати: «без камери», «працює без телефона», «не збирає особистих даних».</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚖️ Цифрове, нецифрове чи ШІ?</h2>\n\n  <p style=\"margin:0 0 12px;\">Порівнюючи рішення, став однакові питання до кожного: чи вирішує воно потребу? Чи безпечне? Чи просте у використанні? Чи не збирає зайвих даних? Чи доступне школі? Цифрове рішення не автоматично найкраще, а ШІ доречний лише тоді, коли дає справжню користь, яку не дають простіші способи.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📝 Паперовий прототип</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Прототип (prototype)</b> — перша версія, яку можна перевірити. Паперовий прототип — це малюнок пристрою з підписами: що де світиться, яку кнопку натискати. Його показують користувачеві чи партнерові й питають, чи все зрозуміло. <b>Відгук (feedback)</b> допомагає виправити задум ще до програмування.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Наша користувачка — Оленка</b> (вигаданий персонаж), учениця 4 класу. У неї порушення слуху, і вона часто не чує дзвоника на урок. Їй потрібен надійний спосіб вчасно дізнаватися, що урок починається.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Потреба.</b> Запиши: <i>«Користувач — ___. Потреба — ___»</i>.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Три критерії.</b> Запиши три вимірні критерії успіху для рішення Оленки й одне обмеження.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Порівняй рішення.</b> Оціни кожне за своїми критеріями:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Цифрове:</b> micro:bit на парті Оленки блимає великою іконкою, коли вчитель натискає кнопку на своєму micro:bit.</li>\n    <li style=\"margin:8px 0;\"><b>Нецифрове:</b> учитель на початку уроку піднімає велику кольорову картку, а сусід по парті легенько торкається плеча.</li>\n    <li style=\"margin:8px 0;\"><b>ШІ-рішення:</b> камера в класі постійно знімає Оленку, розпізнає її обличчя й надсилає повідомлення на телефон.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Прототип і відгук.</b> Намалюй паперовий прототип обраного рішення. Покажи партнерові й запитай: «Що ти побачиш, коли почнеться урок? Як це вимкнути?» Запиши один відгук і що зміниш.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 1–2, приклад.</b> Користувач — Оленка, учениця з порушенням слуху. Потреба — вчасно дізнаватися про початок уроку без звуку. Критерії: сигнал видно з місця Оленки; спрацьовує за 2 секунди після натискання вчителя; Оленка може вимкнути його сама. Обмеження: без камер і без збирання особистих даних.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Цифрове рішення відповідає критеріям. Нецифрове теж працює й нічого не коштує, але залежить від того, чи не забудуть. ШІ-рішення порушує обмеження: постійна зйомка й розпізнавання обличчя — зайве збирання даних; до того ж потрібен телефон.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Потребу й два критерії запиши за зразком: <i>«Сигнал видно з ___»</i>, <i>«Вимикається ___»</i>.</p>\n    <p style=\"margin:10px 0 0;\">Порівняй лише цифрове й ШІ-рішення за одним питанням: чи збирає воно зайві дані про Оленку?</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо потреба, два критерії й обґрунтований вибір записані.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Коротке тестування з користувачем.</b> Дай партнерові виконати роль Оленки з твоїм паперовим прототипом. Змініть один критерій, якщо тест показав, що він неточний.</p>\n    <p style=\"margin:10px 0 0;\"><b>ШІ як помічник ідей.</b> Разом із учителем напиши промпт: «Запропонуй три способи повідомити ученицю з порушенням слуху про початок уроку, без камер і телефонів». Порівняй відповідь зі своїми критеріями й обмеженням: що підходить, а що ні?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The user needs a visual signal. My criterion is: the signal is visible from two metres.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u32-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. З чого починається людиноцентричний дизайн?</label>\n    <select id=\"g4-u32-q1\" name=\"g4-u32-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>З вибору плати</option>\n      <option>З користувача та його потреби</option>\n      <option>З кольору корпусу</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">З користувача та його потреби. Інструмент обирають потім.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u32-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Який критерій вимірний?</label>\n    <select id=\"g4-u32-q2\" name=\"g4-u32-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>«Пристрій гарний»</option>\n      <option>«Сигнал видно з відстані 2 метри»</option>\n      <option>«Усім сподобається»</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">«Видно з 2 метрів» — це можна перевірити.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u32-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Чому ШІ-камера — невдале рішення для Оленки?</label>\n    <select id=\"g4-u32-q3\" name=\"g4-u32-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Бо ШІ завжди поганий</option>\n      <option>Бо вона збирає зайві особисті дані й не потрібна для цієї задачі</option>\n      <option>Бо камери дорогі</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Вона збирає зайві дані, а просте рішення працює без неї. ШІ доречний лише тоді, коли дає справжню користь.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Спершу я з'ясовую ___, бо ___. Інструмент для Оленки я обираю за ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Потребу Оленки й три вимірні критерії записано.</li>\n      <li style=\"margin:8px 0;\">Я порівнюю три рішення й обґрунтовую вибір.</li>\n      <li style=\"margin:8px 0;\">Мій паперовий прототип показано партнерові, відгук записано.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> потреба, два критерії й обґрунтований вибір.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> картку проєкту (потреба, критерії, обмеження, вибір) і паперовий прототип з відгуком.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>user / need</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">користувач / потреба</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>accessibility</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">доступність</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>criterion</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">критерій успіху</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>constraint</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">обмеження</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>prototype</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">прототип</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>feedback</b></td><td style=\"padding:8px 10px;\">відгук</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>We start with the user, not with the tool.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-6","grade":4,"module":4,"number":6,"title":"Від потреби до плану: дизайн-мислення і декомпозиція","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок33_Гра1_Вимірно-чи-нечітко.html","title":"Вимірно чи нечітко?","description":"сортування карток","data":{"id":"m4g33a","lesson":33,"tag":"ВИМІР","icon":"⚖️","type":"sort","title":"Вимірно чи нечітко?","file":"М4_Урок33_Гра1_Вимірно-чи-нечітко.html","conceptName":"вимірні критерії","concept":"Вимірний критерій містить число або чітку дію, яку можна перевірити. Хай двоє людей перевірять його незалежно — вони мають дійти однакового висновку. «Зручний» і «крутий» перевірити неможливо.","skill":"відрізняти вимірні критерії від нечітких формулювань","data":{"categories":[{"id":"m","label":"📏 Вимірно","hint":"є число чи чітка дія"},{"id":"v","label":"🌫 Нечітко","hint":"перевірити неможливо"}],"items":[{"text":"«зручний»","cat":"v","explain":"Кожен розуміє «зручний» по-своєму — перевірити не можна.","hint":"що саме перевіряти?"},{"text":"«вмикається однією кнопкою»","cat":"m","explain":"Чітка дія: натискаємо одну кнопку — працює чи ні.","hint":"можна перевірити"},{"text":"«іконку видно з відстані 2 метри»","cat":"m","explain":"Є число — можна відійти на 2 метри й перевірити.","hint":"є число"},{"text":"«гарний»","cat":"v","explain":"«Гарний» — це смак, а не критерій.","hint":"смак — не вимір"},{"text":"«сигнал з'являється за 1 секунду після натискання»","cat":"m","explain":"Час можна виміряти секундоміром.","hint":"можна виміряти час"},{"text":"«усім сподобається»","cat":"v","explain":"Перевірити «усім» і «сподобається» неможливо.","hint":"як це перевірити?"},{"text":"«звук — не довше 1 секунди»","cat":"m","explain":"Тривалість звуку можна виміряти.","hint":"є межа в секундах"},{"text":"«крутий»","cat":"v","explain":"«Крутий» нічого не каже про перевірку.","hint":"що це означає?"}]}},"after":{"index":3,"heading":"✍️ Як писати вимірні критерії"}},{"path":"app/games/М4_Урок33_Гра2_Дизайн-бриф.html","title":"Дизайн-бриф","description":"сценарний вибір","data":{"id":"m4g33b","lesson":33,"tag":"БРИФ","icon":"📋","type":"quiz","title":"Дизайн-бриф","file":"М4_Урок33_Гра2_Дизайн-бриф.html","conceptName":"дизайн-бриф і тести","concept":"Дизайн-бриф — короткий опис проєкту: користувач і потреба, введення й виведення, цикл, критерії, обмеження, підзавдання й тести. Бриф затверджує учитель: це домовленість, що саме ми будуємо.","skill":"складати дизайн-бриф і прив'язувати тест до кожного критерію","data":{"questions":[{"q":"Навіщо до кожного критерію писати тест?","options":["Щоб потім перевірити, чи критерій виконано","Щоб бриф був довшим","Щоб учитель не питав"],"correct":0,"explain":"Критерій корисний, коли до нього є тест: «Роблю ___ — очікую ___».","wrong":"Якщо тест не вигадується — критерій нечіткий, його варто переписати."},{"q":"Яке підзавдання названо добре?","options":["«скинути сигнал»","«частина 2»","«різне»"],"correct":0,"explain":"Дієслово каже, що робить частина. «Частина 2» не пояснює нічого.","wrong":"Добра назва починається з дієслова й називає мету."},{"q":"ШІ запропонував ідею для бейджа. Хто вирішує, чи брати її в проєкт?","options":["Автор проєкту разом з учителем","ШІ сам вирішує","Ніхто"],"correct":0,"explain":"Вирішують люди: чи потрібна ідея користувачеві, чи безпечна, чи не збирає зайвих даних.","wrong":"ШІ — помічник ідей, а рішення ухвалюють люди."},{"q":"У план влізло вісім функцій, а урок один. Що зробити?","options":["Поділити на обов'язкове (не більше трьох частин) і бажане","Робити все одразу","Викинути все"],"correct":0,"explain":"Обов'язкове — без чого бейдж не виконує потребу; бажане — якщо лишиться час.","wrong":"Прототип треба зібрати за один урок. Вісім функцій — нереалістично."},{"q":"Навіщо бриф затверджує учитель?","options":["Перевіряє безпеку, реалістичність і обладнання — це домовленість","Щоб ускладнити проєкт","Це зайвий крок"],"correct":0,"explain":"Затверджений бриф — домовленість: на наступному уроці будуємо саме його.","wrong":"Учитель перевіряє, чи безпечна ідея і чи реально зробити її за урок."},{"q":"Які обмеження спільні для всіх бейджів класу?","options":["Без камер і записів, без особистих даних, тихий звук, працює без телефона","Жодних обмежень","Лише «щоб було гарно»"],"correct":0,"explain":"Обмеження захищають приватність і спокій класу.","wrong":"Згадай: приватність, тихий звук, жодного телефона."}]}},"after":{"index":1,"heading":"📋 Що таке дизайн-бриф"}}],"legacyTitle":"Урок 33. Від потреби до плану: дизайн-мислення і декомпозиція","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 33</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Від потреби до плану: дизайн-мислення і декомпозиція</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">From Need to Plan: Design Thinking and Decomposition</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як перетворити ідею на план, за яким можна написати й перевірити програму?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я складаю дизайн-бриф (<b>design brief</b>) для «Розумного сигнального бейджа».</li>\n      <li style=\"margin:6px 0;\">Я розбиваю проєкт на підзавдання (<b>decompose</b>).</li>\n      <li style=\"margin:6px 0;\">Я планую тести, за якими перевірю критерії успіху.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📋 Що таке дизайн-бриф</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Дизайн-бриф (design brief)</b> — короткий опис проєкту: для кого, навіщо і як ми перевіримо, що вийшло. Різні команди складають брифи по-різному. У нашому проєкті бриф міститиме:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>користувача й потребу</b>;</li>\n    <li style=\"margin:8px 0;\"><b>введення й виведення</b> micro:bit;</li>\n    <li style=\"margin:8px 0;\"><b>цикл</b>, який знадобиться, і навіщо;</li>\n    <li style=\"margin:8px 0;\"><b>критерії успіху</b> — вимірні;</li>\n    <li style=\"margin:8px 0;\"><b>обмеження</b> — що не можна робити;</li>\n    <li style=\"margin:8px 0;\"><b>підзавдання й тести</b>.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧩 Декомпозиція проєкту</h2>\n\n  <p style=\"margin:0 0 12px;\">Бейдж — невелика програма, але в ній кілька частин. Розбий її на <b>підзавдання</b> й назви кожне дієсловом: «показати готовність», «подати сигнал», «скинути сигнал». Кожне підзавдання потім можна зібрати й перевірити окремо.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✍️ Як писати вимірні критерії</h2>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:420px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Нечітко</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Вимірно</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«зручний»</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«вмикається однією кнопкою»</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«помітний»</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«іконку видно з відстані 2 метри»</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«швидкий»</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«сигнал з'являється за 1 секунду після натискання»</td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«не заважає»</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">«звук — не довше 1 секунди»</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Вимірний критерій містить число або чітку дію, яку можна перевірити. Хай двоє людей перевірять його незалежно — вони мають дійти однакового висновку.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">📏 Реалістичний план</h2>\n\n  <p style=\"margin:0 0 12px;\">Прототип треба зібрати за один урок. Тому поділи ідеї на дві групи: <b>обов'язкове</b> — без чого бейдж не виконує потребу, і <b>бажане</b> — що можна додати, якщо лишиться час. В обов'язковому — не більше трьох частин.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Спільні обмеження для всіх бейджів у нашому класі:</b> без камер і мікрофонних записів, без збирання імен чи інших особистих даних, звук — тихий і короткий, бейдж працює без телефона. До них можна додати власні.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Навіщо затвердження вчителем?</b> Учитель перевіряє, чи безпечна ідея, чи реально зробити її за урок і чи вистачить обладнання. Затверджений бриф — це домовленість: на уроці 34 ти будуєш саме його, а не щось зовсім інше.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧪 Тест для кожного критерію</h2>\n\n  <p style=\"margin:0 0 12px;\">Критерій успіху стає корисним, коли до нього є тест: <i>«Натискаю A один раз — очікую іконку «?» протягом 3 секунд»</i>. Якщо тест придумати не вдається, критерій, мабуть, нечіткий — його варто переписати.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔗 Як бриф стане програмою</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Введення</b> з брифу стануть блоками подій: <i>on button A pressed</i>.</li>\n    <li style=\"margin:8px 0;\"><b>Виведення</b> — блоками показу: <i>show icon</i>, <i>play tone</i>.</li>\n    <li style=\"margin:8px 0;\"><b>Цикл</b> — блоком <i>repeat</i> чи <i>forever</i>.</li>\n    <li style=\"margin:8px 0;\"><b>Підзавдання</b> — окремими скриптами, які ти збереш і перевіриш по черзі на уроці 34.</li>\n    <li style=\"margin:8px 0;\"><b>Тести</b> — таблицею, за якою ти перевірятимеш бейдж на уроці 35.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🤖 ШІ як помічник ідей</h2>\n\n  <p style=\"margin:0 0 12px;\">ШІ може запропонувати ідеї для бейджа. Але вирішуєш ти разом з учителем: чи потрібна ця ідея користувачеві, чи безпечна вона і чи не збирає зайвих даних.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Критерій «бейдж має бути крутим» — його неможливо перевірити.</li>\n    <li style=\"margin:8px 0;\">У плані більше функцій, ніж можна зробити за урок.</li>\n    <li style=\"margin:8px 0;\">Немає обмежень — і до проєкту потрапляє камера чи збирання імен.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">Обери один виклик для «Розумного сигнального бейджа»:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">📣 <b>«Потрібна допомога»</b> — тихо показати вчителеві, що є запитання.</li>\n    <li style=\"margin:8px 0;\">🤫 <b>«Тиха робота»</b> — показати іншим, що ти зосереджуєшся й просиш не турбувати.</li>\n    <li style=\"margin:8px 0;\">🎲 <b>«Команда A/B»</b> — швидко розподілитися на команди в грі.</li>\n    <li style=\"margin:8px 0;\">⏱ <b>«Таймер»</b> — показати, скільки лишилося часу на завдання.</li>\n  </ul>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Бриф.</b> Заповни бриф у документі чи зошиті:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:420px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Розділ</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Мій бейдж</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Користувач і потреба</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Введення</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Виведення</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Цикл і навіщо</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Критерії успіху (3)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">Обмеження</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Декомпозиція.</b> Розбий програму на 3–4 підзавдання з дієсловами.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Тести.</b> До кожного критерію запиши тест: «Роблю ___ — очікую ___».</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Затвердження.</b> Покажи бриф учителеві. Внеси правки, якщо вони є.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити: зразок для «Потрібна допомога»</summary>\n    <p style=\"margin:10px 0 0;\"><b>Користувач:</b> учень чи учениця, які соромляться піднімати руку. <b>Введення:</b> кнопки A і B. <b>Виведення:</b> іконка «?» і тихий сигнал. <b>Цикл:</b> repeat (2) — мигнути двічі, щоб помітили. <b>Критерії:</b> іконку видно з відстані 2 м; сигнал з'являється за 1 секунду після A; кнопка B скидає сигнал. <b>Обмеження:</b> без звуку голосніше за тихий, без збирання імен.</p>\n    <p style=\"margin:10px 0 0;\"><b>Підзавдання:</b> показати готовність; подати сигнал; скинути сигнал. <b>Тест:</b> «Натискаю B під час сигналу — очікую порожній екран».</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Скористайся зразком для «Потрібна допомога» і зміни його для свого виклику.</p>\n    <p style=\"margin:10px 0 0;\">Досить двох критеріїв і двох підзавдань.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо бриф заповнено, а вчитель його затвердив.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Правдоподібна, але проблемна ідея.</b> ШІ запропонував: «Нехай камера автоматично визначає, чи учню потрібна допомога, щоб не треба було натискати кнопку». Звучить зручно. Оціни ідею за чотирма питаннями: приватність (що знімає камера?), надійність (чи правильно вона вгадає?), потреба (чи справді кнопка — проблема?), вибір людини (хто вирішує, чи просити допомоги?). Прийми чи відхили ідею й поясни.</p>\n    <p style=\"margin:10px 0 0;\"><b>Два концепти.</b> Придумай два варіанти бейджа й оціни їх за критеріями в балах від 1 до 3. Який переміг?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>My design brief has three success criteria and one constraint.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u33-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Навіщо до кожного критерію писати тест?</label>\n    <select id=\"g4-u33-q1\" name=\"g4-u33-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб бриф був довшим</option>\n      <option>Щоб потім перевірити, чи критерій виконано</option>\n      <option>Щоб учитель не питав</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб перевірити виконання. Якщо тест не вигадується — критерій нечіткий.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u33-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Яке підзавдання названо добре?</label>\n    <select id=\"g4-u33-q2\" name=\"g4-u33-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>«частина 2»</option>\n      <option>«скинути сигнал»</option>\n      <option>«різне»</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">«Скинути сигнал»: дієслово каже, що робить частина.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u33-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Хто вирішує, чи брати ідею від ШІ в проєкт?</label>\n    <select id=\"g4-u33-q3\" name=\"g4-u33-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>ШІ</option>\n      <option>Автор проєкту разом з учителем</option>\n      <option>Ніхто</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Люди — автор проєкту й учитель, з огляду на потребу й безпеку.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Мій план такий: користувач ___, потреба ___. Я перевірю успіх тестом ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Мій бриф заповнено й затверджено вчителем.</li>\n      <li style=\"margin:8px 0;\">Програму розбито на 3–4 підзавдання, названі дієсловами.</li>\n      <li style=\"margin:8px 0;\">Кожен критерій має тест.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> бриф за зразком із двома критеріями, затверджений учителем.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> бриф, декомпозицію й тести (документ або зошит) з позначкою вчителя.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>design brief</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">дизайн-бриф</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>success criterion</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">критерій успіху</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>constraint</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">обмеження</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>decompose</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">розбити на частини</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>human decision</b></td><td style=\"padding:8px 10px;\">рішення людини</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>I decomposed my badge into three subtasks.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-7","grade":4,"module":4,"number":7,"title":"Створюємо прототип «Розумний сигнальний бейдж»","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок34_Гра1_Збери-бейдж.html","title":"Збери бейдж частинами","description":"послідовність кроків","data":{"id":"m4g34a","lesson":34,"tag":"БЕЙДЖ","icon":"🧱","type":"order","title":"Збери бейдж частинами","file":"М4_Урок34_Гра1_Збери-бейдж.html","conceptName":"будуємо частинами","concept":"Прототип збирають частина за частиною: додав одну частину — запустив — перевірив — лише тоді наступна. Якщо щось зламалося, ти точно знаєш, що додав останнім.","skill":"збирати програму бейджа поетапно з тестом після кожної частини","data":{"rounds":[{"title":"Початковий стан і сигнал","steps":["on start → clear screen → plot x (2) y (2)","Запусти: у центрі світиться крапка?","Додай on button A pressed → repeat (2) → спалахи «?»","Натисни A: два спалахи, знак лишається?","Збережи як badge_version_1"],"hint":"після кожної частини — тест","explain":"Крапка — знак «я ввімкнений і готовий». Блок show icon після repeat лишає знак на екрані."},{"title":"Скидання і друга версія","steps":["Додай on button B pressed","clear screen","plot x (2) y (2)","Тест: A, потім B — знак зник, крапка повернулася?","Збережи як badge_version_2"],"hint":"B прибирає сигнал і повертає крапку","explain":"Дві версії збережено окремо: якщо нова зміна все зіпсує, завжди є куди повернутися."}]}},"after":{"index":1,"heading":"🧱 Будуємо частинами"}},{"path":"app/games/М4_Урок34_Гра2_Чому-не-працює.html","title":"Чому бейдж не працює?","description":"сценарний вибір","data":{"id":"m4g34b","lesson":34,"tag":"СТАРТ","icon":"🏁","type":"quiz","title":"Чому бейдж не працює?","file":"М4_Урок34_Гра2_Чому-не-працює.html","conceptName":"типові помилки прототипу","concept":"Три класичні помилки: зібрали всю програму одразу — незрозуміло, яка частина не працює; забули on start — екран порожній; перезаписали версію 1 — повертатися нікуди.","skill":"діагностувати типові помилки при збиранні прототипу","data":{"questions":[{"q":"Після ввімкнення екран бейджа порожній, і неясно, чи він узагалі працює. Чого бракує?","options":["Блока on start із початковим станом","Ще однієї кнопки","Гучнішого звуку"],"correct":0,"explain":"on start виконується один раз при ввімкненні: крапка в центрі каже «я готовий».","wrong":"Початковий стан задають блоком, що спрацьовує при ввімкненні плати."},{"q":"Навіщо тестувати кожну частину одразу після додавання?","options":["Щоб знати, яка саме частина зламала програму","Щоб програма була довшою","Тестувати не потрібно"],"correct":0,"explain":"Додав — запустив — перевірив. Збій одразу прив'язаний до останньої частини.","wrong":"Якщо зібрати все одразу, доведеться шукати помилку серед усіх частин."},{"q":"Версію 1 перезаписали новою, і нова зламалася. Що втрачено?","options":["Можливість повернутися до робочої версії","Нічого","Лише назву файлу"],"correct":0,"explain":"Зберігай версії з номерами: badge_version_1, badge_version_2 — тоді завжди є куди повернутися.","wrong":"Збереження версій — це страховка: робоча копія лишається недоторканою."},{"q":"Після циклу repeat знак «?» не лишається на екрані. Що перевірити?","options":["Чи блок show icon стоїть після repeat, а не всередині","Чи достатньо пауз","Чи правильна кнопка"],"correct":0,"explain":"Блок усередині repeat гасне наступним clear screen; щоб знак лишився, show icon має бути після циклу.","wrong":"Подивись, де стоїть фінальний show icon: всередині циклу чи після нього?"},{"q":"Що робить блок on start?","options":["Виконується один раз при ввімкненні","Повторюється без кінця","Реагує на кнопку A"],"correct":0,"explain":"on start — це початковий стан: він спрацьовує один раз при ввімкненні.","wrong":"Безкінечно працює forever, а на кнопку реагує on button pressed."},{"q":"На платі V1 сигнал-звук не чути. Як зберегти доступність сигналу?","options":["Покластися на велику іконку — вона працює на будь-якій платі","Зробити звук гучнішим","Прибрати сигнал узагалі"],"correct":0,"explain":"Доступність — кілька способів сигналу. Іконка видима й на V1, і людині, що не чує.","wrong":"Згадай: сигнал не має залежати від одного способу."}]}},"after":{"index":5,"heading":"⚠️ Типові помилки"}}],"legacyTitle":"Урок 34. Створюємо прототип «Розумний сигнальний бейдж»","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 34</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Створюємо прототип «Розумний сигнальний бейдж»</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Building a “Smart Signal Badge” Prototype</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як будувати програму частинами, щоб помилки знаходилися одразу?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я збираю програму бейджа за своїм планом частина за частиною.</li>\n      <li style=\"margin:6px 0;\">Я тестую кожну частину одразу після додавання.</li>\n      <li style=\"margin:6px 0;\">Я зберігаю дві версії прототипу й пояснюю, що змінилося.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧱 Будуємо частинами</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Прототип (prototype)</b> — версія, яку вже можна перевірити, але ще не готовий магазинний виріб. Його збирають не весь одразу, а <b>частина за частиною</b>: додав одну частину — запустив — перевірив — лише тоді наступна. Якщо щось зламалося, ти точно знаєш, що саме додав останнім.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🏁 Початковий стан</h2>\n\n  <p style=\"margin:0 0 12px;\">У нашому проєкті ми задаємо <b>початковий стан (initialise)</b>: що бейдж показує одразу після ввімкнення. Для цього в MakeCode є блок <b>on start</b>. Одна світла крапка в центрі — знак «я ввімкнений і готовий».</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">💾 Зберігаємо версії</h2>\n\n  <p style=\"margin:0 0 12px;\">Після кожного великого кроку зберігай копію проєкту з номером: <b>badge_version_1</b>, <b>badge_version_2</b>. Це збереження версій (versioning). Якщо нова зміна все зіпсує, завжди можна повернутися до попередньої версії, яка працювала.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">♿ Сигнал для різних людей</h2>\n\n  <p style=\"margin:0 0 12px;\">Звук сам по собі не робить пристрій доступним: людина з порушенням слуху його не почує. Доступність часто означає <b>кілька способів сигналу</b> — наприклад, велика іконка і тихий звук. На платі V1 без динаміка лишиться іконка — і сигнал все одно працюватиме.</p>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #B38600;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;\"><b>Яка у тебе плата?</b> У школі можуть бути micro:bit V1 або V2. Кнопки A і B, екран 5×5, датчик руху, рівень освітленості й температура є в обох. А <b>сенсорний логотип, мікрофон і вбудований динамік</b> є лише у V2. На V1 звук чути лише через навушники чи динамік, під'єднаний до контактів. Якщо програма використовує ці можливості, перевір, яка плата перед тобою.</p>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Зібрали всю програму відразу — і незрозуміло, яка частина не працює.</li>\n    <li style=\"margin:8px 0;\">Забули on start — після ввімкнення екран порожній, і неясно, чи працює бейдж.</li>\n    <li style=\"margin:8px 0;\">Перезаписали версію 1 новою — і повертатися нікуди.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🔌 Працюємо в MakeCode для micro:bit: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a>. Програму перевіряй у симуляторі ліворуч, а на станції з платою — кнопкою <b>Download</b> завантаж її на справжній micro:bit.</p>\n\n  <p style=\"margin:0 0 12px;\">Збери бейдж за своїм брифом. Нижче — приклад для виклику «Потрібна допомога»; зміни іконки й кількість під свій план.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Початковий стан.</b> Збери й запусти:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on start</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">clear screen</div>\n      <div style=\"border-left:6px solid #5C2D91;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">plot x (2) y (2)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Тест: після запуску в центрі світиться одна крапка? Якщо так, перша частина готова — і лише тепер додаємо наступну.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Сигнал — версія 1.</b> Додай і перевір:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button A pressed</div>\n      <div style=\"border-left:6px solid #00AA00;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">repeat (2) times</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">show icon ?</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">pause (ms) (400)</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">clear screen</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 56px;border-radius:4px;\">pause (ms) (300)</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">show icon ?</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Тест: A — дві спалахи, потім знак лишається. Додай коментар (правою кнопкою по блоку → <i>Add Comment</i>): навіщо цей скрипт. Збережи як <b>badge_version_1</b>.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Скидання — версія 2.</b> Додай кнопку B, яка прибирає сигнал і повертає крапку:</p>\n\n  <div style=\"background:#F8FAFC;border:1px solid #D9E2F0;border-radius:10px;padding:12px 14px;margin:12px 0;\">\n    <div style=\"font-family:'Courier New',monospace;font-size:16px;line-height:1.45;\">\n      <div style=\"border-left:6px solid #D400D4;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 0px;border-radius:4px;\">on button B pressed</div>\n      <div style=\"border-left:6px solid #1E90FF;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">clear screen</div>\n      <div style=\"border-left:6px solid #5C2D91;background:#FFFFFF;padding:4px 10px;margin:4px 0 4px 28px;border-radius:4px;\">plot x (2) y (2)</div>\n    </div>\n  </div>\n\n  <p style=\"margin:0 0 12px;\">Тест: A, потім B — знак зник, крапка повернулася? Якщо плата V2, можеш додати тихий звук у сигнал A. Додай коментар і збережи як <b>badge_version_2</b>.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. На платі.</b> На станції завантаж версію 2 на micro:bit (<b>Download</b>) і повтори тести. Запиши в чек-лист: що перевірено і що змінилося між версіями 1 і 2.</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:460px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Частина</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Тест</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Пройдено?</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">початковий стан</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">крапка після запуску</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">сигнал (A)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">два спалахи, знак лишається</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">скидання (B)</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">знак зникає, крапка повертається</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Кроки 1–3.</b> Усі три тести мають пройти. Якщо A не показує знак після циклу — перевір, чи блок show icon стоїть <b>після</b> repeat, а не всередині.</p>\n    <p style=\"margin:10px 0 0;\"><b>Версії.</b> У версії 1 — старт і сигнал. У версії 2 додано скидання і, можливо, звук. Обидві збережені окремо.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Збери лише початковий стан і сигнал кнопки A.</p>\n    <p style=\"margin:10px 0 0;\">Протестуй обидві частини й збережи одну версію.</p>\n    <p style=\"margin:10px 0 0;\">Завдання виконано, якщо бейдж показує крапку після старту і подає сигнал за кнопкою A.</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Функція.</b> Винеси сигнал в окрему функцію (<i>Functions → Make a Function…</i>, назва «сигнал») і виклич її з кнопки A. Що стало зрозумілішим?</p>\n    <p style=\"margin:10px 0 0;\"><b>Другий режим.</b> Додай режим, наприклад «Тиха робота» за кнопками A+B, не збираючи жодних особистих даних.</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>I tested each part after I added it. I saved version 1 and version 2.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u34-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Навіщо тестувати кожну частину одразу?</label>\n    <select id=\"g4-u34-q1\" name=\"g4-u34-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб знати, яка частина зламала програму</option>\n      <option>Щоб програма була довшою</option>\n      <option>Тестувати не потрібно</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб одразу бачити, яка частина спричинила помилку.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u34-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Що робить блок on start?</label>\n    <select id=\"g4-u34-q2\" name=\"g4-u34-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Виконується один раз при ввімкненні</option>\n      <option>Повторюється без кінця</option>\n      <option>Реагує на кнопку A</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Виконується один раз при ввімкненні — задає початковий стан.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u34-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Навіщо зберігати badge_version_1 окремо?</label>\n    <select id=\"g4-u34-q3\" name=\"g4-u34-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб повернутися до робочої версії, якщо нова зламається</option>\n      <option>Щоб зайняти більше місця</option>\n      <option>Так вимагає micro:bit</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб мати робочу версію, до якої можна повернутися.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Я будую бейдж частинами: спершу ___, потім ___. Після кожної частини я ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Мій прототип працює: початковий стан, сигнал і скидання.</li>\n      <li style=\"margin:8px 0;\">Кожну частину протестовано, чек-лист заповнено.</li>\n      <li style=\"margin:8px 0;\">Збережено дві версії з коментарями, і я пояснюю, що змінилося.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> початковий стан і сигнал кнопки A, одна версія.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> проєкти badge_version_1 і badge_version_2 (посилання або .hex), чек-лист і демонстрацію на платі чи в симуляторі.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>prototype</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">прототип</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>implement</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">втілити, реалізувати</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>initialise</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">задати початковий стан</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>version</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">версія</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>comment</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">коментар</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>test</b></td><td style=\"padding:8px 10px;\">тест</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>My prototype shows a dot at the start. Button A shows the help signal.</i></p>\n  </div>\n\n</div>\n"},{"id":"4-4-8","grade":4,"module":4,"number":8,"title":"Тестуємо, удосконалюємо, презентуємо і передаємо проєкт","moduleTitle":"Керовані системи, micro:bit і проєкт бейджа","games":[{"path":"app/games/М4_Урок35_Гра1_Корисний-відгук.html","title":"Корисний відгук","description":"сценарний вибір","data":{"id":"m4g35a","lesson":35,"tag":"ВІДГУК","icon":"👥","type":"quiz","title":"Корисний відгук","file":"М4_Урок35_Гра1_Корисний-відгук.html","conceptName":"тести, відгук і покращення","concept":"Найцінніший тест — коли пристроєм користується інша людина без твоїх пояснень. Після будь-якої зміни повторюй попередні тести: нова зміна може зламати те, що працювало.","skill":"ставити корисні запитання для відгуку й перевіряти проєкт після змін","data":{"questions":[{"q":"Яке запитання партнерові дає корисний відгук?","options":["«Як, на твою думку, скасувати сигнал?»","«Тобі подобається?»","«Правда ж, гарно?»"],"correct":0,"explain":"Таке запитання перевіряє, чи зрозумілий бейдж без пояснень автора.","wrong":"«Подобається?» — відповідь, з якою нічого не зробиш. Питай про дії."},{"q":"Ти щось змінив(-ла) у програмі. Що робити далі?","options":["Повторити попередні тести","Одразу презентувати","Видалити старі версії"],"correct":1,"explain":"Нова зміна могла зламати те, що працювало. Тести повторюють до і після змін в однакових умовах.","wrong":"Зміна могла ненароком щось зламати — це перевіряють повторним тестом."},{"q":"У таблиці тестів є стовпчики «Очікую» і «Бачу». Як їх читати?","options":["Очікуване проти фактичного: збіг — тест пройдено","Це дві колонки для краси","«Бачу» заповнюють до тесту"],"correct":0,"explain":"Expected і actual: якщо збігаються — pass, ні — fail, і це привід шукати причину.","wrong":"Очікуване записуємо до тесту, фактичне — після. Потім порівнюємо."},{"q":"Тести показали дві проблеми: скидання не працює і іконка могла б бути контрастнішою. Що виправляти першим?","options":["Скидання: спершу виправляють те, що заважає основній функції","Іконку: вона помітніша","Обидва одразу"],"correct":0,"explain":"Спершу помилка основної функції, потім покращення за відгуком — одна продумана зміна.","wrong":"Що важливіше для роботи бейджа: зовнішність чи основна дія?"},{"q":"Тест «швидко натискаю A двічі» дає миготіння, що не закінчується. Що це?","options":["Привід для покращення в наступній версії","Нормальна поведінка","Зламана плата"],"correct":0,"explain":"Незвичні ситуації теж тестують — цей результат записуємо і виправляємо.","wrong":"Бейдж має лишатися керованим у будь-якій ситуації, навіть незвичній."},{"q":"Навіщо картка передавання?","options":["Щоб інша людина могла користуватися проєктом без автора","Щоб проєкт був довшим","Для оцінки за почерк"],"correct":0,"explain":"Передавання — момент, коли проєкт отримує інша людина: їй потрібні призначення, кнопки, результати тестів.","wrong":"Уяви, що проєкт отримує молодший клас. Що їм потрібно знати?"}]}},"after":{"index":2,"heading":"👥 Відгук користувача"}},{"path":"app/games/М4_Урок35_Гра2_Картка-передавання.html","title":"Що в картці передавання?","description":"сортування карток","data":{"id":"m4g35b","lesson":35,"tag":"КАРТКА","icon":"🤝","type":"sort","title":"Що в картці передавання?","file":"М4_Урок35_Гра2_Картка-передавання.html","conceptName":"картка передавання","concept":"Картка передавання містить: назву й призначення, кнопки та їхні дії, результати тестів і покращення, хто що зробив і чи допомагав ШІ, що можна покращити далі. Жодних особистих даних!","skill":"визначати, що має бути в картці передавання, а чого там бути не повинно","data":{"categories":[{"id":"yes","label":"✅ Має бути","hint":"допоможе новій людині"},{"id":"no","label":"🚫 Не місце в картці","hint":"зайве або небезпечне"}],"items":[{"text":"Назва й призначення бейджа","cat":"yes","explain":"Нова людина має зрозуміти, що це і навіщо.","hint":"з чого почати знайомство"},{"text":"Кнопки та що вони роблять","cat":"yes","explain":"Без інструкції кнопок людина не знає, з чого почати.","hint":"інструкція користування"},{"text":"Результати тестів і що покращено","cat":"yes","explain":"Докази роботи й історія змін — важлива частина картки.","hint":"докази"},{"text":"Хто що зробив і чи допомагав ШІ","cat":"yes","explain":"Чесно вказуємо внесок людей і інструментів.","hint":"прозорість"},{"text":"Що можна покращити далі","cat":"yes","explain":"Це дороговказ для наступної версії.","hint":"плани на майбутнє"},{"text":"Пароль від акаунта MakeCode","cat":"no","explain":"Паролі ніколи не записують у документи, які передають іншим!","hint":"це секрет"},{"text":"Домашня адреса автора","cat":"no","explain":"Особисті дані не потрібні для користування бейджем.","hint":"особисті дані — ні"},{"text":"Улюблений колір автора","cat":"no","explain":"Цікаво, але для користування бейджем не допомагає.","hint":"не стосується проєкту"}]}},"after":{"index":4,"heading":"🤝 Передавання проєкту"}},{"path":"app/games/М4_Урок35_Гра3_Презентація.html","title":"Презентація за 60–90 секунд","description":"послідовність кроків","data":{"id":"m4g35c","lesson":35,"tag":"ПЕРЕДАЧА","icon":"🎤","type":"order","title":"Презентація за 60–90 секунд","file":"М4_Урок35_Гра3_Презентація.html","conceptName":"презентація проєкту","concept":"Коротка презентація має чотири частини: проблема (для кого бейдж), рішення (покажи в роботі), докази (скільки тестів пройдено), покращення (що змінено).","skill":"вибудовувати коротку презентацію проєкту й фінальний цикл тестування","data":{"rounds":[{"title":"Презентація бейджа класові","steps":["Проблема: для кого бейдж і яку потребу він вирішує","Рішення: покажи бейдж у роботі — натисни A, потім B","Докази: скільки тестів пройдено і що показав відгук","Покращення: що змінено у версії 3 і що зробиш далі"],"hint":"одне речення про проблему — на початку","explain":"Говори повільно, тримай бейдж так, щоб бачили всі, і будь готовий чи готова відповісти на запитання."},{"title":"Фінальний цикл удосконалення","steps":["Проведи всі тести за таблицею","Збери відгук партнера без підказок","Внеси одне покращення","Повтори всі тести","Збережи як badge_version_3","Створи картку передавання"],"hint":"після зміни — тести знову","explain":"Одна продумана зміна краща за п'ять поспішних. Нову версію зберігаємо лише коли всі тести знову пройдено."}]}},"after":{"index":5,"heading":"🎤 Презентація за 60–90 секунд"}}],"legacyTitle":"Урок 35. Тестуємо, удосконалюємо, презентуємо і передаємо проєкт","practice":null,"html":"<div style=\"max-width:880px;margin:0 auto;padding:16px;font-family:'Inter',-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:#1A1A1A;line-height:1.6;font-size:16px;background:#FFFFFF;\">\n  \n\n  <div style=\"background:#0033A0;color:#FFFFFF;padding:22px 24px;border-radius:12px;border-bottom:5px solid #FFD700;\">\n    <p style=\"margin:0 0 8px;font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#D6E0F5;\">Клас 4 &bull; Модуль 4 &bull; Урок 35</p>\n    <h1 style=\"margin:0 0 10px;font-size:27px;line-height:1.2;font-weight:800;\">Тестуємо, удосконалюємо, презентуємо і передаємо проєкт</h1>\n    <p style=\"margin:0;font-size:16px;color:#EAF0FC;\">Testing, Improving, Presenting and Handing Over a Project</p>\n  </div>\n\n  <div style=\"background:#FFF9DB;border-left:5px solid #FFD700;border-radius:8px;padding:16px 18px;margin:16px 0;\">\n    <p style=\"margin:0;font-size:18px;font-weight:700;\">Питання уроку: як докази тестування й відгуки перетворюють першу робочу версію на кращу?</p>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🎯 Чого я навчуся</h2>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:6px 0;\">Я перевіряю свій бейдж за планом тестів і записую очікуване й фактичне.</li>\n      <li style=\"margin:6px 0;\">Я вношу одне покращення на основі тестів чи відгуку й перевіряю, що нічого не зламалося.</li>\n      <li style=\"margin:6px 0;\">Я передаю проєкт іншій людині з карткою-інструкцією й коротко презентую його.</li>\n    </ul>\n  </div>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🧪 Тестуємо за критеріями</h2>\n\n  <p style=\"margin:0 0 12px;\">Під час фінальної перевірки повертаємося до <b>критеріїв успіху</b> з брифу. Для кожного — <b>тест</b>: що роблю, що <b>очікую (expected)</b>, що <b>бачу насправді (actual)</b>, пройдено (pass) чи ні (fail). Тести проводять в однакових умовах до і після змін.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">👥 Відгук користувача</h2>\n\n  <p style=\"margin:0 0 12px;\">Найцінніший тест — коли пристроєм користується інша людина без твоїх пояснень. Не питай «Тобі подобається?». Запитай: <i>«Що, на твою думку, зробить кнопка A? Як скасувати сигнал?»</i> Так видно, чи зрозумілий бейдж без автора. Це <b>відгук (feedback)</b>. Записуй відповіді партнера дослівно, навіть якщо вони несподівані: саме вони підкажуть, що покращити.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🔧 Одне покращення</h2>\n\n  <p style=\"margin:0 0 12px;\">Спершу виправ помилку, яка заважає основній функції. Якщо таких немає, <b>покращ (improve)</b> те, на що вказав відгук: контрастніша іконка, коротший сигнал, зрозуміліше скидання. Одна продумана зміна краща за п'ять поспішних.</p>\n\n  <p style=\"margin:0 0 12px;\">Після зміни <b>повтори попередні тести</b>. Нова зміна може ненароком зламати те, що працювало. Лише коли всі тести знову пройдено, зберігай нову версію.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🤝 Передавання проєкту</h2>\n\n  <p style=\"margin:0 0 12px;\"><b>Передавання (handover)</b> — момент, коли проєкт отримує інша людина: учитель, однокласник, молодший клас. Щоб вона могла ним користуватися без тебе, потрібна <b>картка передавання</b>:</p>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">назва й призначення бейджа;</li>\n    <li style=\"margin:8px 0;\">кнопки та що вони роблять;</li>\n    <li style=\"margin:8px 0;\">результати тестів і що покращено;</li>\n    <li style=\"margin:8px 0;\">хто що зробив, які інструменти використано і чи допомагав ШІ;</li>\n    <li style=\"margin:8px 0;\">що можна покращити далі.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🎤 Презентація за 60–90 секунд</h2>\n\n  <ol style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\"><b>Проблема:</b> для кого бейдж і яку потребу він вирішує — одне речення.</li>\n    <li style=\"margin:8px 0;\"><b>Рішення:</b> покажи бейдж у роботі — натисни A, потім B.</li>\n    <li style=\"margin:8px 0;\"><b>Докази:</b> скільки тестів пройдено і що показав відгук.</li>\n    <li style=\"margin:8px 0;\"><b>Покращення:</b> що змінено у версії 3 і що зробиш далі.</li>\n  </ol>\n\n  <p style=\"margin:0 0 12px;\">Говори повільно й тримай бейдж так, щоб його бачили всі. Одне-два речення скажи англійською. Наприкінці будь готовий чи готова відповісти на одне запитання класу.</p>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">⚠️ Типові помилки</h2>\n\n  <ul style=\"margin:0 0 14px;padding-left:22px;\">\n    <li style=\"margin:8px 0;\">Після зміни не повторили старі тести — і не помітили, що скидання зламалося.</li>\n    <li style=\"margin:8px 0;\">Питали «Тобі подобається?» — і отримали відповідь, з якою нічого не зробиш.</li>\n    <li style=\"margin:8px 0;\">Картка передавання без інструкції кнопок — людина не знає, з чого почати.</li>\n  </ul>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">🛠 Основне завдання</h2>\n\n  <p style=\"margin:0 0 12px;\">🔌 Працюємо в MakeCode для micro:bit: <a href=\"https://itnauka.org/outer/\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color:#0033A0;font-weight:700;\">відкрий його через каталог перевірених сервісів ↗</a>. Програму перевіряй у симуляторі ліворуч, а на станції з платою — кнопкою <b>Download</b> завантаж її на справжній micro:bit.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 1. Тести.</b> Відкрий badge_version_2. Проведи чотири тести й заповни таблицю:</p>\n\n  <div style=\"overflow-x:auto;margin:12px 0;\">\n    <table style=\"border-collapse:collapse;width:100%;min-width:540px;font-size:16px;\">\n      <thead><tr><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Що роблю</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Очікую</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Бачу</th><th style=\"text-align:left;padding:9px 10px;border:1px solid #D9E2F0;background:#F0F4F8;\">Pass / Fail</th></tr></thead>\n      <tbody>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">натискаю A один раз</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">знак «?» видно</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">натискаю B під час сигналу</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">сигнал зникає, крапка повертається</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">даю бейдж партнерові без пояснень</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">розуміє обидві кнопки</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n        <tr><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">швидко натискаю A двічі</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\">бейдж лишається керованим</td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td><td style=\"padding:9px 10px;border:1px solid #D9E2F0;\"></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 2. Відгук.</b> Попроси партнера виконати завдання без підказки. Запиши його відповіді на два запитання з розділу вище.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 3. Покращення.</b> Обери й реалізуй одну зміну. Повтори всі чотири тести. Збережи як <b>badge_version_3</b>.</p>\n\n  <p style=\"margin:0 0 12px;\"><b>Крок 4. Передавання й презентація.</b> Створи картку передавання: один слайд, сторінку в документі чи аркуш. Потім за 60–90 секунд розкажи класу: яка проблема, яке рішення, що показали тести, що покращено. Одне-два речення — англійською.</p>\n\n  <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:17px;\">Звірити</summary>\n    <p style=\"margin:10px 0 0;\"><b>Крок 1.</b> Якщо тест «швидко натискаю A двічі» дає миготіння, що не закінчується, — це привід для покращення в Кроці 3.</p>\n    <p style=\"margin:10px 0 0;\"><b>Крок 3.</b> Приклад покращення: партнер не зрозумів, що B скидає сигнал → на старті показати коротку підказку «B» перед крапкою. Після зміни всі чотири тести пройдено знову.</p>\n  </details>\n\n  <details style=\"background:#FFF4E5;border:1px solid #E0A458;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#8A5A00;\">🆘 Потрібна допомога?</summary>\n    <p style=\"margin:12px 0 0;\">Проведи два тести: кнопки A і B.</p>\n    <p style=\"margin:10px 0 0;\">Запиши один відгук і зроби одну зміну; повтори обидва тести.</p>\n    <p style=\"margin:10px 0 0;\">Картку передавання склади за рамкою: «Бейдж ___. Кнопка A ___. Кнопка B ___»</p>\n  </details>\n\n  <details style=\"background:#EAF0FC;border:1px solid #0033A0;border-radius:10px;padding:16px 18px;margin:18px 0;\">\n    <summary style=\"font-weight:700;cursor:pointer;font-size:18px;color:#0033A0;\">🚀 Хочеш більше?</summary>\n    <p style=\"margin:12px 0 0;\"><b>Незвичні ситуації (edge cases).</b> Що буде, якщо натиснути A і B одночасно? Якщо тримати A довго? Придумай ще один незвичний тест і проведи його.</p>\n    <p style=\"margin:10px 0 0;\"><b>Обмеження й наступна версія.</b> Запиши, чого бейдж поки не вміє і що ти зробиш у версії 4. Порівняй: які рішення ухвалювала людина, а в чому допомагав інструмент чи ШІ?</p>\n    <p style=\"margin:10px 0 0;\">Скажи англійською: <i>The test passed. I improved the reset button after feedback.</i></p>\n  </details>\n\n  <h2 style=\"margin:28px 0 10px;font-size:21px;color:#0033A0;\">✅ Перевір себе</h2>\n  <p style=\"margin:0 0 16px;font-size:16px;color:#3D4757;\">Самоперевірка — не оцінюється. Спочатку обери відповідь, потім відкривай пояснення.</p>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u35-q1\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">1. Що робити після будь-якої зміни в коді?</label>\n    <select id=\"g4-u35-q1\" name=\"g4-u35-q1\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Одразу презентувати</option>\n      <option>Повторити попередні тести</option>\n      <option>Видалити старі версії</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Повторити попередні тести: зміна могла зламати те, що працювало.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u35-q2\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">2. Яке запитання дає корисний відгук?</label>\n    <select id=\"g4-u35-q2\" name=\"g4-u35-q2\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>«Тобі подобається?»</option>\n      <option>«Як, на твою думку, скасувати сигнал?»</option>\n      <option>«Правда ж, гарно?»</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Друге: воно перевіряє, чи зрозумілий бейдж без пояснень.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:14px 0;\">\n    <label for=\"g4-u35-q3\" style=\"display:block;font-weight:700;margin-bottom:10px;font-size:17px;\">3. Навіщо картка передавання?</label>\n    <select id=\"g4-u35-q3\" name=\"g4-u35-q3\" style=\"width:100%;padding:12px;font-size:16px;border:2px solid #0033A0;border-radius:8px;background:#FFFFFF;color:#1A1A1A;\">\n      <option value=\"\" disabled selected>Обери відповідь…</option>\n      <option>Щоб інша людина могла користуватися проєктом без автора</option>\n      <option>Щоб проєкт був довшим</option>\n      <option>Для оцінки за почерк</option>\n    </select>\n    <details style=\"background:#F0F4F8;border-radius:8px;padding:12px 14px;margin:14px 0 0;\">\n      <summary style=\"font-weight:700;cursor:pointer;font-size:16px;\">Перевірити</summary>\n      <p style=\"margin:10px 0 0;\">Щоб проєктом могли користуватися без тебе.</p>\n    </details>\n  </div>\n\n  <div style=\"background:#F0F4F8;border-left:5px solid #0033A0;border-radius:8px;padding:16px 18px;margin:24px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#0033A0;\">🗣 Поясни своїми словами</h2>\n    <p style=\"margin:0;\">Дай відповідь на питання уроку. Спирайся на власні записи з цього уроку, а не на загальні слова:</p>\n    <p style=\"margin:10px 0 0;font-size:18px;\"><i>«Тести показали ___. Відгук підказав ___. Тому у версії 3 я ___»</i></p>\n  </div>\n\n  <div style=\"background:#E9F4ED;border:1px solid #1B6B3A;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 10px;font-size:20px;color:#155C32;\">✅ Готово, якщо…</h2>\n    <p style=\"margin:0 0 8px;\"><b>Основний маршрут:</b></p>\n    <ul style=\"margin:0;padding-left:22px;\">\n      <li style=\"margin:8px 0;\">Мій бейдж проходить основні тести, таблицю заповнено.</li>\n      <li style=\"margin:8px 0;\">Одну проблему виправлено на основі тестів чи відгуку, тести повторено.</li>\n      <li style=\"margin:8px 0;\">Картку передавання створено, а інша людина користується бейджем за нею.</li>\n    </ul>\n    <p style=\"margin:12px 0 0;\"><b>Маршрут з допомогою:</b> два тести, одна зміна з повторними тестами, картка за рамкою.</p>\n    <p style=\"margin:14px 0 0;padding-top:14px;border-top:1px solid #B8DAC6;\"><b>Що показати:</b> працюючий проєкт badge_version_3 (посилання або .hex), таблицю тестів, картку передавання й презентацію.</p>\n  </div>\n\n  <div style=\"background:#FFFFFF;border:1px solid #D9E2F0;border-radius:10px;padding:18px 20px;margin:20px 0;\">\n    <h2 style=\"margin:0 0 12px;font-size:20px;color:#0033A0;\">🇬🇧 Cambridge</h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"border-collapse:collapse;width:100%;min-width:380px;font-size:16px;\">\n        <tbody>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>test</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">тест</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>expected / actual</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">очікуване / фактичне</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>feedback</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">відгук</td></tr>\n          <tr><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\"><b>improve</b></td><td style=\"padding:8px 10px;border-bottom:1px solid #EDF1F8;\">покращити</td></tr>\n          <tr><td style=\"padding:8px 10px;\"><b>handover</b></td><td style=\"padding:8px 10px;\">передавання проєкту</td></tr>\n        </tbody>\n      </table>\n    </div>\n    <p style=\"margin:14px 0 0;\"><b>Say it:</b> <i>Our badge passed three tests. After feedback we improved the reset button.</i></p>\n  </div>\n\n</div>\n"}];
